CREATE OR REPLACE FUNCTION "public"."abandon_multiplayer_match"("p_match_id" "uuid", "p_reason" "text" DEFAULT 'player_quit'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_student_id UUID;
  v_match RECORD;
  v_opponent_id UUID;
  v_opponent_reward INTEGER;
  v_elo_change INTEGER;
  v_abandoner_stats RECORD;
  v_opponent_stats RECORD;
  v_season TEXT;
BEGIN
  -- Get authenticated student ID
  v_student_id := auth.uid();
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Non authentifié';
  END IF;

  -- Fetch match details WITH LOCK to prevent race condition
  SELECT * INTO v_match
  FROM minesweeper_multiplayer_matches
  WHERE id = p_match_id
  FOR UPDATE;  -- CRITICAL: Locks row until transaction completes

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match introuvable';
  END IF;

  -- Verify player is a participant
  IF v_match.player1_id != v_student_id AND v_match.player2_id != v_student_id THEN
    RAISE EXCEPTION 'Vous ne participez pas à ce match';
  END IF;

  -- Verify match can be abandoned (in_progress or countdown)
  IF v_match.status NOT IN ('in_progress', 'countdown') THEN
    RAISE EXCEPTION 'Le match ne peut pas être abandonné (status: %)', v_match.status;
  END IF;

  -- Determine opponent
  IF v_match.player1_id = v_student_id THEN
    v_opponent_id := v_match.player2_id;
  ELSE
    v_opponent_id := v_match.player1_id;
  END IF;

  -- Get current season
  v_season := TO_CHAR(NOW(), 'YYYY-MM');

  -- Get ELO ratings
  SELECT rank INTO v_abandoner_stats
  FROM minesweeper_player_stats
  WHERE student_id = v_student_id AND season = v_season;

  SELECT rank INTO v_opponent_stats
  FROM minesweeper_player_stats
  WHERE student_id = v_opponent_id AND season = v_season;

  -- Default ELO
  IF v_abandoner_stats.rank IS NULL THEN
    v_abandoner_stats := ROW(1500);
  END IF;
  IF v_opponent_stats.rank IS NULL THEN
    v_opponent_stats := ROW(1500);
  END IF;

  -- Calculate ELO change (opponent wins, abandoner loses)
  IF v_match.match_type = 'ranked' THEN
    v_elo_change := calculate_elo_change(
      v_opponent_stats.rank,
      v_abandoner_stats.rank
    );
  ELSE
    v_elo_change := 0;
  END IF;

  -- Small reward for opponent (half of normal quick match reward)
  v_opponent_reward := CASE v_match.difficulty
    WHEN 'beginner' THEN 10
    WHEN 'intermediate' THEN 25
    WHEN 'expert' THEN 50
    ELSE 10
  END;

  -- Update match record
  UPDATE minesweeper_multiplayer_matches
  SET
    status = 'abandoned',
    winner_id = v_opponent_id,
    completed_at = NOW(),
    winner_reward = v_opponent_reward,
    loser_reward = 0,
    elo_change = v_elo_change
  WHERE id = p_match_id;

  -- Award gidouilles to opponent
  INSERT INTO gidouilles_history (
    student_id,
    amount,
    reason,
    description
  ) VALUES (
    v_opponent_id,
    v_opponent_reward,
    'minesweeper_multiplayer_opponent_quit',
    FORMAT('Victoire par abandon (%s)', v_match.difficulty)
  );

  -- Update opponent stats (win by forfeit)
  INSERT INTO minesweeper_player_stats (
    student_id,
    season,
    games_played,
    games_won,
    rank,
    win_streak
  ) VALUES (
    v_opponent_id,
    v_season,
    1,
    1,
    v_opponent_stats.rank + v_elo_change,
    1
  )
  ON CONFLICT (student_id, season) DO UPDATE
  SET
    games_played = minesweeper_player_stats.games_played + 1,
    games_won = minesweeper_player_stats.games_won + 1,
    rank = EXCLUDED.rank, -- Use pre-calculated rank directly (already includes ELO change)
    win_streak = minesweeper_player_stats.win_streak + 1,
    best_win_streak = GREATEST(
      minesweeper_player_stats.best_win_streak,
      minesweeper_player_stats.win_streak + 1
    ),
    updated_at = NOW();

  -- Update abandoner stats (loss by forfeit)
  INSERT INTO minesweeper_player_stats (
    student_id,
    season,
    games_played,
    games_won,
    rank,
    win_streak
  ) VALUES (
    v_student_id,
    v_season,
    1,
    0,
    GREATEST(0, v_abandoner_stats.rank - v_elo_change),
    0
  )
  ON CONFLICT (student_id, season) DO UPDATE
  SET
    games_played = minesweeper_player_stats.games_played + 1,
    rank = EXCLUDED.rank, -- Use pre-calculated rank directly (already includes ELO loss and floor at 0)
    win_streak = 0,
    updated_at = NOW();

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'abandoned_by', v_student_id,
    'winner_id', v_opponent_id,
    'reason', p_reason,
    'elo_change', v_elo_change
  );
END;
$$;


ALTER FUNCTION "public"."abandon_multiplayer_match"("p_match_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."abandon_multiplayer_match"("p_match_id" "uuid", "p_reason" "text") IS 'Handle match abandonment with automatic win for opponent';



CREATE OR REPLACE FUNCTION "public"."abandon_tournament_game"("p_game_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_game RECORD;
BEGIN
  v_student_id := auth.uid();

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Must be authenticated';
  END IF;

  SELECT * INTO v_game
  FROM public.minesweeper_tournament_games
  WHERE id = p_game_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found';
  END IF;

  IF v_game.student_id != v_student_id THEN
    RAISE EXCEPTION 'This game does not belong to you';
  END IF;

  IF v_game.status != 'in_progress' THEN
    RAISE EXCEPTION 'Game is not in progress';
  END IF;

  UPDATE public.minesweeper_tournament_games
  SET
    status = 'abandoned',
    completed_at = NOW()
  WHERE id = p_game_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."abandon_tournament_game"("p_game_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."abandon_tournament_game"("p_game_id" "uuid") IS 'Allows a student to abandon an in-progress tournament game.';



CREATE OR REPLACE FUNCTION "public"."accept_proposal_atomic"("p_proposal_id" "uuid", "p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_proposal marketplace_proposals;
  v_listing marketplace_listings;
  v_trade_id UUID;
  v_current_offer JSONB;
  v_execute_result JSONB;
BEGIN
  SELECT * INTO v_proposal
  FROM marketplace_proposals
  WHERE id = p_proposal_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Proposition introuvable');
  END IF;

  IF v_proposal.status != 'pending' THEN
    RETURN json_build_object('success', false, 'error', 'Cette proposition a déjà été traitée');
  END IF;

  SELECT * INTO v_listing
  FROM marketplace_listings
  WHERE id = v_proposal.listing_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND OR v_listing.status != 'active' THEN
    RETURN json_build_object('success', false, 'error', 'Cette annonce n''est plus disponible');
  END IF;

  IF v_listing.creator_id != p_user_id THEN
    RETURN json_build_object('success', false, 'error', 'Vous n''êtes pas autorisé à accepter cette proposition');
  END IF;

  v_current_offer := jsonb_build_object(
    'from_initiator', jsonb_build_object(
      'cards', COALESCE(to_jsonb(v_listing.offered_card_ids), '[]'::jsonb),
      'gidouilles', COALESCE(v_listing.offered_gidouilles, 0)
    ),
    'from_partner', jsonb_build_object(
      'cards', COALESCE(to_jsonb(v_proposal.offered_card_ids), '[]'::jsonb),
      'gidouilles', COALESCE(v_proposal.offered_gidouilles, 0)
    )
  );

  v_trade_id := gen_random_uuid();
  INSERT INTO marketplace_trades (
    id, initiator_id, partner_id, trade_type, status,
    listing_id, proposal_id, current_offer, created_at, updated_at
  ) VALUES (
    v_trade_id, v_listing.creator_id, v_proposal.proposer_id,
    'marketplace', 'negotiating',
    v_listing.id, v_proposal.id,
    v_current_offer, NOW(), NOW()
  );

  v_execute_result := execute_trade(v_trade_id);

  IF NOT (v_execute_result->>'success')::boolean THEN
    DELETE FROM marketplace_trades WHERE id = v_trade_id;
    RETURN json_build_object(
      'success', false,
      'error', COALESCE(v_execute_result->>'error', 'Erreur lors de l''exécution de l''échange')
    );
  END IF;

  DECLARE
    v_other_proposal RECORD;
  BEGIN
    FOR v_other_proposal IN
      SELECT id FROM marketplace_proposals
      WHERE listing_id = v_listing.id
        AND id != p_proposal_id
        AND status = 'pending'
    LOOP
      UPDATE marketplace_proposals
      SET status = 'rejected', responded_at = NOW(),
          response_message = 'Autre proposition acceptée'
      WHERE id = v_other_proposal.id;

      DELETE FROM marketplace_locked_cards
      WHERE locked_entity_id = v_other_proposal.id;
    END LOOP;
  END;

  DELETE FROM marketplace_locked_cards
  WHERE locked_entity_id = v_listing.id;

  RETURN json_build_object(
    'success', true,
    'message', 'Proposition acceptée et échange effectué',
    'trade_id', v_trade_id
  );

EXCEPTION
  WHEN lock_not_available THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Une autre transaction est en cours sur cette annonce'
    );
  WHEN OTHERS THEN
    RAISE LOG 'Error in accept_proposal_atomic: %', SQLERRM;
    RETURN json_build_object(
      'success', false,
      'error', 'Une erreur est survenue: ' || SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."accept_proposal_atomic"("p_proposal_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_buddy_xp"("p_student_id" "uuid", "p_xp" integer, "p_is_milestone" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_buddy public.student_buddies%ROWTYPE;
    v_xp_to_add INTEGER;
    v_new_xp INTEGER;
    v_new_level INTEGER;
    v_old_level INTEGER;
    v_daily_cap INTEGER := 100;
    v_daily_cap_reached BOOLEAN := false;
    v_today DATE := CURRENT_DATE;
    -- XP thresholds for levels 1-20
    v_xp_table INTEGER[] := ARRAY[0, 30, 70, 120, 180, 260, 360, 480, 620, 780, 960, 1160, 1400, 1680, 2000, 2400, 2900, 3500, 4200, 5000];
BEGIN
    -- Lock the row to prevent concurrent XP updates
    SELECT * INTO v_buddy
    FROM public.student_buddies
    WHERE student_id = p_student_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'error', 'buddy_not_found',
            'xp_gained', 0
        );
    END IF;

    -- Reset daily XP counter if new day
    IF v_buddy.last_xp_date IS NULL OR v_buddy.last_xp_date < v_today THEN
        v_buddy.xp_earned_today := 0;
    END IF;

    -- Calculate XP to add (enforce daily cap unless milestone)
    IF p_is_milestone THEN
        v_xp_to_add := p_xp;
    ELSE
        IF v_buddy.xp_earned_today >= v_daily_cap THEN
            v_xp_to_add := 0;
            v_daily_cap_reached := true;
        ELSIF v_buddy.xp_earned_today + p_xp > v_daily_cap THEN
            v_xp_to_add := v_daily_cap - v_buddy.xp_earned_today;
            v_daily_cap_reached := true;
        ELSE
            v_xp_to_add := p_xp;
        END IF;
    END IF;

    -- Skip update if nothing to add
    IF v_xp_to_add <= 0 THEN
        RETURN jsonb_build_object(
            'xp_gained', 0,
            'new_xp', v_buddy.xp,
            'new_level', v_buddy.level,
            'leveled_up', false,
            'daily_cap_reached', v_daily_cap_reached
        );
    END IF;

    -- Calculate new XP and level
    v_new_xp := v_buddy.xp + v_xp_to_add;
    v_old_level := v_buddy.level;
    v_new_level := 1;

    FOR i IN REVERSE 20..2 LOOP
        IF v_new_xp >= v_xp_table[i] THEN
            v_new_level := i;
            EXIT;
        END IF;
    END LOOP;

    -- Update the buddy
    UPDATE public.student_buddies
    SET
        xp = v_new_xp,
        level = v_new_level,
        xp_earned_today = CASE
            WHEN p_is_milestone THEN xp_earned_today  -- Milestones don't count toward cap
            ELSE v_buddy.xp_earned_today + v_xp_to_add
        END,
        last_xp_date = v_today
    WHERE student_id = p_student_id;

    RETURN jsonb_build_object(
        'xp_gained', v_xp_to_add,
        'new_xp', v_new_xp,
        'new_level', v_new_level,
        'leveled_up', v_new_level > v_old_level,
        'daily_cap_reached', v_daily_cap_reached
    );
END;
$$;


ALTER FUNCTION "public"."add_buddy_xp"("p_student_id" "uuid", "p_xp" integer, "p_is_milestone" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_student_gidouilles"("p_student_id" "uuid", "p_amount" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_is_teacher BOOLEAN;
  v_student_in_class BOOLEAN;
  v_current_gidouilles INTEGER;
  v_new_gidouilles INTEGER;
BEGIN
  -- Get the current user's ID (the teacher calling this function)
  v_teacher_id := auth.uid();

  -- Check if caller is a teacher or admin
  v_is_teacher := is_teacher_or_admin();

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Unauthorized: Only teachers can modify gidouilles';
  END IF;

  -- Check if student is in one of the teacher's classes
  SELECT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
  ) INTO v_student_in_class;

  IF NOT v_student_in_class THEN
    RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
  END IF;

  -- Get current gidouilles
  SELECT gidouilles INTO v_current_gidouilles
  FROM profiles
  WHERE id = p_student_id;

  -- Calculate new balance
  v_new_gidouilles := v_current_gidouilles + p_amount;

  -- Ensure balance doesn't go negative
  IF v_new_gidouilles < 0 THEN
    RAISE EXCEPTION 'Insufficient gidouilles: Cannot go below 0 (current: %, attempted change: %)', v_current_gidouilles, p_amount;
  END IF;

  -- Update gidouilles
  UPDATE profiles
  SET
    gidouilles = v_new_gidouilles,
    updated_at = NOW()
  WHERE id = p_student_id;

  -- Return new balance
  RETURN v_new_gidouilles;
END;
$$;


ALTER FUNCTION "public"."add_student_gidouilles"("p_student_id" "uuid", "p_amount" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_student_gidouilles"("p_student_id" "uuid", "p_amount" integer) IS 'Adds or subtracts gidouilles to/from a student balance. Only teachers who have the student in their classes can call this. Returns the new gidouilles balance. Ensures balance never goes negative.';



CREATE OR REPLACE FUNCTION "public"."add_student_to_class_chat"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  class_conversation_id UUID;
BEGIN
  -- Find the class chat room
  SELECT id INTO class_conversation_id
  FROM conversations
  WHERE class_id = NEW.class_id
  AND is_group = true
  LIMIT 1;

  -- Add student to the class chat (if it exists)
  IF class_conversation_id IS NOT NULL THEN
    INSERT INTO conversation_participants (
      conversation_id,
      user_id,
      joined_at
    ) VALUES (
      class_conversation_id,
      NEW.student_id,
      NOW()
    )
    ON CONFLICT (conversation_id, user_id) DO NOTHING; -- Avoid duplicates
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."add_student_to_class_chat"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_student_to_class_chat"() IS 'Auto-adds students to class chat when they join a class';



CREATE OR REPLACE FUNCTION "public"."add_warning"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_type" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total INTEGER;
    v_counts JSON;
BEGIN
    -- Auth check: caller must be teacher of this class
    IF NOT is_class_teacher(p_class_id) THEN
        RETURN json_build_object('success', false, 'error', 'Unauthorized: you do not teach this class');
    END IF;

    -- Validate warning type
    IF p_warning_type NOT IN ('C', 'M', 'R', 'T') THEN
        RETURN json_build_object('success', false, 'error', 'Invalid warning type: ' || p_warning_type);
    END IF;

    -- Serialize concurrent additions for the same student+class+period
    PERFORM pg_advisory_xact_lock(hashtext(p_student_id::text || p_class_id::text || p_academic_period_id::text));

    -- Count current active warnings
    SELECT COUNT(*) INTO v_total
    FROM student_warnings
    WHERE student_id = p_student_id
      AND class_id = p_class_id
      AND academic_period_id = p_academic_period_id
      AND deleted_at IS NULL;

    -- Enforce max 20
    IF v_total >= 20 THEN
        RETURN json_build_object('success', false, 'error', 'Student already has 20 warnings');
    END IF;

    -- Insert warning
    INSERT INTO student_warnings (student_id, class_id, academic_period_id, warning_type, created_by)
    VALUES (p_student_id, p_class_id, p_academic_period_id, p_warning_type, auth.uid());

    -- Return updated counts
    SELECT json_build_object(
        'C', COALESCE(SUM(CASE WHEN warning_type = 'C' THEN 1 ELSE 0 END), 0),
        'M', COALESCE(SUM(CASE WHEN warning_type = 'M' THEN 1 ELSE 0 END), 0),
        'R', COALESCE(SUM(CASE WHEN warning_type = 'R' THEN 1 ELSE 0 END), 0),
        'T', COALESCE(SUM(CASE WHEN warning_type = 'T' THEN 1 ELSE 0 END), 0)
    ) INTO v_counts
    FROM student_warnings
    WHERE student_id = p_student_id
      AND class_id = p_class_id
      AND academic_period_id = p_academic_period_id
      AND deleted_at IS NULL;

    RETURN json_build_object('success', true, 'counts', v_counts);
END;
$$;


ALTER FUNCTION "public"."add_warning"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_warning"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_type" "text") IS 'Atomically add a single warning and return updated counts for the student';



CREATE OR REPLACE FUNCTION "public"."add_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total INTEGER;
    v_to_add INTEGER;
    v_type TEXT;
    v_counts JSON;
BEGIN
    -- Auth check: caller must be teacher of this class
    IF NOT is_class_teacher(p_class_id) THEN
        RETURN json_build_object('success', false, 'error', 'Unauthorized: you do not teach this class');
    END IF;

    -- Validate input array
    v_to_add := COALESCE(array_length(p_warning_types, 1), 0);
    IF v_to_add = 0 THEN
        RETURN json_build_object('success', false, 'error', 'No warning types provided');
    END IF;

    IF v_to_add > 20 THEN
        RETURN json_build_object('success', false, 'error', 'Cannot add more than 20 warnings at once');
    END IF;

    -- Validate each warning type
    FOREACH v_type IN ARRAY p_warning_types LOOP
        IF v_type NOT IN ('C', 'M', 'R', 'T') THEN
            RETURN json_build_object('success', false, 'error', 'Invalid warning type: ' || v_type);
        END IF;
    END LOOP;

    -- Serialize concurrent additions for the same student+class+period
    PERFORM pg_advisory_xact_lock(hashtext(p_student_id::text || p_class_id::text || p_academic_period_id::text));

    -- Count current active warnings
    SELECT COUNT(*) INTO v_total
    FROM student_warnings
    WHERE student_id = p_student_id
      AND class_id = p_class_id
      AND academic_period_id = p_academic_period_id
      AND deleted_at IS NULL;

    -- Enforce max 20
    IF v_total + v_to_add > 20 THEN
        RETURN json_build_object(
            'success', false,
            'error', format('Would exceed 20 warnings (current: %s, adding: %s)', v_total, v_to_add)
        );
    END IF;

    -- Insert all warnings in one statement
    INSERT INTO student_warnings (student_id, class_id, academic_period_id, warning_type, created_by)
    SELECT p_student_id, p_class_id, p_academic_period_id, unnest(p_warning_types), auth.uid();

    -- Return updated counts
    SELECT json_build_object(
        'C', COALESCE(SUM(CASE WHEN warning_type = 'C' THEN 1 ELSE 0 END), 0),
        'M', COALESCE(SUM(CASE WHEN warning_type = 'M' THEN 1 ELSE 0 END), 0),
        'R', COALESCE(SUM(CASE WHEN warning_type = 'R' THEN 1 ELSE 0 END), 0),
        'T', COALESCE(SUM(CASE WHEN warning_type = 'T' THEN 1 ELSE 0 END), 0)
    ) INTO v_counts
    FROM student_warnings
    WHERE student_id = p_student_id
      AND class_id = p_class_id
      AND academic_period_id = p_academic_period_id
      AND deleted_at IS NULL;

    RETURN json_build_object('success', true, 'counts', v_counts, 'added', v_to_add);
END;
$$;


ALTER FUNCTION "public"."add_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[]) IS 'Atomically add multiple warnings for the same student and return updated counts';



CREATE OR REPLACE FUNCTION "public"."app_is_anti_fraud_enabled"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_value TEXT;
BEGIN
    SELECT value INTO v_value
    FROM public.app_config
    WHERE key = 'anti_fraud_enabled'
    LIMIT 1;

    -- Case-insensitive : 'true' / 'TRUE' / 'True' acceptés.
    RETURN lower(coalesce(v_value, 'false')) = 'true';
EXCEPTION
    WHEN OTHERS THEN
        -- Fail-safe : si problème de lecture, on considère désactivé.
        RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."app_is_anti_fraud_enabled"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."app_is_anti_fraud_enabled"() IS 'Lit app_config.anti_fraud_enabled. Retourne true si value=''true'' (case-insensitive). Fail-safe : false si table ou row absente.';



CREATE OR REPLACE FUNCTION "public"."approve_vip_card"("p_student_id" "uuid", "p_instance_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_vip_cards JSONB;
  v_card_data JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_now_str TEXT;
BEGIN
  v_teacher_id := auth.uid();

  IF NOT is_teacher_or_admin() THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Only teachers can approve VIP cards'
    );
  END IF;

  -- Verify student is in one of the teacher's ACTIVE classes
  IF NOT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
      AND cm.status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Student is not in your active classes'
    );
  END IF;

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  v_card_data := v_vip_cards->p_instance_id;

  IF v_card_data IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card instance not found: ' || p_instance_id
    );
  END IF;

  IF v_card_data->>'usedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card has already been used'
    );
  END IF;

  IF v_card_data->>'activationApprovedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card has already been approved'
    );
  END IF;

  v_card_id := v_card_data->>'cardId';

  SELECT id, name INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  IF v_template IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card template not found: ' || v_card_id
    );
  END IF;

  v_now_str := to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  v_vip_cards := jsonb_set(
    v_vip_cards,
    ARRAY[p_instance_id],
    v_card_data || jsonb_build_object(
      'activationApprovedAt', v_now_str,
      'activationApprovedBy', v_teacher_id::TEXT
    )
  );

  INSERT INTO public.vip_cards_activity (
    student_id, card_instance_id, card_template_id, action, metadata
  ) VALUES (
    p_student_id, p_instance_id, v_card_id, 'approved',
    jsonb_build_object('approved_by', v_teacher_id::TEXT, 'approved_at', v_now_str)
  );

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'cardName', v_template.name,
    'instanceId', p_instance_id,
    'cardId', v_card_id
  );
END;
$$;


ALTER FUNCTION "public"."approve_vip_card"("p_student_id" "uuid", "p_instance_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_vip_card"("p_student_id" "uuid", "p_instance_id" "text") IS 'Teacher-only RPC to approve a student VIP card activation request.
Sets activationApprovedAt/By on the JSONB instance. Does NOT consume the card.
Logs action=approved to vip_cards_activity.';



