CREATE OR REPLACE FUNCTION "public"."audit_trigger_func"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_old_values JSONB;
    v_new_values JSONB;
    v_record_id UUID;
BEGIN
    -- Get record ID (handle both NEW and OLD)
    v_record_id := COALESCE(
        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.id END,
        CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.id END
    );

    -- Prepare old/new values based on operation
    IF TG_OP = 'DELETE' THEN
        v_old_values := to_jsonb(OLD);
        v_new_values := NULL;
    ELSIF TG_OP = 'INSERT' THEN
        v_old_values := NULL;
        v_new_values := to_jsonb(NEW);
    ELSIF TG_OP = 'UPDATE' THEN
        -- Only store changed fields for UPDATE to reduce storage
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
    END IF;

    -- Insert audit log entry
    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_values,
        new_values
    ) VALUES (
        auth.uid(),
        TG_OP,
        TG_TABLE_NAME,
        v_record_id,
        v_old_values,
        v_new_values
    );

    -- Return appropriate value
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


ALTER FUNCTION "public"."audit_trigger_func"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_trigger_func"() IS 'Generic audit trigger function for RGPD compliance - logs all changes to sensitive tables';



CREATE OR REPLACE FUNCTION "public"."auto_activate_scheduled_tournaments"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_activated_count INTEGER;
BEGIN
  UPDATE public.minesweeper_tournaments
  SET status = 'active'
  WHERE status = 'scheduled'
    AND start_date <= NOW()
    AND end_date > NOW();

  GET DIAGNOSTICS v_activated_count = ROW_COUNT;

  RETURN v_activated_count;
END;
$$;


