CREATE OR REPLACE FUNCTION "public"."auto_expire_listings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_expired_count INTEGER;
    v_listing RECORD;
BEGIN
    -- Update expired listings
    UPDATE public.marketplace_listings
    SET
        status = 'expired',
        updated_at = NOW()
    WHERE expires_at < NOW()
    AND status = 'active';

    GET DIAGNOSTICS v_expired_count = ROW_COUNT;

    -- Unlock cards for expired listings
    FOR v_listing IN
        SELECT id FROM public.marketplace_listings
        WHERE status = 'expired'
        AND updated_at >= NOW() - INTERVAL '1 minute'
    LOOP
        PERFORM public.unlock_cards(v_listing.id);
    END LOOP;

    -- Reject pending proposals for expired listings
    UPDATE public.marketplace_proposals
    SET
        status = 'rejected',
        responded_at = NOW(),
        response_message = 'Listing expired'
    WHERE listing_id IN (
        SELECT id FROM public.marketplace_listings
        WHERE status = 'expired'
        AND updated_at >= NOW() - INTERVAL '1 minute'
    )
    AND status = 'pending';

    RETURN v_expired_count;
END;
$$;


ALTER FUNCTION "public"."auto_expire_listings"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_expire_listings"() IS 'Automatically expire old listings and cleanup locks';



CREATE OR REPLACE FUNCTION "public"."auto_log_template_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM log_template_action(NEW.id, 'created', NEW.created_by);
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM log_template_action(
      NEW.id,
      'updated',
      NEW.created_by,
      jsonb_build_object(
        'old', row_to_json(OLD),
        'new', row_to_json(NEW)
      )
    );
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM log_template_action(OLD.id, 'deleted', OLD.created_by);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."auto_log_template_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_achievement_manual"("p_teacher_id" "uuid", "p_student_id" "uuid", "p_achievement_id" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_achievement RECORD;
  v_is_teacher BOOLEAN;
BEGIN
  -- Verify teacher has access to this student
  SELECT EXISTS (
    SELECT 1 FROM class_members cm
    JOIN classes c ON cm.class_id = c.id
    WHERE cm.student_id = p_student_id
    AND c.teacher_id = p_teacher_id
  ) INTO v_is_teacher;

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Teacher does not have access to this student';
  END IF;

  -- Get achievement
  SELECT * INTO v_achievement
  FROM achievements
  WHERE id = p_achievement_id
  AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Achievement not found';
  END IF;

  -- Check if achievement allows manual awarding
  IF v_achievement.unlock_type NOT IN ('manual', 'event_based') THEN
    RAISE EXCEPTION 'This achievement cannot be manually awarded';
  END IF;

  -- Award the achievement
  INSERT INTO student_achievements (
    student_id,
    achievement_id,
    unlocked_by,
    unlock_reason,
    points_awarded,
    gidouilles_awarded
  )
  VALUES (
    p_student_id,
    p_achievement_id,
    p_teacher_id,
    COALESCE(p_reason, 'Manually awarded by teacher'),
    COALESCE((v_achievement.metadata->>'points')::INTEGER, 0),
    COALESCE((v_achievement.metadata->>'gidouilles_reward')::INTEGER, 0)
  )
  ON CONFLICT DO NOTHING;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."award_achievement_manual"("p_teacher_id" "uuid", "p_student_id" "uuid", "p_achievement_id" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_achievement_manual"("p_teacher_id" "uuid", "p_student_id" "uuid", "p_achievement_id" "text", "p_reason" "text") IS 'Allow teachers to manually award achievements to their students.';



CREATE OR REPLACE FUNCTION "public"."award_gidouilles_on_victory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  player_id UUID;
  gidouilles_to_award INTEGER;
BEGIN
  -- Only process completed combats with victory
  IF NEW.status = 'completed' AND NEW.outcome = 'victory' THEN
    -- Award gidouilles to all participants
    -- XP to gidouilles: 10:1 ratio + 5 bonus for victory
    gidouilles_to_award := (NEW.xp_gained / 10) + 5;

    -- Award to organizer
    UPDATE profiles
    SET gidouilles = gidouilles + gidouilles_to_award
    WHERE id = NEW.organizer_id;

    -- Award to all ready players
    FOREACH player_id IN ARRAY NEW.ready_player_ids
    LOOP
      UPDATE profiles
      SET gidouilles = gidouilles + gidouilles_to_award
      WHERE id = player_id;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."award_gidouilles_on_victory"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_gidouilles_on_victory"() IS 'Awards gidouilles to combat participants on victory';



CREATE OR REPLACE FUNCTION "public"."award_random_vip_card"("p_student_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_is_teacher BOOLEAN;
  v_student_in_class BOOLEAN;
  v_current_gidouilles INTEGER;
  v_new_gidouilles INTEGER;
  v_card_id TEXT;
  v_instance_id UUID;
  v_new_card_instance JSONB;
  v_earned_at TIMESTAMPTZ;
  v_template RECORD;
BEGIN
  -- Get the current user's ID (the teacher calling this function)
  v_teacher_id := auth.uid();

  -- Check if caller is a teacher or admin
  v_is_teacher := is_teacher_or_admin();

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Unauthorized: Only teachers can award VIP cards';
  END IF;

  -- Check if student is in one of the teacher's classes
  SELECT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
  ) INTO v_student_in_class;

  IF NOT v_student_in_class THEN
    RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
  END IF;

  -- Get current gidouilles count
  SELECT gidouilles INTO v_current_gidouilles
  FROM profiles
  WHERE id = p_student_id;

  -- Check if student has enough gidouilles (at least 3)
  IF v_current_gidouilles < 3 THEN
    RAISE EXCEPTION 'Insufficient gidouilles: Student needs at least 3 gidouilles (current: %)', v_current_gidouilles;
  END IF;

  -- Calculate new gidouilles value
  v_new_gidouilles := v_current_gidouilles - 3;

  -- Select random VIP card from enabled templates
  SELECT id, rarity, uses_total INTO v_template
  FROM vip_card_templates
  WHERE is_enabled = TRUE
  ORDER BY random()
  LIMIT 1;

  IF v_template IS NULL THEN
    RAISE EXCEPTION 'No VIP cards available';
  END IF;

  v_card_id := v_template.id;

  -- Generate unique instance ID
  v_instance_id := gen_random_uuid();

  -- Capture earned timestamp
  v_earned_at := now();

  -- Create new card instance
  v_new_card_instance := jsonb_build_object(
    'cardId', v_card_id,
    'earnedAt', v_earned_at,
    'usedAt', null,
    'acquiredFrom', 'teacher_draw',
    'usesRemaining', v_template.uses_total
  );

  -- Update student profile: deduct gidouilles and add VIP card
  UPDATE profiles
  SET
    gidouilles = v_new_gidouilles,
    vip_cards = COALESCE(vip_cards, '{}'::jsonb) || jsonb_build_object(v_instance_id::TEXT, v_new_card_instance),
    updated_at = NOW()
  WHERE id = p_student_id;

  -- Log activity
  INSERT INTO vip_cards_activity (
    student_id,
    card_instance_id,
    card_template_id,
    action,
    metadata
  ) VALUES (
    p_student_id,
    v_instance_id::TEXT,
    v_card_id,
    'gained',
    jsonb_build_object(
      'acquired_from', 'teacher_draw',
      'awarded_by', v_teacher_id,
      'gidouilles_cost', 3,
      'old_balance', v_current_gidouilles,
      'new_balance', v_new_gidouilles,
      'rarity', v_template.rarity
    )
  );

  -- Return complete card information as JSONB
  RETURN jsonb_build_object(
    'cardId', v_card_id,
    'instanceId', v_instance_id,
    'earnedAt', v_earned_at
  );
END;
$$;


ALTER FUNCTION "public"."award_random_vip_card"("p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_random_vip_card"("p_student_id" "uuid") IS 'Awards a random VIP card to a student (costs 3 gidouilles). Logs activity with acquired_from=teacher_draw.';



CREATE OR REPLACE FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_selected_card_id TEXT;
  v_instance_id UUID;
  v_vip_cards JSONB;
  v_now TIMESTAMPTZ := NOW();
  v_new_instance JSONB;
  v_template RECORD;
BEGIN
  -- ========================================================================
  -- CARD SELECTION
  -- ========================================================================
  -- If no card_id specified, draw random card with weighted rarity probabilities

  IF p_card_id IS NULL THEN
    -- Get active config probabilities from vip_card_config
    WITH config AS (
      SELECT common_probability, rare_probability, epic_probability, legendary_probability
      FROM vip_card_config
      WHERE is_active = TRUE
      LIMIT 1
    ),
    rarity_selection AS (
      SELECT
        CASE
          WHEN random() * 100 < (SELECT common_probability FROM config) THEN 'common'
          WHEN random() * 100 < (SELECT common_probability + rare_probability FROM config) THEN 'rare'
          WHEN random() * 100 < (SELECT common_probability + rare_probability + epic_probability FROM config) THEN 'epic'
          ELSE 'legendary'
        END AS selected_rarity
    )
    SELECT t.id INTO v_selected_card_id
    FROM vip_card_templates t, rarity_selection r
    WHERE t.is_enabled = TRUE
      AND t.rarity = r.selected_rarity
    ORDER BY random()
    LIMIT 1;

    -- Fallback: if no card found for selected rarity, pick any enabled card
    IF v_selected_card_id IS NULL THEN
      SELECT id INTO v_selected_card_id
      FROM vip_card_templates
      WHERE is_enabled = TRUE
      ORDER BY random()
      LIMIT 1;
    END IF;
  ELSE
    v_selected_card_id := p_card_id;
  END IF;

  IF v_selected_card_id IS NULL THEN
    RAISE EXCEPTION 'No VIP card available';
  END IF;

  -- ========================================================================
  -- GET TEMPLATE INFO
  -- ========================================================================

  SELECT uses_total INTO v_template
  FROM vip_card_templates
  WHERE id = v_selected_card_id;

  -- ========================================================================
  -- GET AND LOCK STUDENT'S VIP CARDS
  -- ========================================================================
  -- FOR UPDATE prevents race conditions when multiple awards happen simultaneously

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  -- Initialize as empty object if null
  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- ========================================================================
  -- CREATE NEW CARD INSTANCE
  -- ========================================================================
  -- Structure: {"<uuid>": {cardId, earnedAt, usedAt, acquiredFrom, usesRemaining}}

  v_instance_id := gen_random_uuid();
  v_new_instance := jsonb_build_object(
    'cardId', v_selected_card_id,
    'earnedAt', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'usedAt', NULL,
    'acquiredFrom', 'draw',
    'usesRemaining', v_template.uses_total  -- NULL for single-use, integer for multi-use
  );

  -- Add new instance to collection
  v_vip_cards := v_vip_cards || jsonb_build_object(v_instance_id::TEXT, v_new_instance);

  -- ========================================================================
  -- UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET
    vip_cards = v_vip_cards,
    updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- LOG ACTIVITY (NEW - was previously handled by trigger)
  -- ========================================================================
  -- We now explicitly log 'gained' actions from RPC functions to ensure
  -- rich metadata and avoid duplicate inserts with the trigger.

  INSERT INTO vip_cards_activity (
    student_id,
    card_instance_id,
    card_template_id,
    action,
    metadata
  ) VALUES (
    p_student_id,
    v_instance_id::TEXT,
    v_selected_card_id,
    'gained',
    jsonb_build_object(
      'acquired_from', 'draw',
      'rarity', (SELECT rarity FROM vip_card_templates WHERE id = v_selected_card_id)
    )
  );

  RETURN v_selected_card_id;
END;
$$;


ALTER FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text") IS 'Awards a VIP card to a student via random draw (no cost).
Logs the "gained" action to vip_cards_activity with draw metadata.
If p_card_id is NULL, selects a random card based on rarity probabilities.';



CREATE OR REPLACE FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'draw'::"text", "p_extra_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_selected_card_id TEXT;
  v_instance_id UUID;
  v_vip_cards JSONB;
  v_now TIMESTAMPTZ := NOW();
  v_new_instance JSONB;
  v_template RECORD;
  v_audit_metadata JSONB;
BEGIN
  -- ========================================================================
  -- CARD SELECTION
  -- ========================================================================

  IF p_card_id IS NULL THEN
    WITH config AS (
      SELECT common_probability, rare_probability, epic_probability, legendary_probability
      FROM vip_card_config
      WHERE is_active = TRUE
      LIMIT 1
    ),
    rarity_selection AS (
      SELECT
        CASE
          WHEN random() * 100 < (SELECT common_probability FROM config) THEN 'common'
          WHEN random() * 100 < (SELECT common_probability + rare_probability FROM config) THEN 'rare'
          WHEN random() * 100 < (SELECT common_probability + rare_probability + epic_probability FROM config) THEN 'epic'
          ELSE 'legendary'
        END AS selected_rarity
    )
    SELECT t.id INTO v_selected_card_id
    FROM vip_card_templates t, rarity_selection r
    WHERE t.is_enabled = TRUE
      AND t.rarity = r.selected_rarity
    ORDER BY random()
    LIMIT 1;

    IF v_selected_card_id IS NULL THEN
      SELECT id INTO v_selected_card_id
      FROM vip_card_templates
      WHERE is_enabled = TRUE
      ORDER BY random()
      LIMIT 1;
    END IF;
  ELSE
    v_selected_card_id := p_card_id;
  END IF;

  IF v_selected_card_id IS NULL THEN
    RAISE EXCEPTION 'No VIP card available';
  END IF;

  -- ========================================================================
  -- GET TEMPLATE INFO
  -- ========================================================================

  SELECT uses_total INTO v_template
  FROM vip_card_templates
  WHERE id = v_selected_card_id;

  -- ========================================================================
  -- GET AND LOCK STUDENT'S VIP CARDS
  -- ========================================================================

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- ========================================================================
  -- CREATE NEW CARD INSTANCE
  -- ========================================================================

  v_instance_id := gen_random_uuid();
  v_new_instance := jsonb_build_object(
    'cardId', v_selected_card_id,
    'earnedAt', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'usedAt', NULL,
    'acquiredFrom', p_source,
    'usesRemaining', v_template.uses_total
  );

  v_vip_cards := v_vip_cards || jsonb_build_object(v_instance_id::TEXT, v_new_instance);

  -- ========================================================================
  -- UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET
    vip_cards = v_vip_cards,
    updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- LOG ACTIVITY
  -- ========================================================================
  -- Build audit metadata: base fields + optional caller-provided extra metadata
  v_audit_metadata := jsonb_build_object(
    'acquired_from', p_source,
    'rarity', (SELECT rarity FROM vip_card_templates WHERE id = v_selected_card_id)
  ) || COALESCE(p_extra_metadata, '{}'::JSONB);

  INSERT INTO vip_cards_activity (
    student_id,
    card_instance_id,
    card_template_id,
    action,
    metadata
  ) VALUES (
    p_student_id,
    v_instance_id::TEXT,
    v_selected_card_id,
    'gained',
    v_audit_metadata
  );

  RETURN v_selected_card_id;
END;
$$;


ALTER FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text", "p_source" "text", "p_extra_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_vip_card_no_cost"("p_student_id" "uuid", "p_card_id" "text", "p_source" "text", "p_extra_metadata" "jsonb") IS 'Awards a VIP card to a student (no cost).
p_source: "draw", "teacher_award", "exchange", "choose", etc.
p_extra_metadata: optional JSONB merged into the audit trail entry (e.g. exchange_id).
Logs the "gained" action to vip_cards_activity with source + extra metadata.';



CREATE OR REPLACE FUNCTION "public"."award_vip_cards_with_filters"("p_student_id" "uuid", "p_count" integer, "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Constants
  c_min_count CONSTANT INT := 1;
  c_max_count CONSTANT INT := 10;

  -- Authorization variables
  v_caller_id UUID;
  v_is_teacher BOOLEAN;
  v_student_in_class BOOLEAN;

  -- Filter variables (parsed from p_filters JSONB)
  v_force_rarity TEXT;
  v_min_rarity TEXT;
  v_exclude_card_ids TEXT[];
  v_only_cards_with_actions BOOLEAN;

  -- Rarity probabilities (for normal draw and minRarity enforcement)
  v_common_prob INTEGER;
  v_rare_prob INTEGER;
  v_epic_prob INTEGER;
  v_legendary_prob INTEGER;
  v_common_max INTEGER;
  v_rare_max INTEGER;
  v_epic_max INTEGER;

  -- Student profile variables
  v_vip_cards JSONB;

  -- Card drawing variables
  v_drawn_cards JSONB := '[]'::jsonb;
  v_card_id TEXT;
  v_instance_id UUID;
  v_earned_at TIMESTAMPTZ;
  v_new_card_instance JSONB;
  v_loop_counter INT;

  -- Rarity selection (for minRarity and normal draws)
  v_roll INTEGER;
  v_selected_rarity TEXT;

  -- Card details for return value
  v_card_name TEXT;
  v_card_rarity TEXT;

  -- Available cards count (for validation)
  v_available_cards_count INT;

BEGIN
  -- ========================================
  -- 1. VALIDATE INPUT PARAMETERS
  -- ========================================

  -- Validate count range
  IF p_count < c_min_count OR p_count > c_max_count THEN
    RAISE EXCEPTION 'Invalid count: Must be between % and % (received: %)',
      c_min_count, c_max_count, p_count;
  END IF;

  -- Validate student exists
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_student_id) THEN
    RAISE EXCEPTION 'Student not found: %', p_student_id;
  END IF;

  -- ========================================
  -- 2. AUTHORIZATION
  -- ========================================

  v_caller_id := auth.uid();
  v_is_teacher := is_teacher_or_admin();

  -- Only teachers can call this function
  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Unauthorized: Only teachers and admins can award VIP cards with filters';
  END IF;

  -- Verify student is in teacher's classes
  SELECT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_caller_id
  ) INTO v_student_in_class;

  IF NOT v_student_in_class THEN
    RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
  END IF;

  -- ========================================
  -- 3. PARSE FILTERS FROM JSONB
  -- ========================================

  -- Extract forceRarity filter (optional)
  v_force_rarity := p_filters->>'forceRarity';

  -- Validate forceRarity value if provided
  IF v_force_rarity IS NOT NULL AND v_force_rarity NOT IN ('common', 'rare', 'epic', 'legendary') THEN
    RAISE EXCEPTION 'Invalid forceRarity filter: Must be common, rare, epic, or legendary (received: %)', v_force_rarity;
  END IF;

  -- Extract minRarity filter (optional)
  v_min_rarity := p_filters->>'minRarity';

  -- Validate minRarity value if provided
  IF v_min_rarity IS NOT NULL AND v_min_rarity NOT IN ('common', 'rare', 'epic', 'legendary') THEN
    RAISE EXCEPTION 'Invalid minRarity filter: Must be common, rare, epic, or legendary (received: %)', v_min_rarity;
  END IF;

  -- Extract excludeCardIds filter (optional array)
  IF p_filters ? 'excludeCardIds' THEN
    SELECT ARRAY(
      SELECT jsonb_array_elements_text(p_filters->'excludeCardIds')
    ) INTO v_exclude_card_ids;
  ELSE
    v_exclude_card_ids := ARRAY[]::TEXT[];
  END IF;

  -- Extract onlyCardsWithActions filter (optional boolean)
  v_only_cards_with_actions := COALESCE((p_filters->>'onlyCardsWithActions')::boolean, FALSE);

  RAISE NOTICE 'Filters parsed: forceRarity=%, minRarity=%, excludeCardIds=%, onlyCardsWithActions=%',
    v_force_rarity, v_min_rarity, v_exclude_card_ids, v_only_cards_with_actions;

  -- ========================================
  -- 4. VALIDATE FILTERS COMPATIBILITY
  -- ========================================

  -- forceRarity and minRarity are mutually exclusive
  IF v_force_rarity IS NOT NULL AND v_min_rarity IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid filters: forceRarity and minRarity cannot be used together';
  END IF;

  -- Check if any cards match the filters
  SELECT COUNT(*) INTO v_available_cards_count
  FROM vip_card_templates
  WHERE is_enabled = TRUE
    AND (v_force_rarity IS NULL OR rarity = v_force_rarity)
    AND (v_exclude_card_ids IS NULL OR NOT (id = ANY(v_exclude_card_ids)))
    AND (NOT v_only_cards_with_actions OR action IS NOT NULL);

  IF v_available_cards_count = 0 THEN
    RAISE EXCEPTION 'No cards available matching filters: forceRarity=%, excludeCardIds=%, onlyCardsWithActions=%',
      v_force_rarity, v_exclude_card_ids, v_only_cards_with_actions;
  END IF;

  RAISE NOTICE 'Available cards matching filters: %', v_available_cards_count;

  -- ========================================
  -- 5. LOCK STUDENT PROFILE (PREVENT RACE CONDITIONS)
  -- ========================================

  -- Use SELECT FOR UPDATE to prevent concurrent modifications
  SELECT vip_cards
  INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  -- Initialize vip_cards if null
  v_vip_cards := COALESCE(v_vip_cards, '{}'::jsonb);

  -- ========================================
  -- 6. LOAD RARITY PROBABILITIES (FOR NON-FORCED DRAWS)
  -- ========================================

  -- Only load probabilities if not using forceRarity
  IF v_force_rarity IS NULL THEN
    -- Read active config from vip_card_config table
    SELECT
      common_probability,
      rare_probability,
      epic_probability,
      legendary_probability
    INTO
      v_common_prob, v_rare_prob, v_epic_prob, v_legendary_prob
    FROM vip_card_config
    WHERE is_active = TRUE
    LIMIT 1;

    -- Fallback to default probabilities if no active config found
    IF v_common_prob IS NULL THEN
      v_common_prob := 60;
      v_rare_prob := 25;
      v_epic_prob := 12;
      v_legendary_prob := 3;
      RAISE NOTICE 'No active config found, using default probabilities';
    END IF;

    -- Calculate cumulative probability ranges
    v_common_max := v_common_prob;                          -- 1-60
    v_rare_max := v_common_max + v_rare_prob;               -- 61-85
    v_epic_max := v_rare_max + v_epic_prob;                 -- 86-97
    -- legendary is anything above v_epic_max (98-100)

    RAISE NOTICE 'Using rarity probabilities: common=%, rare=%, epic=%, legendary=%',
      v_common_prob, v_rare_prob, v_epic_prob, v_legendary_prob;
  END IF;

  -- ========================================
  -- 7. DRAW CARDS WITH FILTERS
  -- ========================================

  FOR v_loop_counter IN 1..p_count LOOP

    -- ------------------------------------
    -- STEP 1: Determine Rarity for This Card
    -- ------------------------------------

    IF v_force_rarity IS NOT NULL THEN
      -- FILTER MODE: forceRarity
      -- All cards must be of the forced rarity
      v_selected_rarity := v_force_rarity;

      RAISE NOTICE 'Draw %: forced rarity=%', v_loop_counter, v_selected_rarity;

    ELSIF v_min_rarity IS NOT NULL AND v_loop_counter = 1 THEN
      -- FILTER MODE: minRarity (FIRST CARD ONLY)
      -- First card must be at least minRarity or higher
      -- Use weighted selection from eligible rarities only

      -- Map minRarity to eligible rarities (current and higher)
      -- Rarity hierarchy: common < rare < epic < legendary
      v_roll := floor(random() * 100 + 1)::int;

      IF v_min_rarity = 'common' THEN
        -- All rarities eligible (normal draw)
        IF v_roll <= v_common_max THEN
          v_selected_rarity := 'common';
        ELSIF v_roll <= v_rare_max THEN
          v_selected_rarity := 'rare';
        ELSIF v_roll <= v_epic_max THEN
          v_selected_rarity := 'epic';
        ELSE
          v_selected_rarity := 'legendary';
        END IF;

      ELSIF v_min_rarity = 'rare' THEN
        -- Only rare, epic, legendary eligible
        -- Recalculate probabilities: rare/(rare+epic+legendary), etc.
        DECLARE
          v_eligible_total INT;
          v_rare_cutoff INT;
          v_epic_cutoff INT;
        BEGIN
          v_eligible_total := v_rare_prob + v_epic_prob + v_legendary_prob;
          v_rare_cutoff := (v_rare_prob * 100 / v_eligible_total);
          v_epic_cutoff := v_rare_cutoff + (v_epic_prob * 100 / v_eligible_total);

          IF v_roll <= v_rare_cutoff THEN
            v_selected_rarity := 'rare';
          ELSIF v_roll <= v_epic_cutoff THEN
            v_selected_rarity := 'epic';
          ELSE
            v_selected_rarity := 'legendary';
          END IF;
        END;

      ELSIF v_min_rarity = 'epic' THEN
        -- Only epic, legendary eligible
        DECLARE
          v_eligible_total INT;
          v_epic_cutoff INT;
        BEGIN
          v_eligible_total := v_epic_prob + v_legendary_prob;
          v_epic_cutoff := (v_epic_prob * 100 / v_eligible_total);

          IF v_roll <= v_epic_cutoff THEN
            v_selected_rarity := 'epic';
          ELSE
            v_selected_rarity := 'legendary';
          END IF;
        END;

      ELSIF v_min_rarity = 'legendary' THEN
        -- Only legendary eligible
        v_selected_rarity := 'legendary';

      END IF;

      RAISE NOTICE 'Draw % (minRarity=%): rolled %, selected rarity=%',
        v_loop_counter, v_min_rarity, v_roll, v_selected_rarity;

    ELSE
      -- NORMAL MODE: Weighted rarity selection (no filters or subsequent minRarity cards)
      v_roll := floor(random() * 100 + 1)::int;

      IF v_roll <= v_common_max THEN
        v_selected_rarity := 'common';
      ELSIF v_roll <= v_rare_max THEN
        v_selected_rarity := 'rare';
      ELSIF v_roll <= v_epic_max THEN
        v_selected_rarity := 'epic';
      ELSE
        v_selected_rarity := 'legendary';
      END IF;

      RAISE NOTICE 'Draw %: rolled %, selected rarity=%', v_loop_counter, v_roll, v_selected_rarity;

    END IF;

    -- ------------------------------------
    -- STEP 2: Select Random Card from Filtered Pool
    -- ------------------------------------

    SELECT id, name, rarity INTO v_card_id, v_card_name, v_card_rarity
    FROM vip_card_templates
    WHERE is_enabled = TRUE
      AND rarity = v_selected_rarity
      AND (v_exclude_card_ids IS NULL OR NOT (id = ANY(v_exclude_card_ids)))
      AND (NOT v_only_cards_with_actions OR action IS NOT NULL)
    ORDER BY random()
    LIMIT 1;

    -- ------------------------------------
    -- STEP 3: Fallback if No Cards Match Filters
    -- ------------------------------------

    IF v_card_id IS NULL THEN
      RAISE NOTICE 'No enabled cards for rarity=% with filters, falling back to common', v_selected_rarity;

      -- Fallback to common rarity with same filters
      SELECT id, name, rarity INTO v_card_id, v_card_name, v_card_rarity
      FROM vip_card_templates
      WHERE rarity = 'common'
        AND is_enabled = TRUE
        AND (v_exclude_card_ids IS NULL OR NOT (id = ANY(v_exclude_card_ids)))
        AND (NOT v_only_cards_with_actions OR action IS NOT NULL)
      ORDER BY random()
      LIMIT 1;

      -- If still no cards, abort
      IF v_card_id IS NULL THEN
        RAISE EXCEPTION 'No enabled VIP cards available matching filters (checked % and common)', v_selected_rarity;
      END IF;
    END IF;

    RAISE NOTICE 'Drew card: % (name=%, rarity=%)', v_card_id, v_card_name, v_card_rarity;

    -- ------------------------------------
    -- STEP 4: Create Card Instance
    -- ------------------------------------

    -- Generate unique instance ID
    v_instance_id := gen_random_uuid();

    -- Capture earned timestamp
    v_earned_at := NOW();

    -- Create new card instance
    v_new_card_instance := jsonb_build_object(
      'cardId', v_card_id,
      'earnedAt', v_earned_at,
      'usedAt', null
    );

    -- Add to student's vip_cards JSONB
    v_vip_cards := v_vip_cards || jsonb_build_object(
      v_instance_id::text,
      v_new_card_instance
    );

    -- Add to results array with full card details
    v_drawn_cards := v_drawn_cards || jsonb_build_object(
      'cardId', v_card_id,
      'instanceId', v_instance_id,
      'name', v_card_name,
      'rarity', v_card_rarity,
      'earnedAt', v_earned_at
    );

  END LOOP;

  -- ========================================
  -- 8. UPDATE STUDENT PROFILE
  -- ========================================

  UPDATE profiles
  SET
    vip_cards = v_vip_cards,
    updated_at = NOW()
  WHERE id = p_student_id;

  -- ========================================
  -- 9. RETURN RESULTS
  -- ========================================

  RETURN jsonb_build_object(
    'cards', v_drawn_cards
  );

END;
$$;


ALTER FUNCTION "public"."award_vip_cards_with_filters"("p_student_id" "uuid", "p_count" integer, "p_filters" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_vip_cards_with_filters"("p_student_id" "uuid", "p_count" integer, "p_filters" "jsonb") IS 'Awards VIP cards to a student with advanced filtering capabilities. Used for action-triggered card draws (e.g., "Soldes" card that draws 2 more cards). Supports filters: forceRarity (force all cards to specific rarity), minRarity (guarantee at least 1 card of minimum rarity or higher), excludeCardIds (exclude specific cards), onlyCardsWithActions (only draw cards with actions). Only teachers can call this function. Uses SELECT FOR UPDATE to prevent race conditions. Returns JSONB array of drawn cards with full details (cardId, instanceId, name, rarity, earnedAt).';



CREATE OR REPLACE FUNCTION "public"."award_weekly_best_bonuses"("p_week_start" "date", "p_week_end" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_role TEXT;
  v_bonus_count INTEGER := 0;
  v_record RECORD;
  v_class_id UUID;
  -- Notification grouping
  v_notif_data JSONB := '{}'::JSONB;
  v_student_id UUID;
  v_game_entry RECORD;
  v_total_reward NUMERIC;
  v_game_label TEXT;
  v_message TEXT;
BEGIN
  SELECT role INTO v_caller_role FROM profiles WHERE id = auth.uid();

  IF auth.uid() IS NOT NULL AND v_caller_role != 'admin' THEN
    RAISE EXCEPTION 'Unauthorized: Only admins can award weekly bonuses';
  END IF;

  IF p_week_end <= p_week_start THEN
    RAISE EXCEPTION 'Invalid week boundaries: end (%) must be after start (%)', p_week_end, p_week_start;
  END IF;

  FOR v_record IN
    SELECT student_id, best_reward_game_type, best_theoretical_reward
    FROM weekly_best_rewards
    WHERE week_start = p_week_start
      AND week_end = p_week_end
      AND bonus_awarded_at IS NULL
      AND best_theoretical_reward > 0
    ORDER BY student_id, best_reward_game_type
    FOR UPDATE
  LOOP
    SELECT cm.class_id INTO v_class_id
    FROM class_members cm
    WHERE cm.student_id = v_record.student_id
      AND cm.status = 'active'
    LIMIT 1;

    UPDATE profiles
    SET gidouilles = gidouilles + v_record.best_theoretical_reward
    WHERE id = v_record.student_id;

    INSERT INTO gidouilles_activity (
      student_id, class_id, delta, reason, created_by
    ) VALUES (
      v_record.student_id, v_class_id,
      v_record.best_theoretical_reward,
      'weekly_best_game_bonus:' || v_record.best_reward_game_type, NULL
    );

    UPDATE weekly_best_rewards
    SET bonus_awarded = v_record.best_theoretical_reward,
        bonus_awarded_at = NOW(),
        updated_at = NOW()
    WHERE student_id = v_record.student_id
      AND week_start = p_week_start
      AND best_reward_game_type = v_record.best_reward_game_type;

    IF NOT v_notif_data ? v_record.student_id::TEXT THEN
      v_notif_data := v_notif_data || jsonb_build_object(
        v_record.student_id::TEXT,
        jsonb_build_array(jsonb_build_object(
          'game', v_record.best_reward_game_type,
          'reward', v_record.best_theoretical_reward
        ))
      );
    ELSE
      v_notif_data := jsonb_set(
        v_notif_data,
        ARRAY[v_record.student_id::TEXT],
        (v_notif_data -> v_record.student_id::TEXT) || jsonb_build_array(jsonb_build_object(
          'game', v_record.best_reward_game_type,
          'reward', v_record.best_theoretical_reward
        ))
      );
    END IF;

    v_bonus_count := v_bonus_count + 1;
  END LOOP;

  FOR v_student_id IN
    SELECT key::UUID FROM jsonb_each(v_notif_data) AS kv(key, value)
  LOOP
    v_total_reward := 0;
    v_message := E'Récompenses hebdomadaires pour tes jeux :\n\n';

    FOR v_game_entry IN
      SELECT value FROM jsonb_array_elements(v_notif_data -> v_student_id::TEXT) AS value
    LOOP
      -- CHANGED: added 'mathemo' label
      v_game_label := CASE (v_game_entry.value ->> 'game')
        WHEN 'minesweeper' THEN 'Démineur'
        WHEN 'riddle' THEN 'Énigme'
        WHEN '2048' THEN '2048'
        WHEN 'mathemo' THEN 'Mathémo'
        ELSE (v_game_entry.value ->> 'game')
      END;
      v_message := v_message || format(
        E'  • %s : %s gidouille(s)\n',
        v_game_label,
        ROUND((v_game_entry.value ->> 'reward')::NUMERIC, 2)
      );
      v_total_reward := v_total_reward + (v_game_entry.value ->> 'reward')::NUMERIC;
    END LOOP;

    v_message := v_message || format(
      E'\nTotal : %s gidouille(s) pour la semaine du %s au %s.\nContinue comme ça !',
      ROUND(v_total_reward, 2),
      TO_CHAR(p_week_start, 'DD/MM/YYYY'),
      TO_CHAR(p_week_end, 'DD/MM/YYYY')
    );

    INSERT INTO notifications (
      title, message, type, is_system,
      system_event_type, target_type, target_user_ids
    ) VALUES (
      'Récompense hebdomadaire Jeux',
      v_message,
      'info',
      true,
      'weekly_best_bonus',
      'users',
      ARRAY[v_student_id]
    );
  END LOOP;

  RETURN v_bonus_count;
END;
$$;


ALTER FUNCTION "public"."award_weekly_best_bonuses"("p_week_start" "date", "p_week_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_weekly_best_bonuses"("p_week_start" "date", "p_week_end" "date") IS 'Awards weekly best game bonuses per game type. Each game type gets its own bonus. Sends one grouped notification per student.';



CREATE OR REPLACE FUNCTION "public"."award_weekly_reward"("p_student_id" "uuid", "p_class_id" "uuid", "p_week_start" "date", "p_week_end" "date", "p_gidouilles" integer DEFAULT 1, "p_reason" "text" DEFAULT 'no_warnings'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_reward_id UUID;
    v_caller_role TEXT;
BEGIN
    -- SECURITY CHECK (Issue #1): Get caller's role to enforce authorization
    -- SECURITY DEFINER functions bypass RLS, so we must check permissions explicitly
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- Authorization: Only admins, teachers of the class, or service_role can award rewards
    IF auth.uid() IS NOT NULL AND NOT (
        v_caller_role = 'admin'
        OR (v_caller_role = 'teacher' AND EXISTS (
            SELECT 1 FROM public.classes
            WHERE id = p_class_id
            AND teacher_id = auth.uid()
        ))
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have permission to award rewards for this class';
    END IF;

    -- FIX (Issue #6): Use atomic INSERT with WHERE NOT EXISTS to prevent race condition
    -- Insert the reward record only if student had no warnings that week
    INSERT INTO public.weekly_rewards (
        student_id,
        class_id,
        week_start,
        week_end,
        gidouilles_awarded,
        reason
    )
    SELECT p_student_id, p_class_id, p_week_start, p_week_end, p_gidouilles, p_reason
    WHERE NOT EXISTS (
        SELECT 1 FROM public.student_warnings
        WHERE student_id = p_student_id
        AND class_id = p_class_id
        AND DATE(created_at) BETWEEN p_week_start AND p_week_end
        AND deleted_at IS NULL
    )
    ON CONFLICT (student_id, class_id, week_start) DO NOTHING
    RETURNING id INTO v_reward_id;

    -- Only update gidouilles if we actually inserted a new record
    IF v_reward_id IS NOT NULL THEN
        -- Update student's gidouilles (and log in history)
        PERFORM public.update_student_gidouilles(
            p_student_id,
            p_class_id,
            p_gidouilles,
            p_reason,
            NULL  -- System-generated
        );
    END IF;

    RETURN v_reward_id;
END;
$$;


ALTER FUNCTION "public"."award_weekly_reward"("p_student_id" "uuid", "p_class_id" "uuid", "p_week_start" "date", "p_week_end" "date", "p_gidouilles" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_tournament_scores"("p_tournament_id" "uuid") RETURNS TABLE("updated_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  -- Update games that have status = 'won' but score IS NULL
  WITH updated AS (
    UPDATE minesweeper_tournament_games g
    SET
      grid_3bv = calculate_3bv(g.grid_state),
      score = calculate_tournament_score(
        calculate_3bv(g.grid_state),
        g.time_seconds,
        (SELECT public.get_cycle_for_grade(p.grade) FROM profiles p WHERE p.id = g.student_id),
        (SELECT t.difficulty FROM minesweeper_tournaments t WHERE t.id = g.tournament_id)
      )
    WHERE g.tournament_id = p_tournament_id
      AND g.status = 'won'
      AND g.score IS NULL
      AND g.grid_state IS NOT NULL
      AND g.time_seconds IS NOT NULL
    RETURNING 1
  )
  SELECT COUNT(*)::INTEGER INTO v_count FROM updated;

  updated_count := v_count;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."backfill_tournament_scores"("p_tournament_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_tournament_scores"("p_tournament_id" "uuid") IS 'Backfills scores for tournament games that were won before 3BV scoring was implemented.
   Returns the count of games updated.';



CREATE OR REPLACE FUNCTION "public"."calculate_3bv"("p_grid_state" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_rows INTEGER;
  v_cols INTEGER;
  v_mines JSONB;
  v_adjacent_counts JSONB;
  v_total_cells INTEGER;
  v_mine_count INTEGER;
  v_safe_cells INTEGER;

  -- Arrays for grid processing (1-indexed for PostgreSQL)
  v_is_mine BOOLEAN[];
  v_adj_count INTEGER[];
  v_visited BOOLEAN[];

  v_openings INTEGER := 0;
  v_isolated INTEGER := 0;

  v_idx INTEGER;
  v_row INTEGER;
  v_col INTEGER;
  v_mine JSONB;
  v_key TEXT;
  v_count INTEGER;

  -- BFS queue for flood-fill
  v_queue INTEGER[];
  v_queue_start INTEGER;
  v_queue_end INTEGER;
  v_current INTEGER;
  v_curr_row INTEGER;
  v_curr_col INTEGER;
  v_neighbor_row INTEGER;
  v_neighbor_col INTEGER;
  v_neighbor_idx INTEGER;
  v_dr INTEGER;
  v_dc INTEGER;
BEGIN
  -- 1. Parse grid dimensions
  v_rows := (p_grid_state->>'rows')::INTEGER;
  v_cols := (p_grid_state->>'cols')::INTEGER;
  v_mines := p_grid_state->'mines';
  v_adjacent_counts := p_grid_state->'adjacentCounts';

  v_total_cells := v_rows * v_cols;
  v_mine_count := jsonb_array_length(v_mines);
  v_safe_cells := v_total_cells - v_mine_count;

  -- 2. Initialize arrays (1-indexed, size = total_cells)
  v_is_mine := ARRAY_FILL(FALSE, ARRAY[v_total_cells]);
  v_adj_count := ARRAY_FILL(0, ARRAY[v_total_cells]);
  v_visited := ARRAY_FILL(FALSE, ARRAY[v_total_cells]);

  -- 3. Mark mine positions
  FOR v_idx IN 0..jsonb_array_length(v_mines) - 1 LOOP
    v_mine := v_mines->v_idx;
    v_row := (v_mine->>0)::INTEGER;
    v_col := (v_mine->>1)::INTEGER;
    v_is_mine[v_row * v_cols + v_col + 1] := TRUE;
  END LOOP;

  -- 4. Build adjacent counts grid
  FOR v_row IN 0..v_rows - 1 LOOP
    FOR v_col IN 0..v_cols - 1 LOOP
      v_idx := v_row * v_cols + v_col + 1;
      IF NOT v_is_mine[v_idx] THEN
        v_key := v_row || ',' || v_col;
        v_count := COALESCE((v_adjacent_counts->>v_key)::INTEGER, 0);
        v_adj_count[v_idx] := v_count;
      END IF;
    END LOOP;
  END LOOP;

  -- 5. Count openings using BFS flood-fill from zeros
  FOR v_row IN 0..v_rows - 1 LOOP
    FOR v_col IN 0..v_cols - 1 LOOP
      v_idx := v_row * v_cols + v_col + 1;

      -- Skip if mine, already visited, or not a zero cell
      IF v_is_mine[v_idx] OR v_visited[v_idx] OR v_adj_count[v_idx] != 0 THEN
        CONTINUE;
      END IF;

      -- Found a new opening - count it
      v_openings := v_openings + 1;

      -- BFS flood-fill from this zero
      v_queue := ARRAY[v_idx];
      v_queue_start := 1;
      v_queue_end := 1;
      v_visited[v_idx] := TRUE;

      WHILE v_queue_start <= v_queue_end LOOP
        v_current := v_queue[v_queue_start];
        v_queue_start := v_queue_start + 1;

        v_curr_row := (v_current - 1) / v_cols;
        v_curr_col := (v_current - 1) % v_cols;

        -- Check all 8 neighbors
        FOR v_dr IN -1..1 LOOP
          FOR v_dc IN -1..1 LOOP
            IF v_dr = 0 AND v_dc = 0 THEN
              CONTINUE;
            END IF;

            v_neighbor_row := v_curr_row + v_dr;
            v_neighbor_col := v_curr_col + v_dc;

            -- Bounds check
            IF v_neighbor_row < 0 OR v_neighbor_row >= v_rows OR
               v_neighbor_col < 0 OR v_neighbor_col >= v_cols THEN
              CONTINUE;
            END IF;

            v_neighbor_idx := v_neighbor_row * v_cols + v_neighbor_col + 1;

            -- Skip if mine or already visited
            IF v_is_mine[v_neighbor_idx] OR v_visited[v_neighbor_idx] THEN
              CONTINUE;
            END IF;

            -- Mark as visited (revealed by this opening)
            v_visited[v_neighbor_idx] := TRUE;

            -- If this neighbor is also a zero, add to queue for further expansion
            IF v_adj_count[v_neighbor_idx] = 0 THEN
              v_queue_end := v_queue_end + 1;
              v_queue := v_queue || v_neighbor_idx;
            END IF;
          END LOOP;
        END LOOP;
      END LOOP;
    END LOOP;
  END LOOP;

  -- 6. Count isolated numbers (safe cells not visited by any opening)
  FOR v_idx IN 1..v_total_cells LOOP
    IF NOT v_is_mine[v_idx] AND NOT v_visited[v_idx] THEN
      v_isolated := v_isolated + 1;
    END IF;
  END LOOP;

  RETURN v_openings + v_isolated;
END;
$$;


ALTER FUNCTION "public"."calculate_3bv"("p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_3bv"("p_grid_state" "jsonb") IS 'Calculates the 3BV (Bechtel Board Benchmark Value) for a Minesweeper grid.
   3BV = number of openings (zero regions) + number of isolated numbers (not revealed by openings).
   This represents the minimum number of clicks needed to solve the board.';



CREATE OR REPLACE FUNCTION "public"."calculate_daily_challenge_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Student info
  v_student_grade TEXT;
  v_cycle TEXT;

  -- Base rewards (Strategy D)
  v_base_reward NUMERIC(10,2);
  v_reference_time INTEGER;

  -- Time multiplier
  v_time_ratio NUMERIC;
  v_time_mult NUMERIC;

  -- Result
  v_result NUMERIC(10,2);
BEGIN
  -- ========================================================================
  -- STEP 1: Get student's grade and cycle
  -- ========================================================================
  SELECT grade INTO v_student_grade
  FROM public.profiles
  WHERE id = p_student_id;

  v_cycle := public.get_cycle_for_grade(v_student_grade);

  -- If no valid cycle, no gidouilles
  IF v_cycle IS NULL THEN
    RETURN 0.00;
  END IF;

  -- ========================================================================
  -- STEP 2: Determine base reward and get dynamic reference time
  -- ========================================================================
  CASE p_difficulty
    WHEN 'beginner' THEN
      v_base_reward := 1.0;
    WHEN 'intermediate' THEN
      v_base_reward := 3.0;
    WHEN 'expert' THEN
      v_base_reward := 6.0;
    ELSE
      RETURN 0.0;
  END CASE;

  -- Get dynamic reference time
  BEGIN
    v_reference_time := public.get_minesweeper_reference_time(v_cycle, p_difficulty);
  EXCEPTION
    WHEN raise_exception THEN
      v_reference_time := CASE p_difficulty
        WHEN 'beginner' THEN 180
        WHEN 'intermediate' THEN 600
        WHEN 'expert' THEN 1200
      END;
  END;

  -- ========================================================================
  -- STEP 3: Calculate time multiplier
  -- ========================================================================
  -- Formula: 1.3 (instant) → 1.0 (at ref time) → 0.7 (double ref time, floor)
  v_time_ratio := p_time_seconds::NUMERIC / v_reference_time;
  v_time_mult := GREATEST(0.7, 1.3 - 0.3 * v_time_ratio);

  -- ========================================================================
  -- STEP 4: Calculate final reward
  -- ========================================================================
  -- Daily challenge: No hint penalty, no daily degressive
  -- Just base * time_mult
  v_result := v_base_reward * v_time_mult;

  -- Apply bounds
  v_result := GREATEST(0.30, v_result);
  v_result := LEAST(8.00, v_result);
  v_result := ROUND(v_result, 2);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."calculate_daily_challenge_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_daily_challenge_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid") IS 'Calculates daily challenge gidouilles with Strategy D. Time mult: 1.3→1.0→0.7 (floor at 2x ref time). Dynamic reference times.';



CREATE OR REPLACE FUNCTION "public"."calculate_elo_change"("p_winner_elo" integer, "p_loser_elo" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_k_factor INTEGER := 32; -- Standard K-factor for moderate volatility
  v_expected_score NUMERIC;
  v_elo_change INTEGER;
BEGIN
  -- Calculate expected score for winner using ELO formula
  -- E = 1 / (1 + 10^((R_opponent - R_player) / 400))
  v_expected_score := 1.0 / (1.0 + POWER(10.0, (p_loser_elo - p_winner_elo)::NUMERIC / 400.0));

  -- Calculate ELO change: K * (actual_score - expected_score)
  -- Winner gets actual_score = 1, so: K * (1 - expected_score)
  v_elo_change := ROUND(v_k_factor * (1.0 - v_expected_score))::INTEGER;

  -- Ensure minimum change of 1 point
  IF v_elo_change < 1 THEN
    v_elo_change := 1;
  END IF;

  RETURN v_elo_change;
END;
$$;


ALTER FUNCTION "public"."calculate_elo_change"("p_winner_elo" integer, "p_loser_elo" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_elo_change"("p_winner_elo" integer, "p_loser_elo" integer) IS 'Calculate ELO rating change for winner (K-factor 32)';



CREATE OR REPLACE FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_base_reward INTEGER;
  v_time_bonus_percent NUMERIC;
  v_time_bonus INTEGER;
  v_total_before_multiplier INTEGER;
  v_hint_penalty_multiplier NUMERIC;  -- NEW: Hints penalty
  v_games_won_today INTEGER;
  v_degressive_multiplier NUMERIC;
  v_final_reward INTEGER;
  v_today_start TIMESTAMPTZ;
BEGIN
  -- Base rewards by difficulty
  CASE p_difficulty
    WHEN 'beginner' THEN
      v_base_reward := 10;
      -- Time bonus: < 60 seconds = +50%, linear decrease to 0% at 180s
      IF p_time_seconds < 60 THEN
        v_time_bonus_percent := 0.5; -- 50%
      ELSIF p_time_seconds < 180 THEN
        -- Linear interpolation: 50% at 60s, 0% at 180s
        v_time_bonus_percent := 0.5 * (180 - p_time_seconds) / 120.0;
      ELSE
        v_time_bonus_percent := 0.0;
      END IF;
    WHEN 'intermediate' THEN
      v_base_reward := 30;
      -- Time bonus: < 300 seconds (5 min) = +50%, linear decrease to 0% at 600s (10 min)
      IF p_time_seconds < 300 THEN
        v_time_bonus_percent := 0.5; -- 50%
      ELSIF p_time_seconds < 600 THEN
        v_time_bonus_percent := 0.5 * (600 - p_time_seconds) / 300.0;
      ELSE
        v_time_bonus_percent := 0.0;
      END IF;
    WHEN 'expert' THEN
      v_base_reward := 60;
      -- Time bonus: < 600 seconds (10 min) = +50%, linear decrease to 0% at 1200s (20 min)
      IF p_time_seconds < 600 THEN
        v_time_bonus_percent := 0.5; -- 50%
      ELSIF p_time_seconds < 1200 THEN
        v_time_bonus_percent := 0.5 * (1200 - p_time_seconds) / 600.0;
      ELSE
        v_time_bonus_percent := 0.0;
      END IF;
    ELSE
      -- Invalid difficulty
      RETURN 0;
  END CASE;

  -- Calculate time bonus
  v_time_bonus := FLOOR(v_base_reward * v_time_bonus_percent);
  v_total_before_multiplier := v_base_reward + v_time_bonus;

  -- ✅ NEW: Apply hints penalty BEFORE degressive multiplier
  -- Each hint costs 10 gidouilles upfront + 30% penalty on final reward
  IF p_hints_used > 0 THEN
    v_hint_penalty_multiplier := 0.7;  -- 30% penalty
    v_total_before_multiplier := FLOOR(v_total_before_multiplier * v_hint_penalty_multiplier);
  END IF;

  -- Daily degressive multiplier based on games won today
  v_today_start := date_trunc('day', NOW());

  SELECT COUNT(*) INTO v_games_won_today
  FROM public.minesweeper_games
  WHERE student_id = p_student_id
    AND status = 'won'
    AND completed_at >= v_today_start;

  -- Calculate degressive multiplier: 100% for first win, -15% per additional win, minimum 30%
  -- Win 1: 100%, Win 2: 85%, Win 3: 70%, Win 4: 55%, Win 5: 40%, Win 6+: 30%
  v_degressive_multiplier := 1.0 - (v_games_won_today * 0.15);

  -- Enforce minimum 30% multiplier
  IF v_degressive_multiplier < 0.3 THEN
    v_degressive_multiplier := 0.3;
  END IF;

  -- Apply degressive multiplier
  v_final_reward := FLOOR(v_total_before_multiplier * v_degressive_multiplier);

  -- Per-game cap: 100 gidouilles max
  IF v_final_reward > 100 THEN
    v_final_reward := 100;
  END IF;

  -- Ensure non-negative
  IF v_final_reward < 0 THEN
    v_final_reward := 0;
  END IF;

  RETURN v_final_reward;
END;
$$;


ALTER FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer) IS 'Calculates gidouilles reward for winning a Minesweeper game. Base reward + up to 50% time bonus, then applies hints penalty (30% if any hints used), then daily degressive multiplier (15% reduction per win, minimum 30%). Capped at 100 per game.';



CREATE OR REPLACE FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer DEFAULT 0, "p_reduced_penalty_hints" integer DEFAULT 0) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Student info
  v_student_grade TEXT;
  v_cycle TEXT;

  -- Base rewards (Strategy D: scaled by /10)
  v_base_reward NUMERIC(10,2);
  v_reference_time INTEGER;

  -- Time multiplier calculation
  v_time_ratio NUMERIC;
  v_time_mult NUMERIC;

  -- Hint penalty calculation
  v_hints_gidouilles INTEGER;  -- Hints paid with gidouilles
  v_hints_reduced INTEGER;     -- Hints with reduced penalty
  v_hint_penalty NUMERIC;

  -- Penalty rates (progressive)
  -- Gidouilles hints: 10%, 22%, 35% for 1, 2, 3 hints
  -- Reduced penalty hints: 5%, 11%, 17% for 1, 2, 3 hints
  v_gidouilles_penalties NUMERIC[] := ARRAY[0.10, 0.22, 0.35];
  v_reduced_penalties NUMERIC[] := ARRAY[0.05, 0.11, 0.17];

  -- Daily degressive
  v_games_won_today INTEGER;
  v_daily_mult NUMERIC;
  v_today_start TIMESTAMPTZ;

  -- Final calculation
  v_result NUMERIC(10,2);
BEGIN
  -- ========================================================================
  -- STEP 0: Get student's grade and cycle
  -- ========================================================================
  SELECT grade INTO v_student_grade
  FROM public.profiles
  WHERE id = p_student_id;

  -- Get cycle for this grade
  v_cycle := public.get_cycle_for_grade(v_student_grade);

  -- If no valid cycle (no grade or invalid grade), no gidouilles awarded
  -- This incentivizes students to set their grade level
  IF v_cycle IS NULL THEN
    RETURN 0.00;
  END IF;

  -- ========================================================================
  -- STEP 1: Determine base reward and get dynamic reference time
  -- ========================================================================
  CASE p_difficulty
    WHEN 'beginner' THEN
      v_base_reward := 1.0;
    WHEN 'intermediate' THEN
      v_base_reward := 3.0;
    WHEN 'expert' THEN
      v_base_reward := 6.0;
    ELSE
      RETURN 0.0;  -- Unknown difficulty
  END CASE;

  -- Get dynamic reference time for this cycle/difficulty
  -- This uses the median-based times recalculated weekly
  BEGIN
    v_reference_time := public.get_minesweeper_reference_time(v_cycle, p_difficulty);
  EXCEPTION
    WHEN raise_exception THEN
      -- Fallback to hardcoded values if something goes wrong
      v_reference_time := CASE p_difficulty
        WHEN 'beginner' THEN 180
        WHEN 'intermediate' THEN 600
        WHEN 'expert' THEN 1200
      END;
  END;

  -- ========================================================================
  -- STEP 2: Calculate time multiplier (continuous formula)
  -- ========================================================================
  -- Formula: 1.3 (instant) → 1.0 (at ref time) → 0.7 (double ref time, floor)
  v_time_ratio := p_time_seconds::NUMERIC / v_reference_time;
  v_time_mult := GREATEST(0.7, 1.3 - 0.3 * v_time_ratio);

  -- ========================================================================
  -- STEP 3: Calculate hint penalty (progressive, source-aware)
  -- ========================================================================
  -- Split hints by source
  v_hints_reduced := COALESCE(p_reduced_penalty_hints, 0);
  v_hints_gidouilles := COALESCE(p_hints_used, 0) - v_hints_reduced;

  -- Ensure non-negative
  v_hints_gidouilles := GREATEST(0, v_hints_gidouilles);
  v_hints_reduced := GREATEST(0, v_hints_reduced);

  -- Calculate penalty from each source
  v_hint_penalty := 0.0;

  -- Add penalty for gidouilles-based hints
  IF v_hints_gidouilles > 0 THEN
    v_hint_penalty := v_hint_penalty + v_gidouilles_penalties[LEAST(v_hints_gidouilles, 3)];
  END IF;

  -- Add penalty for reduced-penalty hints
  IF v_hints_reduced > 0 THEN
    v_hint_penalty := v_hint_penalty + v_reduced_penalties[LEAST(v_hints_reduced, 3)];
  END IF;

  -- Cap total penalty at 50% (0.50)
  v_hint_penalty := LEAST(0.50, v_hint_penalty);

  -- ========================================================================
  -- STEP 4: Daily degressive multiplier
  -- ========================================================================
  v_today_start := date_trunc('day', NOW() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris';

  SELECT COUNT(*) INTO v_games_won_today
  FROM public.minesweeper_games
  WHERE student_id = p_student_id
    AND status = 'won'
    AND completed_at >= v_today_start;

  -- Daily mult: 100% first win, -15% each subsequent, min 30%
  v_daily_mult := GREATEST(0.30, 1.0 - (v_games_won_today * 0.15));

  -- ========================================================================
  -- STEP 5: Final calculation
  -- ========================================================================
  v_result := v_base_reward * v_time_mult * (1.0 - v_hint_penalty) * v_daily_mult;

  -- Apply absolute bounds
  v_result := GREATEST(0.30, v_result);
  v_result := LEAST(8.00, v_result);
  v_result := ROUND(v_result, 2);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer, "p_reduced_penalty_hints" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_minesweeper_gidouilles"("p_difficulty" "text", "p_time_seconds" integer, "p_student_id" "uuid", "p_hints_used" integer, "p_reduced_penalty_hints" integer) IS 'Calculates gidouilles with Strategy D. Time mult: 1.3→1.0→0.7 (floor at 2x ref time). Dynamic reference times.';



CREATE OR REPLACE FUNCTION "public"."calculate_minesweeper_points"("p_difficulty" "text", "p_time_seconds" integer, "p_hints_used" integer, "p_student_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_base_points INTEGER;
  v_reference_time INTEGER;
  v_speed_bonus NUMERIC;
  v_hint_penalty NUMERIC;
  v_streak INTEGER;
  v_streak_bonus NUMERIC;
  v_is_first_today BOOLEAN;
  v_daily_bonus INTEGER;
  v_total_points INTEGER;
BEGIN
  -- Set base points and reference time by difficulty
  CASE p_difficulty
    WHEN 'beginner' THEN
      v_base_points := 50;
      v_reference_time := 120;  -- 2 minutes
    WHEN 'intermediate' THEN
      v_base_points := 200;
      v_reference_time := 600;  -- 10 minutes
    WHEN 'expert' THEN
      v_base_points := 500;
      v_reference_time := 1200; -- 20 minutes
    ELSE
      RETURN 0; -- Unknown difficulty
  END CASE;

  -- Calculate speed bonus: max(0, 1 - time/refTime)
  v_speed_bonus := GREATEST(0, 1 - (p_time_seconds::NUMERIC / v_reference_time));

  -- Calculate hint penalty: 0.9 ^ hints_used (-10% per hint)
  v_hint_penalty := POWER(0.9, p_hints_used);

  -- Calculate streak (consecutive wins before this game)
  -- Count consecutive wins going backwards from most recent completed game
  WITH recent_games AS (
    SELECT
      status,
      ROW_NUMBER() OVER (ORDER BY completed_at DESC) AS rn
    FROM public.minesweeper_games
    WHERE student_id = p_student_id
      AND status IN ('won', 'lost')
      AND completed_at IS NOT NULL
    ORDER BY completed_at DESC
    LIMIT 10  -- Only look at last 10 games for performance
  ),
  streak_calc AS (
    SELECT
      COUNT(*) AS streak
    FROM recent_games
    WHERE status = 'won'
      AND rn <= (
        SELECT COALESCE(MIN(rn) - 1, 10)
        FROM recent_games
        WHERE status = 'lost'
      )
  )
  SELECT COALESCE(streak, 0) INTO v_streak FROM streak_calc;

  -- Streak bonus: +5% per consecutive win, max +25%
  v_streak_bonus := 1 + LEAST(0.25, v_streak * 0.05);

  -- Check if first win of the day
  SELECT NOT EXISTS (
    SELECT 1
    FROM public.minesweeper_games
    WHERE student_id = p_student_id
      AND status = 'won'
      AND DATE(completed_at AT TIME ZONE 'UTC') = CURRENT_DATE
  ) INTO v_is_first_today;

  -- Daily bonus: 20 points for first win of the day
  v_daily_bonus := CASE WHEN v_is_first_today THEN 20 ELSE 0 END;

  -- Calculate total points
  v_total_points := FLOOR(
    v_base_points * (1 + v_speed_bonus) * v_hint_penalty * v_streak_bonus
  ) + v_daily_bonus;

  RETURN v_total_points;
END;
$$;


ALTER FUNCTION "public"."calculate_minesweeper_points"("p_difficulty" "text", "p_time_seconds" integer, "p_hints_used" integer, "p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_minesweeper_points"("p_difficulty" "text", "p_time_seconds" integer, "p_hints_used" integer, "p_student_id" "uuid") IS 'Calculates points for a Minesweeper win based on difficulty, time, hints, streak, and daily bonus.';



CREATE OR REPLACE FUNCTION "public"."calculate_riddle_gidouilles"("p_difficulty" integer, "p_attempt_number" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_multiplier INTEGER;
BEGIN
  -- Degressive multiplier based on attempt number
  v_multiplier := CASE
    WHEN p_attempt_number = 1 THEN 3
    WHEN p_attempt_number = 2 THEN 2
    ELSE 1
  END;

  RETURN p_difficulty * v_multiplier;
END;
$$;


ALTER FUNCTION "public"."calculate_riddle_gidouilles"("p_difficulty" integer, "p_attempt_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_tournament_score"("p_grid_3bv" integer, "p_time_seconds" integer, "p_cycle" "text", "p_difficulty" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actual_3bvs NUMERIC;
  v_reference_3bvs NUMERIC;
  v_raw_score NUMERIC;
BEGIN
  -- Calculate actual 3BV/s (efficiency)
  v_actual_3bvs := p_grid_3bv::NUMERIC / GREATEST(1, p_time_seconds);

  -- Get reference for this cycle/difficulty
  SELECT reference_3bvs INTO v_reference_3bvs
  FROM public.minesweeper_tournament_3bv_reference
  WHERE cycle = p_cycle AND difficulty = p_difficulty;

  -- Fallback if no reference found
  IF v_reference_3bvs IS NULL OR v_reference_3bvs <= 0 THEN
    v_reference_3bvs := 0.25;
  END IF;

  -- Calculate score: 100 × ratio, clamped [10, 300]
  v_raw_score := 100.0 * v_actual_3bvs / v_reference_3bvs;

  RETURN GREATEST(10, LEAST(300, FLOOR(v_raw_score)));
END;
$$;


ALTER FUNCTION "public"."calculate_tournament_score"("p_grid_3bv" integer, "p_time_seconds" integer, "p_cycle" "text", "p_difficulty" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_tournament_score"("p_grid_3bv" integer, "p_time_seconds" integer, "p_cycle" "text", "p_difficulty" "text") IS 'Calculates tournament score based on 3BV/s efficiency.
   Score 100 = performance equal to reference for the cycle.
   Score range: 10 (minimum) to 300 (3x reference, maximum).';



CREATE OR REPLACE FUNCTION "public"."calculate_week_boundaries"("p_date" "date", "p_first_day" integer) RETURNS TABLE("week_start" "date", "week_end" "date")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_dow INTEGER; -- Day of week (0=Sunday, 6=Saturday)
  v_days_since_week_start INTEGER;
  v_week_start DATE;
  v_week_end DATE;
BEGIN
  -- Get day of week (0=Sunday, 6=Saturday)
  v_dow := EXTRACT(DOW FROM p_date)::INTEGER;

  -- Calculate days since week start
  v_days_since_week_start := (v_dow - p_first_day + 7) % 7;

  -- Calculate week boundaries
  v_week_start := p_date - v_days_since_week_start;
  v_week_end := v_week_start + 6;

  RETURN QUERY SELECT v_week_start, v_week_end;
END;
$$;


ALTER FUNCTION "public"."calculate_week_boundaries"("p_date" "date", "p_first_day" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_week_boundaries"("p_date" "date", "p_first_day" integer) IS 'Calculates week start and end dates based on school week configuration (e.g., Sunday-Thursday for Israeli schools)';



