CREATE OR REPLACE FUNCTION "public"."can_access_assignment"("p_assignment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();

    -- Check if user is:
    -- 1. The assignment creator (teacher) - always has access
    -- 2. A student in an assigned class (with timing/status checks)
    -- 3. An individually assigned student (with timing/status checks)
    RETURN EXISTS (
        SELECT 1 FROM public.worksheet_assignments wa
        WHERE wa.id = p_assignment_id
        AND (
            -- Creator/teacher access (always)
            wa.created_by = v_user_id
            OR
            -- Student access requires:
            -- - Assignment status = 'active'
            -- - Current time >= available_from (if set)
            (
                wa.status = 'active'
                AND (wa.available_from IS NULL OR wa.available_from <= NOW())
                AND (
                    -- Class member access via junction table (NEW)
                    EXISTS (
                        SELECT 1 FROM public.worksheet_assignment_classes wac
                        JOIN public.class_members cm ON cm.class_id = wac.class_id
                        JOIN public.classes c ON c.id = wac.class_id
                        WHERE wac.assignment_id = wa.id
                        AND cm.student_id = v_user_id
                        AND c.is_active = TRUE
                    )
                    OR
                    -- Legacy: Class member access via class_id (DEPRECATED, backward compat)
                    EXISTS (
                        SELECT 1 FROM public.class_members cm
                        JOIN public.classes c ON c.id = cm.class_id
                        WHERE cm.class_id = wa.class_id
                        AND cm.student_id = v_user_id
                        AND c.is_active = TRUE
                    )
                    OR
                    -- Individual student assignment access
                    EXISTS (
                        SELECT 1 FROM public.worksheet_assignment_students was
                        WHERE was.assignment_id = wa.id
                        AND was.student_id = v_user_id
                    )
                )
            )
        )
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_access_assignment"("p_assignment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_assignment"("p_assignment_id" "uuid") IS 'Security definer function to check if current user can access a worksheet assignment';



CREATE OR REPLACE FUNCTION "public"."can_access_kanban_board"("p_board_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_owner_id UUID;
    v_class_id UUID;
BEGIN
    SELECT owner_id, class_id
    INTO v_owner_id, v_class_id
    FROM public.kanban_boards
    WHERE id = p_board_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF v_owner_id = auth.uid() THEN
        RETURN TRUE;
    END IF;

    IF v_class_id IS NOT NULL THEN
        RETURN public.is_class_teacher(v_class_id)
            OR public.is_class_member(v_class_id);
    END IF;

    RETURN FALSE;
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_access_kanban_board"("p_board_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_kanban_board"("p_board_id" "uuid") IS 'TRUE if auth.uid() can see a kanban board: owner, class teacher, or class member.';



CREATE OR REPLACE FUNCTION "public"."can_access_kanban_column"("p_column_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_board_id UUID;
BEGIN
    SELECT board_id
    INTO v_board_id
    FROM public.kanban_columns
    WHERE id = p_column_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    RETURN public.can_access_kanban_board(v_board_id);
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


