COMMENT ON FUNCTION "public"."can_access_kanban_column"("p_column_id" "uuid") IS 'TRUE if auth.uid() can access the board owning the given column. Used to gate kanban_cards policies.';



CREATE OR REPLACE FUNCTION "public"."can_assign_kanban_card"("p_card_id" "uuid", "p_assignee" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_board UUID;
    v_owner UUID;
BEGIN
    -- Resolve the card's board.
    SELECT col.board_id INTO v_board
    FROM public.kanban_cards c
    JOIN public.kanban_columns col ON col.id = c.column_id
    WHERE c.id = p_card_id;

    IF v_board IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Assignee must be a board member.
    IF NOT public.is_kanban_board_member(v_board, p_assignee) THEN
        RETURN FALSE;
    END IF;

    -- Actor must have access to the board (sanity check; RLS already filters
    -- but this keeps the helper composable from non-RLS callers too).
    IF NOT public.can_access_kanban_board(v_board) THEN
        RETURN FALSE;
    END IF;

    SELECT owner_id INTO v_owner FROM public.kanban_boards WHERE id = v_board;

    -- Mixte rule: board owner has full control; everyone else can only act
    -- on themselves.
    IF v_owner = auth.uid() THEN
        RETURN TRUE;
    END IF;
    IF p_assignee = auth.uid() THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_assign_kanban_card"("p_card_id" "uuid", "p_assignee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_kanban_card_tag"("p_card_id" "uuid", "p_tag_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_card_board UUID;
    v_tag_board UUID;
BEGIN
    SELECT col.board_id INTO v_card_board
    FROM public.kanban_cards c
    JOIN public.kanban_columns col ON col.id = c.column_id
    WHERE c.id = p_card_id;

    SELECT board_id INTO v_tag_board
    FROM public.kanban_tags
    WHERE id = p_tag_id;

    IF v_card_board IS NULL OR v_tag_board IS NULL THEN
        RETURN FALSE;
    END IF;
    IF v_card_board <> v_tag_board THEN
        RETURN FALSE;
    END IF;

    RETURN public.can_access_kanban_board(v_card_board);
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_manage_kanban_card_tag"("p_card_id" "uuid", "p_tag_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_moderate_message"("moderator_uuid" "uuid", "message_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  moderator_role TEXT;
  message_sender_id UUID;
  message_recipient_ids UUID[];
  user_uuid UUID;
BEGIN
  -- Get moderator's role
  SELECT role INTO moderator_role
  FROM profiles
  WHERE id = moderator_uuid;

  -- Admins can moderate anything
  IF moderator_role = 'admin' THEN
    RETURN TRUE;
  END IF;

  -- Only teachers can moderate (besides admins)
  IF moderator_role != 'teacher' THEN
    RETURN FALSE;
  END IF;

  -- Get message sender and recipients
  SELECT sender_id INTO message_sender_id
  FROM private_messages
  WHERE id = message_uuid;

  IF message_sender_id IS NULL THEN
    RETURN FALSE; -- Message doesn't exist
  END IF;

  SELECT array_agg(recipient_id) INTO message_recipient_ids
  FROM message_inbox
  WHERE message_id = message_uuid;

  -- Teacher can moderate if either sender or any recipient is their student
  -- Check if sender is teacher's student
  IF EXISTS (
    SELECT 1
    FROM get_teacher_students(moderator_uuid)
    WHERE student_id = message_sender_id
  ) THEN
    RETURN TRUE;
  END IF;

  -- Check if any recipient is teacher's student
  FOREACH user_uuid IN ARRAY message_recipient_ids
  LOOP
    IF EXISTS (
      SELECT 1
      FROM get_teacher_students(moderator_uuid)
      WHERE student_id = user_uuid
    ) THEN
      RETURN TRUE;
    END IF;
  END LOOP;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."can_moderate_message"("moderator_uuid" "uuid", "message_uuid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_moderate_message"("moderator_uuid" "uuid", "message_uuid" "uuid") IS 'Checks if a teacher can moderate a message (message involves their students)';



CREATE OR REPLACE FUNCTION "public"."can_participate_in_tournament"("p_tournament_id" "uuid", "p_student_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tournament RECORD;
BEGIN
  -- Get tournament
  SELECT * INTO v_tournament
  FROM public.minesweeper_tournaments
  WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  -- Check if tournament is active
  IF v_tournament.status != 'active' THEN
    RETURN FALSE;
  END IF;

  -- Check date range
  IF NOW() < v_tournament.start_date OR NOW() > v_tournament.end_date THEN
    RETURN FALSE;
  END IF;

  -- Verify student is actually a student
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = p_student_id AND role = 'student'
  ) THEN
    RETURN FALSE;
  END IF;

  -- Global tournaments: all students can participate
  IF v_tournament.scope = 'global' THEN
    RETURN TRUE;
  END IF;

  -- Class-scoped tournaments: check membership
  RETURN EXISTS (
    SELECT 1 FROM public.minesweeper_tournament_classes tc
    JOIN public.class_members cm ON cm.class_id = tc.class_id
    WHERE tc.tournament_id = p_tournament_id
    AND cm.student_id = p_student_id
  );
END;
$$;


ALTER FUNCTION "public"."can_participate_in_tournament"("p_tournament_id" "uuid", "p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_participate_in_tournament"("p_tournament_id" "uuid", "p_student_id" "uuid") IS 'Checks if a student can participate in a tournament (active, in date range, member of participating class or global).';



