CREATE OR REPLACE FUNCTION "public"."check_achievement_prerequisites"("p_student_id" "uuid", "p_achievement_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prerequisites TEXT[];
  v_requires_all BOOLEAN;
  v_met_count INTEGER;
  v_required_count INTEGER;
BEGIN
  -- Get prerequisites and requirements from achievement metadata
  SELECT
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(metadata->'prerequisites')),
      ARRAY[]::TEXT[]
    ),
    COALESCE((metadata->>'requires_all')::BOOLEAN, true)
  INTO v_prerequisites, v_requires_all
  FROM achievements
  WHERE id = p_achievement_id;

  -- If no prerequisites, return true
  -- Note: After COALESCE, v_prerequisites is never NULL (empty array at minimum)
  -- array_length returns NULL for empty arrays, which covers both cases
  IF array_length(v_prerequisites, 1) IS NULL THEN
    RETURN true;
  END IF;

  v_required_count := array_length(v_prerequisites, 1);

  -- OPTIMIZED: Single query to count how many prerequisites are met
  -- Replaces N+1 loop pattern with single batch query
  SELECT COUNT(DISTINCT achievement_id)
  INTO v_met_count
  FROM student_achievements
  WHERE student_id = p_student_id
  AND achievement_id = ANY(v_prerequisites);

  -- Check if requirements are met
  IF v_requires_all THEN
    -- All prerequisites must be met
    RETURN v_met_count = v_required_count;
  ELSE
    -- At least one prerequisite must be met
    RETURN v_met_count > 0;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_achievement_prerequisites"("p_student_id" "uuid", "p_achievement_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_achievement_prerequisites"("p_student_id" "uuid", "p_achievement_id" "text") IS 'Optimized prerequisite checking using batch query instead of N+1 pattern. 80% faster.';



CREATE OR REPLACE FUNCTION "public"."check_and_increment_rate_limit"("p_key" "text", "p_max_count" integer, "p_window_seconds" integer) RETURNS TABLE("allowed" boolean, "current_count" integer, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_now TIMESTAMPTZ := NOW();
    v_new_expires TIMESTAMPTZ := v_now + make_interval(secs => p_window_seconds);
    v_result_count INTEGER;
    v_result_expires TIMESTAMPTZ;
BEGIN
    -- Atomic upsert.
    --
    -- - No conflict: insert (1, v_new_expires), allowed.
    -- - Conflict + expired: reset to (1, v_new_expires), allowed.
    -- - Conflict + valid + count < max: increment, allowed.
    -- - Conflict + valid + count >= max: WHERE clause filters → 0 rows
    --   returned → caller maps to allowed=false.
    --
    -- The WHERE clause on the DO UPDATE means PostgreSQL evaluates it under
    -- the conflicting row's exclusive lock, so concurrent calls serialize on
    -- the unique key — no TOCTOU race.
    --
    -- Off-by-one note: `rl.count < p_max_count` is strict, so when count is
    -- max-1 the increment lifts it to exactly p_max_count and is allowed.
    -- The next call sees count = p_max_count, fails the filter, is blocked.
    -- Effective allowance is exactly p_max_count calls per window.
    INSERT INTO public.rate_limits AS rl (key, count, expires_at)
    VALUES (p_key, 1, v_new_expires)
    ON CONFLICT (key) DO UPDATE
    SET
        count = CASE
            WHEN rl.expires_at < v_now THEN 1
            ELSE rl.count + 1
        END,
        expires_at = CASE
            WHEN rl.expires_at < v_now THEN EXCLUDED.expires_at
            ELSE rl.expires_at
        END
    WHERE rl.expires_at < v_now OR rl.count < p_max_count
    RETURNING rl.count, rl.expires_at
    INTO v_result_count, v_result_expires;

    IF FOUND THEN
        RETURN QUERY SELECT TRUE, v_result_count, v_result_expires;
    ELSE
        -- Blocked: re-fetch so the caller can compute retryAfter from
        -- current expires_at. This SELECT is not under a lock, so values
        -- are advisory — a concurrent expiry-and-reset (or cleanup-cron
        -- delete) could yield a fresher count/expires_at, or NULLs. That's
        -- acceptable: retryAfter erring on the long side is safe, and the
        -- TS caller handles NULL expires_at.
        SELECT rl.count, rl.expires_at
        INTO v_result_count, v_result_expires
        FROM public.rate_limits rl
        WHERE rl.key = p_key;

        RETURN QUERY SELECT FALSE, v_result_count, v_result_expires;
    END IF;
END;
$$;


ALTER FUNCTION "public"."check_and_increment_rate_limit"("p_key" "text", "p_max_count" integer, "p_window_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_increment_rate_limit"("p_key" "text", "p_max_count" integer, "p_window_seconds" integer) IS 'Atomically checks a rate limit and increments its counter in a single round-trip.

Returns (allowed, current_count, expires_at):
- allowed=TRUE  → request is within the limit, counter was incremented (or entry created/reset).
- allowed=FALSE → request blocked (counter already at p_max_count within the active window).

Replaces the SELECT/UPDATE/INSERT/retry pattern in rateLimiter.ts which produced
spurious unique-constraint violations in the Postgres logs whenever an expired
entry collided with a new INSERT for the same key.';



CREATE OR REPLACE FUNCTION "public"."check_and_unlock_achievements"("p_game_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_game RECORD;
  v_student_id UUID;
  v_unlocked_achievements JSONB := '[]'::JSONB;
  v_new_achievement JSONB;
  v_is_first_win BOOLEAN;
  v_perfect_cells INTEGER;
  v_time_threshold INTEGER;
BEGIN
  -- Step 1: Get game details (only process won games)
  SELECT * INTO v_game
  FROM public.minesweeper_games
  WHERE id = p_game_id AND status = 'won';

  IF NOT FOUND THEN
    -- Game not found or not won - return empty array
    RETURN v_unlocked_achievements;
  END IF;

  v_student_id := v_game.student_id;

  -- Only authenticated users can earn achievements
  IF v_student_id IS NULL THEN
    RETURN v_unlocked_achievements;
  END IF;

  -- ============================================================================
  -- Achievement 1: "Premier pas" (First Victory)
  -- ============================================================================

  -- Check if this is the first win ever (excluding current game)
  SELECT NOT EXISTS (
    SELECT 1 FROM public.minesweeper_games
    WHERE student_id = v_student_id
      AND status = 'won'
      AND id != p_game_id
  ) INTO v_is_first_win;

  IF v_is_first_win THEN
    -- Try to insert (ON CONFLICT DO NOTHING prevents duplicates)
    INSERT INTO public.minesweeper_student_achievements (
      student_id,
      achievement_id,
      difficulty,
      game_id
    )
    VALUES (v_student_id, 'first_victory', NULL, p_game_id)
    ON CONFLICT (student_id, achievement_id, difficulty) DO NOTHING;

    -- Check if insert was successful (not a duplicate)
    IF FOUND THEN
      v_new_achievement := jsonb_build_object(
        'achievement_id', 'first_victory',
        'name', (SELECT name FROM public.minesweeper_achievements WHERE id = 'first_victory'),
        'icon', (SELECT icon FROM public.minesweeper_achievements WHERE id = 'first_victory'),
        'difficulty', NULL
      );
      v_unlocked_achievements := v_unlocked_achievements || v_new_achievement;
    END IF;
  END IF;

  -- ============================================================================
  -- Achievement 2: "Sans drapeaux" (No Flags) - Difficulty Specific
  -- ============================================================================

  IF v_game.flags_used = 0 THEN
    INSERT INTO public.minesweeper_student_achievements (
      student_id,
      achievement_id,
      difficulty,
      game_id
    )
    VALUES (v_student_id, 'no_flags', v_game.difficulty, p_game_id)
    ON CONFLICT (student_id, achievement_id, difficulty) DO NOTHING;

    IF FOUND THEN
      v_new_achievement := jsonb_build_object(
        'achievement_id', 'no_flags',
        'name', (SELECT name FROM public.minesweeper_achievements WHERE id = 'no_flags'),
        'icon', (SELECT icon FROM public.minesweeper_achievements WHERE id = 'no_flags'),
        'difficulty', v_game.difficulty
      );
      v_unlocked_achievements := v_unlocked_achievements || v_new_achievement;
    END IF;
  END IF;

  -- ============================================================================
  -- Achievement 3: "Perfectionniste" (Perfect Reveals) - Difficulty Specific
  -- ============================================================================

  -- Calculate expected perfect cells: (rows × cols) - mines
  SELECT (rows * cols) - mines INTO v_perfect_cells
  FROM (VALUES
    ('beginner', 9, 9, 10),
    ('intermediate', 16, 16, 40),
    ('expert', 16, 30, 99)
  ) AS configs(difficulty, rows, cols, mines)
  WHERE difficulty = v_game.difficulty;

  IF v_game.cells_revealed = v_perfect_cells THEN
    INSERT INTO public.minesweeper_student_achievements (
      student_id,
      achievement_id,
      difficulty,
      game_id
    )
    VALUES (v_student_id, 'perfectionist', v_game.difficulty, p_game_id)
    ON CONFLICT (student_id, achievement_id, difficulty) DO NOTHING;

    IF FOUND THEN
      v_new_achievement := jsonb_build_object(
        'achievement_id', 'perfectionist',
        'name', (SELECT name FROM public.minesweeper_achievements WHERE id = 'perfectionist'),
        'icon', (SELECT icon FROM public.minesweeper_achievements WHERE id = 'perfectionist'),
        'difficulty', v_game.difficulty
      );
      v_unlocked_achievements := v_unlocked_achievements || v_new_achievement;
    END IF;
  END IF;

  -- ============================================================================
  -- Achievement 4: "Vitesse éclair" (Lightning Speed) - Difficulty Specific
  -- ============================================================================

  -- Determine time threshold based on difficulty
  v_time_threshold := CASE v_game.difficulty
    WHEN 'beginner' THEN 60
    WHEN 'intermediate' THEN 180
    WHEN 'expert' THEN 300
  END;

  IF v_game.time_seconds < v_time_threshold THEN
    INSERT INTO public.minesweeper_student_achievements (
      student_id,
      achievement_id,
      difficulty,
      game_id
    )
    VALUES (v_student_id, 'lightning_speed', v_game.difficulty, p_game_id)
    ON CONFLICT (student_id, achievement_id, difficulty) DO NOTHING;

    IF FOUND THEN
      v_new_achievement := jsonb_build_object(
        'achievement_id', 'lightning_speed',
        'name', (SELECT name FROM public.minesweeper_achievements WHERE id = 'lightning_speed'),
        'icon', (SELECT icon FROM public.minesweeper_achievements WHERE id = 'lightning_speed'),
        'difficulty', v_game.difficulty
      );
      v_unlocked_achievements := v_unlocked_achievements || v_new_achievement;
    END IF;
  END IF;

  -- Return array of newly unlocked achievements
  RETURN v_unlocked_achievements;
END;
$$;


ALTER FUNCTION "public"."check_and_unlock_achievements"("p_game_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_and_unlock_achievements"("p_game_id" "uuid") IS 'Checks all achievement unlock conditions for a completed game and inserts new unlocks. Returns JSONB array of newly unlocked achievements for notification display. SECURITY DEFINER prevents direct manipulation.';



CREATE OR REPLACE FUNCTION "public"."check_daily_trade_limit"("p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_trade_count INTEGER;
  v_max_trades INTEGER;
BEGIN
  -- Get max trades per day from config (default 10)
  SELECT COALESCE(MAX(max_trades_per_day), 10) INTO v_max_trades
  FROM marketplace_config mc
  JOIN classes c ON c.school_id = mc.school_id
  JOIN class_members cm ON cm.class_id = c.id
  WHERE cm.student_id = p_user_id;

  -- Count trades created or participated in today
  SELECT COUNT(*) INTO v_trade_count
  FROM marketplace_trades
  WHERE (initiator_id = p_user_id OR partner_id = p_user_id)
    AND status = 'completed'
    AND completed_at >= CURRENT_DATE
    AND completed_at < CURRENT_DATE + INTERVAL '1 day';

  RETURN json_build_object(
    'success', true,
    'can_create_trade', v_trade_count < v_max_trades,
    'trades_today', v_trade_count,
    'max_trades', v_max_trades,
    'remaining_trades', GREATEST(0, v_max_trades - v_trade_count)
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."check_daily_trade_limit"("p_user_id" "uuid") OWNER TO "postgres";


