CREATE OR REPLACE FUNCTION "public"."check_gidouilles_balance"("p_user_id" "uuid", "p_required_amount" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_balance INTEGER;
BEGIN
  -- Get current balance with lock to prevent race conditions
  SELECT gidouilles INTO v_balance
  FROM profiles
  WHERE id = p_user_id
  FOR UPDATE NOWAIT;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Utilisateur introuvable'
    );
  END IF;

  RETURN json_build_object(
    'success', true,
    'has_sufficient_balance', v_balance >= p_required_amount,
    'current_balance', v_balance,
    'required_amount', p_required_amount,
    'deficit', GREATEST(0, p_required_amount - v_balance)
  );

EXCEPTION
  WHEN lock_not_available THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Une autre transaction est en cours'
    );
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."check_gidouilles_balance"("p_user_id" "uuid", "p_required_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_marketplace_enabled"("p_student_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_class_id UUID;
    v_class_enabled BOOLEAN;
BEGIN
    -- Get student's class
    SELECT cm.class_id INTO v_class_id
    FROM public.class_members cm
    WHERE cm.student_id = p_student_id
    LIMIT 1;

    IF v_class_id IS NULL THEN
        RETURN false;
    END IF;

    -- Check class-level config (new approach: config per class)
    SELECT mc.enabled_for_class INTO v_class_enabled
    FROM public.marketplace_config mc
    WHERE mc.class_id = v_class_id;

    -- If class config exists, use its enabled_for_class value
    IF v_class_enabled IS NOT NULL THEN
        RETURN v_class_enabled;
    END IF;

    -- No class config found - marketplace is disabled by default
    RETURN false;
END;
$$;


ALTER FUNCTION "public"."check_marketplace_enabled"("p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_marketplace_enabled"("p_student_id" "uuid") IS 'Check if marketplace is enabled for a student based on their class config';



CREATE OR REPLACE FUNCTION "public"."check_match_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID := auth.uid();
  v_match RECORD;
BEGIN
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check for active match
  SELECT
    m.id,
    m.match_type,
    m.difficulty,
    m.seed,
    m.status,
    CASE
      WHEN m.player1_id = v_student_id THEN m.player2_id
      ELSE m.player1_id
    END AS opponent_id,
    CASE
      WHEN m.player1_id = v_student_id THEN 1
      ELSE 2
    END AS player_number
  INTO v_match
  FROM minesweeper_multiplayer_matches m
  WHERE (m.player1_id = v_student_id OR m.player2_id = v_student_id)
    AND m.status IN ('countdown', 'in_progress')
  ORDER BY m.created_at DESC
  LIMIT 1;

  IF v_match.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'in_match', true,
      'match_id', v_match.id,
      'opponent_id', v_match.opponent_id,
      'seed', v_match.seed,
      'difficulty', v_match.difficulty,
      'match_type', v_match.match_type,
      'status', v_match.status,
      'player_number', v_match.player_number
    );
  ELSE
    RETURN jsonb_build_object(
      'in_match', false
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_match_status"() OWNER TO "postgres";


