CREATE OR REPLACE FUNCTION "public"."check_perimeter_skill_is_competence"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_family text;
BEGIN
    SELECT family INTO v_family
      FROM public.skills
     WHERE id = NEW.skill_id;

    IF v_family IS DISTINCT FROM 'competence' THEN
        RAISE EXCEPTION
            'evaluation_task_perimeter.skill_id must reference a competence skill (got family=%)',
            v_family;
    END IF;

    RETURN NEW;
END $$;


