CREATE OR REPLACE FUNCTION "public"."check_profanity_simple"("p_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_bad_words TEXT[] := ARRAY['merde', 'putain', 'connard', 'salope']; -- Basic French profanity list
  v_word TEXT;
BEGIN
  -- Convert to lowercase for comparison
  p_text := LOWER(p_text);

  -- Check each bad word
  FOREACH v_word IN ARRAY v_bad_words
  LOOP
    IF position(v_word IN p_text) > 0 THEN
      RETURN true;
    END IF;
  END LOOP;

  RETURN false;
END;
$$;


