CREATE OR REPLACE FUNCTION "public"."cleanup_abandoned_minesweeper_games"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted_count INTEGER := 0;
  v_temp INTEGER;
BEGIN
  -- Delete public games (student_id IS NULL) older than 24 hours and in_progress
  DELETE FROM public.minesweeper_games
  WHERE student_id IS NULL
    AND status = 'in_progress'
    AND created_at < NOW() - INTERVAL '24 hours';

  GET DIAGNOSTICS v_temp = ROW_COUNT;
  v_deleted_count := v_temp;

  -- Delete in-progress authenticated games older than 7 days
  DELETE FROM public.minesweeper_games
  WHERE student_id IS NOT NULL
    AND status = 'in_progress'
    AND created_at < NOW() - INTERVAL '7 days';

  GET DIAGNOSTICS v_temp = ROW_COUNT;
  v_deleted_count := v_deleted_count + v_temp;

  RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_abandoned_minesweeper_games"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_abandoned_minesweeper_games"() IS 'Cleanup job to delete abandoned in-progress games: public games >24h old, authenticated games >7 days old. Returns count of deleted games. Should be scheduled via cron.';



