CREATE OR REPLACE FUNCTION "public"."cleanup_stale_presence"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  UPDATE user_presence
  SET status = 'offline', updated_at = now()
  WHERE status = 'online'
  AND last_heartbeat < now() - interval '270 seconds';
  -- Changed from '2 minutes' to '270 seconds' (4.5 minutes)
  -- Accommodates 180s heartbeat + 90s buffer for reliability
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_presence"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_stale_presence"() IS 'Marks users offline if no heartbeat in 270s (180s heartbeat + 90s grace period). Optimized for Supabase Realtime with 180s heartbeat strategy to stay within 2M messages/month free tier.';



CREATE OR REPLACE FUNCTION "public"."cleanup_stale_queue_entries"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  DELETE FROM public.minesweeper_multiplayer_queue
  WHERE
    -- Remove entries older than 1 hour
    joined_at < NOW() - INTERVAL '1 hour'
    -- OR remove matched/cancelled entries older than 5 minutes
    OR (status IN ('matched', 'cancelled') AND joined_at < NOW() - INTERVAL '5 minutes');
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_queue_entries"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_stale_queue_entries"() IS 'Removes old queue entries (>1 hour) and matched/cancelled entries (>5 minutes)';



CREATE OR REPLACE FUNCTION "public"."cleanup_stale_trades"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_cancelled_count INTEGER;
    v_stale_threshold INTERVAL := INTERVAL '30 minutes';
BEGIN
    -- Start job tracking (same as Vercel cron jobs)
    v_run_id := start_job_run('cleanup_stale_trades', '{}'::jsonb);

    BEGIN
        -- Cancel stale trades (negotiating status, no activity for 30+ minutes)
        UPDATE marketplace_trades
        SET
            status = 'cancelled',
            cancelled_at = NOW(),
            updated_at = NOW()
        WHERE status = 'negotiating'
          AND updated_at < NOW() - v_stale_threshold;

        GET DIAGNOSTICS v_cancelled_count = ROW_COUNT;

        -- Log result
        IF v_cancelled_count > 0 THEN
            RAISE NOTICE '[cleanup_stale_trades] Cancelled % stale trades', v_cancelled_count;
        END IF;

        -- Complete job successfully
        PERFORM complete_job_run(
            v_run_id,
            'success',
            NULL,
            jsonb_build_object(
                'cancelled_count', v_cancelled_count,
                'threshold_minutes', 30
            )
        );

    EXCEPTION WHEN OTHERS THEN
        -- Complete job with failure
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object('cancelled_count', COALESCE(v_cancelled_count, 0))
        );
        -- Re-raise to ensure proper error handling
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_trades"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_stale_trades"() IS 'Cancels marketplace trades that have been inactive for 30+ minutes. Called by pg_cron every 10 minutes. Logs to background_job_runs for monitoring.';



CREATE OR REPLACE FUNCTION "public"."cleanup_stuck_job_runs"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_stuck_count INTEGER;
    v_stuck_threshold INTERVAL := INTERVAL '1 hour';
BEGIN
    -- Start job run tracking
    v_run_id := start_job_run('cleanup_stuck_job_runs', '{}'::jsonb);

    BEGIN
        -- Mark stuck jobs as timeout
        -- Use max INTEGER value for execution_time_ms to avoid overflow
        UPDATE background_job_runs
        SET
            status = 'timeout',
            completed_at = NOW(),
            execution_time_ms = 2147483647,  -- Max INT (job ran too long to measure)
            error_message = 'Auto-marked as timeout: job exceeded 1 hour runtime'
        WHERE status = 'running'
          AND started_at < NOW() - v_stuck_threshold;

        GET DIAGNOSTICS v_stuck_count = ROW_COUNT;

        -- Complete job run with success
        PERFORM complete_job_run(
            v_run_id,
            'success',
            NULL,
            jsonb_build_object(
                'stuck_jobs_marked', v_stuck_count,
                'threshold_hours', 1
            )
        );

    EXCEPTION WHEN OTHERS THEN
        -- Complete job run with failure
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object('stuck_jobs_marked', COALESCE(v_stuck_count, 0))
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."cleanup_stuck_job_runs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_stuck_job_runs"() IS 'pg_cron job that marks jobs stuck in running status > 1 hour as timeout.
     Runs every hour at minute 30.';



CREATE OR REPLACE FUNCTION "public"."complete_job_run"("p_run_id" "uuid", "p_status" "text", "p_error_message" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_started_at TIMESTAMPTZ; v_execution_time INTEGER; BEGIN SELECT started_at
  INTO v_started_at FROM public.background_job_runs WHERE id = p_run_id; v_execution_time := EXTRACT(EPOCH FROM (now() - v_started_at)) * 1000; UPDATE
  public.background_job_runs SET status = p_status, completed_at = now(), error_message = p_error_message, execution_time_ms = v_execution_time, metadata =
  COALESCE(p_metadata, metadata) WHERE id = p_run_id; END; $$;


ALTER FUNCTION "public"."complete_job_run"("p_run_id" "uuid", "p_status" "text", "p_error_message" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_job_run"("p_run_id" "uuid", "p_status" "text", "p_error_message" "text", "p_metadata" "jsonb") IS 'Completes a job run with status (success/failed/timeout).';



CREATE OR REPLACE FUNCTION "public"."complete_minesweeper_game"("p_game_id" "uuid", "p_grid_state" "jsonb") RETURNS TABLE("gidouilles_earned" numeric, "achievements" "jsonb", "points_earned" integer, "breakdown" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_game_record RECORD;
  v_user_role TEXT;
  v_time_seconds INTEGER;
  v_gidouilles NUMERIC(10,2);
  v_points INTEGER;
  v_is_valid BOOLEAN;
  v_grid_size INTEGER;
  v_unlocked_achievements JSONB;
  v_reduced_penalty_hints INTEGER;

  v_student_grade TEXT;
  v_cycle TEXT;
  v_school_id UUID;

  v_base_reward NUMERIC(10,2);
  v_reference_time INTEGER;
  v_time_ratio NUMERIC;
  v_time_mult NUMERIC;
  v_hints_gidouilles INTEGER;
  v_hints_reduced INTEGER;
  v_hint_penalty NUMERIC;
  v_breakdown JSONB;

  v_theoretical_reward NUMERIC(10,2);
  v_actual_reward NUMERIC(10,2);
  v_is_first_win BOOLEAN;
  v_week_best_reward NUMERIC(10,2);
  v_daily_result RECORD;

  v_gidouilles_penalties NUMERIC[] := ARRAY[0.0, 0.10, 0.22, 0.35];
  v_reduced_penalties NUMERIC[] := ARRAY[0.0, 0.05, 0.11, 0.17];

  -- Leaderboard evolution
  v_old_avg_top10 NUMERIC(10,1);
  v_new_avg_top10 NUMERIC(10,1);
  v_old_rank INTEGER;
  v_new_rank INTEGER;
BEGIN
  -- Step 1: Get game and verify ownership
  SELECT * INTO v_game_record
  FROM public.minesweeper_games
  WHERE id = p_game_id
    AND student_id = auth.uid()
    AND status = 'in_progress';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found, not owned by you, or already completed';
  END IF;

  -- Step 2: Get user role and grade
  SELECT role, grade INTO v_user_role, v_student_grade
  FROM public.profiles
  WHERE id = v_game_record.student_id;

  v_cycle := public.get_cycle_for_grade(v_student_grade);

  -- Get school_id for daily limit calculation (from ACTIVE membership)
  SELECT DISTINCT c.school_id INTO v_school_id
  FROM public.class_members cm
  JOIN public.classes c ON c.id = cm.class_id
  WHERE cm.student_id = v_game_record.student_id
    AND cm.status = 'active'
  LIMIT 1;

  -- Calculate old avg_top10 and rank BEFORE updating the game
  SELECT ROUND(AVG(pe), 1) INTO v_old_avg_top10
  FROM (
    SELECT mg.points_earned AS pe
    FROM public.minesweeper_games mg
    WHERE mg.student_id = v_game_record.student_id
      AND mg.status = 'won'
      AND mg.points_earned > 0
    ORDER BY mg.points_earned DESC
    LIMIT 10
  ) top10;

  -- Get old rank from leaderboard view
  SELECT rank INTO v_old_rank
  FROM public.minesweeper_leaderboard
  WHERE student_id = v_game_record.student_id;

  -- Step 3: Validate grid_state represents a legitimate win
  v_is_valid := public.validate_minesweeper_win(p_grid_state, v_game_record.difficulty);

  IF NOT v_is_valid THEN
    RAISE EXCEPTION 'Invalid grid state: does not represent a valid win condition';
  END IF;

  -- Step 4: Validate grid_state size
  v_grid_size := pg_column_size(p_grid_state);
  IF v_grid_size > 100000 THEN
    RAISE EXCEPTION 'Grid state too large: exceeds 100KB';
  END IF;

  -- Step 5: Calculate time_seconds server-side
  IF v_game_record.started_at IS NOT NULL THEN
    v_time_seconds := GREATEST(1, EXTRACT(EPOCH FROM (NOW() - v_game_record.started_at))::INTEGER);
  ELSE
    v_time_seconds := 1;
  END IF;

  CASE v_game_record.difficulty
    WHEN 'beginner' THEN v_time_seconds := LEAST(v_time_seconds, 3600);
    WHEN 'intermediate' THEN v_time_seconds := LEAST(v_time_seconds, 7200);
    WHEN 'expert' THEN v_time_seconds := LEAST(v_time_seconds, 14400);
  END CASE;

  v_reduced_penalty_hints := COALESCE(v_game_record.reduced_penalty_hints, 0);

  -- Step 6a: Determine base reward
  CASE v_game_record.difficulty
    WHEN 'beginner' THEN v_base_reward := 1.0;
    WHEN 'intermediate' THEN v_base_reward := 3.0;
    WHEN 'expert' THEN v_base_reward := 6.0;
    ELSE v_base_reward := 0.0;
  END CASE;

  -- Step 6b: Get dynamic reference time
  IF v_cycle IS NOT NULL THEN
    BEGIN
      v_reference_time := public.get_minesweeper_reference_time(v_cycle, v_game_record.difficulty);
    EXCEPTION
      WHEN raise_exception THEN
        v_reference_time := CASE v_game_record.difficulty
          WHEN 'beginner' THEN 180
          WHEN 'intermediate' THEN 600
          WHEN 'expert' THEN 1200
        END;
    END;
  ELSE
    v_reference_time := CASE v_game_record.difficulty
      WHEN 'beginner' THEN 180
      WHEN 'intermediate' THEN 600
      WHEN 'expert' THEN 1200
    END;
  END IF;

  -- Step 6c: Calculate time multiplier
  v_time_ratio := v_time_seconds::NUMERIC / v_reference_time;
  v_time_mult := GREATEST(0.7, 1.3 - 0.3 * v_time_ratio);
  v_time_mult := ROUND(v_time_mult, 2);

  -- Step 6d: Calculate hint penalty
  v_hints_reduced := COALESCE(v_reduced_penalty_hints, 0);
  v_hints_gidouilles := COALESCE(v_game_record.hints_used, 0) - v_hints_reduced;
  v_hints_gidouilles := GREATEST(0, v_hints_gidouilles);
  v_hints_reduced := GREATEST(0, v_hints_reduced);

  v_hint_penalty := 0.0;
  IF v_hints_gidouilles > 0 THEN
    v_hint_penalty := v_hint_penalty + v_gidouilles_penalties[LEAST(v_hints_gidouilles, 3) + 1];
  END IF;
  IF v_hints_reduced > 0 THEN
    v_hint_penalty := v_hint_penalty + v_reduced_penalties[LEAST(v_hints_reduced, 3) + 1];
  END IF;
  v_hint_penalty := LEAST(0.50, v_hint_penalty);
  v_hint_penalty := ROUND(v_hint_penalty, 2);

  -- Calculate theoretical reward
  IF v_user_role = 'student' AND v_cycle IS NOT NULL THEN
    v_theoretical_reward := v_base_reward * v_time_mult * (1.0 - v_hint_penalty);
    v_theoretical_reward := GREATEST(0.30, v_theoretical_reward);
    v_theoretical_reward := LEAST(8.00, v_theoretical_reward);
    v_theoretical_reward := ROUND(v_theoretical_reward, 2);
  ELSE
    v_theoretical_reward := 0.0;
  END IF;

  -- Call record_game_reward to get actual reward
  IF v_user_role = 'student' AND v_theoretical_reward > 0 AND v_school_id IS NOT NULL THEN
    SELECT * INTO v_daily_result
    FROM public.record_game_reward(
      v_game_record.student_id,
      'minesweeper',
      p_game_id,
      v_theoretical_reward,
      v_school_id
    );

    v_actual_reward := COALESCE(v_daily_result.actual_reward, 0);
    v_is_first_win := COALESCE(v_daily_result.is_first_win, FALSE);
    v_week_best_reward := COALESCE(v_daily_result.week_best_reward, v_theoretical_reward);
    v_gidouilles := v_actual_reward;
  ELSE
    v_actual_reward := 0;
    v_is_first_win := FALSE;
    v_week_best_reward := 0;
    v_gidouilles := 0;
  END IF;

  -- Step 7: Calculate points
  v_points := public.calculate_minesweeper_points(
    v_game_record.difficulty,
    v_time_seconds,
    COALESCE(v_game_record.hints_used, 0),
    v_game_record.student_id
  );

  -- Step 8: Update game record
  UPDATE public.minesweeper_games
  SET
    status = 'won',
    completed_at = NOW(),
    time_seconds = v_time_seconds,
    gidouilles_awarded = v_actual_reward,
    points_earned = v_points,
    grid_state = p_grid_state
  WHERE id = p_game_id;

  -- Calculate new avg_top10 and rank AFTER updating the game
  SELECT ROUND(AVG(pe), 1) INTO v_new_avg_top10
  FROM (
    SELECT mg.points_earned AS pe
    FROM public.minesweeper_games mg
    WHERE mg.student_id = v_game_record.student_id
      AND mg.status = 'won'
      AND mg.points_earned > 0
    ORDER BY mg.points_earned DESC
    LIMIT 10
  ) top10;

  -- Get new rank from leaderboard view
  SELECT rank INTO v_new_rank
  FROM public.minesweeper_leaderboard
  WHERE student_id = v_game_record.student_id;

  v_breakdown := jsonb_build_object(
    'cycle', v_cycle,
    'base_reward', v_base_reward,
    'reference_time', v_reference_time,
    'time_seconds', v_time_seconds,
    'time_mult', v_time_mult,
    'hints_used', COALESCE(v_game_record.hints_used, 0),
    'reduced_penalty_hints', v_reduced_penalty_hints,
    'hint_penalty', v_hint_penalty,
    'theoretical_reward', v_theoretical_reward,
    'actual_reward', v_actual_reward,
    'is_first_win_of_day', v_is_first_win,
    'week_best_reward', v_week_best_reward,
    'old_avg_top10', COALESCE(v_old_avg_top10, 0),
    'new_avg_top10', COALESCE(v_new_avg_top10, 0),
    'old_rank', v_old_rank,
    'new_rank', COALESCE(v_new_rank, 1)
  );

  -- Step 9: Check and unlock achievements
  v_unlocked_achievements := public.check_and_unlock_achievements(p_game_id);

  RETURN QUERY SELECT v_gidouilles, v_unlocked_achievements, v_points, v_breakdown;
END;
$$;


ALTER FUNCTION "public"."complete_minesweeper_game"("p_game_id" "uuid", "p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_minesweeper_game"("p_game_id" "uuid", "p_grid_state" "jsonb") IS 'Completes Minesweeper game. Returns breakdown with leaderboard evolution (old/new avg_top10 and rank).';



CREATE OR REPLACE FUNCTION "public"."complete_multiplayer_match"("p_match_id" "uuid", "p_time_seconds" integer, "p_grid_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_student_id UUID;
  v_match RECORD;
  v_opponent_id UUID;
  v_base_gidouilles INTEGER;
  v_bonus_gidouilles INTEGER := 0;
  v_total_gidouilles INTEGER;
  v_elo_change INTEGER;
  v_winner_stats RECORD;
  v_loser_stats RECORD;
  v_season TEXT;
  v_difficulty_config RECORD;
BEGIN
  -- Get authenticated student ID
  v_student_id := auth.uid();
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Non authentifié';
  END IF;

  -- Fetch match details WITH LOCK to prevent race condition
  SELECT * INTO v_match
  FROM minesweeper_multiplayer_matches
  WHERE id = p_match_id
  FOR UPDATE;  -- CRITICAL: Locks row until transaction completes

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Match introuvable';
  END IF;

  -- Verify player is a participant
  IF v_match.player1_id != v_student_id AND v_match.player2_id != v_student_id THEN
    RAISE EXCEPTION 'Vous ne participez pas à ce match';
  END IF;

  -- Verify match is in progress
  IF v_match.status != 'in_progress' THEN
    RAISE EXCEPTION 'Le match n''est pas en cours (status: %)', v_match.status;
  END IF;

  -- Verify match hasn't already been completed
  IF v_match.winner_id IS NOT NULL THEN
    RAISE EXCEPTION 'Le match est déjà terminé';
  END IF;

  -- Validate time bounds (min 10s, max 2 hours)
  IF p_time_seconds < 10 OR p_time_seconds > 7200 THEN
    RAISE EXCEPTION 'Temps invalide: %s secondes', p_time_seconds;
  END IF;

  -- Get current season (needed for ELO queries)
  v_season := TO_CHAR(NOW(), 'YYYY-MM');

  -- SERVER-SIDE WIN VALIDATION
  -- Reuse the existing validate_minesweeper_win function
  -- This function checks:
  -- 1. All non-mine cells are revealed
  -- 2. No mines are revealed
  -- 3. Grid dimensions match difficulty
  IF NOT EXISTS (
    SELECT 1 FROM public.validate_minesweeper_win(
      p_grid_state,
      v_match.difficulty
    )
  ) THEN
    RAISE EXCEPTION 'La grille soumise n''est pas une victoire valide';
  END IF;

  -- Determine opponent
  IF v_match.player1_id = v_student_id THEN
    v_opponent_id := v_match.player2_id;
  ELSE
    v_opponent_id := v_match.player1_id;
  END IF;

  -- Get difficulty configuration for rewards
  SELECT * INTO v_difficulty_config
  FROM (VALUES
    ('beginner', 9, 9, 10, 20, 25, 180),
    ('intermediate', 16, 16, 40, 50, 60, 600),
    ('expert', 16, 30, 99, 100, 120, 1200)
  ) AS configs(difficulty, rows, cols, mines, quick_reward, ranked_reward, base_time)
  WHERE difficulty = v_match.difficulty;

  -- Calculate base gidouilles based on match type
  IF v_match.match_type = 'quick' THEN
    v_base_gidouilles := v_difficulty_config.quick_reward;
  ELSIF v_match.match_type = 'ranked' THEN
    v_base_gidouilles := v_difficulty_config.ranked_reward;
  ELSE
    v_base_gidouilles := v_difficulty_config.quick_reward; -- Default to quick
  END IF;

  -- Speed bonus: +20% if under base_time / 2
  IF p_time_seconds < (v_difficulty_config.base_time / 2) THEN
    v_bonus_gidouilles := ROUND(v_base_gidouilles * 0.2);
  END IF;

  v_total_gidouilles := v_base_gidouilles + v_bonus_gidouilles;

  -- Get current ELO ratings (filter by current season)
  SELECT rank INTO v_winner_stats
  FROM minesweeper_player_stats
  WHERE student_id = v_student_id AND season = v_season;

  SELECT rank INTO v_loser_stats
  FROM minesweeper_player_stats
  WHERE student_id = v_opponent_id AND season = v_season;

  -- Default ELO if no stats exist yet
  IF v_winner_stats IS NULL THEN
    v_winner_stats := ROW(1500);
  END IF;
  IF v_loser_stats IS NULL THEN
    v_loser_stats := ROW(1500);
  END IF;

  -- Calculate ELO change (only for ranked matches)
  IF v_match.match_type = 'ranked' THEN
    v_elo_change := calculate_elo_change(
      v_winner_stats.rank,
      v_loser_stats.rank
    );
  ELSE
    v_elo_change := 0; -- No ELO change for quick/challenge matches
  END IF;

  -- Update match record
  UPDATE minesweeper_multiplayer_matches
  SET
    status = 'completed',
    winner_id = v_student_id,
    completed_at = NOW(),
    duration_seconds = p_time_seconds,
    winner_reward = v_total_gidouilles,
    loser_reward = 0, -- Loser gets nothing in competitive mode
    elo_change = v_elo_change
  WHERE id = p_match_id;

  -- Award gidouilles to winner
  INSERT INTO gidouilles_history (
    student_id,
    amount,
    reason,
    description
  ) VALUES (
    v_student_id,
    v_total_gidouilles,
    'minesweeper_multiplayer_win',
    FORMAT('Victoire multijoueur (%s, %s)', v_match.difficulty, v_match.match_type)
  );

  -- Update winner stats
  INSERT INTO minesweeper_player_stats (
    student_id,
    season,
    games_played,
    games_won,
    rank,
    win_streak
  ) VALUES (
    v_student_id,
    v_season,
    1,
    1,
    COALESCE(v_winner_stats.rank, 1500) + v_elo_change,
    1
  )
  ON CONFLICT (student_id, season) DO UPDATE
  SET
    games_played = minesweeper_player_stats.games_played + 1,
    games_won = minesweeper_player_stats.games_won + 1,
    rank = EXCLUDED.rank, -- Use pre-calculated rank directly (already includes ELO change)
    win_streak = minesweeper_player_stats.win_streak + 1,
    best_win_streak = GREATEST(
      minesweeper_player_stats.best_win_streak,
      minesweeper_player_stats.win_streak + 1
    ),
    updated_at = NOW();

  -- Update loser stats
  INSERT INTO minesweeper_player_stats (
    student_id,
    season,
    games_played,
    games_won,
    rank,
    win_streak
  ) VALUES (
    v_opponent_id,
    v_season,
    1,
    0,
    GREATEST(0, COALESCE(v_loser_stats.rank, 1500) - v_elo_change), -- Can't go below 0
    0
  )
  ON CONFLICT (student_id, season) DO UPDATE
  SET
    games_played = minesweeper_player_stats.games_played + 1,
    rank = EXCLUDED.rank, -- Use pre-calculated rank directly (already includes ELO loss and floor at 0)
    win_streak = 0, -- Reset streak
    updated_at = NOW();

  -- Return success with rewards info
  RETURN jsonb_build_object(
    'success', true,
    'winner_id', v_student_id,
    'gidouilles', v_total_gidouilles,
    'base_reward', v_base_gidouilles,
    'speed_bonus', v_bonus_gidouilles,
    'elo_change', v_elo_change,
    'new_elo', COALESCE(v_winner_stats.rank, 1500) + v_elo_change,
    'time_seconds', p_time_seconds
  );
END;
$$;


ALTER FUNCTION "public"."complete_multiplayer_match"("p_match_id" "uuid", "p_time_seconds" integer, "p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_multiplayer_match"("p_match_id" "uuid", "p_time_seconds" integer, "p_grid_state" "jsonb") IS 'Complete multiplayer match with win validation and rewards distribution';



CREATE OR REPLACE FUNCTION "public"."complete_tournament_game"("p_game_id" "uuid", "p_status" "text", "p_time_seconds" integer, "p_grid_state" "jsonb") RETURNS TABLE("success" boolean, "final_status" "text", "grid_3bv" integer, "score" integer, "actual_3bvs" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_game RECORD;
  v_tournament RECORD;
  v_student_grade TEXT;
  v_cycle TEXT;
  v_grid_3bv INTEGER;
  v_score INTEGER;
  v_actual_3bvs NUMERIC;
BEGIN
  -- Step 1: Verify game exists and belongs to current user
  SELECT g.*, t.difficulty
  INTO v_game
  FROM public.minesweeper_tournament_games g
  JOIN public.minesweeper_tournaments t ON t.id = g.tournament_id
  WHERE g.id = p_game_id
    AND g.student_id = auth.uid()
    AND g.status = 'in_progress';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found, not owned by you, or already completed';
  END IF;

  -- Step 2: Validate status
  IF p_status NOT IN ('won', 'lost') THEN
    RAISE EXCEPTION 'Invalid status: must be won or lost';
  END IF;

  -- Step 3: For wins, calculate 3BV and score
  IF p_status = 'won' THEN
    -- Validate grid state represents a win
    IF NOT public.validate_minesweeper_win(p_grid_state, v_game.difficulty) THEN
      RAISE EXCEPTION 'Invalid grid state: does not represent a valid win';
    END IF;

    -- Calculate 3BV
    v_grid_3bv := public.calculate_3bv(p_grid_state);

    -- Get student's cycle
    SELECT grade INTO v_student_grade
    FROM public.profiles
    WHERE id = v_game.student_id;

    v_cycle := public.get_cycle_for_grade(v_student_grade);

    -- Calculate score (with fallback if no cycle)
    IF v_cycle IS NOT NULL THEN
      v_score := public.calculate_tournament_score(v_grid_3bv, p_time_seconds, v_cycle, v_game.difficulty);
    ELSE
      -- Fallback: use cycle_3 as default
      v_score := public.calculate_tournament_score(v_grid_3bv, p_time_seconds, 'cycle_3', v_game.difficulty);
    END IF;

    v_actual_3bvs := v_grid_3bv::NUMERIC / GREATEST(1, p_time_seconds);
  ELSE
    -- Lost game: no 3BV or score
    v_grid_3bv := NULL;
    v_score := NULL;
    v_actual_3bvs := NULL;
  END IF;

  -- Step 4: Update game record
  UPDATE public.minesweeper_tournament_games
  SET
    status = p_status,
    time_seconds = CASE WHEN p_status = 'won' THEN p_time_seconds ELSE NULL END,
    grid_state = p_grid_state,
    grid_3bv = v_grid_3bv,
    score = v_score,
    completed_at = NOW()
  WHERE id = p_game_id;

  -- Step 5: Return result
  success := TRUE;
  final_status := p_status;
  grid_3bv := v_grid_3bv;
  score := v_score;
  actual_3bvs := v_actual_3bvs;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."complete_tournament_game"("p_game_id" "uuid", "p_status" "text", "p_time_seconds" integer, "p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_tournament_game"("p_game_id" "uuid", "p_status" "text", "p_time_seconds" integer, "p_grid_state" "jsonb") IS 'Completes a tournament game. For wins, calculates 3BV and score based on efficiency.
   Returns success, final_status, grid_3bv, score, and actual_3bvs.';



CREATE OR REPLACE FUNCTION "public"."compute_calculer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    v_a_count        integer;   -- A1..A3
    v_b_count        integer;   -- B1..B5
    v_c_count        integer;   -- C1..C3
    v_d1             boolean;
    v_d2             boolean;
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    v_a_count := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['A1','A2','A3']));
    v_b_count := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['B1','B2','B3','B4','B5']));
    v_c_count := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['C1','C2','C3']));
    v_d1      := ('D1' = ANY (v_acquired));
    v_d2      := ('D2' = ANY (v_acquired));

    -- Satisfaisante : (>=2 of B) AND (>=1 of A) AND (>=1 of D).
    v_satisfaisante := (v_b_count >= 2) AND (v_a_count >= 1) AND (v_d1 OR v_d2);

    -- Très bonne : Satisfaisante AND D1 AND D2 AND (>=3 of B) AND (>=2 of A) AND (>=1 of C).
    v_tres_bonne := v_satisfaisante
                AND v_d1 AND v_d2
                AND (v_b_count >= 3)
                AND (v_a_count >= 2)
                AND (v_c_count >= 1);

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        IF NOT v_d1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'D1');
        END IF;
        IF NOT v_d2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'D2');
        END IF;
        IF v_b_count < 3 THEN
            -- ≥ 3 among B1..B5
            v_missing := v_missing || jsonb_build_object(
                'kind', 'n_of_subdim', 'letter', 'B', 'n', 3, 'total', 5
            );
        END IF;
        IF v_a_count < 2 THEN
            -- ≥ 2 among A1..A3
            v_missing := v_missing || jsonb_build_object(
                'kind', 'n_of_subdim', 'letter', 'A', 'n', 2, 'total', 3
            );
        END IF;
        IF v_c_count < 1 THEN
            -- ≥ 1 of C
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'C');
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of B (Satisfaisante not reached).
    IF v_b_count >= 1 THEN
        -- Missing for Satisfaisante:
        IF v_b_count < 2 THEN
            -- ≥ 2 among B1..B5
            v_missing := v_missing || jsonb_build_object(
                'kind', 'n_of_subdim', 'letter', 'B', 'n', 2, 'total', 5
            );
        END IF;
        IF v_a_count < 1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A');
        END IF;
        IF NOT (v_d1 OR v_d2) THEN
            -- ≥ 1 among {D1, D2} (only first two D matter for Calculer Satisfaisante)
            v_missing := v_missing || jsonb_build_object(
                'kind', 'one_of_codes',
                'codes', jsonb_build_array('D1', 'D2')
            );
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    IF v_b_count < 1 THEN
        v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'B');
    END IF;

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_calculer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_calculer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Calculer. Cœur : D1+D2 (contrôle) + C (calcul littéral). See docs/wip/referentiel/college-competences.md §2.';



CREATE OR REPLACE FUNCTION "public"."compute_chercher_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    -- Per-subdimension counts and flags:
    v_a_count        integer;   -- acquired among A1..A3
    v_b_count        integer;   -- acquired among B1..B5
    v_b1             boolean;
    v_b2_b5_count    integer;   -- acquired among B2..B5
    v_c1             boolean;
    v_c2             boolean;
    v_d_count        integer;   -- acquired among D1..D3
    -- Derived predicates:
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    -- Missing list collector (typed JSONB objects — refactor 2026-06-09):
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    -- Load the set of observable codes acquired for this competence.
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id
             FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    -- Per-subdimension counts.
    v_a_count     := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['A1','A2','A3']));
    v_b_count     := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['B1','B2','B3','B4','B5']));
    v_b1          := ('B1' = ANY (v_acquired));
    v_b2_b5_count := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['B2','B3','B4','B5']));
    v_c1          := ('C1' = ANY (v_acquired));
    v_c2          := ('C2' = ANY (v_acquired));
    v_d_count     := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['D1','D2','D3']));

    -- Test Satisfaisante (used both for the level itself and as a precondition of Très bonne).
    v_satisfaisante := v_b1 AND (v_a_count >= 2) AND (v_b2_b5_count >= 1);

    -- Test Très bonne : Satisfaisante AND C2 AND C1 AND (>=1 of D).
    v_tres_bonne := v_satisfaisante AND v_c2 AND v_c1 AND (v_d_count >= 1);

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        -- Build the missing-for-next list (target = Très bonne).
        IF NOT v_c2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C2');
        END IF;
        IF NOT v_c1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C1');
        END IF;
        IF v_d_count < 1 THEN
            -- any one of D1/D2/D3
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'D');
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of A AND >=1 of B (Satisfaisante not reached).
    IF (v_a_count >= 1) AND (v_b_count >= 1) THEN
        -- Missing for Satisfaisante:
        IF NOT v_b1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B1');
        END IF;
        IF v_a_count < 2 THEN
            -- ≥ 2 of A1..A3
            v_missing := v_missing || jsonb_build_object(
                'kind', 'n_of_subdim', 'letter', 'A', 'n', 2, 'total', 3
            );
        END IF;
        IF v_b2_b5_count < 1 THEN
            -- ≥ 1 of B2..B5 (subset of B sub-dim)
            v_missing := v_missing || jsonb_build_object(
                'kind', 'one_of_codes',
                'codes', jsonb_build_array('B2', 'B3', 'B4', 'B5')
            );
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    -- Missing for Fragile:
    IF v_a_count < 1 THEN
        v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A');
    END IF;
    IF v_b_count < 1 THEN
        v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'B');
    END IF;

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_chercher_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_chercher_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Chercher. Cœur : C2 (réorientation). See docs/wip/referentiel/college-competences.md §1.';



CREATE OR REPLACE FUNCTION "public"."compute_communiquer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    v_a1             boolean;
    v_a2             boolean;
    v_b1             boolean;
    v_b2             boolean;
    v_c1             boolean;
    v_c2             boolean;
    v_a_count        integer;   -- A1..A2
    v_b_count        integer;   -- B1..B2
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    v_a1 := ('A1' = ANY (v_acquired));
    v_a2 := ('A2' = ANY (v_acquired));
    v_b1 := ('B1' = ANY (v_acquired));
    v_b2 := ('B2' = ANY (v_acquired));
    v_c1 := ('C1' = ANY (v_acquired));
    v_c2 := ('C2' = ANY (v_acquired));

    v_a_count := (CASE WHEN v_a1 THEN 1 ELSE 0 END) + (CASE WHEN v_a2 THEN 1 ELSE 0 END);
    v_b_count := (CASE WHEN v_b1 THEN 1 ELSE 0 END) + (CASE WHEN v_b2 THEN 1 ELSE 0 END);

    v_satisfaisante := (v_b_count >= 1) AND (v_a_count >= 1);

    v_tres_bonne := v_satisfaisante AND v_c1 AND v_c2 AND v_a1 AND v_a2;

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        IF NOT v_c1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C1');
        END IF;
        IF NOT v_c2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C2');
        END IF;
        IF NOT v_a1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A1');
        END IF;
        IF NOT v_a2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A2');
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of B OR >=1 of A.
    IF (v_b_count >= 1) OR (v_a_count >= 1) THEN
        -- Missing for Satisfaisante:
        IF v_b_count < 1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'B');
        END IF;
        IF v_a_count < 1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A');
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    v_missing := jsonb_build_array(
        jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A'),
        jsonb_build_object('kind', 'one_of_subdim', 'letter', 'B')
    );

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_communiquer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_communiquer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Communiquer. Cœur : C1+C2 (dialogue) + A1+A2 (langage). See docs/wip/referentiel/college-competences.md §4.';



CREATE OR REPLACE FUNCTION "public"."compute_competence_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_code text;
BEGIN
    SELECT code INTO v_code
      FROM public.math_competences
     WHERE id = p_math_competence_id;

    IF v_code IS NULL THEN
        RETURN;  -- Empty result set; defensive — unknown competence id.
    END IF;

    CASE v_code
        WHEN 'chercher'    THEN RETURN QUERY SELECT * FROM public.compute_chercher_level   (p_student_id, p_math_competence_id);
        WHEN 'calculer'    THEN RETURN QUERY SELECT * FROM public.compute_calculer_level   (p_student_id, p_math_competence_id);
        WHEN 'raisonner'   THEN RETURN QUERY SELECT * FROM public.compute_raisonner_level  (p_student_id, p_math_competence_id);
        WHEN 'communiquer' THEN RETURN QUERY SELECT * FROM public.compute_communiquer_level(p_student_id, p_math_competence_id);
        WHEN 'modeliser'   THEN RETURN QUERY SELECT * FROM public.compute_modeliser_level  (p_student_id, p_math_competence_id);
        WHEN 'representer' THEN RETURN QUERY SELECT * FROM public.compute_representer_level(p_student_id, p_math_competence_id);
        ELSE
            -- Unknown competence code; should never happen given the CHECK on math_competences.code
            RETURN;
    END CASE;
END $$;


ALTER FUNCTION "public"."compute_competence_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_competence_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — dispatch over the 6 conjunctive rule functions, keyed by math_competences.code.';



CREATE OR REPLACE FUNCTION "public"."compute_daily_summary"("p_student_id" "uuid", "p_class_id" "uuid", "p_summary_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_summary_id UUID;
    v_gidouilles_gained INTEGER;
    v_gidouilles_lost INTEGER;
    v_bonus_gained INTEGER;
    v_bonus_used INTEGER;
    v_warnings_issued INTEGER;
    v_warnings_removed INTEGER;
    v_vip_cards_gained INTEGER;
    v_vip_cards_used INTEGER;
    v_caller_role TEXT;
BEGIN
    -- SECURITY CHECK (Issue #1): Get caller's role to enforce authorization
    -- SECURITY DEFINER functions bypass RLS, so we must check permissions explicitly
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- Authorization: Only admins, teachers of the student, or service_role can compute summaries
    IF auth.uid() IS NOT NULL AND NOT (
        v_caller_role = 'admin'
        OR (v_caller_role = 'teacher' AND EXISTS (
            SELECT 1 FROM public.classes
            WHERE id = p_class_id
            AND teacher_id = auth.uid()
        ))
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have permission to compute summaries for this student';
    END IF;
    -- Calculate gidouilles (positive = gained, negative = lost)
    SELECT
        COALESCE(SUM(CASE WHEN delta > 0 THEN delta ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN delta < 0 THEN delta ELSE 0 END), 0)
    INTO v_gidouilles_gained, v_gidouilles_lost
    FROM public.gidouilles_history
    WHERE student_id = p_student_id
    AND class_id = p_class_id
    AND DATE(created_at) = p_summary_date;

    -- Calculate bonus (positive = gained, negative = used)
    SELECT
        COALESCE(SUM(CASE WHEN delta > 0 THEN delta ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN delta < 0 THEN delta ELSE 0 END), 0)
    INTO v_bonus_gained, v_bonus_used
    FROM public.bonus_history
    WHERE student_id = p_student_id
    AND class_id = p_class_id
    AND DATE(created_at) = p_summary_date;

    -- Calculate warnings (issued vs removed)
    -- FIX (Issue #9): Simplify confusing logic for warning calculations
    SELECT
        COUNT(*) FILTER (WHERE deleted_at IS NULL),
        COUNT(*) FILTER (WHERE deleted_at IS NOT NULL)
    INTO v_warnings_issued, v_warnings_removed
    FROM public.student_warnings
    WHERE student_id = p_student_id
    AND class_id = p_class_id
    AND DATE(created_at) = p_summary_date;

    -- Calculate VIP cards (gained vs used)
    SELECT
        COUNT(*) FILTER (WHERE action = 'gained'),
        COUNT(*) FILTER (WHERE action = 'used')
    INTO v_vip_cards_gained, v_vip_cards_used
    FROM public.vip_cards_activity
    WHERE student_id = p_student_id
    AND DATE(created_at) = p_summary_date;

    -- Insert or update the summary
    INSERT INTO public.daily_summaries (
        student_id,
        class_id,
        summary_date,
        gidouilles_gained,
        gidouilles_lost,
        bonus_gained,
        bonus_used,
        warnings_issued,
        warnings_removed,
        vip_cards_gained,
        vip_cards_used
    ) VALUES (
        p_student_id,
        p_class_id,
        p_summary_date,
        v_gidouilles_gained,
        v_gidouilles_lost,
        v_bonus_gained,
        v_bonus_used,
        v_warnings_issued,
        v_warnings_removed,
        v_vip_cards_gained,
        v_vip_cards_used
    )
    ON CONFLICT (student_id, class_id, summary_date)
    DO UPDATE SET
        gidouilles_gained = EXCLUDED.gidouilles_gained,
        gidouilles_lost = EXCLUDED.gidouilles_lost,
        bonus_gained = EXCLUDED.bonus_gained,
        bonus_used = EXCLUDED.bonus_used,
        warnings_issued = EXCLUDED.warnings_issued,
        warnings_removed = EXCLUDED.warnings_removed,
        vip_cards_gained = EXCLUDED.vip_cards_gained,
        vip_cards_used = EXCLUDED.vip_cards_used,
        updated_at = NOW()
    RETURNING id INTO v_summary_id;

    RETURN v_summary_id;
END;
$$;


ALTER FUNCTION "public"."compute_daily_summary"("p_student_id" "uuid", "p_class_id" "uuid", "p_summary_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_modeliser_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    v_a1             boolean;
    v_a2             boolean;
    v_a3             boolean;
    v_b1             boolean;
    v_b2             boolean;
    v_c1             boolean;
    v_c2             boolean;
    v_c3             boolean;
    v_a_count        integer;   -- A1..A3
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    v_a1 := ('A1' = ANY (v_acquired));
    v_a2 := ('A2' = ANY (v_acquired));
    v_a3 := ('A3' = ANY (v_acquired));
    v_b1 := ('B1' = ANY (v_acquired));
    v_b2 := ('B2' = ANY (v_acquired));
    v_c1 := ('C1' = ANY (v_acquired));
    v_c2 := ('C2' = ANY (v_acquired));
    v_c3 := ('C3' = ANY (v_acquired));

    v_a_count := (CASE WHEN v_a1 THEN 1 ELSE 0 END)
               + (CASE WHEN v_a2 THEN 1 ELSE 0 END)
               + (CASE WHEN v_a3 THEN 1 ELSE 0 END);

    v_satisfaisante := v_a2 AND v_a3 AND v_b1;

    v_tres_bonne := v_satisfaisante AND v_b2 AND v_c1 AND (v_c2 OR v_c3);

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        IF NOT v_b2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B2');
        END IF;
        IF NOT v_c1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C1');
        END IF;
        IF NOT (v_c2 OR v_c3) THEN
            -- ≥ 1 among {C2, C3}
            v_missing := v_missing || jsonb_build_object(
                'kind', 'one_of_codes',
                'codes', jsonb_build_array('C2', 'C3')
            );
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of A.
    IF v_a_count >= 1 THEN
        -- Missing for Satisfaisante:
        IF NOT v_a2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A2');
        END IF;
        IF NOT v_a3 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A3');
        END IF;
        IF NOT v_b1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B1');
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    v_missing := jsonb_build_array(
        jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A')
    );

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_modeliser_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_modeliser_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Modéliser. Cœur : C1 (validation) + B2 + (C2|C3). See docs/wip/referentiel/college-competences.md §5.';



CREATE OR REPLACE FUNCTION "public"."compute_raisonner_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    v_a1             boolean;
    v_b1             boolean;
    v_b2             boolean;
    v_c_count        integer;   -- C1..C3
    v_d1             boolean;
    v_d2             boolean;
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    v_a1      := ('A1' = ANY (v_acquired));
    v_b1      := ('B1' = ANY (v_acquired));
    v_b2      := ('B2' = ANY (v_acquired));
    v_c_count := (SELECT COUNT(*) FROM unnest(v_acquired) c WHERE c = ANY (ARRAY['C1','C2','C3']));
    v_d1      := ('D1' = ANY (v_acquired));
    v_d2      := ('D2' = ANY (v_acquired));

    v_satisfaisante := v_a1 AND v_b1;

    v_tres_bonne := v_satisfaisante AND v_b2 AND v_d2 AND (v_c_count >= 1);

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        IF NOT v_b2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B2');
        END IF;
        IF NOT v_d2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'D2');
        END IF;
        IF v_c_count < 1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'one_of_subdim', 'letter', 'C');
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of {A1, B1, D1}
    IF v_a1 OR v_b1 OR v_d1 THEN
        -- Missing for Satisfaisante:
        IF NOT v_a1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A1');
        END IF;
        IF NOT v_b1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B1');
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    -- Missing for Fragile : ≥ 1 of {A1, B1, D1} (cross-subdim, narrow set).
    v_missing := jsonb_build_array(
        jsonb_build_object(
            'kind', 'one_of_codes',
            'codes', jsonb_build_array('A1', 'B1', 'D1')
        )
    );

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_raisonner_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_raisonner_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Raisonner. Cœur : B2 (cas général) + D2 + C. See docs/wip/referentiel/college-competences.md §3.';



CREATE OR REPLACE FUNCTION "public"."compute_representer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") RETURNS TABLE("niveau" "text", "validated_observables" "jsonb", "missing_for_next" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_acquired       text[];
    v_a1             boolean;
    v_a2             boolean;
    v_b1             boolean;
    v_b2             boolean;
    v_c1             boolean;
    v_c2             boolean;
    v_d1             boolean;
    v_d2             boolean;
    v_a_count        integer;   -- A1..A2
    v_b_count        integer;   -- B1..B2
    v_satisfaisante  boolean;
    v_tres_bonne     boolean;
    v_missing        jsonb := '[]'::jsonb;
BEGIN
    SELECT COALESCE(array_agg(s.observable_code), ARRAY[]::text[])
      INTO v_acquired
      FROM public.student_observable_state sos
      JOIN public.skills s ON s.id = sos.skill_id
     WHERE sos.student_id = p_student_id
       AND sos.is_acquis  = TRUE
       AND s.subdimension_id IN (
           SELECT id FROM public.math_competence_subdimensions
            WHERE math_competence_id = p_math_competence_id
       );

    v_a1 := ('A1' = ANY (v_acquired));
    v_a2 := ('A2' = ANY (v_acquired));
    v_b1 := ('B1' = ANY (v_acquired));
    v_b2 := ('B2' = ANY (v_acquired));
    v_c1 := ('C1' = ANY (v_acquired));
    v_c2 := ('C2' = ANY (v_acquired));
    v_d1 := ('D1' = ANY (v_acquired));
    v_d2 := ('D2' = ANY (v_acquired));

    v_a_count := (CASE WHEN v_a1 THEN 1 ELSE 0 END) + (CASE WHEN v_a2 THEN 1 ELSE 0 END);
    v_b_count := (CASE WHEN v_b1 THEN 1 ELSE 0 END) + (CASE WHEN v_b2 THEN 1 ELSE 0 END);

    v_satisfaisante := v_a2 AND v_b1 AND v_b2;

    v_tres_bonne := v_satisfaisante AND v_c1 AND v_c2 AND (v_d1 OR v_d2);

    IF v_tres_bonne THEN
        RETURN QUERY SELECT 'tres_bonne'::text,
                            to_jsonb(v_acquired),
                            '[]'::jsonb;
        RETURN;
    END IF;

    IF v_satisfaisante THEN
        IF NOT v_c1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C1');
        END IF;
        IF NOT v_c2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'C2');
        END IF;
        IF NOT (v_d1 OR v_d2) THEN
            -- ≥ 1 among {D1, D2} (only first two D matter for Représenter)
            v_missing := v_missing || jsonb_build_object(
                'kind', 'one_of_codes',
                'codes', jsonb_build_array('D1', 'D2')
            );
        END IF;
        RETURN QUERY SELECT 'satisfaisante'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Fragile : >=1 of A OR >=1 of B.
    IF (v_a_count >= 1) OR (v_b_count >= 1) THEN
        -- Missing for Satisfaisante:
        IF NOT v_a2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'A2');
        END IF;
        IF NOT v_b1 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B1');
        END IF;
        IF NOT v_b2 THEN
            v_missing := v_missing || jsonb_build_object('kind', 'observable', 'code', 'B2');
        END IF;
        RETURN QUERY SELECT 'fragile'::text,
                            to_jsonb(v_acquired),
                            v_missing;
        RETURN;
    END IF;

    -- Insuffisante : residual.
    v_missing := jsonb_build_array(
        jsonb_build_object('kind', 'one_of_subdim', 'letter', 'A'),
        jsonb_build_object('kind', 'one_of_subdim', 'letter', 'B')
    );

    RETURN QUERY SELECT 'insuffisante'::text,
                        to_jsonb(v_acquired),
                        v_missing;
END $$;


ALTER FUNCTION "public"."compute_representer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compute_representer_level"("p_student_id" "uuid", "p_math_competence_id" "uuid") IS 'Decision 69 — conjunctive rule for Représenter. Cœur : C1+C2 (conversion + coordination) + 1 of D. See docs/wip/referentiel/college-competences.md §6.';



CREATE OR REPLACE FUNCTION "public"."count_student_active_cards"("p_student_id" "uuid", "p_card_id" "text", "p_lock_row" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
  v_vip_cards JSONB;
BEGIN
  -- Get student's VIP cards (with optional row lock for race condition prevention)
  IF p_lock_row THEN
    SELECT vip_cards INTO v_vip_cards
    FROM profiles
    WHERE id = p_student_id
    FOR UPDATE;
  ELSE
    SELECT vip_cards INTO v_vip_cards
    FROM profiles
    WHERE id = p_student_id;
  END IF;

  IF v_vip_cards IS NULL THEN
    RETURN 0;
  END IF;

  -- Count active (unused) instances of the specified card
  SELECT COUNT(*)::INTEGER INTO v_count
  FROM jsonb_each(v_vip_cards) AS cards(instance_id, card_data)
  WHERE card_data->>'cardId' = p_card_id
    AND (card_data->>'usedAt') IS NULL;

  RETURN COALESCE(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."count_student_active_cards"("p_student_id" "uuid", "p_card_id" "text", "p_lock_row" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."count_student_active_cards"("p_student_id" "uuid", "p_card_id" "text", "p_lock_row" boolean) IS 'Counts the number of active (unused) VIP card instances of a specific type owned by a student. Set p_lock_row=TRUE to prevent race conditions during purchase.';



