    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    notebook_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO notebook_count
    FROM python_notebooks
    WHERE author_id = p_user_id;
    RETURN notebook_count;
EXCEPTION
