CREATE OR REPLACE FUNCTION "public"."create_1on1_chat"("p_user1_id" "uuid", "p_user2_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conversation_id UUID;
  v_are_friends BOOLEAN;
BEGIN
  -- Check if users are friends
  SELECT EXISTS (
    SELECT 1 FROM friendships
    WHERE (
      (requester_id = p_user1_id AND addressee_id = p_user2_id)
      OR (requester_id = p_user2_id AND addressee_id = p_user1_id)
    )
    AND status = 'accepted'
  ) INTO v_are_friends;

  IF NOT v_are_friends THEN
    RAISE EXCEPTION 'Users must be friends to create a 1-on-1 chat';
  END IF;

  -- Check if conversation already exists between these two users
  SELECT c.id INTO v_conversation_id
  FROM conversations c
  WHERE c.is_group = false
  AND EXISTS (
    SELECT 1 FROM conversation_participants cp1
    WHERE cp1.conversation_id = c.id
    AND cp1.user_id = p_user1_id
  )
  AND EXISTS (
    SELECT 1 FROM conversation_participants cp2
    WHERE cp2.conversation_id = c.id
    AND cp2.user_id = p_user2_id
  )
  LIMIT 1;

  -- If conversation exists, return it
  IF v_conversation_id IS NOT NULL THEN
    RETURN v_conversation_id;
  END IF;

  -- Create new conversation
  INSERT INTO conversations (is_group, created_at)
  VALUES (false, NOW())
  RETURNING id INTO v_conversation_id;

  -- Add both participants
  INSERT INTO conversation_participants (conversation_id, user_id, joined_at)
  VALUES
    (v_conversation_id, p_user1_id, NOW()),
    (v_conversation_id, p_user2_id, NOW());

  RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION "public"."create_1on1_chat"("p_user1_id" "uuid", "p_user2_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_1on1_chat"("p_user1_id" "uuid", "p_user2_id" "uuid") IS 'Create a 1-on-1 chat between two friends, or return existing conversation if one exists';



CREATE OR REPLACE FUNCTION "public"."create_class_chat_room"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  new_conversation_id UUID;
BEGIN
  -- Create a conversation for the new class
  INSERT INTO conversations (
    name,
    is_group,
    class_id,
    created_by,
    created_at
  ) VALUES (
    NEW.name || ' - Chat de classe', -- e.g., "6ème A - Chat de classe"
    true, -- is_group
    NEW.id, -- class_id
    NEW.teacher_id, -- created_by (teacher)
    NOW()
  )
  RETURNING id INTO new_conversation_id;

  -- Add the teacher as a participant
  INSERT INTO conversation_participants (
    conversation_id,
    user_id,
    joined_at
  ) VALUES (
    new_conversation_id,
    NEW.teacher_id,
    NOW()
  );

  -- Add all existing class members as participants
  INSERT INTO conversation_participants (
    conversation_id,
    user_id,
    joined_at
  )
  SELECT
    new_conversation_id,
    cm.student_id,
    NOW()
  FROM class_members cm
  WHERE cm.class_id = NEW.id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_class_chat_room"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_class_chat_room"() IS 'Auto-creates a chat room when a class is created';



CREATE OR REPLACE FUNCTION "public"."create_error_report_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_worksheet_id UUID;
    v_worksheet_title TEXT;
    v_teacher_id UUID;
    v_student_firstname TEXT;
    v_student_lastname TEXT;
    v_exercise_position INT;
    v_student_display_name TEXT;
BEGIN
    -- Get worksheet info via assignment
    SELECT w.id, w.title, w.created_by
    INTO v_worksheet_id, v_worksheet_title, v_teacher_id
    FROM worksheet_assignments wa
    JOIN worksheets w ON w.id = wa.worksheet_id
    WHERE wa.id = NEW.assignment_id;

    -- Get exercise position
    SELECT position INTO v_exercise_position
    FROM worksheet_exercises
    WHERE id = NEW.worksheet_exercise_id;

    -- Get student name
    SELECT firstname, lastname
    INTO v_student_firstname, v_student_lastname
    FROM profiles
    WHERE id = NEW.student_id;

    -- Build display name
    IF v_student_firstname IS NOT NULL AND v_student_lastname IS NOT NULL THEN
        v_student_display_name := v_student_firstname || ' ' || v_student_lastname;
    ELSE
        v_student_display_name := 'Un élève';
    END IF;

    -- Create the notification (bypasses RLS due to SECURITY DEFINER)
    INSERT INTO notifications (
        created_by,
        title,
        message,
        type,
        priority,
        action_label,
        action_url,
        target_type,
        target_user_ids,
        expires_at,
        is_system,
        system_event_type
    ) VALUES (
        NULL, -- System notification has no creator
        'Signalement d''erreur',
        format(
            '<strong>%s</strong> a signalé une erreur dans l''exercice %s du devoir "%s".',
            v_student_display_name,
            v_exercise_position + 1,
            v_worksheet_title
        ),
        'alert',
        'normal',
        'Voir les signalements',
        format('/dashboard/teacher/worksheets/%s/assignments/%s/reports',
               v_worksheet_id, NEW.assignment_id),
        'users',
        ARRAY[v_teacher_id],
        now() + interval '30 days',
        true,
        'error_reported'
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_error_report_notification"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_error_report_notification"() IS 'Creates a system notification for the teacher when a student submits an error report. Uses SECURITY DEFINER to bypass RLS.';



