  -- Only create game profile for students
  IF NEW.role = 'student' THEN
    INSERT INTO game_players (user_id)
    VALUES (NEW.id)
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


