CREATE OR REPLACE FUNCTION "public"."create_tournament"("p_name" "text", "p_difficulty" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_class_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_description" "text" DEFAULT NULL::"text", "p_top_x_games" integer DEFAULT 3, "p_podium_rewards" "jsonb" DEFAULT '{"1": 10, "2": 5, "3": 3}'::"jsonb", "p_podium_places" integer DEFAULT 3) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
  v_scope TEXT;
  v_class_id UUID;
  v_tournament_id UUID;
BEGIN
  -- Step 1: Get authenticated user
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Must be authenticated to create a tournament';
  END IF;

  -- Step 2: Get user role
  SELECT role INTO v_user_role
  FROM public.profiles
  WHERE id = v_user_id;

  IF v_user_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Only teachers and admins can create tournaments';
  END IF;

  -- Step 3: Validate inputs
  IF p_name IS NULL OR length(trim(p_name)) < 3 THEN
    RAISE EXCEPTION 'Tournament name must be at least 3 characters';
  END IF;

  IF p_difficulty NOT IN ('beginner', 'intermediate', 'expert') THEN
    RAISE EXCEPTION 'Invalid difficulty: must be beginner, intermediate, or expert';
  END IF;

  IF p_end_date <= p_start_date THEN
    RAISE EXCEPTION 'End date must be after start date';
  END IF;

  IF p_top_x_games < 1 OR p_top_x_games > 20 THEN
    RAISE EXCEPTION 'top_x_games must be between 1 and 20';
  END IF;

  IF p_podium_places < 1 OR p_podium_places > 10 THEN
    RAISE EXCEPTION 'podium_places must be between 1 and 10';
  END IF;

  -- Step 4: Determine scope and validate class ownership
  IF p_class_ids IS NULL OR array_length(p_class_ids, 1) IS NULL THEN
    -- Global tournament (admin only)
    IF v_user_role != 'admin' THEN
      RAISE EXCEPTION 'Only admins can create global tournaments (no classes specified)';
    END IF;
    v_scope := 'global';
  ELSE
    -- Class-scoped tournament
    v_scope := 'classes';

    -- Verify teacher owns all classes OR user is admin
    IF v_user_role = 'teacher' THEN
      FOREACH v_class_id IN ARRAY p_class_ids
      LOOP
        IF NOT EXISTS (
          SELECT 1 FROM public.classes
          WHERE id = v_class_id AND teacher_id = v_user_id
        ) THEN
          RAISE EXCEPTION 'Teacher does not own class: %', v_class_id;
        END IF;
      END LOOP;
    ELSIF v_user_role = 'admin' THEN
      -- Admins can use any class, but verify classes exist
      FOREACH v_class_id IN ARRAY p_class_ids
      LOOP
        IF NOT EXISTS (
          SELECT 1 FROM public.classes WHERE id = v_class_id
        ) THEN
          RAISE EXCEPTION 'Class not found: %', v_class_id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- Step 5: Validate podium_rewards has entries for all places
  FOR i IN 1..p_podium_places
  LOOP
    IF NOT (p_podium_rewards ? i::TEXT) THEN
      RAISE EXCEPTION 'podium_rewards must have entry for place %', i;
    END IF;
    IF NOT ((p_podium_rewards->>i::TEXT)::INTEGER >= 0) THEN
      RAISE EXCEPTION 'podium_rewards for place % must be non-negative integer', i;
    END IF;
  END LOOP;

  -- Step 6: Create tournament
  INSERT INTO public.minesweeper_tournaments (
    creator_id,
    creator_role,
    scope,
    name,
    description,
    difficulty,
    start_date,
    end_date,
    top_x_games,
    podium_rewards,
    podium_places
  ) VALUES (
    v_user_id,
    v_user_role,
    v_scope,
    trim(p_name),
    p_description,
    p_difficulty,
    p_start_date,
    p_end_date,
    p_top_x_games,
    p_podium_rewards,
    p_podium_places
  )
  RETURNING id INTO v_tournament_id;

  -- Step 7: Create class associations (if class-scoped)
  IF v_scope = 'classes' THEN
    INSERT INTO public.minesweeper_tournament_classes (tournament_id, class_id)
    SELECT v_tournament_id, unnest(p_class_ids);
  END IF;

  RETURN v_tournament_id;
END;
$$;


ALTER FUNCTION "public"."create_tournament"("p_name" "text", "p_difficulty" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_class_ids" "uuid"[], "p_description" "text", "p_top_x_games" integer, "p_podium_rewards" "jsonb", "p_podium_places" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_tournament"("p_name" "text", "p_difficulty" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_class_ids" "uuid"[], "p_description" "text", "p_top_x_games" integer, "p_podium_rewards" "jsonb", "p_podium_places" integer) IS 'Creates a Minesweeper tournament. Teachers can only create for their own classes. Admins can create global or class-scoped tournaments.';



CREATE OR REPLACE FUNCTION "public"."delete_all_resolved_errors"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_deleted_logs_count INTEGER;
  v_deleted_occurrences_count INTEGER;
BEGIN
  -- Delete all resolved error_logs and count them
  WITH deleted_logs AS (
    DELETE FROM error_logs
    WHERE resolved = TRUE
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_logs_count FROM deleted_logs;

  -- Delete all resolved error_occurrences and count them
  WITH deleted_occurrences AS (
    DELETE FROM error_occurrences
    WHERE is_resolved = TRUE
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_occurrences_count FROM deleted_occurrences;

  -- Return TOTAL count (logs + occurrences) for better user feedback
  RETURN v_deleted_logs_count + v_deleted_occurrences_count;
END;
$$;


ALTER FUNCTION "public"."delete_all_resolved_errors"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_all_resolved_errors"() IS 'Deletes all resolved errors from BOTH error_logs and error_occurrences tables (admin only, hard delete). Returns the total count of deleted records (logs + occurrences). WARNING: This is a destructive operation that permanently removes all resolved errors regardless of age.';



CREATE OR REPLACE FUNCTION "public"."delete_attachment"("p_attachment_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_storage_path TEXT;
  v_uploaded_by UUID;
  v_conversation_created_by UUID;
BEGIN
  -- Get attachment details
  SELECT
    a.storage_path,
    a.uploaded_by,
    c.created_by
  INTO
    v_storage_path,
    v_uploaded_by,
    v_conversation_created_by
  FROM message_attachments a
  JOIN messages m ON m.id = a.message_id
  JOIN conversations c ON c.id = m.conversation_id
  WHERE a.id = p_attachment_id;

  -- Check permissions: either uploader or teacher who owns the chat
  IF v_uploaded_by != auth.uid() THEN
    IF v_conversation_created_by != auth.uid() OR NOT is_teacher_or_admin() THEN
      RAISE EXCEPTION 'Permission denied: cannot delete this attachment';
    END IF;
  END IF;

  -- Delete the attachment record
  DELETE FROM message_attachments
  WHERE id = p_attachment_id;

  -- Return storage path so application can delete from Supabase Storage
  RETURN v_storage_path;
END;
$$;


ALTER FUNCTION "public"."delete_attachment"("p_attachment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_attachment"("p_attachment_id" "uuid") IS 'Delete attachment and return storage path for cleanup';



CREATE OR REPLACE FUNCTION "public"."delete_exercise_images"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  storage_path TEXT;
  image_pattern TEXT;
BEGIN
  -- Build storage path pattern for this exercise's images
  -- Images are stored at: {userId}/{exerciseId}/{filename}
  -- or: {userId}/{timestamp}-{uuid}.{ext} (newer pattern)
  storage_path := OLD.created_by || '/' || OLD.id || '/';

  -- Delete all images in the exercise's folder from the exercise-images bucket
  -- Note: This requires storage.objects table access
  DELETE FROM storage.objects
  WHERE bucket_id = 'exercise-images'
    AND name LIKE storage_path || '%';

  -- Also check for images with exercise ID in the filename (alternate pattern)
  image_pattern := '%' || OLD.id || '%';
  DELETE FROM storage.objects
  WHERE bucket_id = 'exercise-images'
    AND owner = OLD.created_by
    AND name LIKE image_pattern;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."delete_exercise_images"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_user_account"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_result JSONB := '{}';
    v_count INTEGER;
BEGIN
    -- Validate input parameter
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'User ID cannot be NULL';
    END IF;

    -- ========================================
    -- Phase 1: Anonymize Audit Tables
    -- These records must be kept for compliance but PII must be removed
    -- ========================================

    -- Anonymize error_logs
    UPDATE error_logs
    SET user_id = NULL
    WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('error_logs_anonymized', v_count);

    -- Anonymize resolved_by in error_logs
    UPDATE error_logs
    SET resolved_by = NULL
    WHERE resolved_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('error_logs_resolved_by_anonymized', v_count);

    -- Anonymize gidouilles_activity (renamed from gidouilles_history in 20260103235000)
    UPDATE gidouilles_activity
    SET student_id = NULL
    WHERE student_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('gidouilles_activity_anonymized', v_count);

    -- Anonymize bonus_history
    UPDATE bonus_history
    SET student_id = NULL
    WHERE student_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('bonus_history_anonymized', v_count);

    -- Anonymize shop_purchase_history
    UPDATE shop_purchase_history
    SET student_id = NULL
    WHERE student_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('shop_purchase_history_anonymized', v_count);

    UPDATE shop_purchase_history
    SET refunded_by = NULL
    WHERE refunded_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('shop_purchase_history_refunded_by_anonymized', v_count);

    -- Anonymize item_usage_log
    UPDATE item_usage_log
    SET student_id = NULL
    WHERE student_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('item_usage_log_anonymized', v_count);

    UPDATE item_usage_log
    SET reversed_by = NULL
    WHERE reversed_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('item_usage_log_reversed_by_anonymized', v_count);

    -- Anonymize vip_cards_activity
    UPDATE vip_cards_activity
    SET student_id = NULL
    WHERE student_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('vip_cards_activity_anonymized', v_count);

    -- ========================================
    -- Phase 2: Hard Delete Soft-Deleted Records
    -- ========================================

    DELETE FROM private_messages
    WHERE sender_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('private_messages_deleted', v_count);

    DELETE FROM message_inbox
    WHERE recipient_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('message_inbox_deleted', v_count);

    DELETE FROM notifications
    WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('notifications_deleted', v_count);

    -- ========================================
    -- Phase 3: Handle SET NULL References
    -- ========================================

    UPDATE messages
    SET sender_id = NULL
    WHERE sender_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('messages_sender_nullified', v_count);

    UPDATE exercises
    SET created_by = NULL
    WHERE created_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('exercises_created_by_nullified', v_count);

    UPDATE rag_documents
    SET teacher_id = NULL
    WHERE teacher_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('rag_documents_nullified', v_count);

    -- ========================================
    -- Phase 3b: Handle FK constraints WITHOUT ON DELETE clause
    -- ========================================

    UPDATE game_monsters
    SET spawned_by = NULL
    WHERE spawned_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('game_monsters_spawned_by_nullified', v_count);

    UPDATE game_monsters
    SET defeated_by = NULL
    WHERE defeated_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('game_monsters_defeated_by_nullified', v_count);

    UPDATE game_challenges
    SET created_by = NULL
    WHERE created_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('game_challenges_created_by_nullified', v_count);

    UPDATE message_template_versions
    SET modified_by = NULL
    WHERE modified_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('message_template_versions_nullified', v_count);

    UPDATE message_template_drafts
    SET reviewed_by = NULL
    WHERE reviewed_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('message_template_drafts_reviewed_by_nullified', v_count);

    UPDATE message_template_audit
    SET performed_by = NULL
    WHERE performed_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('message_template_audit_nullified', v_count);

    UPDATE exercise_assignments
    SET assigned_by = NULL
    WHERE assigned_by = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('exercise_assignments_nullified', v_count);

    -- ========================================
    -- Phase 4: Unlock marketplace items
    -- ========================================

    UPDATE student_item_inventory
    SET locked_for_trade_id = NULL
    WHERE student_id = p_user_id AND locked_for_trade_id IS NOT NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := v_result || jsonb_build_object('marketplace_items_unlocked', v_count);

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."delete_user_account"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_user_account"("p_user_id" "uuid") IS 'GDPR Art. 17 compliant account deletion. Anonymizes audit trails and removes personal data. Called before auth.admin.deleteUser() to prepare cascading deletion. Uses gidouilles_activity (renamed from gidouilles_history in 20260103235000).';



CREATE OR REPLACE FUNCTION "public"."discard_vip_cards"("p_student_id" "uuid", "p_instance_ids" "text"[], "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vip_cards JSONB;
  v_now TIMESTAMPTZ := NOW();
  v_now_str TEXT;
  v_instance_id TEXT;
  v_card_data JSONB;
  v_card_id TEXT;
  v_discarded_count INT := 0;
BEGIN
  -- ========================================================================
  -- VALIDATE INPUT
  -- ========================================================================

  IF p_instance_ids IS NULL OR array_length(p_instance_ids, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'No instance IDs provided'
    );
  END IF;

  IF array_length(p_instance_ids, 1) > 20 THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Too many cards to discard (max 20)'
    );
  END IF;

  -- ========================================================================
  -- LOCK STUDENT PROFILE
  -- ========================================================================

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Student profile not found'
    );
  END IF;

  v_vip_cards := COALESCE(v_vip_cards, '{}'::JSONB);
  v_now_str := to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  -- ========================================================================
  -- MARK EACH CARD AS USED + LOG AUDIT
  -- ========================================================================

  FOREACH v_instance_id IN ARRAY p_instance_ids
  LOOP
    v_card_data := v_vip_cards->v_instance_id;

    -- Skip if instance not found
    IF v_card_data IS NULL THEN
      CONTINUE;
    END IF;

    -- Skip if already used
    IF v_card_data->>'usedAt' IS NOT NULL THEN
      CONTINUE;
    END IF;

    v_card_id := v_card_data->>'cardId';

    -- Set usedAt in JSONB
    v_vip_cards := jsonb_set(
      v_vip_cards,
      ARRAY[v_instance_id, 'usedAt'],
      to_jsonb(v_now_str)
    );

    -- Insert audit entry
    INSERT INTO public.vip_cards_activity (
      student_id, card_instance_id, card_template_id, action, metadata
    ) VALUES (
      p_student_id,
      v_instance_id,
      v_card_id,
      'used',
      jsonb_build_object('used_at', v_now_str) || COALESCE(p_metadata, '{}'::JSONB)
    );

    v_discarded_count := v_discarded_count + 1;
  END LOOP;

  -- ========================================================================
  -- UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'discarded_count', v_discarded_count
  );
END;
$$;


ALTER FUNCTION "public"."discard_vip_cards"("p_student_id" "uuid", "p_instance_ids" "text"[], "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."discard_vip_cards"("p_student_id" "uuid", "p_instance_ids" "text"[], "p_metadata" "jsonb") IS 'Atomically marks multiple VIP card instances as used and logs audit entries.
Used by exchange endpoints to ensure discard operations and their audit trail
are in the same transaction. p_metadata is merged into each audit entry.';



CREATE OR REPLACE FUNCTION "public"."draw_multiple_vip_cards"("p_student_id" "uuid", "p_count" integer, "p_payment_method" "text", "p_gidouilles_cost" integer DEFAULT NULL::integer, "p_vip_card_instance_id" "uuid" DEFAULT NULL::"uuid", "p_force_rarity" "text" DEFAULT NULL::"text", "p_min_rarity" "text" DEFAULT NULL::"text", "p_exclude_card_ids" "text"[] DEFAULT NULL::"text"[], "p_only_cards_with_actions" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Constants
  c_max_cost_per_card CONSTANT INT := 10;
  c_min_count CONSTANT INT := 1;
  c_max_count CONSTANT INT := 10;

  -- Authorization variables
  v_caller_id UUID;
  v_is_teacher BOOLEAN;
  v_is_authorized BOOLEAN;
  v_student_in_class BOOLEAN;

  -- Student profile variables
  v_current_gidouilles INT;
  v_vip_cards JSONB;
  v_card_instance JSONB;
  v_card_used_at TEXT;
  v_payment_card_id TEXT;
  v_payment_card_name TEXT;

  -- Card drawing variables (weighted by rarity)
  v_common_prob INTEGER;
  v_rare_prob INTEGER;
  v_epic_prob INTEGER;
  v_legendary_prob INTEGER;
  v_common_max INTEGER;
  v_rare_max INTEGER;
  v_epic_max INTEGER;
  v_roll INTEGER;
  v_selected_rarity TEXT;
  v_drawn_cards JSONB := '[]'::jsonb;
  v_card_id TEXT;
  v_available_card_ids TEXT[];
  v_instance_id UUID;
  v_earned_at TIMESTAMPTZ;
  v_new_card_instance JSONB;
  v_loop_counter INT;

  -- Filter variables
  v_min_rarity_level INT;
  v_rolled_rarity_level INT;

  -- Timestamp for audit
  v_now_str TEXT;

  -- Acquisition source for JSONB instance + audit
  v_acquired_from TEXT;

  -- Class ID for audit trail
  v_class_id UUID;

BEGIN
  -- ========================================
  -- 1. VALIDATE INPUT PARAMETERS
  -- ========================================

  IF p_count < c_min_count OR p_count > c_max_count THEN
    RAISE EXCEPTION 'Invalid count: Must be between % and % (received: %)',
      c_min_count, c_max_count, p_count;
  END IF;

  IF p_payment_method NOT IN ('gidouilles', 'vip_card') THEN
    RAISE EXCEPTION 'Invalid payment_method: Must be ''gidouilles'' or ''vip_card'' (received: ''%'')',
      p_payment_method;
  END IF;

  IF p_force_rarity IS NOT NULL AND p_force_rarity NOT IN ('common', 'rare', 'epic', 'legendary') THEN
    RAISE EXCEPTION 'Invalid force_rarity: Must be ''common'', ''rare'', ''epic'', or ''legendary'' (received: ''%'')',
      p_force_rarity;
  END IF;

  IF p_min_rarity IS NOT NULL AND p_min_rarity NOT IN ('common', 'rare', 'epic', 'legendary') THEN
    RAISE EXCEPTION 'Invalid min_rarity: Must be ''common'', ''rare'', ''epic'', or ''legendary'' (received: ''%'')',
      p_min_rarity;
  END IF;

  IF p_force_rarity IS NOT NULL AND p_min_rarity IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid filters: force_rarity and min_rarity are mutually exclusive';
  END IF;

  -- Compute acquiredFrom once based on payment method
  v_acquired_from := CASE p_payment_method
    WHEN 'gidouilles' THEN 'draw_gidouilles'
    WHEN 'vip_card' THEN 'draw_vip_card'
  END;

  -- ========================================
  -- 2. AUTHORIZATION
  -- ========================================

  v_caller_id := auth.uid();
  v_is_teacher := is_teacher_or_admin();

  IF v_is_teacher THEN
    SELECT EXISTS (
      SELECT 1
      FROM class_members cm
      INNER JOIN classes c ON c.id = cm.class_id
      WHERE cm.student_id = p_student_id
        AND c.teacher_id = v_caller_id
    ) INTO v_student_in_class;

    IF NOT v_student_in_class THEN
      RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
    END IF;

    v_is_authorized := TRUE;
  ELSIF v_caller_id = p_student_id THEN
    v_is_authorized := TRUE;
  ELSE
    RAISE EXCEPTION 'Unauthorized: You can only draw cards for yourself or your students';
  END IF;

  -- ========================================
  -- 3. LOCK STUDENT PROFILE
  -- ========================================

  SELECT gidouilles, vip_cards
  INTO v_current_gidouilles, v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Student profile not found';
  END IF;

  -- Get student's active class for audit trail
  SELECT cm.class_id INTO v_class_id
  FROM class_members cm
  WHERE cm.student_id = p_student_id
    AND cm.status = 'active'
  LIMIT 1;

  -- ========================================
  -- 4. LOAD RARITY PROBABILITIES FROM CONFIG
  -- ========================================

  SELECT
    common_probability,
    rare_probability,
    epic_probability,
    legendary_probability
  INTO
    v_common_prob, v_rare_prob, v_epic_prob, v_legendary_prob
  FROM vip_card_config
  WHERE is_active = TRUE
  LIMIT 1;

  IF v_common_prob IS NULL THEN
    v_common_prob := 60;
    v_rare_prob := 25;
    v_epic_prob := 12;
    v_legendary_prob := 3;
  END IF;

  v_common_max := v_common_prob;
  v_rare_max := v_common_max + v_rare_prob;
  v_epic_max := v_rare_max + v_epic_prob;

  IF p_min_rarity IS NOT NULL THEN
    v_min_rarity_level := CASE p_min_rarity
      WHEN 'common' THEN 1
      WHEN 'rare' THEN 2
      WHEN 'epic' THEN 3
      WHEN 'legendary' THEN 4
    END;
  END IF;

  -- ========================================
  -- 5. PROCESS PAYMENT
  -- ========================================

  IF p_payment_method = 'gidouilles' THEN
    IF p_gidouilles_cost IS NULL THEN
      RAISE EXCEPTION 'Missing parameter: gidouilles_cost is required for gidouilles payment';
    END IF;

    IF p_gidouilles_cost < 0 THEN
      RAISE EXCEPTION 'Invalid gidouilles_cost: Cannot be negative (received: %)', p_gidouilles_cost;
    END IF;

    IF p_gidouilles_cost > (p_count * c_max_cost_per_card) THEN
      RAISE EXCEPTION 'Invalid gidouilles_cost: Maximum % gidouilles for % cards (received: %)',
        (p_count * c_max_cost_per_card), p_count, p_gidouilles_cost;
    END IF;

    IF p_gidouilles_cost = 0 AND NOT v_is_teacher THEN
      RAISE EXCEPTION 'Unauthorized: Students cannot draw free cards (cost must be > 0)';
    END IF;

    IF v_current_gidouilles < p_gidouilles_cost THEN
      RAISE EXCEPTION 'Insufficient gidouilles: Required %, available % (shortfall: %)',
        p_gidouilles_cost, v_current_gidouilles, (p_gidouilles_cost - v_current_gidouilles);
    END IF;

    v_current_gidouilles := v_current_gidouilles - p_gidouilles_cost;

    -- Log gidouilles spent for audit trail
    IF p_gidouilles_cost > 0 THEN
      INSERT INTO gidouilles_activity (
        student_id,
        class_id,
        delta,
        reason,
        created_by
      ) VALUES (
        p_student_id,
        v_class_id,
        -p_gidouilles_cost,
        'Tirage de ' || p_count || ' carte' || CASE WHEN p_count > 1 THEN 's' ELSE '' END || ' VIP',
        NULL
      );
    END IF;

  ELSIF p_payment_method = 'vip_card' THEN
    IF p_vip_card_instance_id IS NULL THEN
      RAISE EXCEPTION 'Missing parameter: vip_card_instance_id is required for vip_card payment';
    END IF;

    v_vip_cards := COALESCE(v_vip_cards, '{}'::jsonb);
    v_card_instance := v_vip_cards->p_vip_card_instance_id::text;

    IF v_card_instance IS NULL THEN
      RAISE EXCEPTION 'VIP card not found: Instance ID % does not exist in student''s cards',
        p_vip_card_instance_id;
    END IF;

    v_card_used_at := v_card_instance->>'usedAt';

    IF v_card_used_at IS NOT NULL THEN
      RAISE EXCEPTION 'VIP card already used: This card was used at %', v_card_used_at;
    END IF;

    -- Extract template ID and look up card name for audit trail
    v_payment_card_id := v_card_instance->>'cardId';

    SELECT name INTO v_payment_card_name
    FROM vip_card_templates
    WHERE id = v_payment_card_id;

    v_payment_card_name := COALESCE(v_payment_card_name, v_payment_card_id);

    -- Mark card as used
    v_now_str := to_char(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
    v_vip_cards := jsonb_set(
      v_vip_cards,
      ARRAY[p_vip_card_instance_id::text, 'usedAt'],
      to_jsonb(v_now_str)
    );

    -- AUDIT: Log VIP card payment atomically within this transaction
    INSERT INTO public.vip_cards_activity (
      student_id, card_instance_id, card_template_id, action, metadata
    ) VALUES (
      p_student_id,
      p_vip_card_instance_id::text,
      COALESCE(v_payment_card_id, 'unknown'),
      'used',
      jsonb_build_object(
        'used_at', v_now_str,
        'action_type', 'draw_cards',
        'cards_drawn', p_count,
        'filters', jsonb_build_object(
          'force_rarity', p_force_rarity,
          'min_rarity', p_min_rarity,
          'exclude_card_ids', to_jsonb(COALESCE(p_exclude_card_ids, ARRAY[]::TEXT[])),
          'only_cards_with_actions', p_only_cards_with_actions
        )
      )
    );

  END IF;

  -- ========================================
  -- 6. DRAW RANDOM VIP CARDS
  -- ========================================

  FOR v_loop_counter IN 1..p_count LOOP

    IF p_force_rarity IS NOT NULL THEN
      v_selected_rarity := p_force_rarity;
    ELSE
      v_roll := floor(random() * 100 + 1)::int;

      IF v_roll <= v_common_max THEN
        v_selected_rarity := 'common';
        v_rolled_rarity_level := 1;
      ELSIF v_roll <= v_rare_max THEN
        v_selected_rarity := 'rare';
        v_rolled_rarity_level := 2;
      ELSIF v_roll <= v_epic_max THEN
        v_selected_rarity := 'epic';
        v_rolled_rarity_level := 3;
      ELSE
        v_selected_rarity := 'legendary';
        v_rolled_rarity_level := 4;
      END IF;

      IF p_min_rarity IS NOT NULL AND v_rolled_rarity_level < v_min_rarity_level THEN
        v_selected_rarity := p_min_rarity;
      END IF;
    END IF;

    SELECT ARRAY_AGG(vct.id)
    INTO v_available_card_ids
    FROM vip_card_templates vct
    WHERE vct.rarity = v_selected_rarity
      AND vct.is_enabled = TRUE
      AND NOT EXISTS (
        SELECT 1
        FROM teacher_vip_card_overrides tvo
        WHERE tvo.card_id = vct.id
          AND tvo.is_enabled = FALSE
          AND tvo.teacher_id IN (
            SELECT DISTINCT c.teacher_id
            FROM class_members cm
            INNER JOIN classes c ON c.id = cm.class_id
            WHERE cm.student_id = p_student_id
          )
      )
      AND (p_exclude_card_ids IS NULL OR vct.id != ALL(p_exclude_card_ids))
      AND (NOT p_only_cards_with_actions OR vct.action IS NOT NULL);

    IF v_available_card_ids IS NULL OR array_length(v_available_card_ids, 1) IS NULL THEN
      IF p_force_rarity IS NOT NULL THEN
        RAISE EXCEPTION 'No enabled VIP cards available for forced rarity ''%'' (all cards may be disabled by teacher overrides, excluded, or filtered out)',
          p_force_rarity;
      END IF;

      SELECT ARRAY_AGG(vct.id)
      INTO v_available_card_ids
      FROM vip_card_templates vct
      WHERE vct.rarity = 'common'
        AND vct.is_enabled = TRUE
        AND NOT EXISTS (
          SELECT 1
          FROM teacher_vip_card_overrides tvo
          WHERE tvo.card_id = vct.id
            AND tvo.is_enabled = FALSE
            AND tvo.teacher_id IN (
              SELECT DISTINCT c.teacher_id
              FROM class_members cm
              INNER JOIN classes c ON c.id = cm.class_id
              WHERE cm.student_id = p_student_id
            )
        )
        AND (p_exclude_card_ids IS NULL OR vct.id != ALL(p_exclude_card_ids))
        AND (NOT p_only_cards_with_actions OR vct.action IS NOT NULL);

      IF v_available_card_ids IS NULL OR array_length(v_available_card_ids, 1) IS NULL THEN
        RAISE EXCEPTION 'No enabled VIP cards available to draw (all cards disabled by teacher overrides, excluded, or filtered out)';
      END IF;
    END IF;

    v_card_id := v_available_card_ids[floor(random() * array_length(v_available_card_ids, 1) + 1)::int];

    v_instance_id := gen_random_uuid();
    v_earned_at := NOW();

    v_new_card_instance := jsonb_build_object(
      'cardId', v_card_id,
      'earnedAt', v_earned_at,
      'usedAt', null,
      'acquiredFrom', v_acquired_from
    );

    v_vip_cards := COALESCE(v_vip_cards, '{}'::jsonb) || jsonb_build_object(
      v_instance_id::text,
      v_new_card_instance
    );

    v_drawn_cards := v_drawn_cards || jsonb_build_object(
      'cardId', v_card_id,
      'instanceId', v_instance_id,
      'earnedAt', v_earned_at
    );

    -- Log 'gained' audit entry for each drawn card
    INSERT INTO public.vip_cards_activity (
      student_id, card_instance_id, card_template_id, action, metadata
    ) VALUES (
      p_student_id,
      v_instance_id::text,
      v_card_id,
      'gained',
      jsonb_build_object(
        'acquired_from', v_acquired_from,
        'rarity', v_selected_rarity,
        'payment_method', p_payment_method,
        'payment_card_name', v_payment_card_name
      )
    );

  END LOOP;

  -- ========================================
  -- 7. UPDATE STUDENT PROFILE
  -- ========================================

  UPDATE profiles
  SET
    gidouilles = v_current_gidouilles,
    vip_cards = v_vip_cards,
    updated_at = NOW()
  WHERE id = p_student_id;

  -- ========================================
  -- 8. RETURN RESULTS
  -- ========================================

  RETURN jsonb_build_object(
    'cards', v_drawn_cards
  );

END;
$$;


ALTER FUNCTION "public"."draw_multiple_vip_cards"("p_student_id" "uuid", "p_count" integer, "p_payment_method" "text", "p_gidouilles_cost" integer, "p_vip_card_instance_id" "uuid", "p_force_rarity" "text", "p_min_rarity" "text", "p_exclude_card_ids" "text"[], "p_only_cards_with_actions" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."draw_multiple_vip_cards"("p_student_id" "uuid", "p_count" integer, "p_payment_method" "text", "p_gidouilles_cost" integer, "p_vip_card_instance_id" "uuid", "p_force_rarity" "text", "p_min_rarity" "text", "p_exclude_card_ids" "text"[], "p_only_cards_with_actions" boolean) IS 'Draws multiple VIP cards for a student with rarity-weighted probabilities.
Includes payment_card_name in gained metadata for precise journal descriptions.';



CREATE OR REPLACE FUNCTION "public"."duplicate_template"("p_template_id" "uuid", "p_user_id" "uuid", "p_new_title" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  new_template_id UUID;
  original_template RECORD;
BEGIN
  -- Get original template
  SELECT * INTO original_template
  FROM message_templates
  WHERE id = p_template_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  -- Create duplicate
  INSERT INTO message_templates (
    title, description, subject_template, body_template,
    trigger_type, trigger_config, scope, created_by, class_id,
    variables, tags, is_active
  ) VALUES (
    COALESCE(p_new_title, original_template.title || ' (copie)'),
    original_template.description,
    original_template.subject_template,
    original_template.body_template,
    original_template.trigger_type,
    original_template.trigger_config,
    'class', -- Duplicates are always class scope
    p_user_id,
    NULL, -- User must assign a class
    original_template.variables,
    original_template.tags,
    original_template.is_active
  ) RETURNING id INTO new_template_id;

  -- Log duplication
  PERFORM log_template_action(
    new_template_id,
    'duplicated',
    p_user_id,
    NULL,
    jsonb_build_object('original_template_id', p_template_id)
  );

  RETURN new_template_id;
END;
$$;


ALTER FUNCTION "public"."duplicate_template"("p_template_id" "uuid", "p_user_id" "uuid", "p_new_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."duplicate_template"("p_template_id" "uuid", "p_user_id" "uuid", "p_new_title" "text") IS 'Duplicate a template for user customization';



CREATE OR REPLACE FUNCTION "public"."enforce_kanban_tags_per_board_cap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_count INT;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM public.kanban_tags
    WHERE board_id = NEW.board_id;

    IF v_count >= 20 THEN
        RAISE EXCEPTION 'Limite de 20 tags par tableau atteinte'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_kanban_tags_per_board_cap"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_kanban_tags_per_board_cap"() IS 'Caps each board at 20 tags. Subqueries are not allowed in CHECK constraints so we use a BEFORE INSERT trigger.';



CREATE OR REPLACE FUNCTION "public"."enforce_single_teacher"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
	-- Le WHEN du trigger garantit déjà NEW.role = 'teacher'.
	-- On refuse s'il existe DÉJÀ un autre compte teacher.
	IF EXISTS (
		SELECT 1 FROM public.profiles
		WHERE role = 'teacher' AND id <> NEW.id
	) THEN
		RAISE EXCEPTION
			'Invariant mono-professeur : un compte teacher existe déjà (un seul professeur autorisé).'
			USING ERRCODE = 'check_violation';
	END IF;
	RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_teacher"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_single_teacher"() IS 'Refactor mono-professeur : empêche l''existence de >= 2 comptes role=teacher (0 ou 1 autorisé).';



CREATE OR REPLACE FUNCTION "public"."ensure_player_stats_exist"("p_student_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.minesweeper_player_stats (student_id)
  VALUES (p_student_id)
  ON CONFLICT (student_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."ensure_player_stats_exist"("p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_player_stats_exist"("p_student_id" "uuid") IS 'Creates player stats entry on first match participation (idempotent)';



CREATE OR REPLACE FUNCTION "public"."ensure_single_active_deck"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- If setting this deck as active, deactivate all other decks for this user
  IF NEW.is_active = true THEN
    UPDATE game_spell_decks
    SET is_active = false
    WHERE user_id = NEW.user_id
      AND id != NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ensure_single_active_deck"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_single_active_deck"() IS 'Ensures only one spell deck is active per user';



CREATE OR REPLACE FUNCTION "public"."execute_trade"("p_trade_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_trade RECORD;
    v_final_trade JSONB;
    v_initiator_cards TEXT[];
    v_initiator_gidouilles INTEGER;
    v_partner_cards TEXT[];
    v_partner_gidouilles INTEGER;
    v_initiator_vip_cards JSONB;
    v_partner_vip_cards JSONB;
    v_card_id TEXT;
    v_card_data JSONB;
    v_card_template_id TEXT;
    v_daily_trade_count INTEGER;
    v_max_trades_per_day INTEGER;
    v_initiator_balance INTEGER;
    v_partner_balance INTEGER;
    v_initiator_name TEXT;
    v_partner_name TEXT;
    v_initiator_class_id UUID;
    v_partner_class_id UUID;
    v_trade_id_short TEXT;
BEGIN
    -- Lock the trade row for update
    SELECT * INTO v_trade
    FROM public.marketplace_trades
    WHERE id = p_trade_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Trade not found');
    END IF;

    -- CRITICAL SECURITY FIX: Verify caller is a participant in the trade
    IF auth.uid() != v_trade.initiator_id AND auth.uid() != v_trade.partner_id THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Non autorisé: vous devez être participant de cet échange'
        );
    END IF;

    IF v_trade.status != 'negotiating' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Trade is not in negotiating status');
    END IF;

    IF v_trade.current_offer IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No offer to execute');
    END IF;

    -- Check daily trade limit for both participants
    SELECT COUNT(*) INTO v_daily_trade_count
    FROM public.marketplace_trades
    WHERE (initiator_id = v_trade.initiator_id OR partner_id = v_trade.initiator_id)
    AND status = 'completed'
    AND completed_at >= CURRENT_DATE;

    -- Get max trades per day from config (default 10)
    SELECT COALESCE(MAX(max_trades_per_day), 10) INTO v_max_trades_per_day
    FROM public.marketplace_config mc
    JOIN public.classes c ON c.school_id = mc.school_id
    JOIN public.class_members cm ON cm.class_id = c.id
    WHERE cm.student_id = v_trade.initiator_id;

    IF v_daily_trade_count >= v_max_trades_per_day THEN
        RETURN jsonb_build_object('success', false, 'error', 'Daily trade limit reached for initiator');
    END IF;

    -- Check partner's daily limit
    SELECT COUNT(*) INTO v_daily_trade_count
    FROM public.marketplace_trades
    WHERE (initiator_id = v_trade.partner_id OR partner_id = v_trade.partner_id)
    AND status = 'completed'
    AND completed_at >= CURRENT_DATE;

    IF v_daily_trade_count >= v_max_trades_per_day THEN
        RETURN jsonb_build_object('success', false, 'error', 'Daily trade limit reached for partner');
    END IF;

    -- Extract trade details
    v_final_trade := v_trade.current_offer;
    v_initiator_cards := ARRAY(SELECT jsonb_array_elements_text(v_final_trade->'from_initiator'->'cards'));
    v_initiator_gidouilles := COALESCE((v_final_trade->'from_initiator'->>'gidouilles')::INTEGER, 0);
    v_partner_cards := ARRAY(SELECT jsonb_array_elements_text(v_final_trade->'from_partner'->'cards'));
    v_partner_gidouilles := COALESCE((v_final_trade->'from_partner'->>'gidouilles')::INTEGER, 0);

    -- Get and lock both profiles for gidouilles verification and update
    SELECT gidouilles, vip_cards INTO v_initiator_balance, v_initiator_vip_cards
    FROM public.profiles
    WHERE id = v_trade.initiator_id
    FOR UPDATE;

    SELECT gidouilles, vip_cards INTO v_partner_balance, v_partner_vip_cards
    FROM public.profiles
    WHERE id = v_trade.partner_id
    FOR UPDATE;

    -- Get names for history logging
    SELECT COALESCE(NULLIF(TRIM(COALESCE(firstname, '') || ' ' || COALESCE(lastname, '')), ''), 'Élève')
    INTO v_initiator_name
    FROM public.profiles WHERE id = v_trade.initiator_id;

    SELECT COALESCE(NULLIF(TRIM(COALESCE(firstname, '') || ' ' || COALESCE(lastname, '')), ''), 'Élève')
    INTO v_partner_name
    FROM public.profiles WHERE id = v_trade.partner_id;

    -- Get class_id for both participants
    SELECT cm.class_id INTO v_initiator_class_id
    FROM public.class_members cm
    WHERE cm.student_id = v_trade.initiator_id
    AND cm.status = 'active'
    LIMIT 1;

    SELECT cm.class_id INTO v_partner_class_id
    FROM public.class_members cm
    WHERE cm.student_id = v_trade.partner_id
    AND cm.status = 'active'
    LIMIT 1;

    -- Short trade ID for display
    v_trade_id_short := LEFT(p_trade_id::TEXT, 8);

    -- Verify gidouilles balance for initiator
    IF v_initiator_gidouilles > 0 THEN
        IF v_initiator_balance IS NULL OR v_initiator_balance < v_initiator_gidouilles THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Solde insuffisant: initiateur a %s mais a besoin de %s',
                               COALESCE(v_initiator_balance, 0), v_initiator_gidouilles)
            );
        END IF;
    END IF;

    -- Verify gidouilles balance for partner
    IF v_partner_gidouilles > 0 THEN
        IF v_partner_balance IS NULL OR v_partner_balance < v_partner_gidouilles THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Solde insuffisant: partenaire a %s mais a besoin de %s',
                               COALESCE(v_partner_balance, 0), v_partner_gidouilles)
            );
        END IF;
    END IF;

    -- ========================================================================
    -- Transfer cards from initiator to partner
    -- ========================================================================
    FOREACH v_card_id IN ARRAY v_initiator_cards
    LOOP
        v_card_data := v_initiator_vip_cards->v_card_id;
        IF v_card_data IS NULL THEN
            RAISE EXCEPTION 'Card % not found for initiator', v_card_id;
        END IF;

        v_card_template_id := v_card_data->>'cardId';
        v_initiator_vip_cards := v_initiator_vip_cards - v_card_id;
        v_partner_vip_cards := jsonb_set(
            COALESCE(v_partner_vip_cards, '{}'::jsonb),
            ARRAY[v_card_id],
            v_card_data || jsonb_build_object('traded_at', NOW(), 'acquiredFrom', 'trade')
        );

        -- Log sender activity (FIX C: include partner name)
        INSERT INTO public.vip_cards_activity (card_instance_id, student_id, card_template_id, action, metadata)
        VALUES (v_card_id, v_trade.initiator_id, v_card_template_id, 'traded',
            jsonb_build_object(
                'trade_id', p_trade_id,
                'traded_to', v_trade.partner_id,
                'traded_to_name', v_partner_name,
                'direction', 'sent'
            ));

        -- Log receiver activity (FIX C: include sender name)
        INSERT INTO public.vip_cards_activity (card_instance_id, student_id, card_template_id, action, metadata)
        VALUES (v_card_id, v_trade.partner_id, v_card_template_id, 'gained',
            jsonb_build_object(
                'acquired_from', 'trade',
                'trade_id', p_trade_id,
                'received_from', v_trade.initiator_id,
                'received_from_name', v_initiator_name
            ));
    END LOOP;

    -- ========================================================================
    -- Transfer cards from partner to initiator
    -- ========================================================================
    FOREACH v_card_id IN ARRAY v_partner_cards
    LOOP
        v_card_data := v_partner_vip_cards->v_card_id;
        IF v_card_data IS NULL THEN
            RAISE EXCEPTION 'Card % not found for partner', v_card_id;
        END IF;

        v_card_template_id := v_card_data->>'cardId';
        v_partner_vip_cards := v_partner_vip_cards - v_card_id;
        v_initiator_vip_cards := jsonb_set(
            COALESCE(v_initiator_vip_cards, '{}'::jsonb),
            ARRAY[v_card_id],
            v_card_data || jsonb_build_object('traded_at', NOW(), 'acquiredFrom', 'trade')
        );

        -- Log sender activity (FIX C: include partner name)
        INSERT INTO public.vip_cards_activity (card_instance_id, student_id, card_template_id, action, metadata)
        VALUES (v_card_id, v_trade.partner_id, v_card_template_id, 'traded',
            jsonb_build_object(
                'trade_id', p_trade_id,
                'traded_to', v_trade.initiator_id,
                'traded_to_name', v_initiator_name,
                'direction', 'sent'
            ));

        -- Log receiver activity (FIX C: include sender name)
        INSERT INTO public.vip_cards_activity (card_instance_id, student_id, card_template_id, action, metadata)
        VALUES (v_card_id, v_trade.initiator_id, v_card_template_id, 'gained',
            jsonb_build_object(
                'acquired_from', 'trade',
                'trade_id', p_trade_id,
                'received_from', v_trade.partner_id,
                'received_from_name', v_partner_name
            ));
    END LOOP;

    -- ========================================================================
    -- Update profiles and log gidouilles activity
    -- ========================================================================

    -- Update initiator profile
    UPDATE public.profiles
    SET
        vip_cards = v_initiator_vip_cards,
        gidouilles = GREATEST(0, COALESCE(gidouilles, 0) - v_initiator_gidouilles + v_partner_gidouilles),
        updated_at = NOW()
    WHERE id = v_trade.initiator_id;

    -- Update partner profile
    UPDATE public.profiles
    SET
        vip_cards = v_partner_vip_cards,
        gidouilles = GREATEST(0, COALESCE(gidouilles, 0) - v_partner_gidouilles + v_initiator_gidouilles),
        updated_at = NOW()
    WHERE id = v_trade.partner_id;

    -- FIX B: Log gidouilles activity with descriptive reasons
    IF v_initiator_gidouilles > 0 THEN
        -- Initiator sent gidouilles
        INSERT INTO public.gidouilles_activity (student_id, class_id, delta, reason, created_by)
        VALUES (v_trade.initiator_id, v_initiator_class_id, -v_initiator_gidouilles,
                format('Donné à %s (échange #%s)', v_partner_name, v_trade_id_short), NULL);
        -- Partner received gidouilles
        INSERT INTO public.gidouilles_activity (student_id, class_id, delta, reason, created_by)
        VALUES (v_trade.partner_id, v_partner_class_id, v_initiator_gidouilles,
                format('Reçu de %s (échange #%s)', v_initiator_name, v_trade_id_short), NULL);
    END IF;

    IF v_partner_gidouilles > 0 THEN
        -- Partner sent gidouilles
        INSERT INTO public.gidouilles_activity (student_id, class_id, delta, reason, created_by)
        VALUES (v_trade.partner_id, v_partner_class_id, -v_partner_gidouilles,
                format('Donné à %s (échange #%s)', v_initiator_name, v_trade_id_short), NULL);
        -- Initiator received gidouilles
        INSERT INTO public.gidouilles_activity (student_id, class_id, delta, reason, created_by)
        VALUES (v_trade.initiator_id, v_initiator_class_id, v_partner_gidouilles,
                format('Reçu de %s (échange #%s)', v_partner_name, v_trade_id_short), NULL);
    END IF;

    -- ========================================================================
    -- Update trade status
    -- ========================================================================
    UPDATE public.marketplace_trades
    SET
        status = 'completed',
        completed_at = NOW(),
        final_trade = v_final_trade,
        updated_at = NOW()
    WHERE id = p_trade_id;

    -- Unlock all cards for this trade
    DELETE FROM public.marketplace_locked_cards
    WHERE locked_entity_id = p_trade_id;

    -- If this was a marketplace listing trade, update listing and proposals
    IF v_trade.listing_id IS NOT NULL THEN
        UPDATE public.marketplace_listings
        SET status = 'completed', completed_at = NOW()
        WHERE id = v_trade.listing_id;

        UPDATE public.marketplace_proposals
        SET status = 'accepted', responded_at = NOW()
        WHERE id = v_trade.proposal_id;

        UPDATE public.marketplace_proposals
        SET status = 'rejected', responded_at = NOW(), response_message = 'Another proposal was accepted'
        WHERE listing_id = v_trade.listing_id AND id != v_trade.proposal_id AND status = 'pending';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'trade_id', p_trade_id,
        'completed_at', NOW()
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Trade execution failed: %', SQLERRM;
        RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."execute_trade"("p_trade_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."execute_trade"("p_trade_id" "uuid") IS 'Atomically execute a trade. Updates vip_cards and gidouilles directly.
Logs to vip_cards_activity (with partner names) and gidouilles_activity
(with descriptive reasons including partner name and trade ID).';



