CREATE OR REPLACE FUNCTION "public"."finalize_tournament"("p_tournament_id" "uuid") RETURNS TABLE("success" boolean, "rewards_distributed" integer, "reference_updates" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tournament RECORD;
  v_standing RECORD;
  v_reward INTEGER;
  v_rewards_count INTEGER := 0;
  v_reference_count INTEGER := 0;
BEGIN
  -- Step 1: Get and validate tournament
  SELECT * INTO v_tournament
  FROM public.minesweeper_tournaments
  WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found';
  END IF;

  -- Only creator or admin can finalize
  IF v_tournament.creator_id != auth.uid() THEN
    -- Check if admin
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND role = 'admin'
    ) THEN
      RAISE EXCEPTION 'Only tournament creator or admin can finalize';
    END IF;
  END IF;

  -- Check tournament is active or past end date
  IF v_tournament.status NOT IN ('active', 'scheduled') THEN
    RAISE EXCEPTION 'Tournament already finalized or cancelled';
  END IF;

  -- Step 2: Distribute rewards to podium
  FOR v_standing IN
    SELECT s.student_id, s.position
    FROM public.minesweeper_tournament_standings s
    WHERE s.tournament_id = p_tournament_id
      AND s.position <= v_tournament.podium_places
    ORDER BY s.position
  LOOP
    -- Get reward amount for this position
    v_reward := (v_tournament.podium_rewards->>v_standing.position::TEXT)::INTEGER;

    IF v_reward IS NOT NULL AND v_reward > 0 THEN
      -- Award gidouilles
      UPDATE public.profiles
      SET gidouilles = COALESCE(gidouilles, 0) + v_reward
      WHERE id = v_standing.student_id;

      -- Record in history
      INSERT INTO public.gidouilles_history (student_id, delta, reason)
      VALUES (
        v_standing.student_id,
        v_reward,
        'Tournament ' || v_tournament.name || ' - Position #' || v_standing.position
      );

      v_rewards_count := v_rewards_count + 1;
    END IF;
  END LOOP;

  -- Step 3: Update 3BV reference values with tournament data
  WITH tournament_stats AS (
    SELECT
      public.get_cycle_for_grade(p.grade) AS cycle,
      t.difficulty,
      AVG(g.grid_3bv::NUMERIC / GREATEST(1, g.time_seconds)) AS avg_3bvs,
      COUNT(*) AS new_samples
    FROM public.minesweeper_tournament_games g
    JOIN public.minesweeper_tournaments t ON t.id = g.tournament_id
    JOIN public.profiles p ON p.id = g.student_id
    WHERE g.tournament_id = p_tournament_id
      AND g.status = 'won'
      AND g.grid_3bv IS NOT NULL
      AND g.time_seconds IS NOT NULL
      AND public.get_cycle_for_grade(p.grade) IS NOT NULL
    GROUP BY public.get_cycle_for_grade(p.grade), t.difficulty
  ),
  updated AS (
    UPDATE public.minesweeper_tournament_3bv_reference ref
    SET
      reference_3bvs = CASE
        WHEN ref.sample_count + ts.new_samples > 0 THEN
          (ref.reference_3bvs * ref.sample_count + ts.avg_3bvs * ts.new_samples)
          / (ref.sample_count + ts.new_samples)
        ELSE ref.reference_3bvs
      END,
      sample_count = ref.sample_count + ts.new_samples,
      updated_at = NOW()
    FROM tournament_stats ts
    WHERE ref.cycle = ts.cycle AND ref.difficulty = ts.difficulty
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_reference_count FROM updated;

  -- Step 4: Mark tournament as completed
  UPDATE public.minesweeper_tournaments
  SET status = 'completed', updated_at = NOW()
  WHERE id = p_tournament_id;

  -- Return results
  success := TRUE;
  rewards_distributed := v_rewards_count;
  reference_updates := v_reference_count;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."finalize_tournament"("p_tournament_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_tournament"("p_tournament_id" "uuid") IS 'Finalizes a tournament: distributes podium rewards and updates 3BV reference values.
   Returns success, rewards_distributed count, and reference_updates count.';



CREATE OR REPLACE FUNCTION "public"."game_leaderboard"("p_game" "text", "p_scope" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("rank" integer, "user_id" "uuid", "firstname" "text", "avatar_url" "text", "score" numeric, "is_me" boolean, "is_teacher" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
	v_uid    uuid := auth.uid();
	v_limit  int  := least(greatest(coalesce(p_limit, 50), 1), 200);  -- clamp [1,200]
BEGIN
	-- Guard: authenticated caller + valid game + valid scope, else empty.
	IF v_uid IS NULL
	   OR p_game  NOT IN ('2048', 'mathemo', 'minesweeper')
	   OR p_scope NOT IN ('class', 'grade', 'school')
	THEN
		RETURN;
	END IF;

	RETURN QUERY
	WITH
	-- Students inside the caller's scope (real students only), joined to scores.
	scoped_students AS (
		SELECT p.id, p.firstname, p.avatar_url, gsu.score
		FROM public.profiles p
		JOIN public.game_scores_unified gsu
		  ON gsu.user_id = p.id AND gsu.game = p_game
		WHERE p.role = 'student'
		  AND coalesce(p.is_test, false) = false
		  AND (
		    -- class: my active classmates (self-join on shared class), school-bounded
		    -- by construction (defense-in-depth: a class spanning two schools could
		    -- not leak cross-school rows even if the data invariant broke).
		    ( p_scope = 'class'
		         AND public.my_school() IS NOT NULL
		         AND p.school_id = public.my_school()
		         AND p.id IN (
		        SELECT cm2.student_id
		        FROM public.class_members cm1
		        JOIN public.class_members cm2 USING (class_id)
		        WHERE cm1.student_id = v_uid
		          AND cm1.status = 'active'
		          AND cm2.status = 'active'
		      ) )
		    -- grade: same grade ∩ my school (requires my grade NOT NULL).
		    OR ( p_scope = 'grade'
		         AND (SELECT grade FROM public.profiles WHERE id = v_uid) IS NOT NULL
		         AND p.grade = (SELECT grade FROM public.profiles WHERE id = v_uid)
		         AND p.school_id = public.my_school() )
		    -- school: my school (requires my_school() NOT NULL).
		    OR ( p_scope = 'school'
		         AND public.my_school() IS NOT NULL
		         AND p.school_id = public.my_school() )
		  )
	),
	-- dense_rank among students only (ties share rank, no gap).
	ranked AS (
		SELECT ss.id, ss.firstname, ss.avatar_url, ss.score,
		       dense_rank() OVER (ORDER BY ss.score DESC)::int AS rk
		FROM scoped_students ss
	),
	-- Single teacher reference row, school-bounded, NOT limit-bound. Admin excluded.
	teacher AS (
		SELECT NULL::int AS rk, p.id, p.firstname, p.avatar_url, gsu.score
		FROM public.profiles p
		JOIN public.game_scores_unified gsu
		  ON gsu.user_id = p.id AND gsu.game = p_game
		WHERE p.role = 'teacher'
		  AND coalesce(p.is_test, false) = false
		  AND p.school_id = public.my_school()
	)
	SELECT r.rk, r.id, r.firstname, r.avatar_url, r.score,
	       (r.id = v_uid) AS is_me, false AS is_teacher
	FROM ranked r
	WHERE r.rk <= v_limit
	UNION ALL
	SELECT t.rk, t.id, t.firstname, t.avatar_url, t.score,
	       (t.id = v_uid) AS is_me, true AS is_teacher
	FROM teacher t
	-- Teacher interleaved by score; on a tie with a student, teacher comes after.
	-- firstname is the final tiebreak so equal-score rows have a stable order.
	ORDER BY score DESC, rank NULLS LAST, firstname;
END;
$$;


ALTER FUNCTION "public"."game_leaderboard"("p_game" "text", "p_scope" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."game_leaderboard"("p_game" "text", "p_scope" "text", "p_limit" integer) IS 'Ranks the caller (auth.uid()) scope for p_game in {2048,mathemo,minesweeper}, p_scope in {class,grade,school}, p_limit clamped [1,200]. dense_rank among students (role=student, is_test=false); single teacher of same school appended as rank=NULL reference row (not limit-bound); admin excluded. School-bounded via my_school() — no cross-school leakage.';



CREATE OR REPLACE FUNCTION "public"."generate_error_signature"("p_error_type" "text", "p_message" "text", "p_file_path" "text", "p_line_number" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN encode(
    digest(
      COALESCE(p_error_type, '') || '||' ||
      COALESCE(p_message, '') || '||' ||
      COALESCE(p_file_path, '') || '||' ||
      COALESCE(p_line_number::TEXT, ''),
      'sha256'
    ),
    'hex'
  );
END;
$$;


ALTER FUNCTION "public"."generate_error_signature"("p_error_type" "text", "p_message" "text", "p_file_path" "text", "p_line_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_join_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    code TEXT;
    exists BOOLEAN;
BEGIN
    LOOP
        code := upper(substring(md5(random()::text) from 1 for 6));
        SELECT EXISTS(SELECT 1 FROM classes WHERE join_code = code) INTO exists;
        EXIT WHEN NOT exists;
    END LOOP;
    RETURN code;
END;
$$;


ALTER FUNCTION "public"."generate_join_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_reward_event_description"("p_source_table" "text", "p_reason" "text", "p_delta" numeric DEFAULT NULL::numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF p_source_table IN ('gidouilles_history', 'gidouilles_activity') THEN
        IF p_reason IS NULL OR p_reason = '' THEN
            IF p_delta IS NOT NULL AND p_delta > 0 THEN
                RETURN 'Gidouilles gagnées';
            ELSIF p_delta IS NOT NULL AND p_delta < 0 THEN
                RETURN 'Gidouilles dépensées';
            ELSE
                RETURN 'Modification de gidouilles';
            END IF;
        END IF;

        CASE p_reason
            WHEN 'weekly_no_warning' THEN RETURN 'Récompense hebdomadaire (0 avertissement)';
            WHEN 'weekly_best_game_bonus' THEN RETURN 'Récompense hebdomadaire pour les jeux';
            -- Per-game weekly bonus
            WHEN 'weekly_best_game_bonus:minesweeper' THEN RETURN 'Démineur : récompense hebdomadaire';
            WHEN 'weekly_best_game_bonus:riddle' THEN RETURN 'Énigme : récompense hebdomadaire';
            WHEN 'weekly_best_game_bonus:2048' THEN RETURN '2048 : récompense hebdomadaire';
            WHEN 'weekly_best_game_bonus:mathemo' THEN RETURN 'Mathémo : récompense hebdomadaire';
            -- Daily rewards
            WHEN 'minesweeper_victory' THEN RETURN 'Victoire au démineur';
            WHEN 'minesweeper_hint' THEN RETURN 'Indice démineur';
            WHEN 'daily_game_reward:minesweeper' THEN RETURN 'Démineur : récompense quotidienne';
            WHEN 'daily_game_reward:riddle' THEN RETURN 'Énigme : récompense quotidienne';
            WHEN 'daily_game_reward:2048' THEN RETURN '2048 : récompense quotidienne';
            WHEN 'daily_game_reward:mathemo' THEN RETURN 'Mathémo : récompense quotidienne';
            -- Other
            WHEN 'shop_purchase' THEN RETURN 'Achat en boutique';
            WHEN 'Modifié par professeur' THEN RETURN 'Modifié par professeur';
            ELSE RETURN p_reason;
        END CASE;
    END IF;

    IF p_source_table = 'bonus_history' THEN
        IF p_reason IS NULL OR p_reason = '' THEN
            IF p_delta IS NOT NULL AND p_delta > 0 THEN
                RETURN 'Bonus gagné';
            ELSIF p_delta IS NOT NULL AND p_delta < 0 THEN
                RETURN 'Bonus utilisé';
            ELSE
                RETURN 'Modification de bonus';
            END IF;
        END IF;
        RETURN p_reason;
    END IF;

    IF p_source_table = 'vip_cards_activity' THEN
        CASE p_reason
            WHEN 'drawn' THEN RETURN 'Carte VIP obtenue';
            WHEN 'used' THEN RETURN 'Carte VIP utilisée';
            WHEN 'traded' THEN RETURN 'Carte VIP échangée';
            WHEN 'gained' THEN RETURN 'Carte VIP reçue';
            ELSE RETURN COALESCE(p_reason, 'Activité carte VIP');
        END CASE;
    END IF;

    RETURN COALESCE(p_reason, 'Événement de récompense');
END;
$$;


ALTER FUNCTION "public"."generate_reward_event_description"("p_source_table" "text", "p_reason" "text", "p_delta" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_reward_event_description"("p_source_table" "text", "p_reason" "text", "p_delta" numeric) IS 'Generate human-readable description for reward events. Used by gidouilles_activity trigger. Accepts NUMERIC delta for decimal gidouilles.';



CREATE OR REPLACE FUNCTION "public"."generate_reward_event_description"("p_reward_type" "public"."reward_type", "p_event_type" "public"."reward_event_type", "p_amount" numeric, "p_item_name" "text", "p_metadata" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- Gidouilles events
    IF p_reward_type = 'gidouilles' THEN
        CASE p_event_type
            WHEN 'earned' THEN
                RETURN format('Gagné %s gidouilles%s',
                    ROUND(ABS(p_amount), 2),
                    CASE WHEN p_metadata->>'reason' IS NOT NULL
                        THEN ' : ' || (p_metadata->>'reason')
                        ELSE ''
                    END);
            WHEN 'spent' THEN
                RETURN format('Dépensé %s gidouilles%s',
                    ROUND(ABS(p_amount), 2),
                    CASE WHEN p_metadata->>'reason' IS NOT NULL
                        THEN ' : ' || (p_metadata->>'reason')
                        ELSE ''
                    END);
            WHEN 'transferred_in' THEN
                RETURN format('Reçu %s gidouilles', ROUND(ABS(p_amount), 2));
            WHEN 'transferred_out' THEN
                RETURN format('Envoyé %s gidouilles', ROUND(ABS(p_amount), 2));
            WHEN 'traded' THEN
                RETURN format('Échangé %s gidouilles', ROUND(ABS(p_amount), 2));
            WHEN 'awarded' THEN
                RETURN format('Reçu %s gidouilles (récompense)', ROUND(ABS(p_amount), 2));
            WHEN 'removed' THEN
                RETURN format('Retiré %s gidouilles', ROUND(ABS(p_amount), 2));
            ELSE
                RETURN format('%s gidouilles', ROUND(p_amount, 2));
        END CASE;
    END IF;

    -- Bonus events
    IF p_reward_type = 'bonus' THEN
        CASE p_event_type
            WHEN 'earned' THEN
                RETURN format('Gagné %s bonus%s',
                    ROUND(ABS(p_amount)),
                    CASE WHEN p_metadata->>'reason' IS NOT NULL
                        THEN ' : ' || (p_metadata->>'reason')
                        ELSE ''
                    END);
            WHEN 'used' THEN
                RETURN format('Utilisé %s bonus', ROUND(ABS(p_amount)));
            WHEN 'awarded' THEN
                RETURN format('Reçu %s bonus (récompense)', ROUND(ABS(p_amount)));
            ELSE
                RETURN format('%s bonus : %s', ROUND(p_amount), p_event_type);
        END CASE;
    END IF;

    -- VIP card events
    IF p_reward_type = 'vip_card' THEN
        CASE p_event_type
            WHEN 'earned' THEN
                RETURN format('Obtenu carte VIP : %s', COALESCE(p_item_name, 'Carte'));
            WHEN 'used' THEN
                RETURN format('Utilisé carte VIP : %s', COALESCE(p_item_name, 'Carte'));
            WHEN 'removed' THEN
                RETURN format('Carte VIP retirée : %s', COALESCE(p_item_name, 'Carte'));
            ELSE
                RETURN format('Carte VIP : %s', COALESCE(p_item_name, 'Carte'));
        END CASE;
    END IF;

    -- Achievement events
    IF p_reward_type = 'achievement' THEN
        RETURN format('Achievement débloqué : %s', COALESCE(p_item_name, 'Achievement'));
    END IF;

    -- Item events
    IF p_reward_type = 'item' THEN
        CASE p_event_type
            WHEN 'purchased' THEN
                RETURN format('Acheté : %s', COALESCE(p_item_name, 'Item'));
            WHEN 'used' THEN
                RETURN format('Utilisé : %s', COALESCE(p_item_name, 'Item'));
            WHEN 'traded' THEN
                RETURN format('Échangé : %s', COALESCE(p_item_name, 'Item'));
            ELSE
                RETURN format('Item : %s', COALESCE(p_item_name, 'Item'));
        END CASE;
    END IF;

    -- Points events
    IF p_reward_type = 'points' THEN
        CASE p_event_type
            WHEN 'earned' THEN
                RETURN format('Gagné %s points%s',
                    ROUND(p_amount),
                    CASE WHEN p_metadata->>'reason' IS NOT NULL
                        THEN ' : ' || (p_metadata->>'reason')
                        ELSE ''
                    END);
            ELSE
                RETURN format('%s points', ROUND(p_amount));
        END CASE;
    END IF;

    -- Default
    RETURN format('%s: %s', p_reward_type, p_event_type);
END;
$$;


ALTER FUNCTION "public"."generate_reward_event_description"("p_reward_type" "public"."reward_type", "p_event_type" "public"."reward_event_type", "p_amount" numeric, "p_item_name" "text", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_reward_event_description"("p_reward_type" "public"."reward_type", "p_event_type" "public"."reward_event_type", "p_amount" numeric, "p_item_name" "text", "p_metadata" "jsonb") IS 'Generates human-readable description for reward events. Single NUMERIC version handles both integer and decimal amounts.';



CREATE OR REPLACE FUNCTION "public"."generate_share_token"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
    result TEXT := '';
    i INTEGER;
BEGIN
    FOR i IN 1..16 LOOP
        result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."generate_share_token"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_variant_seed"("p_worksheet_id" "uuid", "p_student_id" "uuid", "p_base_seed" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  seed_value INTEGER;
BEGIN
  IF p_base_seed IS NOT NULL THEN
    -- Use provided base seed with student-specific offset
    seed_value := p_base_seed + hashtext(p_student_id::TEXT) % 10000;
  ELSE
    -- Generate unique seed based on worksheet and student IDs
    seed_value := abs(hashtext(p_worksheet_id::TEXT || p_student_id::TEXT));
  END IF;

  RETURN seed_value % 2147483647; -- Ensure positive integer within PostgreSQL integer range
END;
$$;


ALTER FUNCTION "public"."generate_variant_seed"("p_worksheet_id" "uuid", "p_student_id" "uuid", "p_base_seed" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_2048_user_rank"("p_user_id" "uuid") RETURNS TABLE("user_rank" bigint, "total_players" bigint, "user_score" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
	RETURN QUERY
	WITH ranked_scores AS (
		SELECT
			user_id,
			best_score,
			RANK() OVER (ORDER BY best_score DESC) AS rank,
			COUNT(*) OVER () AS total
		FROM game_2048_scores
	)
	SELECT
		ranked_scores.rank AS user_rank,
		COALESCE(ranked_scores.total, 0) AS total_players,
		COALESCE(ranked_scores.best_score, 0) AS user_score
	FROM ranked_scores
	WHERE ranked_scores.user_id = p_user_id;
END;
$$;


