CREATE OR REPLACE FUNCTION "public"."get_accessible_kanban_boards"("p_limit" integer DEFAULT 100, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "owner_id" "uuid", "class_id" "uuid", "title" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "column_count" bigint, "card_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    SELECT
        b.id,
        b.owner_id,
        b.class_id,
        b.title,
        b.created_at,
        b.updated_at,
        (SELECT COUNT(*) FROM public.kanban_columns kc WHERE kc.board_id = b.id) AS column_count,
        (SELECT COUNT(*) FROM public.kanban_cards kca
            JOIN public.kanban_columns kcc ON kcc.id = kca.column_id
            WHERE kcc.board_id = b.id) AS card_count
    FROM public.kanban_boards b
    WHERE p_cursor IS NULL OR b.updated_at < p_cursor
    ORDER BY b.updated_at DESC, b.id DESC
    LIMIT GREATEST(1, LEAST(p_limit, 200));
$$;


