COMMENT ON FUNCTION "public"."get_achievement_leaderboard"("p_limit" integer, "p_context" "text") IS 'Get achievement leaderboard with student details. Uses materialized view for global leaderboard.';



CREATE OR REPLACE FUNCTION "public"."get_all_exercise_assignments"() RETURNS TABLE("id" "uuid", "exercise_id" "uuid", "assigned_by" "uuid", "assigned_to_type" "text", "student_id" "uuid", "class_id" "uuid", "assigned_at" timestamp with time zone, "optional_deadline" timestamp with time zone, "notes" "text", "is_active" boolean, "exercise_title" "text", "variations" "jsonb", "shared" "jsonb", "variables" "jsonb", "distribution_mode" "text", "exercise_is_public" boolean, "tags" "text"[], "grades" "text"[], "exercise_creator_id" "uuid", "assigned_by_name" "text", "assigned_by_role" "text", "assigned_to_name" "text", "student_email" "text", "class_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT
        ea.id,
        ea.exercise_id,
        ea.assigned_by,
        ea.assigned_to_type,
        ea.student_id,
        ea.class_id,
        ea.assigned_at,
        ea.optional_deadline,
        ea.notes,
        ea.is_active,
        e.title as exercise_title,
        e.variations,
        e.shared,
        e.variables,
        e.distribution_mode,
        e.is_public as exercise_is_public,
        COALESCE(
            ARRAY(
                SELECT t.name FROM exercise_tags et
                JOIN tags t ON t.id = et.tag_id
                WHERE et.exercise_id = e.id
                ORDER BY t.name
            ),
            '{}'::TEXT[]
        ) AS tags,
        e.grades,
        e.created_by as exercise_creator_id,
        p.full_name as assigned_by_name,
        p.role as assigned_by_role,
        CASE
            WHEN ea.assigned_to_type = 'student' THEN s.full_name
            WHEN ea.assigned_to_type = 'class' THEN c.name
            ELSE 'Public'
        END as assigned_to_name,
        s.email as student_email,
        c.name as class_name
    FROM exercise_assignments ea
    JOIN exercises e ON ea.exercise_id = e.id
    JOIN profiles p ON ea.assigned_by = p.id
    LEFT JOIN profiles s ON ea.student_id = s.id
    LEFT JOIN classes c ON ea.class_id = c.id
    WHERE ea.is_active = TRUE
        AND EXISTS (
            SELECT 1 FROM public.profiles
            WHERE id = auth.uid() AND role = 'admin'
        );
$$;


ALTER FUNCTION "public"."get_all_exercise_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_allowed_recipients"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "full_name" "text", "avatar_url" "text", "role" "text", "relationship" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_role TEXT;
BEGIN
  -- Get user's role (fixed ambiguous column reference)
  SELECT profiles.role INTO v_user_role
  FROM profiles
  WHERE profiles.id = p_user_id;

  -- Students can message their teachers
  IF v_user_role = 'student' THEN
    RETURN QUERY
    SELECT
      p.id AS user_id,
      p.full_name,
      p.avatar_url,
      p.role::TEXT,
      'teacher'::TEXT AS relationship
    FROM get_student_teachers(p_user_id) gst
    JOIN profiles p ON p.id = gst.teacher_id
    ORDER BY p.full_name;

  -- Teachers can message their students
  ELSIF v_user_role = 'teacher' THEN
    RETURN QUERY
    SELECT
      p.id AS user_id,
      p.full_name,
      p.avatar_url,
      p.role::TEXT,
      'student'::TEXT AS relationship
    FROM get_teacher_students(p_user_id) gts
    JOIN profiles p ON p.id = gts.student_id
    ORDER BY p.full_name;

  -- Admins can message anyone
  ELSIF v_user_role = 'admin' THEN
    RETURN QUERY
    SELECT
      p.id AS user_id,
      p.full_name,
      p.avatar_url,
      p.role::TEXT,
      'any'::TEXT AS relationship
    FROM profiles p
    WHERE p.id != p_user_id
    ORDER BY p.full_name;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_allowed_recipients"("p_user_id" "uuid") OWNER TO "postgres";


