CREATE OR REPLACE FUNCTION "public"."get_assessment_results_for_admin"("p_assessment_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("assignment_id" "uuid", "assessment_id" "uuid", "assessment_title" "text", "assessment_grade" "text", "class_id" "uuid", "student_id" "uuid", "student_user_id" "uuid", "student_firstname" "text", "student_lastname" "text", "class_name" "text", "best_score" integer, "attempts_count" bigint, "last_attempt_at" timestamp with time zone, "status" "text", "total_questions" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    aa.id AS assignment_id,
    aa.assessment_id,
    a.title AS assessment_title,
    a.grade AS assessment_grade,
    aa.class_id,
    aa.student_id,
    p.id AS student_user_id,
    p.firstname AS student_firstname,
    p.lastname AS student_lastname,
    c.name AS class_name,
    MAX(ts.score) AS best_score,
    COUNT(ts.id) AS attempts_count,
    MAX(ts.completed_at) AS last_attempt_at,
    CASE
      WHEN COUNT(ts.id) = 0 THEN 'not_started'
      WHEN MAX(ts.completed_at) IS NULL THEN 'in_progress'
      ELSE 'completed'
    END AS status,
    (SELECT total_questions FROM test_sessions WHERE assignment_id = aa.id LIMIT 1) AS total_questions
  FROM public.assessment_assignments aa
  JOIN public.assessments a ON a.id = aa.assessment_id
  LEFT JOIN public.classes c ON c.id = aa.class_id
  LEFT JOIN profiles p ON p.id = COALESCE(aa.student_id, NULL)
  LEFT JOIN public.test_sessions ts ON ts.assignment_id = aa.id AND ts.user_id = p.id
  WHERE a.status != 'archived'
    AND (p_assessment_id IS NULL OR a.id = p_assessment_id)
    AND EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND role = 'admin'
    )
  GROUP BY aa.id, aa.assessment_id, a.title, a.grade, aa.class_id, aa.student_id,
           p.id, p.firstname, p.lastname, c.name;
$$;


ALTER FUNCTION "public"."get_assessment_results_for_admin"("p_assessment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_assessment_results_for_admin"("p_assessment_id" "uuid") IS 'Returns all assessment results (admin only). Optionally filter by assessment_id.';



CREATE OR REPLACE FUNCTION "public"."get_assessment_results_for_student"() RETURNS TABLE("assignment_id" "uuid", "assessment_id" "uuid", "assessment_title" "text", "assessment_grade" "text", "class_id" "uuid", "student_id" "uuid", "student_user_id" "uuid", "student_firstname" "text", "student_lastname" "text", "class_name" "text", "best_score" integer, "attempts_count" bigint, "last_attempt_at" timestamp with time zone, "status" "text", "total_questions" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    aa.id AS assignment_id,
    aa.assessment_id,
    a.title AS assessment_title,
    a.grade AS assessment_grade,
    aa.class_id,
    aa.student_id,
    p.id AS student_user_id,
    p.firstname AS student_firstname,
    p.lastname AS student_lastname,
    c.name AS class_name,
    MAX(ts.score) AS best_score,
    COUNT(ts.id) AS attempts_count,
    MAX(ts.completed_at) AS last_attempt_at,
    CASE
      WHEN COUNT(ts.id) = 0 THEN 'not_started'
      WHEN MAX(ts.completed_at) IS NULL THEN 'in_progress'
      ELSE 'completed'
    END AS status,
    (SELECT total_questions FROM test_sessions WHERE assignment_id = aa.id LIMIT 1) AS total_questions
  FROM public.assessment_assignments aa
  JOIN public.assessments a ON a.id = aa.assessment_id
  LEFT JOIN public.classes c ON c.id = aa.class_id
  LEFT JOIN profiles p ON p.id = COALESCE(aa.student_id, NULL)
  LEFT JOIN public.test_sessions ts ON ts.assignment_id = aa.id AND ts.user_id = p.id
  WHERE a.status != 'archived'
    AND p.id = auth.uid() -- Only show student's own results
  GROUP BY aa.id, aa.assessment_id, a.title, a.grade, aa.class_id, aa.student_id,
           p.id, p.firstname, p.lastname, c.name;
$$;


