CREATE OR REPLACE FUNCTION "public"."get_assignment_completion_stats"("p_assignment_id" "uuid") RETURNS TABLE("total_target_students" bigint, "students_viewed" bigint, "students_completed" bigint, "total_views" bigint, "avg_views_per_student" numeric, "completion_rate" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
    WITH assignment_details AS (
        SELECT
            assigned_to_type,
            student_id,
            class_id
        FROM exercise_assignments
        WHERE id = p_assignment_id
    ),
    target_students AS (
        SELECT
            CASE
                WHEN ad.assigned_to_type = 'student' THEN ARRAY[ad.student_id]
                WHEN ad.assigned_to_type = 'class' THEN ARRAY_AGG(cm.student_id)
                ELSE ARRAY[]::UUID[]  -- Public has no specific target
            END as student_ids
        FROM assignment_details ad
        LEFT JOIN class_members cm ON ad.class_id = cm.class_id
        GROUP BY ad.assigned_to_type, ad.student_id
    )
    SELECT
        CARDINALITY((SELECT student_ids FROM target_students)) as total_target_students,
        COUNT(DISTINCT ec.student_id) FILTER (WHERE ec.id IS NOT NULL) as students_viewed,
        COUNT(DISTINCT ec.student_id) FILTER (WHERE ec.completed_at IS NOT NULL) as students_completed,
        COALESCE(SUM(ec.view_count), 0) as total_views,
        COALESCE(AVG(ec.view_count), 0) as avg_views_per_student,
        CASE
            WHEN CARDINALITY((SELECT student_ids FROM target_students)) > 0
            THEN ROUND(
                COUNT(DISTINCT ec.student_id) FILTER (WHERE ec.completed_at IS NOT NULL)::NUMERIC /
                CARDINALITY((SELECT student_ids FROM target_students))::NUMERIC * 100,
                2
            )
            ELSE 0
        END as completion_rate
    FROM target_students
    LEFT JOIN exercise_completions ec ON ec.assignment_id = p_assignment_id
        AND (
            (SELECT assigned_to_type FROM assignment_details) = 'public'
            OR ec.student_id IN (SELECT unnest(student_ids) FROM target_students)
        );
$$;


ALTER FUNCTION "public"."get_assignment_completion_stats"("p_assignment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_assignment_completion_stats"("p_assignment_id" "uuid") IS 'Returns detailed completion statistics for an assignment including view counts and completion rates';



CREATE OR REPLACE FUNCTION "public"."get_available_cards_for_student"("p_student_id" "uuid") RETURNS TABLE("card_id" "text", "card_name" "text", "rarity" "text", "is_globally_enabled" boolean, "blocked_by_teachers" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    vct.id as card_id,
    vct.name as card_name,
    vct.rarity,
    vct.is_enabled as is_globally_enabled,
    ARRAY_AGG(DISTINCT p.full_name) FILTER (WHERE tvo.is_enabled = FALSE) as blocked_by_teachers
  FROM vip_card_templates vct
  LEFT JOIN teacher_vip_card_overrides tvo ON tvo.card_id = vct.id
    AND tvo.teacher_id IN (
      SELECT DISTINCT c.teacher_id
      FROM class_members cm
      INNER JOIN classes c ON c.id = cm.class_id
      WHERE cm.student_id = p_student_id
    )
  LEFT JOIN profiles p ON p.id = tvo.teacher_id
  GROUP BY vct.id, vct.name, vct.rarity, vct.is_enabled
  ORDER BY
    CASE vct.rarity
      WHEN 'common' THEN 1
      WHEN 'rare' THEN 2
      WHEN 'epic' THEN 3
      WHEN 'legendary' THEN 4
    END,
    vct.name;
END;
$$;


ALTER FUNCTION "public"."get_available_cards_for_student"("p_student_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_available_cards_for_student"("p_student_id" "uuid") IS 'Returns all VIP cards with their availability status for a specific student. Shows which cards are globally enabled and which teachers have disabled each card. Useful for debugging and transparency.';



CREATE OR REPLACE FUNCTION "public"."get_classes_by_user_grade"() RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  user_grades text[];
BEGIN
  -- Get unique grades from user's classes
  SELECT ARRAY_AGG(DISTINCT c.grade)
  INTO user_grades
  FROM class_members cm
  JOIN classes c ON c.id = cm.class_id
  WHERE cm.student_id = auth.uid()
    AND cm.status = 'active'
    AND c.grade IS NOT NULL;

  -- If no grades found, return user's own classes
  IF user_grades IS NULL OR array_length(user_grades, 1) IS NULL THEN
    RETURN QUERY
    SELECT c.id, c.name
    FROM class_members cm
    JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = auth.uid()
      AND cm.status = 'active'
    ORDER BY c.name;
    RETURN;
  END IF;

  -- Return all active classes with matching grades
  RETURN QUERY
  SELECT c.id, c.name
  FROM classes c
  WHERE c.is_active = true
    AND c.grade = ANY(user_grades)
  ORDER BY c.name;
END;
$$;


ALTER FUNCTION "public"."get_classes_by_user_grade"() OWNER TO "postgres";


