CREATE OR REPLACE FUNCTION "public"."get_consent_info"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_consent_id UUID;
    v_student_id UUID;
    v_status consent_status;
    v_expires_at TIMESTAMPTZ;
    v_parent_email TEXT;
    v_student RECORD;
    v_teacher_name TEXT;
    v_school_name TEXT;
BEGIN
    -- Find the consent record by token
    SELECT id, student_id, status, expires_at, parent_email
    INTO v_consent_id, v_student_id, v_status, v_expires_at, v_parent_email
    FROM parental_consents
    WHERE consent_token = p_token;

    -- Token not found
    IF v_consent_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'TOKEN_NOT_FOUND',
            'message', 'Lien de consentement invalide.'
        );
    END IF;

    -- Already granted
    IF v_status = 'granted' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'ALREADY_GRANTED',
            'message', 'Ce consentement a déjà été accordé.'
        );
    END IF;

    -- Token expired
    IF v_expires_at < NOW() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'TOKEN_EXPIRED',
            'message', 'Ce lien a expiré. Contactez l''enseignant pour recevoir un nouveau lien.'
        );
    END IF;

    -- Get student info (limited fields for privacy)
    SELECT firstname, lastname, grade
    INTO v_student
    FROM profiles
    WHERE id = v_student_id;

    -- Try to get teacher name from class_members
    SELECT p.firstname || ' ' || p.lastname
    INTO v_teacher_name
    FROM class_members cm
    JOIN classes c ON cm.class_id = c.id
    JOIN profiles p ON c.teacher_id = p.id
    WHERE cm.student_id = v_student_id
    LIMIT 1;

    -- Try to get school name
    SELECT s.name
    INTO v_school_name
    FROM class_members cm
    JOIN classes c ON cm.class_id = c.id
    JOIN schools s ON c.school_id = s.id
    WHERE cm.student_id = v_student_id
    LIMIT 1;

    RETURN jsonb_build_object(
        'success', true,
        'student', jsonb_build_object(
            'firstname', v_student.firstname,
            'lastname', v_student.lastname,
            'grade', v_student.grade
        ),
        'teacher_name', v_teacher_name,
        'school_name', v_school_name,
        'parent_email', v_parent_email,
        'expires_at', v_expires_at
    );
END;
$$;


ALTER FUNCTION "public"."get_consent_info"("p_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_consent_info"("p_token" "uuid") IS 'Returns limited student info for consent verification page. Called by anonymous parents before granting consent.';



