COMMENT ON FUNCTION "public"."get_deck_stats"("p_user_id" "uuid", "p_deck_id" "uuid") IS 'Get statistics for a deck (total cards, due count, state counts)';



CREATE OR REPLACE FUNCTION "public"."get_due_cards_for_deck"("p_user_id" "uuid", "p_deck_id" "uuid") RETURNS TABLE("card_id" "uuid", "template_id" "uuid", "card_type" "text", "difficulty" real, "stability" real, "state" "text", "next_review" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id AS card_id,
    c.template_id,
    c.card_type,
    COALESCE(s.difficulty, 5.0) AS difficulty,
    COALESCE(s.stability, 0.0) AS stability,
    COALESCE(s.state, 'new'::TEXT) AS state,
    COALESCE(s.next_review, NOW()) AS next_review
  FROM srs_cards c
  LEFT JOIN srs_card_stats s ON (
    s.user_id = p_user_id
    AND s.card_reference_type = c.card_type
    AND (
      (c.card_type = 'template' AND s.card_reference_id::text = c.template_id::text)
      OR (c.card_type = 'custom' AND s.card_reference_id::text = c.id::text)
    )
  )
  WHERE
    c.deck_id = p_deck_id
    AND COALESCE(s.next_review, NOW()) <= NOW()
  ORDER BY COALESCE(s.next_review, NOW()) ASC;
END;
$$;


