CREATE OR REPLACE FUNCTION "public"."get_message_attachments"("p_message_id" "uuid") RETURNS TABLE("id" "uuid", "file_name" "text", "file_type" "text", "file_size" integer, "public_url" "text", "uploaded_by" "uuid", "uploader_firstname" "text", "uploader_lastname" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Check if user is a participant in the conversation
  IF NOT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Permission denied: not a participant';
  END IF;

  RETURN QUERY
  SELECT
    a.id,
    a.file_name,
    a.file_type,
    a.file_size,
    a.public_url,
    a.uploaded_by,
    p.firstname,
    p.lastname,
    a.created_at
  FROM message_attachments a
  LEFT JOIN profiles p ON p.id = a.uploaded_by
  WHERE a.message_id = p_message_id
  ORDER BY a.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_message_attachments"("p_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_message_attachments"("p_message_id" "uuid") IS 'Get all attachments for a message';



CREATE OR REPLACE FUNCTION "public"."get_message_context_for_moderation"("p_message_id" "uuid", "p_before_count" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "conversation_id" "uuid", "sender_id" "uuid", "sender_firstname" "text", "sender_lastname" "text", "sender_avatar_url" "text", "content" "jsonb", "plain_text" "text", "created_at" timestamp with time zone, "is_reported_message" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conversation_id UUID;
  v_message_created_at TIMESTAMPTZ;
BEGIN
  -- Only teachers/admins can access this
  IF NOT is_teacher_or_admin() THEN
    RAISE EXCEPTION 'Permission denied: teachers only';
  END IF;

  -- Get the reported message's conversation and timestamp
  SELECT m.conversation_id, m.created_at
  INTO v_conversation_id, v_message_created_at
  FROM messages m
  WHERE m.id = p_message_id;

  IF v_conversation_id IS NULL THEN
    RAISE EXCEPTION 'Message not found';
  END IF;

  -- Return context messages (before) + the reported message
  RETURN QUERY
  WITH context_messages AS (
    -- Get messages before the reported message
    SELECT
      m.id,
      m.conversation_id,
      m.sender_id,
      p.firstname AS sender_firstname,
      p.lastname AS sender_lastname,
      p.avatar_url AS sender_avatar_url,
      -- Don't mask content for moderation context (teachers need to see it)
      m.content,
      m.plain_text,
      m.created_at,
      FALSE AS is_reported_message
    FROM messages m
    LEFT JOIN profiles p ON p.id = m.sender_id
    WHERE m.conversation_id = v_conversation_id
      AND m.created_at < v_message_created_at
      AND m.deleted_at IS NULL
    ORDER BY m.created_at DESC
    LIMIT p_before_count
  ),
  reported_message AS (
    -- Get the reported message itself (even if deleted, show content for moderation)
    SELECT
      m.id,
      m.conversation_id,
      m.sender_id,
      p.firstname AS sender_firstname,
      p.lastname AS sender_lastname,
      p.avatar_url AS sender_avatar_url,
      m.content,
      m.plain_text,
      m.created_at,
      TRUE AS is_reported_message
    FROM messages m
    LEFT JOIN profiles p ON p.id = m.sender_id
    WHERE m.id = p_message_id
  )
  -- Combine and order chronologically
  SELECT * FROM context_messages
  UNION ALL
  SELECT * FROM reported_message
  ORDER BY created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_message_context_for_moderation"("p_message_id" "uuid", "p_before_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_message_context_for_moderation"("p_message_id" "uuid", "p_before_count" integer) IS 'Get surrounding messages for context when reviewing a reported message (teachers only)';



CREATE OR REPLACE FUNCTION "public"."get_message_details"("p_message_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_name" "text", "sender_avatar_url" "text", "sender_role" "text", "subject" "text", "content" "jsonb", "plain_text" "text", "sent_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_group_message" boolean, "recipient_count" integer, "parent_message_id" "uuid", "thread_root_id" "uuid", "read_at" timestamp with time zone, "is_starred" boolean, "status" "text", "attachments" "jsonb", "recipients" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Verify user has access
  IF NOT EXISTS (
    SELECT 1 FROM private_messages pm
    LEFT JOIN message_inbox mi ON mi.message_id = pm.id
    WHERE pm.id = p_message_id
      AND (pm.sender_id = p_user_id OR mi.recipient_id = p_user_id)
  ) THEN
    RAISE EXCEPTION 'You do not have access to this message';
  END IF;

  RETURN QUERY
  SELECT
    pm.id AS message_id,
    pm.sender_id,
    p.full_name AS sender_name,
    p.avatar_url AS sender_avatar_url,
    p.role::TEXT AS sender_role,  -- Cast to TEXT
    pm.subject,
    pm.content,
    pm.plain_text,
    pm.sent_at,
    pm.edited_at,
    pm.is_group_message,
    pm.recipient_count,
    pm.parent_message_id,
    pm.thread_root_id,
    mi.read_at,
    COALESCE(mi.is_starred, FALSE) AS is_starred,
    COALESCE(mi.status, 'sent') AS status,
    (
      SELECT jsonb_agg(jsonb_build_object(
        'id', ma.id,
        'file_name', ma.file_name,
        'file_type', ma.file_type,
        'file_size', ma.file_size,
        'public_url', ma.public_url,
        'uploaded_at', ma.uploaded_at
      ))
      FROM message_attachments_v2 ma
      WHERE ma.message_id = pm.id
    ) AS attachments,
    (
      SELECT jsonb_agg(jsonb_build_object(
        'id', pr.id,
        'name', pr.full_name,
        'avatar_url', pr.avatar_url,
        'role', pr.role::TEXT  -- Cast to TEXT
      ))
      FROM message_inbox mi2
      JOIN profiles pr ON pr.id = mi2.recipient_id
      WHERE mi2.message_id = pm.id
    ) AS recipients
  FROM private_messages pm
  JOIN profiles p ON p.id = pm.sender_id
  LEFT JOIN message_inbox mi ON mi.message_id = pm.id AND mi.recipient_id = p_user_id
  WHERE pm.id = p_message_id;
END;
$$;


ALTER FUNCTION "public"."get_message_details"("p_message_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_message_details"("p_message_id" "uuid", "p_user_id" "uuid") IS 'Returns full message details with attachments and recipients';



CREATE OR REPLACE FUNCTION "public"."get_message_reaction_counts"("p_message_id" "uuid") RETURNS TABLE("emoji" "text", "count" bigint, "user_reacted" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Check if user is a participant in the conversation
  IF NOT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Permission denied: not a participant';
  END IF;

  RETURN QUERY
  SELECT
    mr.emoji,
    COUNT(*) as count,
    BOOL_OR(mr.user_id = auth.uid()) as user_reacted
  FROM message_reactions mr
  WHERE mr.message_id = p_message_id
  GROUP BY mr.emoji
  ORDER BY COUNT(*) DESC, mr.emoji;
END;
$$;


ALTER FUNCTION "public"."get_message_reaction_counts"("p_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_message_reaction_counts"("p_message_id" "uuid") IS 'Get aggregated reaction counts for a message';



CREATE OR REPLACE FUNCTION "public"."get_message_thread"("p_thread_root_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_name" "text", "sender_avatar_url" "text", "subject" "text", "content" "jsonb", "sent_at" timestamp with time zone, "edited_at" timestamp with time zone, "parent_message_id" "uuid", "level" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Verify user has access to this thread
  IF NOT EXISTS (
    SELECT 1 FROM private_messages pm
    LEFT JOIN message_inbox mi ON mi.message_id = pm.id
    WHERE (pm.id = p_thread_root_id OR pm.thread_root_id = p_thread_root_id)
      AND (pm.sender_id = p_user_id OR mi.recipient_id = p_user_id)
  ) THEN
    RAISE EXCEPTION 'You do not have access to this message thread';
  END IF;

  RETURN QUERY
  WITH RECURSIVE thread_messages AS (
    -- Root message
    SELECT
      pm.id,
      pm.sender_id,
      p.full_name AS sender_name,
      p.avatar_url AS sender_avatar_url,
      pm.subject,
      pm.content,
      pm.sent_at,
      pm.edited_at,
      pm.parent_message_id,
      0 AS level
    FROM private_messages pm
    JOIN profiles p ON p.id = pm.sender_id
    WHERE pm.id = p_thread_root_id
      AND pm.deleted_by_sender = FALSE

    UNION ALL

    -- Recursive: get replies
    SELECT
      pm.id,
      pm.sender_id,
      p.full_name,
      p.avatar_url,
      pm.subject,
      pm.content,
      pm.sent_at,
      pm.edited_at,
      pm.parent_message_id,
      tm.level + 1
    FROM private_messages pm
    JOIN profiles p ON p.id = pm.sender_id
    JOIN thread_messages tm ON pm.parent_message_id = tm.id
    WHERE pm.deleted_by_sender = FALSE
  )
  SELECT * FROM thread_messages
  ORDER BY sent_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_message_thread"("p_thread_root_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_message_thread"("p_thread_root_id" "uuid", "p_user_id" "uuid") IS 'Returns all messages in a thread (recursive)';



CREATE OR REPLACE FUNCTION "public"."get_messages_paginated"("p_conversation_id" "uuid", "p_limit" integer DEFAULT 50, "p_before_id" "uuid" DEFAULT NULL::"uuid", "p_before_timestamp" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "conversation_id" "uuid", "sender_id" "uuid", "sender_firstname" "text", "sender_lastname" "text", "sender_avatar_url" "text", "content" "jsonb", "plain_text" "text", "created_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_flagged" boolean, "deleted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Check if user is a participant (prefix with table name to avoid ambiguity)
  IF NOT EXISTS (
    SELECT 1 FROM conversation_participants cp
    WHERE cp.conversation_id = p_conversation_id
    AND cp.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'User is not a participant in this conversation';
  END IF;

  -- Return messages with pagination (including deleted messages with masked content)
  RETURN QUERY
  SELECT
    m.id,
    m.conversation_id,
    m.sender_id,
    p.firstname,
    p.lastname,
    p.avatar_url,
    -- Mask content for deleted messages
    CASE WHEN m.deleted_at IS NOT NULL THEN NULL ELSE m.content END,
    CASE WHEN m.deleted_at IS NOT NULL THEN NULL ELSE m.plain_text END,
    m.created_at,
    m.edited_at,
    m.is_flagged,
    m.deleted_at
  FROM messages m
  LEFT JOIN profiles p ON p.id = m.sender_id
  WHERE m.conversation_id = p_conversation_id
    -- No longer filter out deleted messages
    -- Cursor-based pagination
    AND (
      p_before_timestamp IS NULL
      OR m.created_at < p_before_timestamp
      OR (m.created_at = p_before_timestamp AND m.id < p_before_id)
    )
  ORDER BY m.created_at DESC, m.id DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_messages_paginated"("p_conversation_id" "uuid", "p_limit" integer, "p_before_id" "uuid", "p_before_timestamp" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_messages_paginated"("p_conversation_id" "uuid", "p_limit" integer, "p_before_id" "uuid", "p_before_timestamp" timestamp with time zone) IS 'Get messages with cursor-based pagination (includes deleted messages with masked content)';



CREATE OR REPLACE FUNCTION "public"."get_minesweeper_reference_time"("p_cycle" "text", "p_difficulty" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result INTEGER;
BEGIN
  SELECT CASE
    WHEN sample_count >= min_samples THEN reference_time
    ELSE fallback_time
  END
  INTO v_result
  FROM public.minesweeper_reference_times
  WHERE cycle = p_cycle AND difficulty = p_difficulty;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Invalid cycle (%) or difficulty (%) combination', p_cycle, p_difficulty;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_minesweeper_reference_time"("p_cycle" "text", "p_difficulty" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_minesweeper_reference_time"("p_cycle" "text", "p_difficulty" "text") IS 'Returns reference time for a cycle/difficulty. Uses fallback if not enough samples.
   Raises exception for invalid cycle/difficulty combination.';



CREATE OR REPLACE FUNCTION "public"."get_my_exercise_assignments"() RETURNS TABLE("id" "uuid", "exercise_id" "uuid", "assigned_by" "uuid", "assigned_to_type" "text", "student_id" "uuid", "class_id" "uuid", "assigned_at" timestamp with time zone, "optional_deadline" timestamp with time zone, "notes" "text", "is_active" boolean, "exercise_title" "text", "variations" "jsonb", "shared" "jsonb", "variables" "jsonb", "distribution_mode" "text", "exercise_is_public" boolean, "tags" "text"[], "grades" "text"[], "exercise_creator_id" "uuid", "assigned_by_name" "text", "assigned_by_role" "text", "assigned_to_name" "text", "student_email" "text", "class_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT
        ea.id,
        ea.exercise_id,
        ea.assigned_by,
        ea.assigned_to_type,
        ea.student_id,
        ea.class_id,
        ea.assigned_at,
        ea.optional_deadline,
        ea.notes,
        ea.is_active,
        e.title as exercise_title,
        e.variations,
        e.shared,
        e.variables,
        e.distribution_mode,
        e.is_public as exercise_is_public,
        COALESCE(
            ARRAY(
                SELECT t.name FROM exercise_tags et
                JOIN tags t ON t.id = et.tag_id
                WHERE et.exercise_id = e.id
                ORDER BY t.name
            ),
            '{}'::TEXT[]
        ) AS tags,
        e.grades,
        e.created_by as exercise_creator_id,
        p.full_name as assigned_by_name,
        p.role as assigned_by_role,
        CASE
            WHEN ea.assigned_to_type = 'student' THEN s.full_name
            WHEN ea.assigned_to_type = 'class' THEN c.name
            ELSE 'Public'
        END as assigned_to_name,
        s.email as student_email,
        c.name as class_name
    FROM exercise_assignments ea
    JOIN exercises e ON ea.exercise_id = e.id
    JOIN profiles p ON ea.assigned_by = p.id
    LEFT JOIN profiles s ON ea.student_id = s.id
    LEFT JOIN classes c ON ea.class_id = c.id
    WHERE ea.is_active = TRUE
        AND (
            ea.student_id = auth.uid()
            OR ea.class_id IN (
                SELECT class_id FROM class_members WHERE student_id = auth.uid()
            )
            OR ea.assigned_to_type = 'public'
        );
$$;


ALTER FUNCTION "public"."get_my_exercise_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_next_export_counter"("p_class_id" "uuid", "p_export_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_counter integer;
BEGIN
  -- Upsert: insert new row with counter=1, or increment existing
  INSERT INTO public.whiteboard_export_counters (class_id, export_date, counter)
  VALUES (p_class_id, p_export_date, 1)
  ON CONFLICT (class_id, export_date)
  DO UPDATE SET
    counter = whiteboard_export_counters.counter + 1,
    updated_at = now()
  RETURNING counter INTO v_counter;

  RETURN v_counter;
END;
$$;


