CREATE OR REPLACE FUNCTION "public"."get_reaction_users"("p_message_id" "uuid", "p_emoji" "text") RETURNS TABLE("user_id" "uuid", "firstname" "text", "lastname" "text", "avatar_url" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Check if user is a participant in the conversation
  IF NOT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Permission denied: not a participant';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.firstname,
