CREATE OR REPLACE FUNCTION "public"."get_reports_for_moderation"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("report_id" "uuid", "message_id" "uuid", "message_content" "jsonb", "message_plain_text" "text", "message_created_at" timestamp with time zone, "sender_id" "uuid", "sender_firstname" "text", "sender_lastname" "text", "sender_avatar_url" "text", "conversation_id" "uuid", "conversation_name" "text", "reported_by" "uuid", "reporter_firstname" "text", "reporter_lastname" "text", "reason" "text", "details" "text", "status" "text", "reviewed_by" "uuid", "reviewer_firstname" "text", "reviewer_lastname" "text", "reviewed_at" timestamp with time zone, "review_notes" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only teachers can access this
  IF NOT is_teacher_or_admin() THEN
    RAISE EXCEPTION 'Permission denied: teachers only';
  END IF;

  RETURN QUERY
  SELECT
    mr.id,
    m.id,
    m.content,
    m.plain_text,
    m.created_at,
    m.sender_id,
    sender.firstname,
    sender.lastname,
    sender.avatar_url,
    c.id,
    c.name,
    mr.reported_by,
    reporter.firstname,
    reporter.lastname,
    mr.reason,
    mr.details,
    mr.status,
    mr.reviewed_by,
    reviewer.firstname,
    reviewer.lastname,
    mr.reviewed_at,
    mr.review_notes,
    mr.created_at
  FROM message_reports mr
  JOIN messages m ON m.id = mr.message_id
  JOIN conversations c ON c.id = m.conversation_id
  LEFT JOIN profiles sender ON sender.id = m.sender_id
  JOIN profiles reporter ON reporter.id = mr.reported_by
  LEFT JOIN profiles reviewer ON reviewer.id = mr.reviewed_by
  WHERE (p_status IS NULL OR mr.status = p_status)
  ORDER BY
    CASE mr.status
      WHEN 'pending' THEN 1
      WHEN 'reviewed' THEN 2
      WHEN 'actioned' THEN 3
      WHEN 'dismissed' THEN 4
    END,
    mr.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_reports_for_moderation"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


