CREATE OR REPLACE FUNCTION "public"."get_teacher_classes_with_data"("p_teacher_id" "uuid", "p_is_test_mode" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "teacher_id" "uuid", "name" "text", "description" "text", "join_code" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "google_classroom_course_id" "uuid", "student_count" bigint, "schedules" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.teacher_id,
    c.name,
    c.description,
    c.join_code,
    c.is_active,
    c.created_at,
    c.updated_at,
    c.google_classroom_course_id,
    -- Count students filtered by test mode
    COALESCE(
      COUNT(DISTINCT cm.student_id) FILTER (
        WHERE p.id IS NOT NULL
        AND p.is_test = p_is_test_mode
      ),
      0
    ) AS student_count,
    -- Aggregate schedules into JSONB array
    COALESCE(
      JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'id', cs.id,
          'class_id', cs.class_id,
          'teacher_id', cs.teacher_id,
          'day_of_week', cs.day_of_week,
          'start_time', cs.start_time,
          'end_time', cs.end_time,
          'subject', cs.subject,
          'room', cs.room,
          'notes', cs.notes
        )
        ORDER BY cs.day_of_week, cs.start_time
      ) FILTER (WHERE cs.id IS NOT NULL),
      '[]'::JSONB
    ) AS schedules
  FROM classes c
  LEFT JOIN class_members cm ON c.id = cm.class_id
  LEFT JOIN profiles p ON cm.student_id = p.id
  LEFT JOIN class_schedules cs ON c.id = cs.class_id
  WHERE c.teacher_id = p_teacher_id
    AND c.is_active = TRUE
  GROUP BY c.id, c.teacher_id, c.name, c.description, c.join_code,
           c.is_active, c.created_at, c.updated_at, c.google_classroom_course_id
  ORDER BY c.name;
END;
$$;


ALTER FUNCTION "public"."get_teacher_classes_with_data"("p_teacher_id" "uuid", "p_is_test_mode" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_teacher_classes_with_data"("p_teacher_id" "uuid", "p_is_test_mode" boolean) IS 'Optimized function to fetch all teacher classes with student counts, schedules, and Google Classroom course association.
Supports test mode filtering for student counts.';



CREATE OR REPLACE FUNCTION "public"."get_teacher_classes_with_students"("p_teacher_id" "uuid", "p_is_test_mode" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "teacher_id" "uuid", "name" "text", "description" "text", "join_code" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "students" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.teacher_id,
    c.name,
    c.description,
    c.join_code,
    c.is_active,
    c.created_at,
    c.updated_at,
    -- Aggregate students into JSONB array with all required fields
    -- Filter by is_test to match the requested mode
    COALESCE(
      JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'id', p.id,
          'firstname', p.firstname,
          'lastname', p.lastname,
          'full_name', p.full_name,
          'avatar_url', p.avatar_url,
          'gidouilles', p.gidouilles,
          'vip_cards', p.vip_cards,
          'role', p.role,
          'is_test', p.is_test
        )
        ORDER BY p.firstname NULLS LAST
      ) FILTER (WHERE p.id IS NOT NULL AND p.is_test = p_is_test_mode),
      '[]'::JSONB
    ) AS students
  FROM classes c
  LEFT JOIN class_members cm ON c.id = cm.class_id
  LEFT JOIN profiles p ON cm.student_id = p.id
  WHERE c.teacher_id = p_teacher_id
    AND c.is_active = TRUE
  GROUP BY c.id, c.teacher_id, c.name, c.description, c.join_code,
           c.is_active, c.created_at, c.updated_at
  ORDER BY c.name;
END;
$$;


