COMMENT ON FUNCTION "public"."get_teacher_classes_with_students"("p_teacher_id" "uuid", "p_is_test_mode" boolean) IS 'Optimized function to fetch all teacher classes with full student data filtered by test mode.
When p_is_test_mode = TRUE, returns only test students (is_test = TRUE).
When p_is_test_mode = FALSE, returns only real students (is_test = FALSE).
This ensures complete data isolation between test and production environments.';



CREATE OR REPLACE FUNCTION "public"."get_teacher_exercise_assignments"() RETURNS TABLE("id" "uuid", "exercise_id" "uuid", "assigned_by" "uuid", "assigned_to_type" "text", "student_id" "uuid", "class_id" "uuid", "assigned_at" timestamp with time zone, "optional_deadline" timestamp with time zone, "notes" "text", "is_active" boolean, "exercise_title" "text", "variations" "jsonb", "shared" "jsonb", "variables" "jsonb", "distribution_mode" "text", "exercise_is_public" boolean, "tags" "text"[], "grades" "text"[], "exercise_creator_id" "uuid", "assigned_by_name" "text", "assigned_by_role" "text", "assigned_to_name" "text", "student_email" "text", "class_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT
        ea.id,
        ea.exercise_id,
        ea.assigned_by,
        ea.assigned_to_type,
        ea.student_id,
        ea.class_id,
        ea.assigned_at,
        ea.optional_deadline,
        ea.notes,
        ea.is_active,
        e.title as exercise_title,
        e.variations,
        e.shared,
        e.variables,
        e.distribution_mode,
        e.is_public as exercise_is_public,
        COALESCE(
            ARRAY(
                SELECT t.name FROM exercise_tags et
                JOIN tags t ON t.id = et.tag_id
                WHERE et.exercise_id = e.id
                ORDER BY t.name
            ),
            '{}'::TEXT[]
        ) AS tags,
        e.grades,
        e.created_by as exercise_creator_id,
        p.full_name as assigned_by_name,
        p.role as assigned_by_role,
        CASE
            WHEN ea.assigned_to_type = 'student' THEN s.full_name
            WHEN ea.assigned_to_type = 'class' THEN c.name
            ELSE 'Public'
        END as assigned_to_name,
        s.email as student_email,
        c.name as class_name
    FROM exercise_assignments ea
    JOIN exercises e ON ea.exercise_id = e.id
    JOIN profiles p ON ea.assigned_by = p.id
    LEFT JOIN profiles s ON ea.student_id = s.id
    LEFT JOIN classes c ON ea.class_id = c.id
    WHERE ea.is_active = TRUE
        AND ea.assigned_by = auth.uid();
$$;


