    COUNT(DISTINCT cm.student_id) as student_count,
    COUNT(DISTINCT c.id) as class_count
  FROM classes c
  INNER JOIN class_members cm ON cm.class_id = c.id
  WHERE c.teacher_id = p_teacher_id;
END;
