CREATE OR REPLACE FUNCTION "public"."get_teacher_overrides_summary"("p_teacher_id" "uuid") RETURNS TABLE("rarity" "text", "total_cards" bigint, "enabled_count" bigint, "disabled_count" bigint, "no_override_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    vct.rarity,
    COUNT(*) as total_cards,
    COUNT(*) FILTER (WHERE tvo.is_enabled = TRUE) as enabled_count,
    COUNT(*) FILTER (WHERE tvo.is_enabled = FALSE) as disabled_count,
    COUNT(*) FILTER (WHERE tvo.id IS NULL) as no_override_count
  FROM vip_card_templates vct
  LEFT JOIN teacher_vip_card_overrides tvo ON tvo.card_id = vct.id
    AND tvo.teacher_id = p_teacher_id
  GROUP BY vct.rarity
  ORDER BY
    CASE vct.rarity
      WHEN 'common' THEN 1
      WHEN 'rare' THEN 2
      WHEN 'epic' THEN 3
      WHEN 'legendary' THEN 4
    END;
END;
$$;


