CREATE OR REPLACE FUNCTION "public"."get_template_statistics"("p_template_id" "uuid") RETURNS TABLE("total_usage" bigint, "unique_users" bigint, "completion_rate" numeric, "avg_time_to_complete" numeric, "last_used_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT as total_usage,
    COUNT(DISTINCT user_id)::BIGINT as unique_users,
    ROUND(
      (COUNT(*) FILTER (WHERE completed = true)::NUMERIC /
       NULLIF(COUNT(*)::NUMERIC, 0) * 100),
      2
    ) as completion_rate,
    ROUND(AVG(time_to_complete), 0) as avg_time_to_complete,
    MAX(used_at) as last_used_at
  FROM template_usage_stats
  WHERE template_id = p_template_id;
END;
$$;


