CREATE OR REPLACE FUNCTION "public"."get_templates_for_context"("p_trigger_type" "text", "p_class_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "subject_template" "text", "body_template" "text", "trigger_type" "text", "scope" "text", "variables" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    t.id,
    t.title,
    t.description,
    t.subject_template,
    t.body_template,
    t.trigger_type,
    t.scope,
    t.variables
  FROM message_templates t
  WHERE t.trigger_type = p_trigger_type
    AND t.is_active = TRUE
    AND (
      t.scope = 'system'
      OR (t.scope = 'class' AND t.class_id = p_class_id)
    )
  ORDER BY
    CASE WHEN t.scope = 'class' THEN 0 ELSE 1 END, -- Prefer class templates
    t.created_at DESC
  LIMIT 1;
END;
$$;


