CREATE OR REPLACE FUNCTION "public"."get_unread_count"("p_conversation_id" "uuid", "p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_read_at TIMESTAMPTZ;
  v_unread_count INTEGER;
BEGIN
  -- Get user's last_read_at for this conversation
  SELECT last_read_at INTO v_last_read_at
  FROM conversation_participants
  WHERE conversation_id = p_conversation_id
  AND user_id = p_user_id;

  -- If never read, count all messages
  IF v_last_read_at IS NULL THEN
    SELECT COUNT(*) INTO v_unread_count
    FROM messages
    WHERE conversation_id = p_conversation_id
    AND sender_id != p_user_id
    AND deleted_at IS NULL;
  ELSE
    -- Count messages after last_read_at
    SELECT COUNT(*) INTO v_unread_count
    FROM messages
    WHERE conversation_id = p_conversation_id
    AND sender_id != p_user_id
    AND created_at > v_last_read_at
    AND deleted_at IS NULL;
  END IF;

  RETURN COALESCE(v_unread_count, 0);
END;
$$;


ALTER FUNCTION "public"."get_unread_count"("p_conversation_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_unread_count"("p_conversation_id" "uuid", "p_user_id" "uuid") IS 'Calculate unread message count for a user in a conversation';



CREATE OR REPLACE FUNCTION "public"."get_user_conversations"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("conversation_id" "uuid", "name" "text", "is_group" boolean, "class_id" "uuid", "last_message_preview" "text", "last_message_at" timestamp with time zone, "unread_count" bigint, "participant_count" bigint, "other_user_id" "uuid", "other_user_firstname" "text", "other_user_lastname" "text", "other_user_avatar_url" "text", "is_muted" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := COALESCE(p_user_id, auth.uid());
BEGIN
  RETURN QUERY
  SELECT
    ucv.conversation_id,
    ucv.name,
    ucv.is_group,
    ucv.class_id,
    ucv.last_message_preview,
    ucv.last_message_at,
    ucv.unread_count,
    ucv.participant_count,
    ucv.other_user_id,
    ucv.other_user_firstname,
    ucv.other_user_lastname,
    ucv.other_user_avatar_url,
    ucv.is_muted
  FROM user_conversations_view ucv
  WHERE ucv.user_id = v_user_id
  ORDER BY
    ucv.last_message_at DESC NULLS LAST,
    ucv.updated_at DESC;
