CREATE OR REPLACE FUNCTION "public"."get_user_frequent_templates"("p_user_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("template_id" "uuid", "title" "text", "usage_count" bigint, "last_used" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    mt.id,
    mt.title,
    COUNT(tus.id)::BIGINT as usage_count,
    MAX(tus.used_at) as last_used
  FROM template_usage_stats tus
  JOIN message_templates mt ON mt.id = tus.template_id
  WHERE tus.user_id = p_user_id
    AND mt.is_active = true
  GROUP BY mt.id, mt.title
  ORDER BY usage_count DESC, last_used DESC
  LIMIT p_limit;
END;
$$;


