CREATE OR REPLACE FUNCTION "public"."get_user_inbox"("p_user_id" "uuid", "p_status" "text" DEFAULT 'inbox'::"text", "p_folder_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_name" "text", "sender_avatar_url" "text", "subject" "text", "content" "jsonb", "plain_text" "text", "sent_at" timestamp with time zone, "read_at" timestamp with time zone, "is_starred" boolean, "status" "text", "is_group_message" boolean, "recipient_count" integer, "has_attachments" boolean, "attachment_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.id AS message_id,
    pm.sender_id,
    p.full_name AS sender_name,
    p.avatar_url AS sender_avatar_url,
    pm.subject,
    pm.content,
    substring(pm.plain_text, 1, 200) AS plain_text,
    pm.sent_at,
    mi.read_at,
    mi.is_starred,
    mi.status,
    pm.is_group_message,
    pm.recipient_count,
    (EXISTS (SELECT 1 FROM message_attachments_v2 ma WHERE ma.message_id = pm.id)) AS has_attachments,
    (SELECT COUNT(*)::INT FROM message_attachments_v2 ma WHERE ma.message_id = pm.id) AS attachment_count
  FROM message_inbox mi
  JOIN private_messages pm ON pm.id = mi.message_id
  JOIN profiles p ON p.id = pm.sender_id
  WHERE mi.recipient_id = p_user_id
    AND mi.deleted = FALSE
    AND pm.deleted_by_sender = FALSE
    AND mi.status = p_status
    AND (p_folder_id IS NULL OR mi.folder_id = p_folder_id)
  ORDER BY pm.sent_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_user_inbox"("p_user_id" "uuid", "p_status" "text", "p_folder_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_inbox"("p_user_id" "uuid", "p_status" "text", "p_folder_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Returns paginated inbox messages for a user';



CREATE OR REPLACE FUNCTION "public"."get_user_moderation_history"("p_user_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "moderator_id" "uuid", "moderator_name" "text", "action" "text", "target_type" "text", "target_id" "uuid", "reason" "text", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Verify caller is a teacher/admin
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.id = auth.uid()
    AND profiles.role IN ('teacher', 'admin')
  ) THEN
    RAISE EXCEPTION 'Permission denied: only teachers can view moderation history';
  END IF;

  -- Return moderation logs for this user
  RETURN QUERY
  SELECT
    ml.id,
    ml.moderator_id,
    p.firstname || ' ' || p.lastname AS moderator_name,
    ml.action,
    ml.target_type,
    ml.target_id,
    ml.reason,
    ml.metadata,
    ml.created_at
  FROM moderation_logs ml
  JOIN profiles p ON p.id = ml.moderator_id
  WHERE ml.target_type = 'user'
  AND ml.target_id = p_user_id
  ORDER BY ml.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_user_moderation_history"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_moderation_history"("p_user_id" "uuid", "p_limit" integer) IS 'Get moderation history for a specific user (teacher-only)';



CREATE OR REPLACE FUNCTION "public"."get_user_sent_messages"("p_user_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("message_id" "uuid", "subject" "text", "content" "jsonb", "plain_text" "text", "sent_at" timestamp with time zone, "is_group_message" boolean, "recipient_count" integer, "has_attachments" boolean, "recipients" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    pm.id AS message_id,
    pm.subject,
    pm.content,
    substring(pm.plain_text, 1, 200) AS plain_text,
    pm.sent_at,
    pm.is_group_message,
    pm.recipient_count,
    (EXISTS (SELECT 1 FROM message_attachments_v2 ma WHERE ma.message_id = pm.id)) AS has_attachments,
    (
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'name', p.full_name,
        'avatar_url', p.avatar_url
      ))
      FROM message_inbox mi
      JOIN profiles p ON p.id = mi.recipient_id
      WHERE mi.message_id = pm.id
    ) AS recipients
  FROM private_messages pm
  WHERE pm.sender_id = p_user_id
    AND pm.deleted_by_sender = FALSE
  ORDER BY pm.sent_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_user_sent_messages"("p_user_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_sent_messages"("p_user_id" "uuid", "p_limit" integer, "p_offset" integer) IS 'Returns paginated sent messages for a user';



