CREATE OR REPLACE FUNCTION "public"."grant_parental_consent"("p_token" "uuid", "p_ip" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_consent_id UUID;
    v_student_id UUID;
    v_status consent_status;
    v_expires_at TIMESTAMPTZ;
    v_student_name TEXT;
BEGIN
    -- Find the consent record by token
    SELECT id, student_id, status, expires_at
    INTO v_consent_id, v_student_id, v_status, v_expires_at
    FROM parental_consents
    WHERE consent_token = p_token;

    -- Token not found
    IF v_consent_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'TOKEN_NOT_FOUND',
            'message', 'Lien de consentement invalide.'
        );
    END IF;

    -- Already granted
    IF v_status = 'granted' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'ALREADY_GRANTED',
            'message', 'Ce consentement a déjà été accordé.'
        );
    END IF;

    -- Token expired
    IF v_expires_at < NOW() THEN
        -- Update status to expired
        UPDATE parental_consents
        SET status = 'expired'
        WHERE id = v_consent_id;

        RETURN jsonb_build_object(
            'success', false,
            'error', 'TOKEN_EXPIRED',
            'message', 'Ce lien a expiré. Contactez l''enseignant pour recevoir un nouveau lien.'
        );
    END IF;

    -- Grant consent - update parental_consents
    UPDATE parental_consents
    SET
        status = 'granted',
        consent_given_at = NOW(),
        consent_ip = p_ip,
        consent_user_agent = p_user_agent
    WHERE id = v_consent_id;

    -- Update student profile
    UPDATE profiles
    SET
        consent_granted_at = NOW(),
        consent_grace_period_ends = NULL -- Clear grace period once consent is granted
    WHERE id = v_student_id;

    -- Get student name for confirmation
    SELECT COALESCE(firstname || ' ' || lastname, firstname, 'L''élève')
    INTO v_student_name
    FROM profiles
    WHERE id = v_student_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Consentement accordé avec succès.',
        'student_name', v_student_name
    );
END;
$$;


ALTER FUNCTION "public"."grant_parental_consent"("p_token" "uuid", "p_ip" "inet", "p_user_agent" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grant_parental_consent"("p_token" "uuid", "p_ip" "inet", "p_user_agent" "text") IS 'Grants parental consent for a student. Called by anonymous parents via consent link. SECURITY DEFINER ensures proper access to update profiles.';



CREATE OR REPLACE FUNCTION "public"."grant_specific_vip_card"("p_student_id" "uuid", "p_card_id" "text", "p_count" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_is_teacher BOOLEAN;
  v_vip_cards JSONB;
  v_new_instance JSONB;
  v_new_instance_id UUID;
  v_earned_at TIMESTAMPTZ;
  v_result JSONB;
  v_cards JSONB[];
  v_template RECORD;
  i INT;
BEGIN
  -- Get the calling user ID
  v_teacher_id := auth.uid();

  -- Check if the user is a teacher or admin
  SELECT is_teacher_or_admin()
  INTO v_is_teacher;

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Only teachers and admins can grant VIP cards';
  END IF;

  -- Verify that the teacher owns this student (via class_members)
  IF NOT EXISTS (
    SELECT 1
    FROM class_members cm
    JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
  ) THEN
    RAISE EXCEPTION 'You do not have permission to grant cards to this student';
  END IF;

  -- Get template info (validate card exists and get rarity)
  SELECT id, rarity, uses_total INTO v_template
  FROM vip_card_templates WHERE id = p_card_id;

  IF v_template IS NULL THEN
    RAISE EXCEPTION 'Invalid card ID: %', p_card_id;
  END IF;

  -- Validate count
  IF p_count < 1 OR p_count > 10 THEN
    RAISE EXCEPTION 'Count must be between 1 and 10';
  END IF;

  -- Lock the student's profile row to prevent race conditions
  SELECT vip_cards
  INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  -- Initialize empty array if vip_cards is null
  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- Initialize result array
  v_cards := ARRAY[]::JSONB[];
  v_earned_at := NOW();

  -- Add the specified card p_count times
  FOR i IN 1..p_count LOOP
    v_new_instance_id := gen_random_uuid();

    v_new_instance := jsonb_build_object(
      'cardId', p_card_id,
      'earnedAt', v_earned_at,
      'usedAt', NULL,
      'acquiredFrom', 'teacher_award',
      'usesRemaining', v_template.uses_total
    );

    -- Add to vip_cards JSONB object
    v_vip_cards := v_vip_cards || jsonb_build_object(v_new_instance_id::TEXT, v_new_instance);

    -- Log activity
    INSERT INTO vip_cards_activity (
      student_id,
      card_instance_id,
      card_template_id,
      action,
      metadata
    ) VALUES (
      p_student_id,
      v_new_instance_id::TEXT,
      p_card_id,
      'gained',
      jsonb_build_object(
        'acquired_from', 'teacher_award',
        'awarded_by', v_teacher_id,
        'rarity', v_template.rarity
      )
    );

    -- Add to result array
    v_cards := v_cards || jsonb_build_object(
      'cardId', p_card_id,
      'instanceId', v_new_instance_id,
      'earnedAt', v_earned_at
    );
  END LOOP;

  -- Update the student's profile
  UPDATE profiles
  SET vip_cards = v_vip_cards
  WHERE id = p_student_id;

  -- Build result object
  v_result := jsonb_build_object('cards', to_jsonb(v_cards));

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."grant_specific_vip_card"("p_student_id" "uuid", "p_card_id" "text", "p_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."grant_specific_vip_card"("p_student_id" "uuid", "p_card_id" "text", "p_count" integer) IS 'Allows teachers to grant a specific VIP card to a student for free. Logs activity with acquired_from=teacher_award.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  pending_student RECORD;
  class_id UUID;
  google_avatar TEXT;
  user_status_value user_status;
BEGIN
  -- Extract Google avatar URL from user metadata if available
  -- Google OAuth stores avatar in 'picture' field (standard), but check both for compatibility
  google_avatar := COALESCE(
    NEW.raw_user_meta_data->>'picture',
    NEW.raw_user_meta_data->>'avatar_url'
  );

  -- Check if this email exists in pending_students (not yet activated)
  SELECT * INTO pending_student
  FROM public.pending_students
  WHERE email = NEW.email AND is_activated = FALSE
  LIMIT 1;

  -- If pending student exists, create profile with pre-populated data
  -- These students were explicitly added by teachers, so they are approved
  IF FOUND THEN
    -- Create profile with pre-populated data (including Google avatar)
    -- Status is 'approved' because teacher explicitly added this student
    INSERT INTO public.profiles (id, email, firstname, lastname, role, school_id, grade, gender, class_ids, avatar_url, status)
    VALUES (
      NEW.id,
      NEW.email,
      pending_student.firstname,
      pending_student.lastname,
      'student',
      pending_student.school_id,
      pending_student.grade,
      pending_student.gender,
      pending_student.class_ids,
      google_avatar,
      'approved'::user_status  -- Explicitly approved (teacher added them)
    );

    -- Enroll student in all pre-assigned classes
    IF pending_student.class_ids IS NOT NULL AND array_length(pending_student.class_ids, 1) > 0 THEN
      FOREACH class_id IN ARRAY pending_student.class_ids
      LOOP
        -- Insert into class_members (ignore if already exists)
        INSERT INTO public.class_members (class_id, student_id)
        VALUES (class_id, NEW.id)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;

    -- Mark the pending student as activated
    UPDATE public.pending_students
    SET is_activated = TRUE,
        activated_at = NOW()
    WHERE id = pending_student.id;

    RAISE NOTICE 'Created profile for pre-populated student: % (enrolled in % classes, avatar: %, status: approved)',
                 NEW.email,
                 COALESCE(array_length(pending_student.class_ids, 1), 0),
                 COALESCE(google_avatar, 'none');
  ELSE
    -- No pending student found - create default profile
    -- Determine status based on email domain
    IF NEW.email LIKE '%@voltairedoha.com' THEN
      user_status_value := 'pending'::user_status;
    ELSE
      user_status_value := 'approved'::user_status;
    END IF;

    INSERT INTO public.profiles (id, email, firstname, lastname, role, avatar_url, status)
    VALUES (
      NEW.id,
      NEW.email,
      COALESCE(NEW.raw_user_meta_data->>'given_name', ''),
      COALESCE(NEW.raw_user_meta_data->>'family_name', ''),
      'student',
      google_avatar,
      user_status_value
    );

    RAISE NOTICE 'Created default profile for new user: % (avatar: %, status: %)',
                 NEW.email,
                 COALESCE(google_avatar, 'none'),
                 user_status_value;
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN unique_violation THEN
    -- Profile already exists, update avatar_url if we have one from Google
    IF google_avatar IS NOT NULL THEN
      UPDATE public.profiles
      SET avatar_url = google_avatar,
          updated_at = NOW()
      WHERE id = NEW.id AND (avatar_url IS NULL OR avatar_url = '');

      RAISE NOTICE 'Updated avatar for existing user: % (avatar: %)', NEW.email, google_avatar;
    END IF;
    RETURN NEW;
  WHEN OTHERS THEN
    -- Log error but don't prevent user creation
    RAISE WARNING 'Failed to create profile for user %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Automatically creates a profile when a user signs up. Extracts and saves Google OAuth avatar from picture or avatar_url field. If the user email exists in pending_students, uses pre-populated data and enrolls them in pre-assigned classes (status: approved). For new users with @voltairedoha.com email, sets status to pending (requires admin approval). Other new users are approved by default.';



