CREATE OR REPLACE FUNCTION "public"."initialize_default_categories"("p_class_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
BEGIN
    -- SECURITY CHECK: Verify caller is the teacher of this class or admin
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    IF auth.uid() IS NULL OR NOT (
        v_caller_role = 'admin'
        OR (v_caller_role = 'teacher' AND EXISTS (
            SELECT 1 FROM public.classes
            WHERE id = p_class_id
            AND teacher_id = auth.uid()
        ))
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have permission to initialize categories for this class';
    END IF;

    -- Insert default categories (ON CONFLICT DO NOTHING to handle re-runs)
    INSERT INTO public.coursework_categories (class_id, name, icon, color, display_order, created_by)
    VALUES
        (p_class_id, 'Cours', '📚', '#3B82F6', 1, auth.uid()),
        (p_class_id, 'Exercices', '✏️', '#10B981', 2, auth.uid()),
        (p_class_id, 'Corrections', '✅', '#8B5CF6', 3, auth.uid()),
        (p_class_id, 'Devoirs', '📝', '#F59E0B', 4, auth.uid()),
        (p_class_id, 'Évaluations', '🎯', '#EF4444', 5, auth.uid())
    ON CONFLICT (class_id, name) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."initialize_default_categories"("p_class_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."initialize_default_categories"("p_class_id" "uuid") IS 'Creates default coursework categories (Cours, Exercices, etc.) for a class. Caller must be the class teacher or admin.';



CREATE OR REPLACE FUNCTION "public"."insert_tutor_messages"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_messages" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  msg JSONB;
  inserted_ids UUID[] := '{}';
  new_id UUID;
BEGIN
  -- Security check: Verify user owns the conversation and it's active
  IF NOT EXISTS (
    SELECT 1 FROM tutor_conversations
    WHERE id = p_conversation_id
    AND student_id = p_user_id
    AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Unauthorized: user does not own this conversation or conversation is not active'
      USING ERRCODE = '42501'; -- insufficient_privilege
  END IF;

  -- Insert each message from the JSONB array
  FOR msg IN SELECT * FROM jsonb_array_elements(p_messages)
  LOOP
    INSERT INTO tutor_messages (
      conversation_id,
      role,
      content,
      help_level,
      help_method_used,
      cheat_detected
    ) VALUES (
      p_conversation_id,
      msg->>'role',
      msg->>'content',
      (msg->>'help_level')::INTEGER,
      msg->>'help_method_used',
      COALESCE((msg->>'cheat_detected')::BOOLEAN, false)
    )
    RETURNING id INTO new_id;

    inserted_ids := array_append(inserted_ids, new_id);
  END LOOP;

  -- Return the inserted message IDs
  RETURN jsonb_build_object(
    'success', true,
    'inserted_ids', to_jsonb(inserted_ids),
    'count', array_length(inserted_ids, 1)
  );
END;
$$;


ALTER FUNCTION "public"."insert_tutor_messages"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_messages" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."insert_tutor_messages"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_messages" "jsonb") IS 'Securely inserts tutor messages after verifying user ownership of the conversation.
   Uses SECURITY DEFINER to bypass RLS while maintaining explicit security checks.';



