CREATE OR REPLACE FUNCTION "public"."is_kanban_board_member"("p_board_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_owner UUID;
    v_class UUID;
    v_is_member BOOLEAN;
BEGIN
    SELECT owner_id, class_id INTO v_owner, v_class
    FROM public.kanban_boards
    WHERE id = p_board_id;

    IF v_owner IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Owner is always a board member.
    IF v_owner = p_user_id THEN
        RETURN TRUE;
    END IF;

    -- Personal board: only the owner counts.
    IF v_class IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Class board: any enrolled student is a member.
    SELECT EXISTS (
        SELECT 1 FROM public.class_members
        WHERE class_id = v_class AND student_id = p_user_id
    ) INTO v_is_member;

    RETURN COALESCE(v_is_member, FALSE);
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


