CREATE OR REPLACE FUNCTION "public"."is_valid_grade_array"("grades" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    grade TEXT;
    valid_grades TEXT[] := ARRAY[
        'CP', 'CE1', 'CE2', 'CM1', 'CM2',
        '6', '5', '4', '3',
        '2', '1_GEN', 'T_GEN', '1_SPE', 'T_SPE', 'T_EXP', 'T_COMP', '1_STMG', 'T_STMG'
    ];
BEGIN
    -- NULL array is valid
    IF grades IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Empty array is valid
    IF array_length(grades, 1) IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Check each element
    FOREACH grade IN ARRAY grades
    LOOP
        IF NOT (grade = ANY(valid_grades)) THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."is_valid_grade_array"("grades" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_valid_grade_array"("grades" "text"[]) IS 'Validates that all elements in a grade array are canonical GradeCode values.';



CREATE OR REPLACE FUNCTION "public"."join_multiplayer_queue"("p_difficulty" "text", "p_match_type" "text" DEFAULT 'quick'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID := auth.uid();
  v_rank INTEGER;
  v_opponent_record RECORD;
  v_match_id UUID;
  v_seed TEXT;
BEGIN
  -- Validate authenticated
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate difficulty
  IF p_difficulty NOT IN ('beginner', 'intermediate', 'expert') THEN
    RAISE EXCEPTION 'Invalid difficulty: %', p_difficulty;
  END IF;

  -- Validate match_type
  IF p_match_type NOT IN ('quick', 'ranked') THEN
    RAISE EXCEPTION 'Invalid match_type: %', p_match_type;
  END IF;

  -- Get player's ELO (ensure stats exist first)
  PERFORM ensure_player_stats_exist(v_student_id);

  SELECT ranked_elo INTO v_rank
  FROM minesweeper_player_stats
  WHERE student_id = v_student_id;

  -- Check if already in queue
  IF EXISTS (
    SELECT 1 FROM minesweeper_multiplayer_queue
    WHERE student_id = v_student_id
      AND status = 'waiting'
  ) THEN
    RAISE EXCEPTION 'Already in queue';
  END IF;

  -- Check if already in active match
  IF EXISTS (
    SELECT 1 FROM minesweeper_multiplayer_matches
    WHERE (player1_id = v_student_id OR player2_id = v_student_id)
      AND status IN ('waiting', 'countdown', 'in_progress')
  ) THEN
    RAISE EXCEPTION 'Already in active match';
  END IF;

  -- Try to find opponent (within ±200 ELO, same difficulty & match_type)
  SELECT
    student_id,
    rank,
    joined_at,
    id AS queue_id
  INTO v_opponent_record
  FROM minesweeper_multiplayer_queue
  WHERE difficulty = p_difficulty
    AND match_type = p_match_type
    AND status = 'waiting'
    AND student_id != v_student_id
    AND ABS(rank - v_rank) <= 200  -- MMR tolerance
  ORDER BY joined_at ASC  -- First come first served within MMR range
  LIMIT 1;

  IF v_opponent_record.student_id IS NOT NULL THEN
    -- Match found! Create match
    v_seed := encode(gen_random_bytes(16), 'hex');  -- Generate random seed

    INSERT INTO minesweeper_multiplayer_matches (
      match_type,
      difficulty,
      seed,
      player1_id,
      player2_id,
      status
    ) VALUES (
      p_match_type,
      p_difficulty,
      v_seed,
      v_opponent_record.student_id,  -- Opponent is player 1 (they joined first)
      v_student_id,                  -- We are player 2
      'countdown'                     -- Start in countdown phase
    ) RETURNING id INTO v_match_id;

    -- Mark both players as matched in queue
    UPDATE minesweeper_multiplayer_queue
    SET status = 'matched'
    WHERE student_id IN (v_student_id, v_opponent_record.student_id)
      AND status = 'waiting';

    -- Initialize game state for both players
    INSERT INTO minesweeper_multiplayer_game_state (match_id, player_id)
    VALUES
      (v_match_id, v_opponent_record.student_id),
      (v_match_id, v_student_id);

    RETURN jsonb_build_object(
      'matched', true,
      'match_id', v_match_id,
      'opponent_id', v_opponent_record.student_id,
      'seed', v_seed,
      'difficulty', p_difficulty,
      'match_type', p_match_type,
      'player_number', 2  -- We are player 2
    );
  ELSE
    -- No match found, join queue
    INSERT INTO minesweeper_multiplayer_queue (
      student_id,
      difficulty,
      match_type,
      rank,
      status
    ) VALUES (
      v_student_id,
      p_difficulty,
      p_match_type,
      v_rank,
      'waiting'
    );

    RETURN jsonb_build_object(
      'matched', false,
      'waiting', true,
      'difficulty', p_difficulty,
      'match_type', p_match_type,
      'rank', v_rank
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."join_multiplayer_queue"("p_difficulty" "text", "p_match_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_multiplayer_queue"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID := auth.uid();
  v_deleted_count INTEGER;
BEGIN
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Mark as cancelled (don't delete for analytics)
  UPDATE minesweeper_multiplayer_queue
  SET status = 'cancelled'
  WHERE student_id = v_student_id
    AND status = 'waiting';

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'removed', v_deleted_count > 0
  );
END;
$$;


ALTER FUNCTION "public"."leave_multiplayer_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_existing_assessments_to_periods"("p_school_year_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  updated_count INTEGER := 0;
BEGIN
  UPDATE assessments a
  SET academic_period_id = ap.id
  FROM academic_periods ap
  JOIN school_years sy ON sy.id = ap.school_year_id
  JOIN classes c ON c.school_id = sy.school_id
  WHERE c.id = a.class_id
    AND sy.id = p_school_year_id
    AND a.created_at::date BETWEEN ap.start_date AND ap.end_date
    AND a.academic_period_id IS NULL;

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."link_existing_assessments_to_periods"("p_school_year_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."link_existing_assessments_to_periods"("p_school_year_id" "uuid") IS 'Backfills academic_period_id for existing assessments in a given school year. Returns count of updated assessments.';



CREATE OR REPLACE FUNCTION "public"."lock_cards"("p_student_id" "uuid", "p_card_ids" "text"[], "p_entity_id" "uuid", "p_lock_type" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_card_id TEXT;
    v_student_cards JSONB;
    v_card_data JSONB;
BEGIN
    -- Validate lock type
    IF p_lock_type NOT IN ('listing', 'trade') THEN
        RAISE EXCEPTION 'Invalid lock type: %', p_lock_type;
    END IF;

    -- Get student's VIP cards
    SELECT vip_cards INTO v_student_cards
    FROM public.profiles
    WHERE id = p_student_id;

    IF v_student_cards IS NULL THEN
        RAISE EXCEPTION 'Student has no VIP cards';
    END IF;

    -- Check each card
    FOREACH v_card_id IN ARRAY p_card_ids
    LOOP
        -- Check card exists for this student
        v_card_data := v_student_cards->v_card_id;
        IF v_card_data IS NULL THEN
            RAISE EXCEPTION 'Card % does not belong to student', v_card_id;
        END IF;

        -- Check card is not consumed (usedAt set in JSONB)
        IF v_card_data->>'usedAt' IS NOT NULL THEN
            RAISE EXCEPTION 'Card % has been consumed and cannot be traded', v_card_id;
        END IF;

        -- Check card is not already locked
        IF EXISTS (
            SELECT 1 FROM public.marketplace_locked_cards
            WHERE card_instance_id = v_card_id
        ) THEN
            RAISE EXCEPTION 'Card % is already locked', v_card_id;
        END IF;

        -- Lock the card
        INSERT INTO public.marketplace_locked_cards (
            student_id,
            card_instance_id,
            locked_for,
            locked_entity_id
        ) VALUES (
            p_student_id,
            v_card_id,
            p_lock_type,
            p_entity_id
        );
    END LOOP;

    RETURN true;
EXCEPTION
    WHEN OTHERS THEN
        -- Rollback any partial locks
        DELETE FROM public.marketplace_locked_cards
        WHERE locked_entity_id = p_entity_id;

        RAISE;
END;
$$;


ALTER FUNCTION "public"."lock_cards"("p_student_id" "uuid", "p_card_ids" "text"[], "p_entity_id" "uuid", "p_lock_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lock_cards"("p_student_id" "uuid", "p_card_ids" "text"[], "p_entity_id" "uuid", "p_lock_type" "text") IS 'Lock VIP cards to prevent double-spending in marketplace';



CREATE OR REPLACE FUNCTION "public"."log_achievements_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    DECLARE
        v_achievement_name TEXT;
        v_description TEXT;
        v_class_id UUID;
    BEGIN
        IF EXISTS (
            SELECT 1 FROM public.reward_events
            WHERE source_table = 'student_achievements'
            AND source_id = NEW.id
        ) THEN
            RETURN NEW;
        END IF;

        SELECT name INTO v_achievement_name
        FROM public.achievements
        WHERE id = NEW.achievement_id;

        -- Get student's ACTIVE class
        SELECT class_id INTO v_class_id
        FROM public.class_members
        WHERE student_id = NEW.student_id
          AND status = 'active'
        ORDER BY joined_at DESC
        LIMIT 1;

        v_description := generate_reward_event_description(
            'achievement'::public.reward_type,
            'earned'::public.reward_event_type,
            NULL,
            v_achievement_name,
            NEW.metadata
        );

        INSERT INTO public.reward_events (
            student_id,
            reward_type,
            event_type,
            item_name,
            description,
            metadata,
            source_table,
            source_id,
            class_id,
            created_at
        ) VALUES (
            NEW.student_id,
            'achievement',
            'earned',
            v_achievement_name,
            v_description,
            COALESCE(NEW.metadata, '{}') || jsonb_build_object(
                'achievement_id', NEW.achievement_id
            ),
            'student_achievements',
            NEW.id,
            v_class_id,
            NEW.unlocked_at
        );

        RETURN NEW;
    END;
    $$;


ALTER FUNCTION "public"."log_achievements_to_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_bonus_history_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_event_type public.reward_event_type;
    v_description TEXT;
BEGIN
    -- Skip if already logged
    IF EXISTS (
        SELECT 1 FROM public.reward_events
        WHERE source_table = 'bonus_history'
        AND source_id = NEW.id
    ) THEN
        RETURN NEW;
    END IF;

    -- Determine event type
    IF NEW.delta > 0 THEN
        v_event_type := 'earned';
    ELSE
        v_event_type := 'used';
    END IF;

    -- Generate description
    v_description := generate_reward_event_description(
        'bonus'::public.reward_type,
        v_event_type,
        NEW.delta,
        NULL,
        jsonb_build_object('reason', NEW.reason)
    );

    -- Insert into reward_events
    INSERT INTO public.reward_events (
        student_id,
        reward_type,
        event_type,
        amount,
        description,
        metadata,
        source_table,
        source_id,
        class_id,
        created_by,
        created_at
    ) VALUES (
        NEW.student_id,
        'bonus',
        v_event_type,
        NEW.delta,
        v_description,
        jsonb_build_object(
            'reason', NEW.reason,
            'original_delta', NEW.delta
        ),
        'bonus_history',
        NEW.id,
        NEW.class_id,
        NEW.created_by,
        NEW.created_at
    );

    RETURN NEW;
END;
$$;


