CREATE OR REPLACE FUNCTION "public"."log_moderation_action"("p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_log_id UUID;
BEGIN
  -- Verify caller is a teacher/admin
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid()
    AND role IN ('teacher', 'admin')
  ) THEN
    RAISE EXCEPTION 'Permission denied: only teachers can perform moderation actions';
  END IF;

  -- Insert log entry
  INSERT INTO moderation_logs (
    moderator_id,
    action,
    target_type,
    target_id,
    reason,
    metadata
  ) VALUES (
    auth.uid(),
    p_action,
    p_target_type,
    p_target_id,
    p_reason,
    p_metadata
  )
  RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$$;


