CREATE OR REPLACE FUNCTION "public"."log_vip_card_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_old_cards JSONB;
    v_new_cards JSONB;
BEGIN
    IF OLD.vip_cards IS DISTINCT FROM NEW.vip_cards THEN
        v_old_cards := COALESCE(OLD.vip_cards, '{}'::JSONB);
        v_new_cards := COALESCE(NEW.vip_cards, '{}'::JSONB);

        INSERT INTO public.vip_cards_activity (
            student_id,
            card_instance_id,
            card_template_id,
            action,
            metadata
        )
        SELECT
            NEW.id,
            old_cards.instance_id,
            old_cards.card_data->>'cardId',
            'removed',
            jsonb_build_object(
                'removed_by', COALESCE(auth.uid()::TEXT, 'system'),
                'removed_at', to_char(NOW(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
                'was_used', (old_cards.card_data->>'usedAt') IS NOT NULL
            )
        FROM jsonb_each(v_old_cards) AS old_cards(instance_id, card_data)
        WHERE NOT EXISTS (
            SELECT 1
            FROM jsonb_each(v_new_cards) AS new_cards(instance_id, card_data)
            WHERE new_cards.instance_id = old_cards.instance_id
        )
        -- Skip if ANY action was already logged for this card in the current
        -- transaction (covers 'removed' from RPC, 'traded'/'gained' from execute_trade)
        AND NOT EXISTS (
            SELECT 1
            FROM public.vip_cards_activity vca
            WHERE vca.student_id = NEW.id
              AND vca.card_instance_id = old_cards.instance_id
              AND vca.created_at >= NOW()
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_vip_card_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_vip_card_changes"() IS 'Trigger function that logs ONLY card removals to vip_cards_activity.
Gained, used, and traded actions are logged by their respective RPC functions.
Includes dedup check: skips if ANY activity was already logged for that card
in the current transaction (prevents spurious removed entries for trades).';



CREATE OR REPLACE FUNCTION "public"."log_vip_cards_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_event_type public.reward_event_type;
    v_card_name TEXT;
    v_description TEXT;
    v_class_id UUID;
    v_acquired_from TEXT;
    v_action_type TEXT;
    v_used_by TEXT;
    v_trade_id TEXT;
    v_partner_name TEXT;
    v_amount INT;
    v_payment_card_name TEXT;
    v_action_card_name TEXT;
BEGIN
    -- Skip if already logged
    IF EXISTS (
        SELECT 1 FROM public.reward_events
        WHERE source_table = 'vip_cards_activity'
        AND source_id = NEW.id
    ) THEN
        RETURN NEW;
    END IF;

    -- Map action to event type
    CASE NEW.action
        WHEN 'gained' THEN v_event_type := 'earned';
        WHEN 'used' THEN v_event_type := 'used';
        WHEN 'removed' THEN v_event_type := 'removed';
        WHEN 'traded' THEN v_event_type := 'traded';
        WHEN 'sold' THEN v_event_type := 'used';
        WHEN 'approved' THEN RETURN NEW;
        WHEN 'rejected' THEN RETURN NEW;
        WHEN 'requested' THEN RETURN NEW;
        ELSE v_event_type := 'earned';
    END CASE;

    -- Get card name from template
    SELECT name INTO v_card_name
    FROM public.vip_card_templates
    WHERE id = NEW.card_template_id;

    v_card_name := COALESCE(v_card_name, NEW.card_template_id);

    -- Extract metadata fields for contextual descriptions
    v_acquired_from := NEW.metadata->>'acquired_from';
    v_action_type := NEW.metadata->>'action_type';
    v_used_by := NEW.metadata->>'used_by';
    v_trade_id := LEFT(COALESCE(NEW.metadata->>'trade_id', ''), 8);
    v_payment_card_name := NEW.metadata->>'payment_card_name';
    v_action_card_name := NEW.metadata->>'action_card_name';

    -- Build contextual description based on action + metadata
    v_description := CASE
        -- GAINED descriptions
        WHEN NEW.action = 'gained' AND v_acquired_from = 'purchase' THEN
            'Carte VIP achetée'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'draw_gidouilles' THEN
            'Carte VIP obtenue par tirage'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'draw_vip_card' THEN
            'Carte VIP obtenue par tirage (carte ' || COALESCE(v_payment_card_name, 'VIP') || ')'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'exchange' THEN
            'Carte VIP obtenue par échange (carte ' || COALESCE(v_action_card_name, 'VIP') || ')'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'choose' THEN
            'Carte VIP choisie (utilisation de la carte ' || COALESCE(v_action_card_name, 'VIP') || ')'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'teacher_award' THEN
            'Carte VIP offerte par le prof'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'teacher_draw' THEN
            'Carte VIP tirée par le prof'
        WHEN NEW.action = 'gained' AND v_acquired_from = 'trade' THEN
            format('Carte reçue de %s (échange #%s)',
                COALESCE(NEW.metadata->>'received_from_name', 'un élève'),
                v_trade_id)
        WHEN NEW.action = 'gained' THEN
            'Carte VIP obtenue'

        -- USED descriptions
        WHEN NEW.action = 'used' AND v_action_type = 'draw_cards' THEN
            'Carte VIP utilisée pour tirer '
            || COALESCE((NEW.metadata->>'cards_drawn')::TEXT, '')
            || ' cartes'
        WHEN NEW.action = 'used' AND v_action_type = 'exchange_cards' THEN
            'Carte VIP utilisée pour échanger des cartes'
        WHEN NEW.action = 'used' AND v_action_type = 'remove_warnings' THEN
            'Carte VIP utilisée pour retirer '
            || COALESCE((NEW.metadata->>'warnings_removed')::TEXT, '')
            || ' avertissements'
        WHEN NEW.action = 'used' AND v_action_type = 'add_gidouilles' THEN
            'Carte VIP utilisée pour gagner '
            || COALESCE((NEW.metadata->>'gidouilles_amount')::TEXT, '')
            || ' gidouilles'
        WHEN NEW.action = 'used' AND v_action_type = 'choose_card' THEN
            'Carte VIP utilisée pour choisir des cartes'
        WHEN NEW.action = 'used' AND v_used_by = 'exchange' THEN
            'Carte VIP défaussée pour échange (carte ' || COALESCE(v_action_card_name, 'VIP') || ')'
        WHEN NEW.action = 'used' THEN
            'Carte VIP utilisée'

        -- SOLD description
        WHEN NEW.action = 'sold' THEN
            'Carte vendue'

        -- REMOVED description
        WHEN NEW.action = 'removed' THEN
            'Carte VIP retirée par le prof'

        -- TRADED
        WHEN NEW.action = 'traded' THEN
            format('Carte donnée à %s (échange #%s)',
                COALESCE(NEW.metadata->>'traded_to_name', 'un élève'),
                v_trade_id)

        -- Fallback
        ELSE 'Carte VIP'
    END;

    -- Get class_id from student's active membership
    SELECT cm.class_id INTO v_class_id
    FROM public.class_members cm
    WHERE cm.student_id = NEW.student_id
    AND cm.status = 'active'
    LIMIT 1;

    INSERT INTO public.reward_events (
        student_id,
        reward_type,
        event_type,
        item_name,
        description,
        metadata,
        source_table,
        source_id,
        class_id,
        created_by,
        created_at
    ) VALUES (
        NEW.student_id,
        'vip_card',
        v_event_type,
        v_card_name,
        v_description,
        NEW.metadata,
        'vip_cards_activity',
        NEW.id,
        v_class_id,
        NEW.student_id,
        NEW.created_at
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_vip_cards_to_events"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_vip_cards_to_events"() IS 'Trigger on vip_cards_activity that creates reward_events for the student journal.
Maps: gained->earned, used->used, removed->removed, traded->traded, sold->used.
Skips: approved, rejected, requested.';



CREATE OR REPLACE FUNCTION "public"."log_warning_added_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_description TEXT;
    v_type_label TEXT;
BEGIN
    -- Skip if already logged (deduplication)
    IF EXISTS (
        SELECT 1 FROM public.reward_events
        WHERE source_table = 'student_warnings'
        AND source_id = NEW.id
        AND event_type = 'awarded'
    ) THEN
        RETURN NEW;
    END IF;

    -- Map warning_type to French label
    CASE NEW.warning_type
        WHEN 'C' THEN v_type_label := 'Comportement';
        WHEN 'M' THEN v_type_label := 'Matériel';
        WHEN 'R' THEN v_type_label := 'Retard';
        WHEN 'T' THEN v_type_label := 'Travail';
        ELSE v_type_label := NEW.warning_type;
    END CASE;

    v_description := format('Avertissement %s reçu', v_type_label);

    INSERT INTO public.reward_events (
        student_id,
        reward_type,
        event_type,
        item_name,
        description,
        metadata,
        source_table,
        source_id,
        class_id,
        created_by,
        created_at
    ) VALUES (
        NEW.student_id,
        'warning',
        'awarded',
        v_type_label,
        v_description,
        jsonb_build_object(
            'warning_type', NEW.warning_type,
            'academic_period_id', NEW.academic_period_id
        ),
        'student_warnings',
        NEW.id,
        NEW.class_id,
        NEW.created_by,
        NEW.created_at
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_warning_added_to_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_warning_removed_to_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_description TEXT;
    v_type_label TEXT;
    v_source TEXT;
    v_card_name TEXT;
    v_metadata JSONB;
BEGIN
    -- Only fire when deleted_at transitions from NULL to a value
    IF OLD.deleted_at IS NOT NULL OR NEW.deleted_at IS NULL THEN
        RETURN NEW;
    END IF;

    -- Skip if already logged (deduplication)
    IF EXISTS (
        SELECT 1 FROM public.reward_events
        WHERE source_table = 'student_warnings'
        AND source_id = NEW.id
        AND event_type = 'removed'
    ) THEN
        RETURN NEW;
    END IF;

    -- Map warning_type to French label
    CASE NEW.warning_type
        WHEN 'C' THEN v_type_label := 'Comportement';
        WHEN 'M' THEN v_type_label := 'Matériel';
        WHEN 'R' THEN v_type_label := 'Retard';
        WHEN 'T' THEN v_type_label := 'Travail';
        ELSE v_type_label := NEW.warning_type;
    END CASE;

    -- Build description from deletion_context
    v_source := NEW.deletion_context->>'source';
    v_card_name := NEW.deletion_context->>'card_name';

    IF v_source = 'vip_card' AND v_card_name IS NOT NULL THEN
        v_description := format('Retiré grâce à une carte %s', v_card_name);
    ELSE
        v_description := 'Retiré par le professeur';
    END IF;

    -- Build metadata with deletion_context included
    v_metadata := jsonb_build_object(
        'warning_type', NEW.warning_type,
        'academic_period_id', NEW.academic_period_id,
        'deleted_by', NEW.deleted_by
    );

    IF NEW.deletion_context IS NOT NULL THEN
        v_metadata := v_metadata || jsonb_build_object('deletion_context', NEW.deletion_context);
    END IF;

    INSERT INTO public.reward_events (
        student_id,
        reward_type,
        event_type,
        item_name,
        description,
        metadata,
        source_table,
        source_id,
        class_id,
        created_by,
        created_at
    ) VALUES (
        NEW.student_id,
        'warning',
        'removed',
        v_type_label,
        v_description,
        v_metadata,
        'student_warnings',
        NEW.id,
        NEW.class_id,
        NEW.deleted_by,
        NEW.deleted_at
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_warning_removed_to_events"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."python_notebook_checkpoint_runs" (
    "notebook_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "cell_id" "text" NOT NULL,
    "status" "text" NOT NULL,
    "error_message" "text",
    "ran_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempt_count" integer DEFAULT 1 NOT NULL,
    "first_attempted_at" timestamp with time zone,
    "succeeded_at" timestamp with time zone,
    "hint_revealed" boolean DEFAULT false NOT NULL,
    CONSTRAINT "python_notebook_checkpoint_runs_attempt_count_nonnegative" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "python_notebook_checkpoint_runs_status_check" CHECK (("status" = ANY (ARRAY['passed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."python_notebook_checkpoint_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."python_notebook_checkpoint_runs" IS 'Latest run of each checkpoint cell (assertion-based test) executed by a student against the persistent namespace of a Python notebook. Upserted by the API; only the most recent result per (notebook_id, user_id, cell_id) is retained.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."cell_id" IS 'Identifier of the checkpoint cell inside python_notebooks.content -> ''cells'' [].id. Generated client-side (UUID v4 style); validated by the application layer (Zod), not by a SQL constraint.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."status" IS 'Outcome of the last assertion execution: ''passed'' or ''failed''.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."error_message" IS 'Assertion / Python error message captured by the Pyodide worker. Nullable; populated only when status = ''failed''.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."attempt_count" IS 'Total number of times the student clicked Vérifier on this checkpoint, across all sessions. Sticky: never decremented. The first run upserts to 1; subsequent runs increment by 1.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."first_attempted_at" IS 'Timestamp of the very first Vérifier click. Set on initial INSERT and never modified afterwards (the UPSERT preserves it via COALESCE).';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."succeeded_at" IS 'Timestamp of the first time the checkpoint passed. NULL if never passed. Sticky-success: once set, never cleared even on later failed re-runs.';



COMMENT ON COLUMN "public"."python_notebook_checkpoint_runs"."hint_revealed" IS 'Whether the student ever clicked "Voir l''indice". One-way transition false → true via PATCH /checkpoint-runs/[cell_id]/hint-revealed. Informs the dashboard that the student used the teacher''s hint.';



CREATE OR REPLACE FUNCTION "public"."mark_checkpoint_hint_revealed"("p_notebook_id" "uuid", "p_cell_id" "text") RETURNS "public"."python_notebook_checkpoint_runs"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user UUID := auth.uid();
  v_result python_notebook_checkpoint_runs;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Only flip false → true. If the row doesn't exist yet (student clicked
  -- Voir l'indice before ever pressing Vérifier — should be impossible per
  -- the UI threshold but defend anyway), we create it with hint_revealed
  -- = true but no status / no ran_at — the next runCheckpoint will fill it.
  INSERT INTO python_notebook_checkpoint_runs AS r (
    notebook_id, user_id, cell_id, status, ran_at,
    attempt_count, first_attempted_at, hint_revealed
  )
  VALUES (
    p_notebook_id, v_user, p_cell_id, 'failed', NOW(),
    0, NULL, TRUE
  )
  ON CONFLICT (notebook_id, user_id, cell_id) DO UPDATE SET
    hint_revealed = TRUE
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."mark_checkpoint_hint_revealed"("p_notebook_id" "uuid", "p_cell_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_checkpoint_hint_revealed"("p_notebook_id" "uuid", "p_cell_id" "text") IS 'Idempotent flip of hint_revealed from false to true. If the row does not yet exist, creates it with attempt_count=0 (signalling "hint revealed before any attempt"). SECURITY INVOKER → RLS still applies.';



CREATE OR REPLACE FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Update last_read_at and optionally last_read_message_id
  UPDATE conversation_participants
  SET
    last_read_at = NOW(),
    last_read_message_id = COALESCE(p_message_id, last_read_message_id)
  WHERE conversation_id = p_conversation_id
  AND user_id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_conversation_read"("p_conversation_id" "uuid", "p_user_id" "uuid", "p_message_id" "uuid") IS 'Update read status when user views messages';



CREATE OR REPLACE FUNCTION "public"."mark_message_as_read"("p_message_id" "uuid", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE message_inbox
  SET read_at = NOW()
  WHERE message_id = p_message_id
    AND recipient_id = p_user_id
    AND read_at IS NULL; -- Only update if not already read
END;
$$;


