CREATE OR REPLACE FUNCTION "public"."prevent_worksheet_instance_tampering"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  is_owner BOOLEAN;
BEGIN
  -- Check if current user is the worksheet owner (teacher) or admin
  SELECT EXISTS (
    SELECT 1 FROM public.worksheets w
    JOIN public.profiles p ON p.id = auth.uid()
    WHERE w.id = OLD.worksheet_id
    AND (w.created_by = auth.uid() OR p.role = 'admin')
  ) INTO is_owner;

  -- If owner/admin, allow all modifications
  IF is_owner THEN
    RETURN NEW;
  END IF;

  -- For students: only allow modification of specific fields
  -- Critical fields must remain unchanged
  IF OLD.instance_data IS DISTINCT FROM NEW.instance_data THEN
    RAISE EXCEPTION 'Cannot modify instance_data after generation';
  END IF;
  IF OLD.variant_seed IS DISTINCT FROM NEW.variant_seed THEN
    RAISE EXCEPTION 'Cannot modify variant_seed';
  END IF;
  IF OLD.worksheet_id IS DISTINCT FROM NEW.worksheet_id THEN
    RAISE EXCEPTION 'Cannot modify worksheet_id';
  END IF;
  IF OLD.student_id IS DISTINCT FROM NEW.student_id THEN
    RAISE EXCEPTION 'Cannot modify student_id';
  END IF;
  -- Allow legitimate updates: status, time_spent_seconds, accessed_at, submitted_at, updated_at
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_worksheet_instance_tampering"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_achievement_event"("p_event_type" "text", "p_student_id" "uuid", "p_event_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_event_id UUID;
  v_achievement RECORD;
  v_unlocked_achievements JSONB[] := ARRAY[]::JSONB[];
  v_unlock_conditions JSONB;
  v_context_data JSONB;
  v_should_unlock BOOLEAN;
  v_points INTEGER;
  v_gidouilles INTEGER;
BEGIN
  -- Insert event into log
  INSERT INTO achievement_events (event_type, event_data, student_id)
  VALUES (p_event_type, p_event_data, p_student_id)
  RETURNING id INTO v_event_id;

  -- Find achievements that might be triggered by this event
  FOR v_achievement IN
    SELECT *
    FROM achievements
    WHERE is_active = true
    AND unlock_type IN ('automatic', 'event_based')
    AND (
      -- Match by event type in unlock conditions
      metadata->'unlock_conditions'->>'type' = p_event_type
      OR
      -- Match by context
      context = split_part(p_event_type, '_', 1)
    )
    ORDER BY display_order
  LOOP
    v_unlock_conditions := v_achievement.metadata->'unlock_conditions';
    v_should_unlock := false;
    v_context_data := '{}'::jsonb;

    -- Check if prerequisites are met
    IF NOT check_achievement_prerequisites(p_student_id, v_achievement.id) THEN
      CONTINUE;
    END IF;

    -- Evaluate unlock conditions based on event type
    CASE
      -- Minesweeper achievements
      WHEN p_event_type = 'minesweeper_game_completed' THEN
        -- Check difficulty-specific achievements
        IF v_achievement.metadata->>'difficulty_specific' = 'true' THEN
          v_context_data := jsonb_build_object('difficulty', p_event_data->>'difficulty');
        END IF;

        -- Check unlock parameters
        v_should_unlock := true;

        -- Check min_score requirement
        IF v_unlock_conditions->'params'->>'min_score' IS NOT NULL THEN
          v_should_unlock := v_should_unlock AND
            (p_event_data->>'score')::INTEGER >= (v_unlock_conditions->'params'->>'min_score')::INTEGER;
        END IF;

        -- Check max_time requirement
        IF v_unlock_conditions->'params'->>'max_time' IS NOT NULL THEN
          v_should_unlock := v_should_unlock AND
            (p_event_data->>'time_seconds')::INTEGER <= (v_unlock_conditions->'params'->>'max_time')::INTEGER;
        END IF;

        -- Check perfect requirement
        IF v_unlock_conditions->'params'->>'perfect' = 'true' THEN
          v_should_unlock := v_should_unlock AND
            p_event_data->>'perfect' = 'true';
        END IF;

      -- Questions/Assessments achievements
      WHEN p_event_type IN ('question_answered', 'assessment_completed') THEN
        -- Check subject-specific achievements
        IF v_achievement.metadata->>'subject_specific' = 'true' THEN
          v_context_data := jsonb_build_object('subject', p_event_data->>'subject');
        END IF;

        -- For progressive achievements, update progress instead
        IF v_achievement.unlock_type = 'progressive' THEN
          PERFORM update_achievement_progress(
            p_student_id,
            v_achievement.id,
            1,  -- Increment by 1
            p_event_data->>'subject'
          );
          CONTINUE;  -- Skip direct unlock
        END IF;

        -- Check accuracy requirement
        IF v_unlock_conditions->'params'->>'min_accuracy' IS NOT NULL THEN
          v_should_unlock :=
            (p_event_data->>'accuracy')::NUMERIC >= (v_unlock_conditions->'params'->>'min_accuracy')::NUMERIC;
        END IF;

      -- Social achievements
      WHEN p_event_type = 'friend_added' THEN
        v_should_unlock := true;

        -- Check if repeatable
        IF v_achievement.metadata->>'repeatable' = 'true' THEN
          -- Count current iterations
          DECLARE
            v_current_iterations INTEGER;
            v_max_repetitions INTEGER;
          BEGIN
            SELECT COUNT(*) INTO v_current_iterations
            FROM student_achievements
            WHERE student_id = p_student_id
            AND achievement_id = v_achievement.id;

            v_max_repetitions := COALESCE((v_achievement.metadata->>'max_repetitions')::INTEGER, 999);

            IF v_current_iterations >= v_max_repetitions THEN
              v_should_unlock := false;
            ELSE
              v_context_data := jsonb_build_object('iteration', v_current_iterations + 1);
            END IF;
          END;
        END IF;

      ELSE
        -- Generic event processing
        v_should_unlock := v_unlock_conditions->>'type' = p_event_type;
    END CASE;

    -- If should unlock, award the achievement
    IF v_should_unlock THEN
      -- Check if already unlocked (considering context)
      IF NOT EXISTS (
        SELECT 1 FROM student_achievements
        WHERE student_id = p_student_id
        AND achievement_id = v_achievement.id
        AND (
          context_data = v_context_data
          OR (context_data IS NULL AND v_context_data = '{}'::jsonb)
        )
      ) THEN
        -- Calculate rewards
        v_points := COALESCE((v_achievement.metadata->>'points')::INTEGER, 0);
        v_gidouilles := COALESCE((v_achievement.metadata->>'gidouilles_reward')::INTEGER, 0);

        -- Award achievement
        INSERT INTO student_achievements (
          student_id,
          achievement_id,
          context_data,
          points_awarded,
          gidouilles_awarded,
          unlock_reason
        )
        VALUES (
          p_student_id,
          v_achievement.id,
          v_context_data || jsonb_build_object(
            'reference_type', p_event_type,
            'reference_id', p_event_data->>'reference_id'
          ),
          v_points,
          v_gidouilles,
          format('Event: %s', p_event_type)
        );

        -- Add to unlocked list
        v_unlocked_achievements := array_append(
          v_unlocked_achievements,
          jsonb_build_object(
            'achievement_id', v_achievement.id,
            'name', v_achievement.name,
            'description', v_achievement.description,
            'icon', v_achievement.icon,
            'points', v_points,
            'gidouilles', v_gidouilles,
            'context_data', v_context_data
          )
        );
      END IF;
    END IF;
  END LOOP;

  -- Mark event as processed
  UPDATE achievement_events
  SET
    processed = true,
    processed_at = NOW()
  WHERE id = v_event_id;

  -- Return newly unlocked achievements
  RETURN jsonb_build_object(
    'event_id', v_event_id,
    'unlocked_achievements', to_jsonb(v_unlocked_achievements),
    'count', array_length(v_unlocked_achievements, 1)
  );
END;
$$;


ALTER FUNCTION "public"."process_achievement_event"("p_event_type" "text", "p_student_id" "uuid", "p_event_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_achievement_event"("p_event_type" "text", "p_student_id" "uuid", "p_event_data" "jsonb") IS 'Main entry point for achievement processing. Call this when any achievement-worthy event occurs.';



CREATE OR REPLACE FUNCTION "public"."process_message_content"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_plain_text TEXT;
  v_has_profanity BOOLEAN;
BEGIN
  -- Extract plain text from TipTap JSON
  v_plain_text := extract_plain_text_from_tiptap(NEW.content);
  NEW.plain_text := v_plain_text;

  -- Check for profanity (basic check, server-side will do more sophisticated checking)
  v_has_profanity := check_profanity_simple(v_plain_text);

  IF v_has_profanity THEN
    NEW.is_flagged := true;
    NEW.flag_reason := 'Profanité détectée automatiquement';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_message_content"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_weekly_rewards"("p_week_start" "date", "p_week_end" "date", "p_class_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("student_id" "uuid", "class_id" "uuid", "awarded" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_caller_role TEXT;
    v_inserted_count INTEGER;
BEGIN
    -- SECURITY CHECK (Issue #1): Get caller's role to enforce authorization
    -- SECURITY DEFINER functions bypass RLS, so we must check permissions explicitly
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- Authorization: Only admins, teachers, or service_role can process rewards
    IF auth.uid() IS NOT NULL AND v_caller_role NOT IN ('admin', 'teacher') THEN
        RAISE EXCEPTION 'Unauthorized: You do not have permission to process weekly rewards';
    END IF;

    -- FIX (Issue #11): Use batch INSERT instead of looping for better performance
    -- Batch insert rewards for all eligible students without warnings
    WITH eligible_no_warnings AS (
        SELECT cm.student_id, cm.class_id
        FROM public.class_members cm
        WHERE cm.status = 'active'
        AND (p_class_ids IS NULL OR cm.class_id = ANY(p_class_ids))
        AND EXISTS (
            SELECT 1 FROM public.profiles p
            WHERE p.id = cm.student_id
            AND p.role = 'student'
            AND NOT COALESCE(p.is_test, FALSE)
        )
        AND NOT EXISTS (
            SELECT 1 FROM public.student_warnings sw
            WHERE sw.student_id = cm.student_id
            AND sw.class_id = cm.class_id
            AND DATE(sw.created_at) BETWEEN p_week_start AND p_week_end
            AND sw.deleted_at IS NULL
        )
    )
    INSERT INTO public.weekly_rewards (student_id, class_id, week_start, week_end, gidouilles_awarded, reason)
    SELECT student_id, class_id, p_week_start, p_week_end, 1, 'no_warnings'
    FROM eligible_no_warnings
    ON CONFLICT (student_id, class_id, week_start) DO NOTHING;

    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
    RAISE NOTICE 'Inserted % weekly reward records', v_inserted_count;

    -- Now batch update gidouilles for all students who received rewards
    -- This uses the gidouilles_history table for audit trail
    WITH new_rewards AS (
        SELECT wr.student_id, wr.class_id, wr.gidouilles_awarded
        FROM public.weekly_rewards wr
        WHERE wr.week_start = p_week_start
        AND wr.week_end = p_week_end
        AND (p_class_ids IS NULL OR wr.class_id = ANY(p_class_ids))
    )
    INSERT INTO public.gidouilles_history (student_id, class_id, delta, reason, created_by)
    SELECT student_id, class_id, gidouilles_awarded, 'no_warnings', NULL
    FROM new_rewards;

    -- Update profiles.gidouilles in batch
    UPDATE public.profiles p
    SET gidouilles = GREATEST(0, COALESCE(p.gidouilles, 0) + nr.gidouilles_awarded)
    FROM (
        SELECT wr.student_id, SUM(wr.gidouilles_awarded) as gidouilles_awarded
        FROM public.weekly_rewards wr
        WHERE wr.week_start = p_week_start
        AND wr.week_end = p_week_end
        AND (p_class_ids IS NULL OR wr.class_id = ANY(p_class_ids))
        GROUP BY wr.student_id
    ) nr
    WHERE p.id = nr.student_id;

    -- Return summary of all students
    RETURN QUERY
    WITH eligible_students AS (
        SELECT DISTINCT
            cm.student_id,
            cm.class_id
        FROM public.class_members cm
        WHERE cm.status = 'active'
        AND (p_class_ids IS NULL OR cm.class_id = ANY(p_class_ids))
        AND EXISTS (
            SELECT 1 FROM public.profiles p
            WHERE p.id = cm.student_id
            AND p.role = 'student'
            AND NOT COALESCE(p.is_test, FALSE)
        )
    ),
    weekly_warnings AS (
        SELECT
            sw.student_id,
            sw.class_id,
            COUNT(*) as warning_count
        FROM public.student_warnings sw
        WHERE DATE(sw.created_at) BETWEEN p_week_start AND p_week_end
        AND sw.deleted_at IS NULL
        AND (p_class_ids IS NULL OR sw.class_id = ANY(p_class_ids))
        GROUP BY sw.student_id, sw.class_id
    )
    SELECT
        es.student_id,
        es.class_id,
        CASE
            WHEN ww.warning_count IS NULL OR ww.warning_count = 0 THEN TRUE
            ELSE FALSE
        END as awarded,
        CASE
            WHEN ww.warning_count IS NULL OR ww.warning_count = 0 THEN 'no_warnings'
            ELSE 'has_warnings'
        END as reason
    FROM eligible_students es
    LEFT JOIN weekly_warnings ww
        ON es.student_id = ww.student_id
        AND es.class_id = ww.class_id;
END;
$$;


ALTER FUNCTION "public"."process_weekly_rewards"("p_week_start" "date", "p_week_end" "date", "p_class_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_user_to_admin"("user_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Update the user's role to admin
  UPDATE profiles
  SET role = 'admin',
      updated_at = NOW()
  WHERE email = user_email;

  -- Raise notice if no user found
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No user found with email: %', user_email;
  END IF;

  RAISE NOTICE 'User % has been promoted to admin', user_email;
END;
$$;


ALTER FUNCTION "public"."promote_user_to_admin"("user_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."promote_user_to_admin"("user_email" "text") IS 'Promotes a user to admin role by email address. Should only be called by existing admins or via service role.';



CREATE OR REPLACE FUNCTION "public"."purchase_shop_item"("p_student_id" "uuid", "p_template_id" "uuid", "p_quantity" integer DEFAULT 1, "p_purchase_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_template RECORD;
    v_current_balance INTEGER;
    v_final_price INTEGER;
    v_inventory_id UUID;
    v_gidouilles_history_id UUID;
    v_purchase_id UUID;
    v_existing_quantity INTEGER;
    v_daily_purchases INTEGER;
    v_weekly_purchases INTEGER;
    v_last_purchase TIMESTAMPTZ;
    v_student_class_id UUID;
BEGIN
    -- SECURITY: Verify caller is purchasing for themselves
    IF p_student_id != auth.uid() THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Non autorisé'
        );
    END IF;

    -- Validate input
    IF p_quantity <= 0 OR p_quantity > 100 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'La quantité doit être entre 1 et 100'
        );
    END IF;

    -- Get template details
    SELECT * INTO v_template
    FROM shop_item_templates
    WHERE id = p_template_id
    AND is_active = true
    AND (available_from IS NULL OR available_from <= NOW())
    AND (available_until IS NULL OR available_until >= NOW());

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Article non trouvé ou indisponible'
        );
    END IF;

    -- Calculate final price (with discount)
    v_final_price := CEIL(v_template.base_price * p_quantity * (1 - COALESCE(v_template.discount_percentage, 0) / 100.0));

    -- Check student balance WITH ROW LOCK
    SELECT gidouilles INTO v_current_balance
    FROM profiles
    WHERE id = p_student_id
    FOR UPDATE;  -- CRITICAL: Lock row to prevent concurrent modifications

    IF v_current_balance IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Profil étudiant non trouvé'
        );
    END IF;

    IF v_current_balance < v_final_price THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Gidouilles insuffisantes (requis: %s, disponible: %s)', v_final_price, v_current_balance)
        );
    END IF;

    -- Check ownership limit
    IF v_template.max_owned_per_student IS NOT NULL THEN
        SELECT COALESCE(SUM(quantity), 0) INTO v_existing_quantity
        FROM student_item_inventory
        WHERE student_id = p_student_id
        AND template_id = p_template_id;

        IF v_existing_quantity + p_quantity > v_template.max_owned_per_student THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Limite de possession atteinte (max: %s)', v_template.max_owned_per_student)
            );
        END IF;
    END IF;

    -- Check daily purchase limit
    IF v_template.daily_purchase_limit IS NOT NULL THEN
        SELECT COALESCE(SUM(quantity), 0) INTO v_daily_purchases
        FROM shop_purchase_history
        WHERE student_id = p_student_id
        AND template_id = p_template_id
        AND purchased_at >= date_trunc('day', NOW())
        AND refunded_at IS NULL;

        IF v_daily_purchases + p_quantity > v_template.daily_purchase_limit THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Limite quotidienne atteinte (max: %s/jour)', v_template.daily_purchase_limit)
            );
        END IF;
    END IF;

    -- Check weekly purchase limit
    IF v_template.weekly_purchase_limit IS NOT NULL THEN
        SELECT COALESCE(SUM(quantity), 0) INTO v_weekly_purchases
        FROM shop_purchase_history
        WHERE student_id = p_student_id
        AND template_id = p_template_id
        AND purchased_at >= date_trunc('week', NOW())
        AND refunded_at IS NULL;

        IF v_weekly_purchases + p_quantity > v_template.weekly_purchase_limit THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Limite hebdomadaire atteinte (max: %s/semaine)', v_template.weekly_purchase_limit)
            );
        END IF;
    END IF;

    -- Check purchase cooldown
    IF v_template.purchase_cooldown_hours IS NOT NULL AND v_template.purchase_cooldown_hours > 0 THEN
        SELECT MAX(purchased_at) INTO v_last_purchase
        FROM shop_purchase_history
        WHERE student_id = p_student_id
        AND template_id = p_template_id
        AND refunded_at IS NULL;

        IF v_last_purchase IS NOT NULL AND
           v_last_purchase + (v_template.purchase_cooldown_hours || ' hours')::INTERVAL > NOW() THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', format('Temps d''attente requis: %s heures', v_template.purchase_cooldown_hours)
            );
        END IF;
    END IF;

    -- Get student's class for gidouilles update
    SELECT class_id INTO v_student_class_id
    FROM class_members
    WHERE student_id = p_student_id
    AND status = 'active'
    LIMIT 1;

    -- Generate purchase_id early so we can reference it
    v_purchase_id := gen_random_uuid();

    -- Deduct gidouilles atomically (row is already locked by FOR UPDATE above)
    UPDATE profiles
    SET gidouilles = gidouilles - v_final_price
    WHERE id = p_student_id;

    -- Log to gidouilles_history
    INSERT INTO gidouilles_history (
        student_id,
        class_id,
        delta,
        reason,
        created_by
    ) VALUES (
        p_student_id,
        v_student_class_id,
        -v_final_price,
        format('Achat boutique: %s x%s', v_template.display_name, p_quantity),
        auth.uid()
    ) RETURNING id INTO v_gidouilles_history_id;

    -- Check if item is stackable (from properties)
    IF v_template.properties->>'stackable' = 'true' THEN
        -- Try to find existing stackable inventory entry
        SELECT id, quantity INTO v_inventory_id, v_existing_quantity
        FROM student_item_inventory
        WHERE student_id = p_student_id
        AND template_id = p_template_id
        AND uses_remaining IS NULL
        AND instance_data = '{}'
        AND NOT is_locked
        LIMIT 1;

        IF v_inventory_id IS NOT NULL THEN
            -- Update existing stack
            UPDATE student_item_inventory
            SET quantity = quantity + p_quantity,
                updated_at = NOW()
            WHERE id = v_inventory_id;
        ELSE
            -- Create new stack
            INSERT INTO student_item_inventory (
                student_id,
                template_id,
                quantity,
                acquired_via,
                acquisition_data
            ) VALUES (
                p_student_id,
                p_template_id,
                p_quantity,
                'purchase',
                jsonb_build_object('purchase_id', v_purchase_id)
            ) RETURNING id INTO v_inventory_id;
        END IF;
    ELSE
        -- Non-stackable: create individual entries
        FOR i IN 1..p_quantity LOOP
            INSERT INTO student_item_inventory (
                student_id,
                template_id,
                quantity,
                uses_remaining,
                acquired_via,
                acquisition_data
            ) VALUES (
                p_student_id,
                p_template_id,
                1,
                CASE
                    WHEN v_template.properties->>'uses' IS NOT NULL
                    THEN (v_template.properties->>'uses')::INTEGER
                    ELSE NULL
                END,
                'purchase',
                jsonb_build_object('purchase_id', v_purchase_id)
            ) RETURNING id INTO v_inventory_id;  -- Returns last one
        END LOOP;

        -- If we need to return the first inventory ID, get it
        SELECT id INTO v_inventory_id
        FROM student_item_inventory
        WHERE student_id = p_student_id
        AND template_id = p_template_id
        ORDER BY created_at DESC
        LIMIT 1;
    END IF;

    -- Log purchase WITH CONTEXT (use the pre-generated v_purchase_id)
    INSERT INTO shop_purchase_history (
        id,
        student_id,
        template_id,
        inventory_id,
        quantity,
        unit_price,
        total_price,
        discount_applied,
        gidouilles_history_id,
        purchase_context  -- NEW: Include audit context
    ) VALUES (
        v_purchase_id,
        p_student_id,
        p_template_id,
        v_inventory_id,
        p_quantity,
        v_template.base_price,
        v_final_price,
        v_template.base_price * p_quantity - v_final_price,
        v_gidouilles_history_id,
        p_purchase_context  -- NEW: Store IP, user-agent, etc.
    );

    -- Return success
    RETURN jsonb_build_object(
        'success', true,
        'inventory_id', v_inventory_id,
        'purchase_id', v_purchase_id,
        'gidouilles_spent', v_final_price,
        'new_balance', v_current_balance - v_final_price,
        'item_name', v_template.display_name,
        'quantity', p_quantity
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Erreur lors de l''achat',
            'details', SQLERRM
        );
END;
$$;


ALTER FUNCTION "public"."purchase_shop_item"("p_student_id" "uuid", "p_template_id" "uuid", "p_quantity" integer, "p_purchase_context" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purchase_shop_item"("p_student_id" "uuid", "p_template_id" "uuid", "p_quantity" integer, "p_purchase_context" "jsonb") IS 'Atomic purchase of shop items with all validations. Includes purchase_context for audit trail (IP, user-agent).';



CREATE OR REPLACE FUNCTION "public"."purchase_vip_card"("p_student_id" "uuid", "p_card_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_template RECORD;
  v_current_balance INTEGER;
  v_new_balance INTEGER;
  v_current_owned INTEGER;
  v_instance_id UUID;
  v_now TIMESTAMPTZ := NOW();
  v_vip_cards JSONB;
  v_new_instance JSONB;
  v_class_id UUID;
BEGIN
  -- ========================================================================
  -- SECURITY: Verify caller is the student
  -- ========================================================================

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Authentication required'
    );
  END IF;

  IF auth.uid() != p_student_id THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Cannot purchase cards for other students'
    );
  END IF;

  -- ========================================================================
  -- GET AND VALIDATE CARD TEMPLATE
  -- ========================================================================

  SELECT id, name, rarity, base_price, is_purchasable, max_owned_per_student, is_enabled, uses_total
  INTO v_template
  FROM vip_card_templates
  WHERE id = p_card_id;

  IF v_template IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card not found: ' || p_card_id
    );
  END IF;

  IF NOT v_template.is_enabled THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card is disabled and cannot be purchased'
    );
  END IF;

  IF NOT v_template.is_purchasable THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card is not available for purchase'
    );
  END IF;

  -- ========================================================================
  -- GET AND LOCK STUDENT PROFILE
  -- ========================================================================

  SELECT gidouilles, vip_cards INTO v_current_balance, v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_current_balance IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Student not found'
    );
  END IF;

  -- ========================================================================
  -- VALIDATE BALANCE
  -- ========================================================================

  IF v_current_balance < v_template.base_price THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', format('Insufficient balance. Required: %s, Available: %s', v_template.base_price, v_current_balance)
    );
  END IF;

  -- ========================================================================
  -- CHECK OWNERSHIP LIMIT
  -- ========================================================================

  v_current_owned := count_student_active_cards(p_student_id, p_card_id);

  IF v_current_owned >= v_template.max_owned_per_student THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', format('Maximum ownership limit reached (%s/%s)', v_current_owned, v_template.max_owned_per_student),
      'currentOwned', v_current_owned,
      'maxOwned', v_template.max_owned_per_student
    );
  END IF;

  -- ========================================================================
  -- PERFORM PURCHASE
  -- ========================================================================

  v_instance_id := gen_random_uuid();
  v_new_balance := v_current_balance - v_template.base_price;

  -- Security: Validate balance is within safe range
  IF v_new_balance < 0 OR v_new_balance > 10000000 THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Invalid balance calculation detected'
    );
  END IF;

  -- Create new instance with purchase metadata
  v_new_instance := jsonb_build_object(
    'cardId', p_card_id,
    'earnedAt', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'usedAt', NULL,
    'purchasedAt', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'acquiredFrom', 'purchase',
    'usesRemaining', v_template.uses_total
  );

  -- Initialize vip_cards if null
  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- Add new instance
  v_vip_cards := v_vip_cards || jsonb_build_object(v_instance_id::TEXT, v_new_instance);

  -- ========================================================================
  -- UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET
    gidouilles = v_new_balance,
    vip_cards = v_vip_cards,
    updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- LOG VIP CARD ACTIVITY
  -- ========================================================================

  INSERT INTO vip_cards_activity (
    student_id,
    card_instance_id,
    card_template_id,
    action,
    metadata
  ) VALUES (
    p_student_id,
    v_instance_id::TEXT,
    p_card_id,
    'gained',
    jsonb_build_object(
      'acquired_from', 'purchase',
      'price_paid', v_template.base_price,
      'old_balance', v_current_balance,
      'new_balance', v_new_balance,
      'rarity', v_template.rarity
    )
  );

  -- ========================================================================
  -- LOG GIDOUILLES SPENT
  -- ========================================================================
  -- This was missing: the gidouilles deduction was not logged, so it didn't
  -- appear in the student's reward journal.

  -- Get student's active class for audit trail visibility
  SELECT cm.class_id INTO v_class_id
  FROM class_members cm
  WHERE cm.student_id = p_student_id
    AND cm.status = 'active'
  LIMIT 1;

  INSERT INTO gidouilles_activity (
    student_id,
    class_id,
    delta,
    reason,
    created_by
  ) VALUES (
    p_student_id,
    v_class_id,
    -v_template.base_price,
    'Achat carte VIP : ' || v_template.name,
    NULL
  );

  -- ========================================================================
  -- RETURN SUCCESS
  -- ========================================================================

  RETURN jsonb_build_object(
    'success', TRUE,
    'instance', jsonb_build_object(
      'instanceId', v_instance_id::TEXT,
      'cardId', p_card_id,
      'purchasedAt', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'acquiredFrom', 'purchase',
      'usesRemaining', v_template.uses_total
    ),
    'oldBalance', v_current_balance,
    'newBalance', v_new_balance,
    'priceDeducted', v_template.base_price,
    'currentOwned', v_current_owned + 1,
    'maxOwned', v_template.max_owned_per_student
  );
END;
$$;


ALTER FUNCTION "public"."purchase_vip_card"("p_student_id" "uuid", "p_card_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purchase_vip_card"("p_student_id" "uuid", "p_card_id" "text") IS 'Purchases a VIP card for a student using gidouilles.
Validates balance, ownership limits, and card availability.
Logs "gained" to vip_cards_activity and gidouilles spent to gidouilles_activity.';



CREATE OR REPLACE FUNCTION "public"."rag_hybrid_search"("query_text" "text", "query_embedding" "public"."vector", "filter_grades" "text"[] DEFAULT NULL::"text"[], "filter_topics" "text"[] DEFAULT NULL::"text"[], "match_count" integer DEFAULT 10, "fts_weight" double precision DEFAULT 1.0, "vector_weight" double precision DEFAULT 1.0) RETURNS TABLE("document_id" "uuid", "document_title" "text", "chunk_id" "uuid", "chunk_content" "text", "combined_score" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH vector_search AS (
    SELECT
      c.id as chunk_id,
      c.document_id,
      1 - (c.embedding <=> query_embedding) as vector_similarity
    FROM rag_chunks c
    JOIN rag_documents d ON c.document_id = d.id
    WHERE (filter_grades IS NULL OR d.grades && filter_grades)
      AND (filter_topics IS NULL OR d.topics && filter_topics)
    ORDER BY c.embedding <=> query_embedding
    LIMIT match_count * 2
  ),
  fts_search AS (
    SELECT
      c.id as chunk_id,
      c.document_id,
      ts_rank(c.content_tsv, websearch_to_tsquery('french', query_text)) as fts_rank
    FROM rag_chunks c
    JOIN rag_documents d ON c.document_id = d.id
    WHERE c.content_tsv @@ websearch_to_tsquery('french', query_text)
      AND (filter_grades IS NULL OR d.grades && filter_grades)
      AND (filter_topics IS NULL OR d.topics && filter_topics)
    ORDER BY fts_rank DESC
    LIMIT match_count * 2
  ),
  rrf_combined AS (
    SELECT
      COALESCE(v.chunk_id, f.chunk_id) as chunk_id,
      COALESCE(v.document_id, f.document_id) as document_id,
      (
        COALESCE(
          vector_weight / (60.0 + (ROW_NUMBER() OVER (ORDER BY v.vector_similarity DESC NULLS LAST))),
          0.0
        ) +
        COALESCE(
          fts_weight / (60.0 + (ROW_NUMBER() OVER (ORDER BY f.fts_rank DESC NULLS LAST))),
          0.0
        )
      ) as combined_score
    FROM vector_search v
    FULL OUTER JOIN fts_search f ON v.chunk_id = f.chunk_id
  )
  SELECT
    r.document_id,
    d.title as document_title,
    r.chunk_id,
    c.content as chunk_content,
    r.combined_score
  FROM rrf_combined r
  JOIN rag_documents d ON r.document_id = d.id
  JOIN rag_chunks c ON r.chunk_id = c.id
  ORDER BY r.combined_score DESC
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."rag_hybrid_search"("query_text" "text", "query_embedding" "public"."vector", "filter_grades" "text"[], "filter_topics" "text"[], "match_count" integer, "fts_weight" double precision, "vector_weight" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rag_hybrid_search"("query_text" "text", "query_embedding" "public"."vector", "filter_grades" "text"[], "filter_topics" "text"[], "match_count" integer, "fts_weight" double precision, "vector_weight" double precision) IS 'Hybrid search using vector similarity + full-text search with RRF fusion. Uses filter_grades parameter.';



CREATE OR REPLACE FUNCTION "public"."rate_limit_submissions"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF (
        SELECT COUNT(*)
        FROM python_exercise_submissions
        WHERE student_id = NEW.student_id
            AND exercise_id = NEW.exercise_id
            AND created_at > NOW() - INTERVAL '1 minute'
    ) >= 10 THEN
        RAISE EXCEPTION 'Limite de taux dépassée: maximum 10 soumissions par minute';
    END IF;
    RETURN NEW;
END;
$$;


