CREATE OR REPLACE FUNCTION "public"."recalculate_minesweeper_reference_times"() RETURNS TABLE("cycle" "text", "difficulty" "text", "old_time" integer, "new_time" integer, "sample_count" integer, "updated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_start DATE;
  v_week_end DATE;
  v_median_time NUMERIC;
  v_count INTEGER;
  v_current_ref RECORD;
  v_new_time INTEGER;
  v_updated BOOLEAN;
BEGIN
  -- Calculate 4-week window ending yesterday
  v_week_end := CURRENT_DATE - INTERVAL '1 day';
  v_week_start := v_week_end - INTERVAL '4 weeks';

  -- Process each cycle/difficulty combination (single query, 15 rows)
  FOR v_current_ref IN
    SELECT * FROM public.minesweeper_reference_times
    ORDER BY
      CASE cycle
        WHEN 'cycle_2' THEN 1
        WHEN 'cycle_3' THEN 2
        WHEN 'cycle_4' THEN 3
        WHEN 'seconde' THEN 4
        WHEN 'cycle_terminal' THEN 5
      END,
      CASE difficulty
        WHEN 'beginner' THEN 1
        WHEN 'intermediate' THEN 2
        WHEN 'expert' THEN 3
      END
  LOOP

    -- Calculate median time for this cycle/difficulty
    -- Join minesweeper_games with profiles to get the student's grade and cycle
    SELECT
      PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY mg.time_seconds),
      COUNT(*)
    INTO v_median_time, v_count
    FROM public.minesweeper_games mg
    JOIN public.profiles p ON mg.student_id = p.id
    WHERE mg.status = 'won'
      AND mg.student_id IS NOT NULL
      AND mg.completed_at >= v_week_start
      AND mg.completed_at < v_week_end + INTERVAL '1 day'
      AND public.get_cycle_for_grade(p.grade) = v_current_ref.cycle
      AND mg.difficulty = v_current_ref.difficulty;

    v_updated := FALSE;

    -- Only update if enough samples
    IF v_count >= v_current_ref.min_samples AND v_median_time IS NOT NULL THEN
      -- Apply bounds
      v_new_time := GREATEST(
        v_current_ref.min_bound,
        LEAST(v_current_ref.max_bound, ROUND(v_median_time)::INTEGER)
      );

      -- Update reference time
      UPDATE public.minesweeper_reference_times
      SET
        reference_time = v_new_time,
        sample_count = v_count,
        calculated_at = NOW(),
        updated_at = NOW()
      WHERE minesweeper_reference_times.cycle = v_current_ref.cycle
        AND minesweeper_reference_times.difficulty = v_current_ref.difficulty;

      -- Record history
      INSERT INTO public.minesweeper_reference_times_history
        (cycle, difficulty, reference_time, sample_count, week_start, week_end)
      VALUES
        (v_current_ref.cycle, v_current_ref.difficulty, v_new_time, v_count, v_week_start, v_week_end);

      v_updated := TRUE;
    ELSE
      v_new_time := v_current_ref.reference_time;

      -- Update sample count even if not updating reference_time
      UPDATE public.minesweeper_reference_times
      SET
        sample_count = COALESCE(v_count, 0),
        updated_at = NOW()
      WHERE minesweeper_reference_times.cycle = v_current_ref.cycle
        AND minesweeper_reference_times.difficulty = v_current_ref.difficulty;
    END IF;

    -- Return result row
    cycle := v_current_ref.cycle;
    difficulty := v_current_ref.difficulty;
    old_time := v_current_ref.reference_time;
    new_time := v_new_time;
    sample_count := COALESCE(v_count, 0);
    updated := v_updated;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."recalculate_minesweeper_reference_times"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalculate_minesweeper_reference_times"() IS 'Weekly recalculation of reference times using 4-week median by cycle.
   Only updates if sample_count >= min_samples. Applies min/max bounds.
   Called by CRON job on Sundays.';



CREATE OR REPLACE FUNCTION "public"."record_game_reward"("p_student_id" "uuid", "p_game_type" "text", "p_game_id" "uuid", "p_theoretical_reward" numeric, "p_school_id" "uuid") RETURNS TABLE("actual_reward" numeric, "is_first_win" boolean, "week_best_reward" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_timezone TEXT;
  v_first_day INTEGER;
  v_game_date DATE;
  v_week_start DATE;
  v_week_end DATE;
  v_is_first_win BOOLEAN;
  v_actual_reward NUMERIC(10,2);
  v_best_reward NUMERIC(10,2);
  v_student_role TEXT;
  v_class_id UUID;
BEGIN
  -- Security check: Verify caller is the student
  IF auth.uid() != p_student_id THEN
    RAISE EXCEPTION 'Unauthorized: You can only record rewards for yourself';
  END IF;

  -- Verify caller is a student
  SELECT role INTO v_student_role FROM profiles WHERE id = p_student_id;
  IF v_student_role != 'student' THEN
    RAISE EXCEPTION 'Unauthorized: Only students can earn game rewards';
  END IF;

  -- Validate game_type (CHANGED: added 'mathemo')
  IF p_game_type NOT IN ('minesweeper', 'riddle', '2048', 'mathemo') THEN
    RAISE EXCEPTION 'Invalid game_type: must be minesweeper, riddle, 2048, or mathemo, got %', p_game_type;
  END IF;

  -- Validate theoretical_reward
  IF p_theoretical_reward < 0 OR p_theoretical_reward > 1000 THEN
    RAISE EXCEPTION 'Invalid theoretical_reward: must be between 0 and 1000, got %', p_theoretical_reward;
  END IF;

  -- Get student's active class_id for audit trail visibility
  SELECT cm.class_id INTO v_class_id
  FROM class_members cm
  WHERE cm.student_id = p_student_id
    AND cm.status = 'active'
  LIMIT 1;

  -- Get school configuration
  SELECT timezone, COALESCE((timetable->'week_config'->>'first_day')::INTEGER, 1)
  INTO v_timezone, v_first_day
  FROM schools
  WHERE id = p_school_id;

  IF v_timezone IS NULL THEN
    RAISE EXCEPTION 'School % not found', p_school_id;
  END IF;

  -- Calculate game date in school timezone
  v_game_date := (NOW() AT TIME ZONE v_timezone)::DATE;

  -- Calculate week boundaries
  SELECT w.week_start, w.week_end
  INTO v_week_start, v_week_end
  FROM calculate_week_boundaries(v_game_date, COALESCE(v_first_day, 1)) w;

  -- ATOMIC CHECK: Is this the first win of the day FOR THIS GAME TYPE?
  SELECT NOT EXISTS (
    SELECT 1
    FROM daily_game_rewards
    WHERE student_id = p_student_id
      AND game_date = v_game_date
      AND game_type = p_game_type
      AND is_first_win_of_day = TRUE
    FOR UPDATE
  ) INTO v_is_first_win;

  -- Calculate actual reward
  v_actual_reward := CASE WHEN v_is_first_win THEN 1 ELSE 0 END;

  -- Insert reward record
  INSERT INTO daily_game_rewards (
    student_id, game_date, game_type, game_id,
    theoretical_reward, actual_reward, is_first_win_of_day, week_start
  ) VALUES (
    p_student_id, v_game_date, p_game_type, p_game_id,
    p_theoretical_reward, v_actual_reward, v_is_first_win, v_week_start
  );

  -- Update weekly best rewards (UPSERT - best PER GAME TYPE)
  INSERT INTO weekly_best_rewards (
    student_id, week_start, week_end,
    best_theoretical_reward, best_reward_game_type, best_reward_game_id
  ) VALUES (
    p_student_id, v_week_start, v_week_end,
    p_theoretical_reward, p_game_type, p_game_id
  )
  ON CONFLICT (student_id, week_start, best_reward_game_type)
  DO UPDATE SET
    best_theoretical_reward = GREATEST(
      weekly_best_rewards.best_theoretical_reward,
      EXCLUDED.best_theoretical_reward
    ),
    best_reward_game_id = CASE
      WHEN EXCLUDED.best_theoretical_reward > weekly_best_rewards.best_theoretical_reward
      THEN EXCLUDED.best_reward_game_id
      ELSE weekly_best_rewards.best_reward_game_id
    END,
    updated_at = NOW()
  RETURNING best_theoretical_reward INTO v_best_reward;

  -- Award gidouilles if first win
  IF v_is_first_win THEN
    -- Update profile
    UPDATE profiles
    SET gidouilles = gidouilles + v_actual_reward
    WHERE id = p_student_id;

    -- Log in activity with class_id for teacher visibility
    INSERT INTO gidouilles_activity (
      student_id, class_id, delta, reason, created_by
    ) VALUES (
      p_student_id, v_class_id, v_actual_reward::INTEGER,
      'daily_game_reward:' || p_game_type, NULL
    );
  END IF;

  -- Return results
  RETURN QUERY SELECT v_actual_reward, v_is_first_win, v_best_reward;
END;
$$;


ALTER FUNCTION "public"."record_game_reward"("p_student_id" "uuid", "p_game_type" "text", "p_game_id" "uuid", "p_theoretical_reward" numeric, "p_school_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_game_reward"("p_student_id" "uuid", "p_game_type" "text", "p_game_id" "uuid", "p_theoretical_reward" numeric, "p_school_id" "uuid") IS 'Records a game victory and awards gidouilles. Enforces 1 gidouille/day PER GAME TYPE. Tracks weekly best PER GAME TYPE. Includes class_id for teacher audit trail visibility.';



CREATE OR REPLACE FUNCTION "public"."record_listing_view"("p_listing_id" "uuid", "p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_row_count INTEGER;
  v_is_new_view BOOLEAN;
  v_view_count INTEGER;
BEGIN
  -- Try to insert a new view record
  -- ON CONFLICT DO NOTHING means if the view already exists, nothing happens
  INSERT INTO marketplace_listing_views (listing_id, user_id, viewed_at)
  VALUES (p_listing_id, p_user_id, NOW())
  ON CONFLICT (listing_id, user_id)
  DO UPDATE SET viewed_at = NOW(); -- Update timestamp for repeat views

  -- Check if a row was inserted (new view) or updated (repeat view)
  GET DIAGNOSTICS v_row_count = ROW_COUNT;

  -- Note: With ON CONFLICT DO UPDATE, ROW_COUNT is always > 0
  -- We need a different approach to detect first-time views
  -- Check if this user has viewed this listing before (older than 1 second ago)
  v_is_new_view := NOT EXISTS (
    SELECT 1 FROM marketplace_listing_views
    WHERE listing_id = p_listing_id
      AND user_id = p_user_id
      AND viewed_at < NOW() - INTERVAL '1 second'
  );

  -- If it's a new view, increment the view count
  IF v_is_new_view THEN
    UPDATE marketplace_listings
    SET view_count = COALESCE(view_count, 0) + 1
    WHERE id = p_listing_id
    RETURNING view_count INTO v_view_count;
  ELSE
    -- Get current view count without incrementing
    SELECT view_count INTO v_view_count
    FROM marketplace_listings
    WHERE id = p_listing_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'is_new_view', v_is_new_view,
    'view_count', COALESCE(v_view_count, 0)
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."record_listing_view"("p_listing_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_listing_views_batch"("p_listing_ids" "uuid"[], "p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_new_views INTEGER := 0;
  v_updated_listings UUID[];
BEGIN
  -- Bulk insert with conflict handling
  -- Only inserts if no existing record (new unique view)
  INSERT INTO marketplace_listing_views (listing_id, user_id, viewed_at)
  SELECT DISTINCT unnest(p_listing_ids), p_user_id, NOW()
  ON CONFLICT (listing_id, user_id)
  DO UPDATE SET viewed_at = NOW()
  RETURNING listing_id INTO v_updated_listings;

  GET DIAGNOSTICS v_new_views = ROW_COUNT;

  -- Update view counters only for actual new views
  -- Use the returned listing_ids to ensure we only update what was actually inserted
  IF v_new_views > 0 THEN
    UPDATE marketplace_listings ml
    SET view_count = COALESCE(view_count, 0) + 1
    WHERE id = ANY(
      SELECT listing_id
      FROM marketplace_listing_views mlv
      WHERE mlv.listing_id = ANY(p_listing_ids)
        AND mlv.user_id = p_user_id
        AND mlv.viewed_at >= NOW() - INTERVAL '1 second'
    );
  END IF;

  RETURN json_build_object(
    'success', true,
    'new_views', v_new_views,
    'listing_ids', p_listing_ids
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE LOG 'Error in record_listing_views_batch: %', SQLERRM;
    RETURN json_build_object(
      'success', false,
      'error', 'Failed to record views',
      'new_views', 0
    );
END;
$$;


ALTER FUNCTION "public"."record_listing_views_batch"("p_listing_ids" "uuid"[], "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_listing_views_batch"("p_listing_ids" "uuid"[], "p_user_id" "uuid") IS 'Batch record multiple listing views in a single database call. Prevents N+1 query problem and improves performance by 60-70%.';



CREATE OR REPLACE FUNCTION "public"."record_minesweeper_loss"("p_game_id" "uuid", "p_grid_state" "jsonb") RETURNS TABLE("success" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_game_record RECORD;
  v_time_seconds INTEGER;
  v_grid_size INTEGER;
BEGIN
  -- Step 1: Get game and verify ownership
  SELECT * INTO v_game_record
  FROM public.minesweeper_games
  WHERE id = p_game_id
    AND student_id = auth.uid()
    AND status = 'in_progress';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found, not owned by you, or already completed';
  END IF;

  -- Step 2: Validate grid_state size
  v_grid_size := pg_column_size(p_grid_state);
  IF v_grid_size > 100000 THEN
    RAISE EXCEPTION 'Grid state too large: exceeds 100KB';
  END IF;

  -- Step 3: Calculate time_seconds server-side
  IF v_game_record.started_at IS NOT NULL THEN
    v_time_seconds := GREATEST(1, EXTRACT(EPOCH FROM (NOW() - v_game_record.started_at))::INTEGER);
  ELSE
    v_time_seconds := 1;
  END IF;

  -- Cap time to reasonable bounds per difficulty (matches CHECK constraint)
  CASE v_game_record.difficulty
    WHEN 'beginner' THEN v_time_seconds := LEAST(v_time_seconds, 3600);
    WHEN 'intermediate' THEN v_time_seconds := LEAST(v_time_seconds, 7200);
    WHEN 'expert' THEN v_time_seconds := LEAST(v_time_seconds, 14400);
  END CASE;

  -- Step 4: Update game record
  UPDATE public.minesweeper_games
  SET
    status = 'lost',
    grid_state = p_grid_state,
    time_seconds = v_time_seconds,
    gidouilles_awarded = 0,
    completed_at = NOW()
  WHERE id = p_game_id;

  RETURN QUERY SELECT TRUE;
END;
$$;


ALTER FUNCTION "public"."record_minesweeper_loss"("p_game_id" "uuid", "p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_minesweeper_loss"("p_game_id" "uuid", "p_grid_state" "jsonb") IS 'Marks a Minesweeper game as lost. Caps time_seconds per difficulty to satisfy reasonable_time_bounds constraint.';



CREATE OR REPLACE FUNCTION "public"."redistribute_tournament_rewards"("p_tournament_id" "uuid") RETURNS TABLE("success" boolean, "rewards_distributed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tournament RECORD;
  v_standing RECORD;
  v_reward INTEGER;
  v_rewards_count INTEGER := 0;
BEGIN
  -- Get tournament
  SELECT * INTO v_tournament
  FROM public.minesweeper_tournaments
  WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found';
  END IF;

  -- Only creator or admin can redistribute
  IF v_tournament.creator_id != auth.uid() THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND role = 'admin'
    ) THEN
      RAISE EXCEPTION 'Only tournament creator or admin can redistribute rewards';
    END IF;
  END IF;

  -- Check tournament is completed
  IF v_tournament.status != 'completed' THEN
    RAISE EXCEPTION 'Can only redistribute rewards for completed tournaments';
  END IF;

  -- Check if rewards were already distributed (check gidouilles_history)
  IF EXISTS (
    SELECT 1 FROM public.gidouilles_history
    WHERE reason LIKE 'Tournament ' || v_tournament.name || ' - Position #%'
  ) THEN
    RAISE EXCEPTION 'Rewards have already been distributed for this tournament';
  END IF;

  -- Distribute rewards to podium
  FOR v_standing IN
    SELECT s.student_id, s.position
    FROM public.minesweeper_tournament_standings s
    WHERE s.tournament_id = p_tournament_id
      AND s.position <= v_tournament.podium_places
    ORDER BY s.position
  LOOP
    -- Get reward amount for this position
    v_reward := (v_tournament.podium_rewards->>v_standing.position::TEXT)::INTEGER;

    IF v_reward IS NOT NULL AND v_reward > 0 THEN
      -- Award gidouilles
      UPDATE public.profiles
      SET gidouilles = COALESCE(gidouilles, 0) + v_reward
      WHERE id = v_standing.student_id;

      -- Record in history
      INSERT INTO public.gidouilles_history (student_id, delta, reason)
      VALUES (
        v_standing.student_id,
        v_reward,
        'Tournament ' || v_tournament.name || ' - Position #' || v_standing.position
      );

      v_rewards_count := v_rewards_count + 1;
    END IF;
  END LOOP;

  success := TRUE;
  rewards_distributed := v_rewards_count;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."redistribute_tournament_rewards"("p_tournament_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redistribute_tournament_rewards"("p_tournament_id" "uuid") IS 'Redistributes rewards for a completed tournament where finalization ran but
   standings were empty (e.g., due to NULL scores before backfill).
   Only works if no rewards were previously distributed.';



