    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY student_achievement_stats;
END;
$$;


ALTER FUNCTION "public"."refresh_achievement_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_achievement_stats_if_needed"("p_force" boolean DEFAULT false, "p_max_staleness_minutes" integer DEFAULT 15, "p_max_changes" integer DEFAULT 100) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_refresh TIMESTAMPTZ;
  v_changes INTEGER;
  v_should_refresh BOOLEAN;
BEGIN
  -- Get current metadata
  SELECT last_refresh, changes_since_refresh
  INTO v_last_refresh, v_changes
  FROM achievement_stats_metadata
  WHERE id = 1;

  -- Determine if refresh is needed
  v_should_refresh := p_force OR
    v_changes >= p_max_changes OR
    (NOW() - v_last_refresh) > (p_max_staleness_minutes || ' minutes')::INTERVAL;

  IF v_should_refresh THEN
    -- Perform concurrent refresh
    REFRESH MATERIALIZED VIEW CONCURRENTLY student_achievement_stats;

    -- Update metadata
    UPDATE achievement_stats_metadata
    SET
      last_refresh = NOW(),
      changes_since_refresh = 0
    WHERE id = 1;

    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."refresh_achievement_stats_if_needed"("p_force" boolean, "p_max_staleness_minutes" integer, "p_max_changes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_vip_card"("p_student_id" "uuid", "p_instance_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_vip_cards JSONB;
  v_card_data JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_now_str TEXT;
BEGIN
  v_teacher_id := auth.uid();

  IF NOT is_teacher_or_admin() THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Only teachers can reject VIP card activations'
    );
  END IF;

  -- Verify student is in one of the teacher's ACTIVE classes
  IF NOT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
      AND cm.status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Student is not in your active classes'
    );
  END IF;

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  v_card_data := v_vip_cards->p_instance_id;

  IF v_card_data IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card instance not found: ' || p_instance_id
    );
  END IF;

  IF v_card_data->>'activationRequestedAt' IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'No pending activation request for this card'
    );
  END IF;

  v_card_id := v_card_data->>'cardId';

  SELECT id, name INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  v_now_str := to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  v_vip_cards := jsonb_set(
    v_vip_cards,
    ARRAY[p_instance_id],
    (v_vip_cards->p_instance_id)
      - 'activationRequestedAt'
      - 'activationRequestedBy'
      - 'activationApprovedAt'
      - 'activationApprovedBy'
  );

  INSERT INTO public.vip_cards_activity (
    student_id, card_instance_id, card_template_id, action, metadata
  ) VALUES (
    p_student_id, p_instance_id, v_card_id, 'rejected',
    jsonb_build_object('rejected_by', v_teacher_id::TEXT, 'rejected_at', v_now_str)
  );

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'cardName', COALESCE(v_template.name, v_card_id),
    'instanceId', p_instance_id,
    'cardId', v_card_id
  );
END;
$$;


ALTER FUNCTION "public"."reject_vip_card"("p_student_id" "uuid", "p_instance_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reject_vip_card"("p_student_id" "uuid", "p_instance_id" "text") IS 'Teacher-only RPC to reject a student VIP card activation request.
Clears activationRequestedAt/By and activationApprovedAt/By fields.
Uses FOR UPDATE locking. Logs action=rejected to vip_cards_activity.';



CREATE OR REPLACE FUNCTION "public"."remove_student_vip_card"("p_student_id" "uuid", "p_card_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_is_teacher BOOLEAN;
  v_student_in_class BOOLEAN;
  v_vip_cards JSONB;
  v_instance_id TEXT;
  v_oldest_date TIMESTAMPTZ;
  v_oldest_instance_id TEXT;
BEGIN
  -- Get the current user's ID (the teacher calling this function)
  v_teacher_id := auth.uid();

  -- Check if caller is a teacher or admin
  v_is_teacher := is_teacher_or_admin();

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Unauthorized: Only teachers can remove VIP cards';
  END IF;

  -- Check if student is in one of the teacher's classes
  SELECT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
  ) INTO v_student_in_class;

  IF NOT v_student_in_class THEN
    RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
  END IF;

  -- Get student's VIP cards
  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id;

  -- If no cards, return FALSE
  IF v_vip_cards IS NULL OR v_vip_cards = '{}'::jsonb THEN
    RETURN FALSE;
  END IF;

  -- Find oldest unused instance of the specified card
  -- Loop through all card instances
  FOR v_instance_id IN
    SELECT key
    FROM jsonb_each(v_vip_cards)
  LOOP
    DECLARE
      v_card_data JSONB;
      v_card_id_check TEXT;
      v_used_at TEXT;
      v_earned_at TIMESTAMPTZ;
    BEGIN
      v_card_data := v_vip_cards->v_instance_id;
      v_card_id_check := v_card_data->>'cardId';
      v_used_at := v_card_data->>'usedAt';

      -- Check if this is the card we're looking for and it's unused
      IF v_card_id_check = p_card_id AND v_used_at IS NULL THEN
        v_earned_at := (v_card_data->>'earnedAt')::timestamptz;

        -- Track the oldest instance
        IF v_oldest_date IS NULL OR v_earned_at < v_oldest_date THEN
          v_oldest_date := v_earned_at;
          v_oldest_instance_id := v_instance_id;
        END IF;
      END IF;
    END;
  END LOOP;

  -- If we found an instance to remove, delete it from JSONB
  IF v_oldest_instance_id IS NOT NULL THEN
    -- Remove the instance from vip_cards JSONB
    v_vip_cards := v_vip_cards - v_oldest_instance_id;

    -- Update the database
    UPDATE profiles
    SET
      vip_cards = v_vip_cards,
      updated_at = NOW()
    WHERE id = p_student_id;

    RETURN TRUE;
  ELSE
    -- No matching card found
    RETURN FALSE;
  END IF;
END;
$$;


ALTER FUNCTION "public"."remove_student_vip_card"("p_student_id" "uuid", "p_card_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_student_vip_card"("p_student_id" "uuid", "p_card_id" "text") IS 'Removes one instance of a VIP card from a student (no gidouilles refund). Only teachers who have the student in their classes can call this. Returns TRUE if successful, FALSE if no card found.';



CREATE OR REPLACE FUNCTION "public"."remove_vip_card"("p_student_id" "uuid", "p_card_id" "text" DEFAULT NULL::"text", "p_instance_id" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_vip_cards JSONB;
  v_instance_id TEXT;
  v_card_data JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_oldest_instance_id TEXT;
  v_oldest_date TIMESTAMPTZ;
  v_loop_key TEXT;
  v_metadata JSONB;
BEGIN
  v_teacher_id := auth.uid();

  IF NOT is_teacher_or_admin() THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Only teachers can remove VIP cards'
    );
  END IF;

  -- Verify student is in one of the teacher's ACTIVE classes
  IF NOT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
      AND cm.status = 'active'
  ) THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Student is not in your active classes'
    );
  END IF;

  IF p_instance_id IS NULL AND p_card_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Either p_instance_id or p_card_id must be provided'
    );
  END IF;

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  IF p_instance_id IS NOT NULL THEN
    v_instance_id := p_instance_id;
  ELSE
    FOR v_loop_key IN
      SELECT key FROM jsonb_each(v_vip_cards)
    LOOP
      DECLARE
        v_loop_data JSONB;
        v_loop_card_id TEXT;
        v_loop_used_at TEXT;
        v_loop_earned_at TIMESTAMPTZ;
      BEGIN
        v_loop_data := v_vip_cards->v_loop_key;
        v_loop_card_id := v_loop_data->>'cardId';
        v_loop_used_at := v_loop_data->>'usedAt';

        IF v_loop_card_id = p_card_id AND v_loop_used_at IS NULL THEN
          v_loop_earned_at := (v_loop_data->>'earnedAt')::TIMESTAMPTZ;

          IF v_oldest_date IS NULL OR v_loop_earned_at < v_oldest_date THEN
            v_oldest_date := v_loop_earned_at;
            v_oldest_instance_id := v_loop_key;
          END IF;
        END IF;
      END;
    END LOOP;

    IF v_oldest_instance_id IS NULL THEN
      RETURN jsonb_build_object(
        'success', FALSE,
        'error', 'No unused instance found for card: ' || COALESCE(p_card_id, 'unknown')
      );
    END IF;

    v_instance_id := v_oldest_instance_id;
  END IF;

  v_card_data := v_vip_cards->v_instance_id;

  IF v_card_data IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card instance not found: ' || v_instance_id
    );
  END IF;

  IF v_card_data->>'usedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Cannot remove a card that has already been used'
    );
  END IF;

  v_card_id := v_card_data->>'cardId';

  SELECT id, name INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  v_vip_cards := v_vip_cards - v_instance_id;

  -- Build metadata with optional reason
  v_metadata := jsonb_build_object(
    'removed_by', v_teacher_id::TEXT,
    'removed_at', to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
  IF p_reason IS NOT NULL THEN
    v_metadata := v_metadata || jsonb_build_object('reason', p_reason);
  END IF;

  INSERT INTO public.vip_cards_activity (
    student_id, card_instance_id, card_template_id, action, metadata
  ) VALUES (
    p_student_id, v_instance_id, v_card_id, 'removed', v_metadata
  );

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'cardName', COALESCE(v_template.name, v_card_id),
    'instanceId', v_instance_id,
    'cardId', v_card_id
  );
END;
$$;


ALTER FUNCTION "public"."remove_vip_card"("p_student_id" "uuid", "p_card_id" "text", "p_instance_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[], "p_deletion_context" "jsonb" DEFAULT NULL::"jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_to_remove INTEGER;
    v_type TEXT;
    v_warning_id UUID;
    v_removed INTEGER := 0;
    v_counts JSON;
BEGIN
    -- Auth check: caller must be teacher of this class
    IF NOT is_class_teacher(p_class_id) THEN
        RETURN json_build_object('success', false, 'error', 'Unauthorized: you do not teach this class');
    END IF;

    -- Validate input array
    v_to_remove := COALESCE(array_length(p_warning_types, 1), 0);
    IF v_to_remove = 0 THEN
        RETURN json_build_object('success', false, 'error', 'No warning types provided');
    END IF;

    IF v_to_remove > 20 THEN
        RETURN json_build_object('success', false, 'error', 'Cannot remove more than 20 warnings at once');
    END IF;

    -- Validate each warning type
    FOREACH v_type IN ARRAY p_warning_types LOOP
        IF v_type NOT IN ('C', 'M', 'R', 'T') THEN
            RETURN json_build_object('success', false, 'error', 'Invalid warning type: ' || v_type);
        END IF;
    END LOOP;

    -- Serialize concurrent operations for the same student+class+period
    PERFORM pg_advisory_xact_lock(hashtext(p_student_id::text || p_class_id::text || p_academic_period_id::text));

    -- Soft-delete one warning per type entry (most recent first)
    FOREACH v_type IN ARRAY p_warning_types LOOP
        SELECT id INTO v_warning_id
        FROM student_warnings
        WHERE student_id = p_student_id
          AND class_id = p_class_id
          AND academic_period_id = p_academic_period_id
          AND warning_type = v_type
          AND deleted_at IS NULL
        ORDER BY created_at DESC
        LIMIT 1;

        IF v_warning_id IS NOT NULL THEN
            UPDATE student_warnings
            SET deleted_at = NOW(),
                deleted_by = auth.uid(),
                deletion_context = p_deletion_context
            WHERE id = v_warning_id;

            v_removed := v_removed + 1;
        END IF;
    END LOOP;

    -- Return updated counts
    SELECT json_build_object(
        'C', COALESCE(SUM(CASE WHEN warning_type = 'C' THEN 1 ELSE 0 END), 0),
        'M', COALESCE(SUM(CASE WHEN warning_type = 'M' THEN 1 ELSE 0 END), 0),
        'R', COALESCE(SUM(CASE WHEN warning_type = 'R' THEN 1 ELSE 0 END), 0),
        'T', COALESCE(SUM(CASE WHEN warning_type = 'T' THEN 1 ELSE 0 END), 0)
    ) INTO v_counts
    FROM student_warnings
    WHERE student_id = p_student_id
      AND class_id = p_class_id
      AND academic_period_id = p_academic_period_id
      AND deleted_at IS NULL;

    RETURN json_build_object('success', true, 'counts', v_counts, 'removed', v_removed);
END;
$$;


ALTER FUNCTION "public"."remove_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[], "p_deletion_context" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_warnings_bulk"("p_student_id" "uuid", "p_class_id" "uuid", "p_academic_period_id" "uuid", "p_warning_types" "text"[], "p_deletion_context" "jsonb") IS 'Atomically soft-delete multiple warnings (most recent per type) with optional deletion context, return updated counts';



CREATE OR REPLACE FUNCTION "public"."reorder_worksheet_exercises"("p_worksheet_id" "uuid", "p_exercises" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated_count INTEGER := 0;
  v_user_id UUID;
  v_is_authorized BOOLEAN;
BEGIN
  -- Get current user
  v_user_id := auth.uid();

  -- Check authorization: user must be worksheet owner or admin
  SELECT EXISTS (
    SELECT 1 FROM worksheets w
    LEFT JOIN profiles p ON p.id = v_user_id
    WHERE w.id = p_worksheet_id
    AND (w.created_by = v_user_id OR p.role = 'admin')
  ) INTO v_is_authorized;

  IF NOT v_is_authorized THEN
    RAISE EXCEPTION 'Not authorized to modify this worksheet';
  END IF;

  -- Check worksheet is in draft status
  IF NOT EXISTS (
    SELECT 1 FROM worksheets
    WHERE id = p_worksheet_id AND status = 'draft'
  ) THEN
    RAISE EXCEPTION 'Can only reorder exercises in draft worksheets';
  END IF;

  -- Use a temporary high offset to avoid unique constraint conflicts
  -- First pass: move all to temporary positions
  UPDATE worksheet_exercises we
  SET position = we.position + 10000
  FROM jsonb_to_recordset(p_exercises) AS x(id UUID, new_position INTEGER, new_section_id UUID)
  WHERE we.id = x.id
  AND we.worksheet_id = p_worksheet_id;

  -- Second pass: set final positions and section_ids
  UPDATE worksheet_exercises we
  SET
    position = x.new_position,
    section_id = x.new_section_id
  FROM jsonb_to_recordset(p_exercises) AS x(id UUID, new_position INTEGER, new_section_id UUID)
  WHERE we.id = x.id
  AND we.worksheet_id = p_worksheet_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  RETURN v_updated_count;
END;
$$;


ALTER FUNCTION "public"."reorder_worksheet_exercises"("p_worksheet_id" "uuid", "p_exercises" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reorder_worksheet_exercises"("p_worksheet_id" "uuid", "p_exercises" "jsonb") IS 'Atomically reorder worksheet exercises, avoiding unique constraint conflicts';



CREATE OR REPLACE FUNCTION "public"."reorder_worksheet_sections"("p_worksheet_id" "uuid", "p_sections" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated_count INTEGER := 0;
  v_user_id UUID;
  v_is_authorized BOOLEAN;
BEGIN
  -- Get current user
  v_user_id := auth.uid();

  -- Check authorization: user must be worksheet owner or admin
  SELECT EXISTS (
    SELECT 1 FROM worksheets w
    LEFT JOIN profiles p ON p.id = v_user_id
    WHERE w.id = p_worksheet_id
    AND (w.created_by = v_user_id OR p.role = 'admin')
  ) INTO v_is_authorized;

  IF NOT v_is_authorized THEN
    RAISE EXCEPTION 'Not authorized to modify this worksheet';
  END IF;

  -- Check worksheet is in draft status
  IF NOT EXISTS (
    SELECT 1 FROM worksheets
    WHERE id = p_worksheet_id AND status = 'draft'
  ) THEN
    RAISE EXCEPTION 'Can only reorder sections in draft worksheets';
  END IF;

  -- Use a temporary high offset to avoid unique constraint conflicts
  -- First pass: move all to temporary positions
  UPDATE worksheet_sections ws
  SET position = ws.position + 10000
  FROM jsonb_to_recordset(p_sections) AS x(id UUID, new_position INTEGER)
  WHERE ws.id = x.id
  AND ws.worksheet_id = p_worksheet_id;

  -- Second pass: set final positions
  UPDATE worksheet_sections ws
  SET position = x.new_position
  FROM jsonb_to_recordset(p_sections) AS x(id UUID, new_position INTEGER)
  WHERE ws.id = x.id
  AND ws.worksheet_id = p_worksheet_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  RETURN v_updated_count;
END;
$$;


