COMMENT ON FUNCTION "public"."reorder_worksheet_sections"("p_worksheet_id" "uuid", "p_sections" "jsonb") IS 'Atomically reorder worksheet sections, avoiding unique constraint conflicts';



CREATE OR REPLACE FUNCTION "public"."report_message"("p_message_id" "uuid", "p_reason" "text", "p_details" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_report_id UUID;
  v_user_id UUID := auth.uid();
BEGIN
  -- Validate reason
  IF p_reason NOT IN ('spam', 'harassment', 'inappropriate', 'other') THEN
    RAISE EXCEPTION 'Invalid reason. Must be: spam, harassment, inappropriate, or other';
  END IF;

  -- Check if user is a participant in the conversation
  IF NOT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Permission denied: not a participant';
  END IF;

  -- Check if user has already reported this message
  IF EXISTS (
    SELECT 1 FROM message_reports
    WHERE message_id = p_message_id
    AND reported_by = v_user_id
  ) THEN
    RAISE EXCEPTION 'You have already reported this message';
  END IF;

  -- Create the report
  INSERT INTO message_reports (
    message_id,
    reported_by,
    reason,
    details,
    status
  ) VALUES (
    p_message_id,
    v_user_id,
    p_reason,
    p_details,
    'pending'
  )
  RETURNING id INTO v_report_id;

  -- Mark message as reported
  UPDATE messages
  SET is_reported = true
  WHERE id = p_message_id;

  RETURN v_report_id;
END;
$$;


ALTER FUNCTION "public"."report_message"("p_message_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."report_message"("p_message_id" "uuid", "p_reason" "text", "p_details" "text") IS 'Report a message as inappropriate';



CREATE OR REPLACE FUNCTION "public"."request_vip_card_activation"("p_student_id" "uuid", "p_instance_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vip_cards JSONB;
  v_card_data JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_now_str TEXT;
BEGIN
  -- ========================================================================
  -- 1. VERIFY CALLER IS THE STUDENT
  -- ========================================================================

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Authentication required'
    );
  END IF;

  IF auth.uid() != p_student_id THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'You can only request activation for your own cards'
    );
  END IF;

  -- ========================================================================
  -- 2. LOCK AND FETCH STUDENT PROFILE
  -- ========================================================================

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Student profile not found'
    );
  END IF;

  v_vip_cards := COALESCE(v_vip_cards, '{}'::JSONB);

  -- ========================================================================
  -- 3. VALIDATE CARD INSTANCE
  -- ========================================================================

  v_card_data := v_vip_cards->p_instance_id;

  IF v_card_data IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'VIP card instance not found'
    );
  END IF;

  IF v_card_data->>'usedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'This card has already been used'
    );
  END IF;

  IF v_card_data->>'activationRequestedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Activation request already pending'
    );
  END IF;

  v_card_id := v_card_data->>'cardId';

  -- ========================================================================
  -- 4. VERIFY CARD HAS AN ACTION
  -- ========================================================================

  SELECT id, name, action INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card definition not found'
    );
  END IF;

  IF v_template.action IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'This card does not have an activatable action'
    );
  END IF;

  -- ========================================================================
  -- 5. UPDATE INSTANCE WITH ACTIVATION REQUEST
  -- ========================================================================

  v_now_str := to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  v_vip_cards := jsonb_set(
    v_vip_cards,
    ARRAY[p_instance_id],
    v_card_data || jsonb_build_object(
      'activationRequestedAt', v_now_str,
      'activationRequestedBy', p_student_id::TEXT
    )
  );

  -- ========================================================================
  -- 6. UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- 7. LOG AUDIT TRAIL
  -- ========================================================================

  INSERT INTO public.vip_cards_activity (
    student_id, card_instance_id, card_template_id, action, metadata
  ) VALUES (
    p_student_id,
    p_instance_id,
    v_card_id,
    'requested',
    jsonb_build_object(
      'requested_by', p_student_id::TEXT,
      'action_type', v_template.action->>'type'
    )
  );

  -- ========================================================================
  -- 8. RETURN SUCCESS
  -- ========================================================================

  RETURN jsonb_build_object(
    'success', TRUE,
    'cardName', v_template.name,
    'actionType', v_template.action->>'type'
  );
END;
$$;


ALTER FUNCTION "public"."request_vip_card_activation"("p_student_id" "uuid", "p_instance_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_vip_card_activation"("p_student_id" "uuid", "p_instance_id" "text") IS 'Atomically requests activation of a VIP card with an action.
Uses FOR UPDATE to prevent race conditions. Logs requested action to vip_cards_activity.';



CREATE OR REPLACE FUNCTION "public"."resolve_error"("p_error_log_id" "uuid", "p_resolved_by" "uuid", "p_notes" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_signature TEXT;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Only admins can resolve errors';
  END IF;

  UPDATE error_logs
  SET resolved = TRUE, resolved_by = p_resolved_by, resolved_at = NOW(), resolution_notes = p_notes
  WHERE id = p_error_log_id
  RETURNING error_signature INTO v_signature;

  IF v_signature IS NOT NULL THEN
    UPDATE error_occurrences SET is_resolved = TRUE WHERE error_signature = v_signature;
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."resolve_error"("p_error_log_id" "uuid", "p_resolved_by" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_error_by_signature"("p_error_signature" "text", "p_resolved_by" "uuid", "p_notes" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Only admins can resolve errors';
  END IF;

  WITH updated AS (
    UPDATE error_logs
    SET resolved = TRUE, resolved_by = p_resolved_by, resolved_at = NOW(), resolution_notes = p_notes
    WHERE error_signature = p_error_signature AND resolved = FALSE
    RETURNING id
  )
  SELECT COUNT(*) INTO v_count FROM updated;

  UPDATE error_occurrences SET is_resolved = TRUE WHERE error_signature = p_error_signature;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."resolve_error_by_signature"("p_error_signature" "text", "p_resolved_by" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_report"("p_report_id" "uuid", "p_new_status" "text", "p_review_notes" "text" DEFAULT NULL::"text", "p_delete_message" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_message_id UUID;
BEGIN
  -- Only teachers can review reports
  IF NOT is_teacher_or_admin() THEN
    RAISE EXCEPTION 'Permission denied: teachers only';
  END IF;

  -- Validate status
  IF p_new_status NOT IN ('reviewed', 'dismissed', 'actioned') THEN
    RAISE EXCEPTION 'Invalid status. Must be: reviewed, dismissed, or actioned';
  END IF;

  -- Get message_id
  SELECT message_id INTO v_message_id
  FROM message_reports
  WHERE id = p_report_id;

  -- Update report
  UPDATE message_reports
  SET
    status = p_new_status,
    reviewed_by = auth.uid(),
    reviewed_at = NOW(),
    review_notes = p_review_notes
  WHERE id = p_report_id;

  -- If delete_message flag is set, soft delete the message
  IF p_delete_message THEN
    UPDATE messages
    SET deleted_at = NOW()
    WHERE id = v_message_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."review_report"("p_report_id" "uuid", "p_new_status" "text", "p_review_notes" "text", "p_delete_message" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_report"("p_report_id" "uuid", "p_new_status" "text", "p_review_notes" "text", "p_delete_message" boolean) IS 'Teacher reviews and updates report status';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_cleanup_all"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_cache_deleted INTEGER := 0;
    v_notifications_deleted INTEGER := 0;
    v_rate_limits_deleted INTEGER := 0;
    v_total_deleted INTEGER := 0;
    v_cache_success BOOLEAN := false;
    v_notifications_success BOOLEAN := false;
    v_rate_limits_success BOOLEAN := false;
BEGIN
    v_run_id := start_job_run('cleanup_all', '{}'::jsonb);

    BEGIN
        -- ============================================================
        -- CLEANUP 1: Expired cache entries
        -- ============================================================
        BEGIN
            v_cache_deleted := cleanup_expired_cache();
            v_cache_success := true;
            RAISE NOTICE 'Cache cleanup: % entries deleted', v_cache_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Cache cleanup failed: %', SQLERRM;
            v_cache_success := false;
        END;

        -- ============================================================
        -- CLEANUP 2: Expired notifications (hard delete)
        -- ============================================================
        BEGIN
            DELETE FROM notifications
            WHERE expires_at < NOW();

            GET DIAGNOSTICS v_notifications_deleted = ROW_COUNT;
            v_notifications_success := true;
            RAISE NOTICE 'Notifications cleanup: % entries deleted', v_notifications_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Notifications cleanup failed: %', SQLERRM;
            v_notifications_success := false;
        END;

        -- ============================================================
        -- CLEANUP 3: Expired rate_limits entries
        -- ============================================================
        BEGIN
            DELETE FROM rate_limits
            WHERE expires_at < NOW();

            GET DIAGNOSTICS v_rate_limits_deleted = ROW_COUNT;
            v_rate_limits_success := true;
            RAISE NOTICE 'Rate limits cleanup: % entries deleted', v_rate_limits_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Rate limits cleanup failed: %', SQLERRM;
            v_rate_limits_success := false;
        END;

        -- ============================================================
        -- Complete job run with results
        -- ============================================================
        v_total_deleted := v_cache_deleted + v_notifications_deleted + v_rate_limits_deleted;

        PERFORM complete_job_run(
            v_run_id,
            CASE
                WHEN v_cache_success AND v_notifications_success AND v_rate_limits_success THEN 'success'
                WHEN v_cache_success OR v_notifications_success OR v_rate_limits_success THEN 'success'  -- Partial success = success
                ELSE 'failed'
            END,
            NULL,
            jsonb_build_object(
                'cache_deleted', v_cache_deleted,
                'notifications_deleted', v_notifications_deleted,
                'rate_limits_deleted', v_rate_limits_deleted,
                'total_deleted', v_total_deleted,
                'cache_success', v_cache_success,
                'notifications_success', v_notifications_success,
                'rate_limits_success', v_rate_limits_success
            )
        );

        RAISE NOTICE 'Cleanup complete: % total entries deleted (cache: %, notifications: %, rate_limits: %)',
            v_total_deleted, v_cache_deleted, v_notifications_deleted, v_rate_limits_deleted;

    EXCEPTION WHEN OTHERS THEN
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object(
                'cache_deleted', v_cache_deleted,
                'notifications_deleted', v_notifications_deleted,
                'rate_limits_deleted', v_rate_limits_deleted,
                'cache_success', v_cache_success,
                'notifications_success', v_notifications_success,
                'rate_limits_success', v_rate_limits_success
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_cleanup_all"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_cleanup_all"() IS 'pg_cron job that performs all scheduled cleanup tasks.
     Runs daily at 02:00 UTC.
     Cleans up: expired cache entries, expired notifications, expired rate_limits entries.';



CREATE OR REPLACE FUNCTION "public"."run_cleanup_expired_data"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_error_logs_deleted INTEGER := 0;
    v_presence_deleted INTEGER := 0;
    v_friendships_deleted INTEGER := 0;
    v_messages_deleted INTEGER := 0;
    v_private_messages_deleted INTEGER := 0;
    v_audit_logs_deleted INTEGER := 0;
    v_error_occurrences_deleted INTEGER := 0;
    v_background_jobs_deleted INTEGER := 0;
    v_total_deleted INTEGER := 0;
    v_error_logs_success BOOLEAN := false;
    v_presence_success BOOLEAN := false;
    v_friendships_success BOOLEAN := false;
    v_messages_success BOOLEAN := false;
    v_private_messages_success BOOLEAN := false;
    v_audit_logs_success BOOLEAN := false;
    v_error_occurrences_success BOOLEAN := false;
    v_background_jobs_success BOOLEAN := false;
BEGIN
    -- Start job run tracking
    v_run_id := start_job_run('retention_cleanup', jsonb_build_object(
        'retention_periods', jsonb_build_object(
            'error_logs_days', 30,
            'audit_logs_days', 60,
            'error_occurrences_days', 30,
            'background_job_runs_days', 7,
            'presence_days', 30,
            'friendships_years', 2,
            'messages_years', 3,
            'private_messages_years', 3
        )
    ));

    BEGIN
        -- ============================================================
        -- CLEANUP 1: Error logs (30 days, ALL — resolved or not)
        -- ============================================================
        BEGIN
            DELETE FROM error_logs
            WHERE created_at < NOW() - INTERVAL '30 days';
            GET DIAGNOSTICS v_error_logs_deleted = ROW_COUNT;
            v_error_logs_success := true;
            RAISE NOTICE 'Error logs cleanup: % entries deleted', v_error_logs_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Error logs cleanup failed: %', SQLERRM;
            v_error_logs_success := false;
        END;

        -- ============================================================
        -- CLEANUP 2: User presence (30 days)
        -- ============================================================
        BEGIN
            DELETE FROM user_presence
            WHERE updated_at < NOW() - INTERVAL '30 days';
            GET DIAGNOSTICS v_presence_deleted = ROW_COUNT;
            v_presence_success := true;
            RAISE NOTICE 'User presence cleanup: % entries deleted', v_presence_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'User presence cleanup failed: %', SQLERRM;
            v_presence_success := false;
        END;

        -- ============================================================
        -- CLEANUP 3: Rejected friendships (2 years)
        -- ============================================================
        BEGIN
            DELETE FROM friendships
            WHERE status = 'rejected'
              AND updated_at < NOW() - INTERVAL '2 years';
            GET DIAGNOSTICS v_friendships_deleted = ROW_COUNT;
            v_friendships_success := true;
            RAISE NOTICE 'Friendships cleanup: % entries deleted', v_friendships_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Friendships cleanup failed: %', SQLERRM;
            v_friendships_success := false;
        END;

        -- ============================================================
        -- CLEANUP 4: Chat messages (3 years) - HARD DELETE
        -- Per RGPD Art. 17, must be hard delete, not soft delete
        -- ============================================================
        BEGIN
            DELETE FROM messages
            WHERE created_at < NOW() - INTERVAL '3 years';
            GET DIAGNOSTICS v_messages_deleted = ROW_COUNT;
            v_messages_success := true;
            RAISE NOTICE 'Messages cleanup (HARD DELETE): % entries deleted', v_messages_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Messages cleanup failed: %', SQLERRM;
            v_messages_success := false;
        END;

        -- ============================================================
        -- CLEANUP 5: Private messages (3 years) - HARD DELETE
        -- Cascades to message_inbox and message_attachments_v2
        -- ============================================================
        BEGIN
            DELETE FROM private_messages
            WHERE sent_at < NOW() - INTERVAL '3 years';
            GET DIAGNOSTICS v_private_messages_deleted = ROW_COUNT;
            v_private_messages_success := true;
            RAISE NOTICE 'Private messages cleanup (HARD DELETE): % entries deleted', v_private_messages_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Private messages cleanup failed: %', SQLERRM;
            v_private_messages_success := false;
        END;

        -- ============================================================
        -- CLEANUP 6: Audit logs (60 days)
        -- TOAST-heavy table (JSONB before/after snapshots).
        -- ============================================================
        BEGIN
            DELETE FROM audit_logs
            WHERE created_at < NOW() - INTERVAL '60 days';
            GET DIAGNOSTICS v_audit_logs_deleted = ROW_COUNT;
            v_audit_logs_success := true;
            RAISE NOTICE 'Audit logs cleanup: % entries deleted', v_audit_logs_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Audit logs cleanup failed: %', SQLERRM;
            v_audit_logs_success := false;
        END;

        -- ============================================================
        -- CLEANUP 7: Error occurrences (30 days)
        -- ============================================================
        BEGIN
            DELETE FROM error_occurrences
            WHERE last_seen < NOW() - INTERVAL '30 days';
            GET DIAGNOSTICS v_error_occurrences_deleted = ROW_COUNT;
            v_error_occurrences_success := true;
            RAISE NOTICE 'Error occurrences cleanup: % entries deleted', v_error_occurrences_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Error occurrences cleanup failed: %', SQLERRM;
            v_error_occurrences_success := false;
        END;

        -- ============================================================
        -- CLEANUP 8: Background job runs (7 days)
        -- ============================================================
        BEGIN
            DELETE FROM background_job_runs
            WHERE started_at < NOW() - INTERVAL '7 days';
            GET DIAGNOSTICS v_background_jobs_deleted = ROW_COUNT;
            v_background_jobs_success := true;
            RAISE NOTICE 'Background job runs cleanup: % entries deleted', v_background_jobs_deleted;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Background job runs cleanup failed: %', SQLERRM;
            v_background_jobs_success := false;
        END;

        -- ============================================================
        -- Complete job run with results
        -- ============================================================
        v_total_deleted := COALESCE(v_error_logs_deleted, 0) +
                           COALESCE(v_presence_deleted, 0) +
                           COALESCE(v_friendships_deleted, 0) +
                           COALESCE(v_messages_deleted, 0) +
                           COALESCE(v_private_messages_deleted, 0) +
                           COALESCE(v_audit_logs_deleted, 0) +
                           COALESCE(v_error_occurrences_deleted, 0) +
                           COALESCE(v_background_jobs_deleted, 0);

        PERFORM complete_job_run(
            v_run_id,
            CASE
                WHEN v_error_logs_success AND v_presence_success AND v_friendships_success
                     AND v_messages_success AND v_private_messages_success
                     AND v_audit_logs_success AND v_error_occurrences_success
                     AND v_background_jobs_success
                THEN 'success'
                WHEN v_error_logs_success OR v_presence_success OR v_friendships_success
                     OR v_messages_success OR v_private_messages_success
                     OR v_audit_logs_success OR v_error_occurrences_success
                     OR v_background_jobs_success
                THEN 'success'  -- Partial success = success for monitoring
                ELSE 'failed'
            END,
            NULL,
            jsonb_build_object(
                'error_logs_deleted', COALESCE(v_error_logs_deleted, 0),
                'error_logs_success', v_error_logs_success,
                'presence_deleted', COALESCE(v_presence_deleted, 0),
                'presence_success', v_presence_success,
                'friendships_deleted', COALESCE(v_friendships_deleted, 0),
                'friendships_success', v_friendships_success,
                'messages_deleted', COALESCE(v_messages_deleted, 0),
                'messages_success', v_messages_success,
                'private_messages_deleted', COALESCE(v_private_messages_deleted, 0),
                'private_messages_success', v_private_messages_success,
                'audit_logs_deleted', COALESCE(v_audit_logs_deleted, 0),
                'audit_logs_success', v_audit_logs_success,
                'error_occurrences_deleted', COALESCE(v_error_occurrences_deleted, 0),
                'error_occurrences_success', v_error_occurrences_success,
                'background_jobs_deleted', COALESCE(v_background_jobs_deleted, 0),
                'background_jobs_success', v_background_jobs_success,
                'total_deleted', v_total_deleted,
                'rgpd_compliance', 'Art. 5(1)(e) - Storage limitation'
            )
        );

        RAISE NOTICE 'RGPD Retention cleanup complete: % total entries deleted', v_total_deleted;
        RAISE NOTICE '  - Error logs: %, Presence: %, Friendships: %',
            v_error_logs_deleted, v_presence_deleted, v_friendships_deleted;
        RAISE NOTICE '  - Messages: %, Private messages: %',
            v_messages_deleted, v_private_messages_deleted;
        RAISE NOTICE '  - Audit logs: %, Error occurrences: %, Background jobs: %',
            v_audit_logs_deleted, v_error_occurrences_deleted, v_background_jobs_deleted;

    EXCEPTION WHEN OTHERS THEN
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object(
                'error_logs_deleted', COALESCE(v_error_logs_deleted, 0),
                'presence_deleted', COALESCE(v_presence_deleted, 0),
                'friendships_deleted', COALESCE(v_friendships_deleted, 0),
                'messages_deleted', COALESCE(v_messages_deleted, 0),
                'private_messages_deleted', COALESCE(v_private_messages_deleted, 0),
                'audit_logs_deleted', COALESCE(v_audit_logs_deleted, 0),
                'error_occurrences_deleted', COALESCE(v_error_occurrences_deleted, 0),
                'background_jobs_deleted', COALESCE(v_background_jobs_deleted, 0),
                'error_logs_success', v_error_logs_success,
                'presence_success', v_presence_success,
                'friendships_success', v_friendships_success,
                'messages_success', v_messages_success,
                'private_messages_success', v_private_messages_success,
                'audit_logs_success', v_audit_logs_success,
                'error_occurrences_success', v_error_occurrences_success,
                'background_jobs_success', v_background_jobs_success
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_cleanup_expired_data"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_cleanup_expired_data"() IS 'pg_cron job for RGPD Article 5(1)(e) compliant data retention cleanup.
     Runs weekly (Sunday 03:00 UTC).
     Cleans up: error_logs (90d), user_presence (30d), friendships (2y rejected),
     messages (3y), private_messages (3y), student_attempts (5y+inactive),
     student_progress (5y+inactive).
     Tracks all deletions in background_job_runs for compliance audit.';



CREATE OR REPLACE FUNCTION "public"."run_daily_summaries"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_school RECORD;
    v_class RECORD;
    v_summary RECORD;
    v_current_hour INTEGER;
    v_yesterday DATE;
    v_day_of_week INTEGER;
    v_day_start TIMESTAMPTZ;
    v_day_end TIMESTAMPTZ;
    v_has_schedule BOOLEAN;
    v_processed_schools INTEGER := 0;
    v_skipped_schools INTEGER := 0;
    v_processed_classes INTEGER := 0;
    v_total_summaries INTEGER := 0;
    v_class_summaries INTEGER;
BEGIN
    -- Start job run tracking
    v_run_id := start_job_run('daily_summaries', '{}'::jsonb);

    BEGIN
        -- Process each school with distinct timezone
        FOR v_school IN
            SELECT DISTINCT ON (s.id)
                s.id,
                s.name,
                s.timezone
            FROM schools s
            WHERE s.timezone IS NOT NULL
        LOOP
            -- Get current hour in school's timezone
            v_current_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE v_school.timezone)::INTEGER;

            -- Only process if it's 18:00 local time
            IF v_current_hour != 18 THEN
                v_skipped_schools := v_skipped_schools + 1;
                CONTINUE;
            END IF;

            v_processed_schools := v_processed_schools + 1;

            -- Calculate yesterday in school's timezone
            v_yesterday := ((NOW() AT TIME ZONE v_school.timezone) - INTERVAL '1 day')::DATE;
            v_day_of_week := EXTRACT(DOW FROM v_yesterday)::INTEGER;

            -- Calculate day boundaries for yesterday (timezone-aware)
            v_day_start := (v_yesterday::TIMESTAMP AT TIME ZONE v_school.timezone);
            v_day_end := ((v_yesterday + 1)::TIMESTAMP AT TIME ZONE v_school.timezone) - INTERVAL '1 microsecond';

            -- Process each active class in this school
            FOR v_class IN
                SELECT c.id, c.name
                FROM classes c
                WHERE c.school_id = v_school.id
                  AND c.is_active = true
            LOOP
                -- Check if class had a scheduled lesson yesterday
                SELECT EXISTS (
                    SELECT 1 FROM class_schedules cs
                    WHERE cs.class_id = v_class.id
                      AND cs.day_of_week = v_day_of_week
                ) INTO v_has_schedule;

                IF NOT v_has_schedule THEN
                    CONTINUE;
                END IF;

                v_class_summaries := 0;

                -- ============================================================
                -- OPTIMIZED AGGREGATION: 5 queries per class (not per student)
                -- ============================================================
                FOR v_summary IN
                    WITH students AS (
                        SELECT cm.student_id
                        FROM class_members cm
                        WHERE cm.class_id = v_class.id
                          AND cm.status = 'active'
                          AND cm.is_test = false
                    ),
                    gidouilles_agg AS (
                        SELECT
                            ga.student_id,
                            COALESCE(SUM(CASE WHEN ga.delta > 0 THEN ga.delta ELSE 0 END), 0)::INTEGER as gained,
                            COALESCE(SUM(CASE WHEN ga.delta < 0 THEN ABS(ga.delta) ELSE 0 END), 0)::INTEGER as lost
                        FROM gidouilles_activity ga
                        WHERE ga.class_id = v_class.id
                          AND ga.created_at >= v_day_start
                          AND ga.created_at <= v_day_end
                        GROUP BY ga.student_id
                    ),
                    bonus_agg AS (
                        SELECT
                            bh.student_id,
                            COALESCE(SUM(CASE WHEN bh.delta > 0 THEN bh.delta ELSE 0 END), 0)::INTEGER as gained,
                            COALESCE(SUM(CASE WHEN bh.delta < 0 THEN ABS(bh.delta) ELSE 0 END), 0)::INTEGER as lost
                        FROM bonus_history bh
                        WHERE bh.class_id = v_class.id
                          AND bh.created_at >= v_day_start
                          AND bh.created_at <= v_day_end
                        GROUP BY bh.student_id
                    ),
                    vip_agg AS (
                        SELECT
                            vca.student_id,
                            COUNT(*) FILTER (WHERE vca.action = 'gained')::INTEGER as gained,
                            COUNT(*) FILTER (WHERE vca.action = 'used')::INTEGER as used
                        FROM vip_cards_activity vca
                        WHERE vca.created_at >= v_day_start
                          AND vca.created_at <= v_day_end
                        GROUP BY vca.student_id
                    ),
                    warnings_issued_agg AS (
                        SELECT
                            sw.student_id,
                            COUNT(*)::INTEGER as issued
                        FROM student_warnings sw
                        WHERE sw.class_id = v_class.id
                          AND sw.created_at >= v_day_start
                          AND sw.created_at <= v_day_end
                        GROUP BY sw.student_id
                    ),
                    warnings_removed_agg AS (
                        SELECT
                            sw.student_id,
                            COUNT(*)::INTEGER as removed
                        FROM student_warnings sw
                        WHERE sw.class_id = v_class.id
                          AND sw.deleted_at IS NOT NULL
                          AND sw.created_at < v_day_start
                          AND sw.deleted_at >= v_day_start
                          AND sw.deleted_at <= v_day_end
                        GROUP BY sw.student_id
                    )
                    SELECT
                        s.student_id,
                        COALESCE(g.gained, 0) as gidouilles_gained,
                        COALESCE(g.lost, 0) as gidouilles_lost,
                        COALESCE(b.gained, 0) as bonus_gained,
                        COALESCE(b.lost, 0) as bonus_used,
                        COALESCE(v.gained, 0) as vip_cards_gained,
                        COALESCE(v.used, 0) as vip_cards_used,
                        COALESCE(wi.issued, 0) as warnings_issued,
                        COALESCE(wr.removed, 0) as warnings_removed
                    FROM students s
                    LEFT JOIN gidouilles_agg g ON g.student_id = s.student_id
                    LEFT JOIN bonus_agg b ON b.student_id = s.student_id
                    LEFT JOIN vip_agg v ON v.student_id = s.student_id
                    LEFT JOIN warnings_issued_agg wi ON wi.student_id = s.student_id
                    LEFT JOIN warnings_removed_agg wr ON wr.student_id = s.student_id
                    -- Only include students with at least one change
                    WHERE COALESCE(g.gained, 0) > 0
                       OR COALESCE(g.lost, 0) > 0
                       OR COALESCE(b.gained, 0) > 0
                       OR COALESCE(b.lost, 0) > 0
                       OR COALESCE(v.gained, 0) > 0
                       OR COALESCE(v.used, 0) > 0
                       OR COALESCE(wi.issued, 0) > 0
                       OR COALESCE(wr.removed, 0) > 0
                LOOP
                    -- Insert into daily_summaries
                    INSERT INTO daily_summaries (
                        student_id,
                        class_id,
                        summary_date,
                        gidouilles_gained,
                        gidouilles_lost,
                        bonus_gained,
                        bonus_used,
                        warnings_issued,
                        warnings_removed,
                        vip_cards_gained,
                        vip_cards_used
                    ) VALUES (
                        v_summary.student_id,
                        v_class.id,
                        v_yesterday,
                        v_summary.gidouilles_gained,
                        v_summary.gidouilles_lost,
                        v_summary.bonus_gained,
                        v_summary.bonus_used,
                        v_summary.warnings_issued,
                        v_summary.warnings_removed,
                        v_summary.vip_cards_gained,
                        v_summary.vip_cards_used
                    );

                    -- Create notification with raw metadata (client formats at display)
                    INSERT INTO notifications (
                        title,
                        message,
                        type,
                        is_system,
                        system_event_type,
                        target_type,
                        target_user_ids,
                        metadata
                    ) VALUES (
                        '📊 Bilan quotidien',
                        NULL,  -- Client will format from metadata
                        'info',
                        true,
                        'daily_summary',
                        'users',
                        ARRAY[v_summary.student_id],
                        jsonb_build_object(
                            'class_name', v_class.name,
                            'summary_date', v_yesterday,
                            'gidouilles_gained', v_summary.gidouilles_gained,
                            'gidouilles_lost', v_summary.gidouilles_lost,
                            'bonus_gained', v_summary.bonus_gained,
                            'bonus_used', v_summary.bonus_used,
                            'warnings_issued', v_summary.warnings_issued,
                            'warnings_removed', v_summary.warnings_removed,
                            'vip_cards_gained', v_summary.vip_cards_gained,
                            'vip_cards_used', v_summary.vip_cards_used
                        )
                    );

                    v_class_summaries := v_class_summaries + 1;
                END LOOP;

                IF v_class_summaries > 0 THEN
                    v_processed_classes := v_processed_classes + 1;
                    v_total_summaries := v_total_summaries + v_class_summaries;
                    RAISE NOTICE 'Class %: generated % summaries', v_class.name, v_class_summaries;
                END IF;
            END LOOP;
        END LOOP;

        -- Complete job run with success
        PERFORM complete_job_run(
            v_run_id,
            'success',
            NULL,
            jsonb_build_object(
                'schools_processed', v_processed_schools,
                'schools_skipped', v_skipped_schools,
                'classes_processed', v_processed_classes,
                'total_summaries', v_total_summaries
            )
        );

        RAISE NOTICE 'Daily summaries complete: % schools processed, % skipped, % classes, % summaries',
            v_processed_schools, v_skipped_schools, v_processed_classes, v_total_summaries;

    EXCEPTION WHEN OTHERS THEN
        -- Complete job run with failure
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object(
                'schools_processed', v_processed_schools,
                'schools_skipped', v_skipped_schools,
                'classes_processed', v_processed_classes,
                'total_summaries', v_total_summaries
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_daily_summaries"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_daily_summaries"() IS 'pg_cron job that generates daily activity summaries for students.
     Runs every hour, processes each school when it''s 18:00 local time.
     Aggregates data from gidouilles_activity, bonus_history, vip_cards_activity,
     and student_warnings. Creates notifications with raw metadata for client-side formatting.';



CREATE OR REPLACE FUNCTION "public"."run_recalculate_minesweeper_ref_times"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_results RECORD;
    v_updated_count INTEGER := 0;
    v_skipped_count INTEGER := 0;
    v_total_samples INTEGER := 0;
BEGIN
    -- Start job run tracking
    v_run_id := start_job_run('recalculate_minesweeper_ref_times', '{}'::jsonb);

    BEGIN
        -- Call the existing recalculation function and aggregate results
        FOR v_results IN SELECT * FROM recalculate_minesweeper_reference_times()
        LOOP
            IF v_results.updated THEN
                v_updated_count := v_updated_count + 1;
            ELSE
                v_skipped_count := v_skipped_count + 1;
            END IF;
            v_total_samples := v_total_samples + v_results.sample_count;
        END LOOP;

        -- Complete job run with success
        PERFORM complete_job_run(
            v_run_id,
            'success',
            NULL,
            jsonb_build_object(
                'updated_count', v_updated_count,
                'skipped_count', v_skipped_count,
                'total_samples', v_total_samples,
                'combinations_processed', v_updated_count + v_skipped_count
            )
        );

    EXCEPTION WHEN OTHERS THEN
        -- Complete job run with failure
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object(
                'updated_count', v_updated_count,
                'skipped_count', v_skipped_count
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_recalculate_minesweeper_ref_times"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_recalculate_minesweeper_ref_times"() IS 'pg_cron wrapper for recalculate_minesweeper_reference_times() with monitoring.
     Runs every Sunday at 01:30 UTC.';



CREATE OR REPLACE FUNCTION "public"."run_weekly_best_bonuses"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_school RECORD;
    v_processed_count INTEGER := 0;
    v_skipped_count INTEGER := 0;
    v_total_bonuses INTEGER := 0;
    v_school_bonuses INTEGER;
    v_current_day INTEGER;
    v_current_hour INTEGER;
    v_rewards_day INTEGER;
    v_first_day INTEGER;
    v_last_day INTEGER;
    v_today DATE;
    v_current_week_start DATE;
    v_current_week_end DATE;
    v_days_to_week_start INTEGER;
BEGIN
    -- Start job run tracking
    v_run_id := start_job_run('weekly_best_bonuses', '{}'::jsonb);

    BEGIN
        -- Process each school with distinct timezone/week_config
        FOR v_school IN
            SELECT DISTINCT ON (s.id)
                s.id,
                s.name,
                s.timezone,
                COALESCE((s.timetable->'week_config'->>'first_day')::INTEGER, 0) as first_day,
                COALESCE((s.timetable->'week_config'->>'last_day')::INTEGER, 6) as last_day
            FROM schools s
            WHERE s.timezone IS NOT NULL
        LOOP
            v_first_day := v_school.first_day;
            v_last_day := v_school.last_day;

            -- Calculate rewards day (6th day of week = first day of weekend)
            v_rewards_day := (v_first_day + 5) % 7;

            -- Get current day and hour in school's timezone
            v_current_day := EXTRACT(DOW FROM NOW() AT TIME ZONE v_school.timezone)::INTEGER;
            v_current_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE v_school.timezone)::INTEGER;

            -- Check if it's rewards day AND afternoon
            IF v_current_day = v_rewards_day AND v_current_hour >= 12 THEN
                -- Calculate today's date in school's timezone
                v_today := (NOW() AT TIME ZONE v_school.timezone)::DATE;

                -- Calculate days since current week started
                v_days_to_week_start := (v_current_day - v_first_day + 7) % 7;

                -- Current week boundaries
                v_current_week_start := v_today - v_days_to_week_start;
                v_current_week_end := v_current_week_start + 6;

                -- FIX: Award bonuses for the CURRENT week (not previous)
                -- The rewards_day is near the end of the school week,
                -- so the current week is the one we want to award.
                SELECT award_weekly_best_bonuses(v_current_week_start, v_current_week_end)
                INTO v_school_bonuses;

                v_total_bonuses := v_total_bonuses + COALESCE(v_school_bonuses, 0);
                v_processed_count := v_processed_count + 1;

                RAISE NOTICE 'School %: awarded % bonuses for week % to %',
                    v_school.name, v_school_bonuses, v_current_week_start, v_current_week_end;
            ELSE
                v_skipped_count := v_skipped_count + 1;
            END IF;
        END LOOP;

        -- Complete job run with success
        PERFORM complete_job_run(
            v_run_id,
            'success',
            NULL,
            jsonb_build_object(
                'schools_processed', v_processed_count,
                'schools_skipped', v_skipped_count,
                'total_bonuses_awarded', v_total_bonuses
            )
        );

        RAISE NOTICE 'Weekly best bonuses complete: % schools processed, % skipped, % bonuses awarded',
            v_processed_count, v_skipped_count, v_total_bonuses;

    EXCEPTION WHEN OTHERS THEN
        -- Complete job run with failure
        PERFORM complete_job_run(
            v_run_id,
            'failed',
            SQLERRM,
            jsonb_build_object(
                'schools_processed', v_processed_count,
                'schools_skipped', v_skipped_count,
                'total_bonuses_awarded', v_total_bonuses
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_weekly_best_bonuses"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_weekly_best_bonuses"() IS 'pg_cron job that awards weekly best game bonuses. Runs 2x/day, processes each school
     when it''s their rewards day (6th day = first_day + 5) AND afternoon (hour >= 12) locally.
     Awards bonuses for the current week (rewards day falls near end of school week).';



CREATE OR REPLACE FUNCTION "public"."run_weekly_rewards"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_run_id UUID;
    v_class RECORD;
    v_member RECORD;
    v_processed_classes INTEGER := 0;
    v_skipped_classes INTEGER := 0;
    v_total_rewards INTEGER := 0;
    v_class_rewards INTEGER;
    v_current_day INTEGER;
    v_current_hour INTEGER;
    v_rewards_day INTEGER;
    v_first_day INTEGER;
    v_today DATE;
    v_current_week_start DATE;
    v_days_since_week_start INTEGER;
    v_timezone TEXT;
    v_has_warning_action BOOLEAN;
    v_week_start_ts TIMESTAMPTZ;
    v_class_name TEXT;
BEGIN
    v_run_id := start_job_run('weekly_rewards', '{}'::jsonb);

    BEGIN
        FOR v_class IN
            SELECT
                c.id as class_id,
                c.name as class_name,
                c.school_id,
                s.timezone,
                COALESCE((s.timetable->'week_config'->>'first_day')::INTEGER, 1) as first_day
            FROM classes c
            JOIN schools s ON c.school_id = s.id
            WHERE c.is_active = true
              AND s.timezone IS NOT NULL
        LOOP
            v_timezone := v_class.timezone;
            v_first_day := v_class.first_day;
            v_class_name := v_class.class_name;

            v_rewards_day := (v_first_day + 5) % 7;
            v_current_day := EXTRACT(DOW FROM NOW() AT TIME ZONE v_timezone)::INTEGER;
            v_current_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE v_timezone)::INTEGER;

            IF v_current_day = v_rewards_day AND v_current_hour >= 12 THEN
                v_today := (NOW() AT TIME ZONE v_timezone)::DATE;
                v_days_since_week_start := (v_current_day - v_first_day + 7) % 7;
                v_current_week_start := v_today - v_days_since_week_start;
                v_week_start_ts := (v_current_week_start::TIMESTAMP AT TIME ZONE v_timezone);
                v_class_rewards := 0;

                FOR v_member IN
                    SELECT cm.student_id
                    FROM class_members cm
                    WHERE cm.class_id = v_class.class_id
                      AND cm.status = 'active'
                LOOP
                    SELECT EXISTS (
                        SELECT 1 FROM student_warnings sw
                        WHERE sw.student_id = v_member.student_id
                          AND sw.class_id = v_class.class_id
                          AND sw.deleted_at IS NULL
                          AND sw.created_at >= v_week_start_ts
                        UNION ALL
                        SELECT 1 FROM gidouilles_activity ga
                        WHERE ga.student_id = v_member.student_id
                          AND ga.class_id = v_class.class_id
                          AND ga.reason = 'Retiré suite à un avertissement'
                          AND ga.created_at >= v_week_start_ts
                        UNION ALL
                        SELECT 1 FROM vip_cards_activity va
                        WHERE va.student_id = v_member.student_id
                          AND va.action = 'removed'
                          AND va.metadata->>'reason' = 'warning'
                          AND va.created_at >= v_week_start_ts
                    ) INTO v_has_warning_action;

                    IF NOT v_has_warning_action THEN
                        PERFORM update_student_gidouilles(
                            v_member.student_id,
                            v_class.class_id,
                            1,
                            'weekly_no_warning',
                            NULL
                        );

                        INSERT INTO weekly_rewards (
                            student_id, class_id, week_start, week_end, gidouilles_awarded
                        ) VALUES (
                            v_member.student_id, v_class.class_id,
                            v_current_week_start, v_today, 1
                        );

                        INSERT INTO notifications (
                            title, message, type, is_system,
                            system_event_type, target_type, target_user_ids
                        ) VALUES (
                            'Recompense hebdomadaire',
                            format(
                                E'Recompense hebdomadaire - %s\n\n' ||
                                E'Bravo ! Tu as recu 1 gidouille pour avoir passe la semaine ' ||
                                E'du %s au %s sans avertissement.\n\n' ||
                                E'Continue comme ca !',
                                v_class_name,
                                TO_CHAR(v_current_week_start, 'DD/MM/YYYY'),
                                TO_CHAR(v_today, 'DD/MM/YYYY')
                            ),
                            'info',
                            true,
                            'weekly_reward',
                            'users',
                            ARRAY[v_member.student_id]
                        );

                        v_class_rewards := v_class_rewards + 1;
                    END IF;
                END LOOP;

                v_total_rewards := v_total_rewards + v_class_rewards;
                v_processed_classes := v_processed_classes + 1;

                RAISE NOTICE 'Class %: awarded % weekly rewards', v_class_name, v_class_rewards;
            ELSE
                v_skipped_classes := v_skipped_classes + 1;
            END IF;
        END LOOP;

        PERFORM complete_job_run(
            v_run_id, 'success', NULL,
            jsonb_build_object(
                'classes_processed', v_processed_classes,
                'classes_skipped', v_skipped_classes,
                'total_rewards_awarded', v_total_rewards
            )
        );

    EXCEPTION WHEN OTHERS THEN
        PERFORM complete_job_run(
            v_run_id, 'failed', SQLERRM,
            jsonb_build_object(
                'classes_processed', v_processed_classes,
                'classes_skipped', v_skipped_classes,
                'total_rewards_awarded', v_total_rewards
            )
        );
        RAISE;
    END;
END;
$$;


ALTER FUNCTION "public"."run_weekly_rewards"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_weekly_rewards"() IS 'pg_cron job that awards 1 gidouille to students with no warning actions during the week.
     Checks all 3 warning button steps: student_warnings (step 3),
     gidouilles_activity with reason "Retiré suite à un avertissement" (step 1),
     and vip_cards_activity with action "removed" and metadata.reason "warning" (step 2).
     Runs 2x/day, processes each class when it''s their rewards day (6th day = first_day + 5)
     AND afternoon (hour >= 12) locally.';



