CREATE OR REPLACE FUNCTION "public"."save_template_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  next_version INT;
BEGIN
  -- Get next version number
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO next_version
  FROM message_template_versions
  WHERE template_id = OLD.id;

  -- Save old version
  INSERT INTO message_template_versions (
    template_id, version_number, title, description,
    subject_template, body_template, trigger_type, scope,
    variables, tags, modified_by, change_summary
  ) VALUES (
    OLD.id, next_version, OLD.title, OLD.description,
    OLD.subject_template, OLD.body_template, OLD.trigger_type, OLD.scope,
    OLD.variables, OLD.tags, NEW.created_by,
    CASE
      WHEN NEW.title != OLD.title THEN 'Titre modifié'
      WHEN NEW.subject_template != OLD.subject_template THEN 'Sujet modifié'
      WHEN NEW.body_template != OLD.body_template THEN 'Corps modifié'
      ELSE 'Template modifié'
    END
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."save_template_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_private_messages"("p_user_id" "uuid", "p_query" "text", "p_search_in" "text" DEFAULT 'all'::"text", "p_has_attachments" boolean DEFAULT NULL::boolean, "p_sender_name" "text" DEFAULT NULL::"text", "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("message_id" "uuid", "sender_id" "uuid", "sender_name" "text", "subject" "text", "plain_text" "text", "sent_at" timestamp with time zone, "is_starred" boolean, "has_attachments" boolean, "rank" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tsquery TSQUERY;
BEGIN
  -- Convert search query to tsquery
  v_tsquery := plainto_tsquery('french', p_query);

  RETURN QUERY
  SELECT
    msi.message_id,
    pm.sender_id,
    msi.sender_name,
    pm.subject,
    substring(pm.plain_text, 1, 200) AS plain_text,
    msi.sent_at,
    COALESCE(mi.is_starred, FALSE) AS is_starred,
    msi.has_attachments,
    ts_rank(msi.search_tsv, v_tsquery) AS rank
  FROM message_search_index msi
  JOIN private_messages pm ON pm.id = msi.message_id
  LEFT JOIN message_inbox mi ON mi.message_id = msi.message_id AND mi.recipient_id = p_user_id
  WHERE
    -- Full-text search match
    msi.search_tsv @@ v_tsquery

    -- User has access
    AND (
      pm.sender_id = p_user_id
      OR (mi.recipient_id = p_user_id AND mi.deleted = FALSE)
    )

    -- Search scope filter
    AND (
      (p_search_in = 'all')
      OR (p_search_in = 'inbox' AND mi.recipient_id = p_user_id)
      OR (p_search_in = 'sent' AND pm.sender_id = p_user_id)
    )

    -- Optional filters
    AND (p_has_attachments IS NULL OR msi.has_attachments = p_has_attachments)
    AND (p_sender_name IS NULL OR msi.sender_name ILIKE '%' || p_sender_name || '%')
    AND (p_date_from IS NULL OR msi.sent_at >= p_date_from)
    AND (p_date_to IS NULL OR msi.sent_at <= p_date_to)

    -- Exclude soft-deleted
    AND pm.deleted_by_sender = FALSE

  ORDER BY rank DESC, msi.sent_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


