COMMENT ON FUNCTION "public"."search_private_messages"("p_user_id" "uuid", "p_query" "text", "p_search_in" "text", "p_has_attachments" boolean, "p_sender_name" "text", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_limit" integer, "p_offset" integer) IS 'Full-text search for private messages with filters';



CREATE OR REPLACE FUNCTION "public"."search_users_unaccent"("search_term" "text", "result_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "email" "text", "firstname" "text", "lastname" "text", "role" "public"."user_role", "school_id" "uuid", "grade" "text", "is_test" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "school_name" "text", "class_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          p.id,
          p.email,
          p.firstname,
          p.lastname,
          p.role,
          p.school_id,
          p.grade,
          p.is_test,
          p.created_at,
          p.updated_at,
          s.name AS school_name,
          COALESCE(
              ARRAY_AGG(cm.class_id) FILTER (WHERE cm.class_id IS NOT NULL),
              '{}'::UUID[]
          ) AS class_ids
      FROM profiles p
      LEFT JOIN schools s ON p.school_id = s.id
      LEFT JOIN class_members cm ON p.id = cm.student_id
      WHERE
          unaccent(LOWER(p.email)) LIKE '%' || unaccent(LOWER(search_term)) || '%'
          OR unaccent(LOWER(COALESCE(p.firstname, ''))) LIKE '%' || unaccent(LOWER(search_term)) || '%'
          OR unaccent(LOWER(COALESCE(p.lastname, ''))) LIKE '%' || unaccent(LOWER(search_term)) || '%'
      GROUP BY p.id, p.email, p.firstname, p.lastname, p.role, p.school_id,
               p.grade, p.is_test, p.created_at, p.updated_at, s.name
      ORDER BY p.lastname ASC, p.firstname ASC
      LIMIT result_limit;
  END;
  $$;


ALTER FUNCTION "public"."search_users_unaccent"("search_term" "text", "result_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sell_vip_card"("p_student_id" "uuid", "p_card_instance_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vip_cards JSONB;
  v_card_instance JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_current_balance NUMERIC;
  v_sell_price INTEGER;
  v_new_balance NUMERIC;
  v_earned_at TIMESTAMPTZ;
  v_purchased_at TIMESTAMPTZ;
  v_acquired_at TIMESTAMPTZ;
  v_uses_remaining INTEGER;
  v_uses_total INTEGER;
  v_class_id UUID;
  v_now TIMESTAMPTZ := NOW();
  v_cooldown_seconds INTEGER := 300; -- 5 minutes
  v_seconds_remaining INTEGER;
  v_is_locked BOOLEAN;
BEGIN
  -- ========================================================================
  -- SECURITY: Verify caller is the student
  -- ========================================================================

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Authentication required'
    );
  END IF;

  IF auth.uid() != p_student_id THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Unauthorized: Cannot sell cards for other students'
    );
  END IF;

  -- ========================================================================
  -- GET AND LOCK STUDENT PROFILE
  -- ========================================================================

  SELECT gidouilles, vip_cards INTO v_current_balance, v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_current_balance IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Student not found'
    );
  END IF;

  -- Initialize vip_cards if null
  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- ========================================================================
  -- VALIDATE CARD INSTANCE EXISTS
  -- ========================================================================

  v_card_instance := v_vip_cards -> p_card_instance_id;

  IF v_card_instance IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card instance not found'
    );
  END IF;

  v_card_id := v_card_instance ->> 'cardId';

  -- ========================================================================
  -- VALIDATE CARD NOT USED
  -- ========================================================================

  IF (v_card_instance ->> 'usedAt') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Cannot sell a card that has already been used'
    );
  END IF;

  -- ========================================================================
  -- VALIDATE NO PENDING ACTIVATION REQUEST
  -- ========================================================================

  IF (v_card_instance ->> 'activationRequestedAt') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Cannot sell a card with a pending activation request'
    );
  END IF;

  -- ========================================================================
  -- VALIDATE COOLDOWN (5 minutes after acquisition)
  -- ========================================================================

  v_earned_at := (v_card_instance ->> 'earnedAt')::TIMESTAMPTZ;
  v_purchased_at := (v_card_instance ->> 'purchasedAt')::TIMESTAMPTZ;
  -- Use the most recent acquisition timestamp for the cooldown window
  v_acquired_at := GREATEST(v_purchased_at, v_earned_at);

  IF v_acquired_at IS NULL THEN
    -- No acquisition timestamp: block sale as a safe default
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card has no acquisition timestamp; cannot verify cooldown',
      'secondsRemaining', v_cooldown_seconds
    );
  END IF;

  v_seconds_remaining := v_cooldown_seconds - EXTRACT(EPOCH FROM (v_now - v_acquired_at))::INTEGER;

  IF v_seconds_remaining > 0 THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Cooldown active: please wait before selling this card',
      'secondsRemaining', v_seconds_remaining
    );
  END IF;

  -- ========================================================================
  -- VALIDATE NOT LOCKED IN MARKETPLACE
  -- ========================================================================

  SELECT EXISTS(
    SELECT 1 FROM marketplace_locked_cards
    WHERE card_instance_id = p_card_instance_id
      AND student_id = p_student_id
  ) INTO v_is_locked;

  IF v_is_locked THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Cannot sell a card that is listed or in a trade on the marketplace'
    );
  END IF;

  -- ========================================================================
  -- GET TEMPLATE AND CALCULATE SELL PRICE
  -- ========================================================================

  SELECT id, name, rarity, sell_price, uses_total
  INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  IF v_template IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card template not found: ' || v_card_id
    );
  END IF;

  IF v_template.sell_price IS NULL OR v_template.sell_price <= 0 THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'This card cannot be sold'
    );
  END IF;

  -- Calculate sell price (prorated for partial consumables)
  v_sell_price := v_template.sell_price;
  v_uses_total := v_template.uses_total;

  IF v_uses_total IS NOT NULL AND v_uses_total > 0 THEN
    v_uses_remaining := COALESCE((v_card_instance ->> 'usesRemaining')::INTEGER, v_uses_total);

    IF v_uses_remaining < v_uses_total THEN
      -- Prorated price: floor(sell_price * uses_remaining / uses_total), minimum 1
      v_sell_price := GREATEST(1, FLOOR(v_sell_price::NUMERIC * v_uses_remaining / v_uses_total)::INTEGER);
    END IF;
  END IF;

  -- ========================================================================
  -- PERFORM SALE: Remove card and credit gidouilles
  -- ========================================================================

  v_new_balance := v_current_balance + v_sell_price;

  -- Remove card instance from JSONB
  v_vip_cards := v_vip_cards - p_card_instance_id;

  UPDATE profiles
  SET
    gidouilles = v_new_balance,
    vip_cards = v_vip_cards,
    updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- LOG VIP CARD ACTIVITY
  -- ========================================================================

  INSERT INTO vip_cards_activity (
    student_id,
    card_instance_id,
    card_template_id,
    action,
    metadata
  ) VALUES (
    p_student_id,
    p_card_instance_id,
    v_card_id,
    'sold',
    jsonb_build_object(
      'sell_price', v_sell_price,
      'rarity', v_template.rarity,
      'uses_remaining', v_uses_remaining,
      'uses_total', v_uses_total,
      'old_balance', v_current_balance,
      'new_balance', v_new_balance
    )
  );

  -- ========================================================================
  -- LOG GIDOUILLES ACTIVITY
  -- ========================================================================

  SELECT cm.class_id INTO v_class_id
  FROM class_members cm
  WHERE cm.student_id = p_student_id
    AND cm.status = 'active'
  LIMIT 1;

  INSERT INTO gidouilles_activity (
    student_id,
    class_id,
    delta,
    reason,
    created_by
  ) VALUES (
    p_student_id,
    v_class_id,
    v_sell_price,
    'Vente carte VIP : ' || v_template.name,
    NULL
  );

  -- ========================================================================
  -- RETURN SUCCESS
  -- ========================================================================

  RETURN jsonb_build_object(
    'success', TRUE,
    'sellPrice', v_sell_price,
    'cardId', v_card_id,
    'cardName', v_template.name,
    'oldBalance', v_current_balance,
    'newBalance', v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."sell_vip_card"("p_student_id" "uuid", "p_card_instance_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sell_vip_card"("p_student_id" "uuid", "p_card_instance_id" "text") IS 'Sells a VIP card back to the system for gidouilles.
Validates ownership, usage state, cooldown, and marketplace locks.
Prorates price for partially-used consumables (floor, min 1g).
Logs to vip_cards_activity (sold) and gidouilles_activity.';



CREATE OR REPLACE FUNCTION "public"."send_private_message"("p_sender_id" "uuid", "p_recipient_ids" "uuid"[], "p_subject" "text", "p_content" "jsonb", "p_is_group_message" boolean DEFAULT false, "p_class_id" "uuid" DEFAULT NULL::"uuid", "p_parent_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_message_id UUID;
  v_recipient_id UUID;
  v_plain_text TEXT;
  v_thread_root_id UUID;
BEGIN
  -- Validate permissions
  IF p_is_group_message AND p_class_id IS NOT NULL THEN
    -- Validate class message
    IF NOT validate_class_message_recipients(p_sender_id, p_class_id) THEN
      RAISE EXCEPTION 'You do not have permission to send messages to this class';
    END IF;

    -- Get all students in the class
    SELECT array_agg(student_id)
    INTO p_recipient_ids
    FROM get_students_in_class(p_class_id);

  ELSE
    -- Validate individual recipients
    IF NOT validate_message_recipients(p_sender_id, p_recipient_ids) THEN
      RAISE EXCEPTION 'You do not have permission to send messages to one or more recipients';
    END IF;
  END IF;

  -- Extract plain text from TipTap JSON using new function
  v_plain_text := extract_plain_text_from_tiptap(p_content);
  v_plain_text := substring(trim(v_plain_text), 1, 5000); -- Limit length and trim whitespace

  -- Determine thread root
  IF p_parent_message_id IS NOT NULL THEN
    -- Get thread root from parent
    SELECT COALESCE(thread_root_id, id)
    INTO v_thread_root_id
    FROM private_messages
    WHERE id = p_parent_message_id;
  ELSE
    v_thread_root_id := NULL; -- This will be the root
  END IF;

  -- Insert message
  INSERT INTO private_messages (
    sender_id,
    subject,
    content,
    plain_text,
    parent_message_id,
    thread_root_id,
    is_group_message,
    class_id,
    recipient_count
  ) VALUES (
    p_sender_id,
    p_subject,
    p_content,
    v_plain_text,
    p_parent_message_id,
    v_thread_root_id,
    p_is_group_message,
    p_class_id,
    array_length(p_recipient_ids, 1)
  )
  RETURNING id INTO v_message_id;

  -- If this is a root message, set its own thread_root_id
  IF v_thread_root_id IS NULL THEN
    UPDATE private_messages
    SET thread_root_id = v_message_id
    WHERE id = v_message_id;
  END IF;

  -- Create inbox entries for each recipient
  FOREACH v_recipient_id IN ARRAY p_recipient_ids
  LOOP
    INSERT INTO message_inbox (
      message_id,
      recipient_id,
      status
    ) VALUES (
      v_message_id,
      v_recipient_id,
      'inbox'
    );
  END LOOP;

  RETURN v_message_id;
END;
$$;


ALTER FUNCTION "public"."send_private_message"("p_sender_id" "uuid", "p_recipient_ids" "uuid"[], "p_subject" "text", "p_content" "jsonb", "p_is_group_message" boolean, "p_class_id" "uuid", "p_parent_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_private_message"("p_sender_id" "uuid", "p_recipient_ids" "uuid"[], "p_subject" "text", "p_content" "jsonb", "p_is_group_message" boolean, "p_class_id" "uuid", "p_parent_message_id" "uuid") IS 'Sends a private message with validation and creates inbox entries for recipients';



