CREATE OR REPLACE FUNCTION "public"."set_minesweeper_started_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- On INSERT: set started_at if the game is already created with cells revealed
    -- (happens when createGameInDatabase() is called after first click)
    IF NEW.cells_revealed > 0 AND NEW.started_at IS NULL THEN
      NEW.started_at := NOW();
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- On UPDATE: set started_at when transitioning from 0 cells revealed to >0 cells
    -- (original intended flow: insert with cells_revealed=0, then update on first click)
    IF OLD.cells_revealed = 0 AND NEW.cells_revealed > 0 AND NEW.started_at IS NULL THEN
      NEW.started_at := NOW();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_minesweeper_started_at"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_minesweeper_started_at"() IS 'Trigger function to automatically set started_at when first cell is revealed. Handles both INSERT (current flow: game created after first click) and UPDATE (original flow: 0→>0 transition). Prevents client manipulation of game start time.';



CREATE OR REPLACE FUNCTION "public"."set_offer_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_lock_key BIGINT;
BEGIN
    -- Use advisory lock to prevent race conditions
    -- Generate a unique lock key from the trade_id (using first 8 bytes of UUID)
    v_lock_key := ('x' || substr(NEW.trade_id::text, 1, 8))::bit(32)::bigint;

    -- Acquire advisory lock (will wait if another transaction has it)
    PERFORM pg_advisory_xact_lock(v_lock_key);

    -- Now safely get the next offer number
    SELECT COALESCE(MAX(offer_number), 0) + 1 INTO NEW.offer_number
    FROM public.marketplace_trade_offers
    WHERE trade_id = NEW.trade_id;

    -- Lock will be automatically released at end of transaction
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_offer_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_riddle_of_the_day"("p_riddle_id" "uuid", "p_date" "date", "p_selected_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  -- Upsert riddle of the day
  INSERT INTO riddle_of_the_day (riddle_id, date, auto_selected, selected_by)
  VALUES (p_riddle_id, p_date, false, p_selected_by)
  ON CONFLICT (date)
  DO UPDATE SET
    riddle_id = EXCLUDED.riddle_id,
    auto_selected = false,
    selected_by = EXCLUDED.selected_by,
    created_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


