   Used by profiles RLS to allow tournament participants to see each other.';



CREATE OR REPLACE FUNCTION "public"."skill_attempts_after_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_skill_id uuid;
BEGIN
    -- Famille A : boucle sur skills famille knowledge tagués par le template
    IF NEW.template_id IS NOT NULL AND NEW.success IS NOT NULL THEN
        FOR v_skill_id IN
            SELECT qts.skill_id
              FROM public.question_template_skills qts
              JOIN public.skills s ON s.id = qts.skill_id
             WHERE qts.template_id = NEW.template_id
               AND s.family = 'knowledge'
        LOOP
            PERFORM public.update_student_skill_state_a(NEW.student_id, v_skill_id);
        END LOOP;
    -- Famille B : inchangé
    ELSIF NEW.skill_id IS NOT NULL AND NEW.code IS NOT NULL THEN
        PERFORM public.update_student_observable_state(NEW.student_id, NEW.skill_id);
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION "public"."skill_attempts_after_insert"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."skill_attempts_after_insert"() IS 'Trigger : route les attempts vers le cache approprié. Refonte 2026-06-10 : Famille A boucle sur les skills tagués via question_template_skills.';



CREATE OR REPLACE FUNCTION "public"."soft_delete_message"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender_id UUID;
  v_conversation_id UUID;
BEGIN
  -- Get message details
  SELECT sender_id, conversation_id INTO v_sender_id, v_conversation_id
  FROM messages
  WHERE id = p_message_id;

  -- Check permissions: either sender or teacher who created the chat
  IF v_sender_id != auth.uid() THEN
    -- Check if user is teacher who created the group chat
    IF NOT EXISTS (
      SELECT 1 FROM conversations c
      WHERE c.id = v_conversation_id
      AND c.is_group = true
      AND c.created_by = auth.uid()
      AND is_teacher_or_admin()
    ) THEN
      RAISE EXCEPTION 'Permission denied: cannot delete this message';
    END IF;
  END IF;

  -- Soft delete
  UPDATE messages
  SET deleted_at = NOW()
  WHERE id = p_message_id;
END;
$$;


ALTER FUNCTION "public"."soft_delete_message"("p_message_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."soft_delete_message"("p_message_id" "uuid") IS 'Soft delete a message (sets deleted_at timestamp)';



CREATE OR REPLACE FUNCTION "public"."soft_delete_warning"("p_warning_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_affected INTEGER;
    v_caller_role TEXT;
BEGIN
    -- SECURITY CHECK (Issue #1 & #3): Get caller's role to enforce authorization
    -- SECURITY DEFINER functions bypass RLS, so we must check permissions explicitly
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- FIX (Issue #3): Only teachers and admins can delete warnings
    -- Students should NOT be able to delete their own warnings
    IF v_caller_role NOT IN ('teacher', 'admin') THEN
        RAISE EXCEPTION 'Unauthorized: Only teachers and admins can delete warnings';
    END IF;

    -- Attempt to soft delete the warning
    UPDATE public.student_warnings
    SET
        deleted_at = NOW(),
        deleted_by = auth.uid()
    WHERE id = p_warning_id
    AND deleted_at IS NULL  -- Only delete active warnings
    AND EXISTS (
        -- Teacher must be teaching this student
        SELECT 1 FROM public.class_members cm
        JOIN public.classes c ON c.id = cm.class_id
        WHERE cm.student_id = student_warnings.student_id
        AND cm.class_id = student_warnings.class_id
        AND (
            c.teacher_id = auth.uid()  -- Teacher owns the class
            OR v_caller_role = 'admin'  -- Or user is admin
        )
    );

    GET DIAGNOSTICS v_affected = ROW_COUNT;

    RETURN v_affected > 0;
END;
$$;


ALTER FUNCTION "public"."soft_delete_warning"("p_warning_id" "uuid") OWNER TO "postgres";


