CREATE OR REPLACE FUNCTION "public"."student_has_exercise_access"("p_exercise_id" "uuid", "p_student_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT EXISTS (
        -- Exercise is public
        SELECT 1 FROM exercises
        WHERE id = p_exercise_id
        AND is_public = TRUE
    ) OR EXISTS (
        -- Student has an active assignment
        SELECT 1 FROM exercise_assignments ea
        WHERE ea.exercise_id = p_exercise_id
        AND ea.is_active = TRUE
        AND (
            -- Direct assignment
            ea.student_id = p_student_id
            -- Class assignment
            OR ea.class_id IN (
                SELECT class_id FROM class_members WHERE student_id = p_student_id
            )
            -- Public assignment
            OR ea.assigned_to_type = 'public'
        )
    );
$$;


