CREATE OR REPLACE FUNCTION "public"."toggle_reaction"("p_message_id" "uuid", "p_emoji" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_reaction_exists BOOLEAN;
BEGIN
  -- Check if user is a participant in the conversation
  IF NOT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Permission denied: not a participant';
  END IF;

  -- Check if reaction already exists
  SELECT EXISTS (
    SELECT 1 FROM message_reactions
    WHERE message_id = p_message_id
    AND user_id = v_user_id
    AND emoji = p_emoji
  ) INTO v_reaction_exists;

  IF v_reaction_exists THEN
    -- Remove reaction
    DELETE FROM message_reactions
    WHERE message_id = p_message_id
    AND user_id = v_user_id
    AND emoji = p_emoji;

    RETURN false; -- Reaction removed
  ELSE
    -- Add reaction
    INSERT INTO message_reactions (message_id, user_id, emoji)
    VALUES (p_message_id, v_user_id, p_emoji)
    ON CONFLICT (message_id, user_id, emoji) DO NOTHING;

    RETURN true; -- Reaction added
  END IF;
END;
$$;


