CREATE OR REPLACE FUNCTION "public"."update_folder_message_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Handle INSERT: increment new folder count
  IF TG_OP = 'INSERT' AND NEW.folder_id IS NOT NULL THEN
    UPDATE user_folders
    SET message_count = message_count + 1
    WHERE id = NEW.folder_id;
  END IF;

  -- Handle UPDATE: adjust counts if folder changed
  IF TG_OP = 'UPDATE' AND (OLD.folder_id IS DISTINCT FROM NEW.folder_id) THEN
    -- Decrement old folder
    IF OLD.folder_id IS NOT NULL THEN
      UPDATE user_folders
      SET message_count = GREATEST(message_count - 1, 0)
      WHERE id = OLD.folder_id;
    END IF;

    -- Increment new folder
    IF NEW.folder_id IS NOT NULL THEN
      UPDATE user_folders
      SET message_count = message_count + 1
      WHERE id = NEW.folder_id;
    END IF;
  END IF;

  -- Handle DELETE: decrement folder count
  IF TG_OP = 'DELETE' AND OLD.folder_id IS NOT NULL THEN
    UPDATE user_folders
    SET message_count = GREATEST(message_count - 1, 0)
    WHERE id = OLD.folder_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_folder_message_count"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_folder_message_count"() IS 'Updates folder message counts when messages are moved';



