CREATE OR REPLACE FUNCTION "public"."update_message_search_index"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender_name TEXT;
  v_sender_role TEXT;
  v_has_attachments BOOLEAN;
BEGIN
  -- Get sender info
  SELECT full_name, role
  INTO v_sender_name, v_sender_role
  FROM profiles
  WHERE id = NEW.sender_id;

  -- Check for attachments
  SELECT EXISTS (
    SELECT 1 FROM message_attachments_v2
    WHERE message_id = NEW.id
  ) INTO v_has_attachments;

  -- Insert or update search index
  INSERT INTO message_search_index (
    message_id,
    sender_name,
    sender_role,
    subject_tsv,
    content_tsv,
    sent_at,
    has_attachments,
    recipient_count
  ) VALUES (
    NEW.id,
    v_sender_name,
    v_sender_role,
    to_tsvector('french', COALESCE(NEW.subject, '')),
    to_tsvector('french', COALESCE(NEW.plain_text, '')),
    NEW.sent_at,
    v_has_attachments,
    NEW.recipient_count
  )
  ON CONFLICT (message_id) DO UPDATE SET
    subject_tsv = to_tsvector('french', COALESCE(NEW.subject, '')),
    content_tsv = to_tsvector('french', COALESCE(NEW.plain_text, '')),
    has_attachments = v_has_attachments;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_message_search_index"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_message_search_index"() IS 'Updates search index when a message is created or updated';



CREATE OR REPLACE FUNCTION "public"."update_message_status"("p_message_id" "uuid", "p_user_id" "uuid", "p_status" "text") RETURNS "void"
