CREATE OR REPLACE FUNCTION "public"."update_player_combat_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  player_id UUID;
BEGIN
  -- Only process completed combats
  IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
    -- Update stats for organizer
    IF NEW.outcome = 'victory' THEN
      UPDATE game_players
      SET
        total_combats = total_combats + 1,
        combats_won = combats_won + 1,
        prestige = prestige + COALESCE(NEW.prestige_gained, 0),
        xp = xp + COALESCE(NEW.xp_gained, 0)
      WHERE user_id = NEW.organizer_id;
    ELSE
      UPDATE game_players
      SET
        total_combats = total_combats + 1,
        combats_lost = combats_lost + 1
      WHERE user_id = NEW.organizer_id;
    END IF;

    -- Update stats for all participants
    FOREACH player_id IN ARRAY NEW.ready_player_ids
    LOOP
      IF NEW.outcome = 'victory' THEN
        UPDATE game_players
        SET
          total_combats = total_combats + 1,
          combats_won = combats_won + 1,
          prestige = prestige + COALESCE(NEW.prestige_gained, 0),
          xp = xp + COALESCE(NEW.xp_gained, 0)
        WHERE user_id = player_id;
      ELSE
        UPDATE game_players
        SET
          total_combats = total_combats + 1,
          combats_lost = combats_lost + 1
        WHERE user_id = player_id;
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_player_combat_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_player_combat_stats"() IS 'Updates player combat statistics on combat completion';



