CREATE OR REPLACE FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_delta" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_teacher_id UUID;
  v_is_teacher BOOLEAN;
  v_student_in_class BOOLEAN;
  v_new_gidouilles INTEGER;
BEGIN
  -- Get the current user's ID (the teacher calling this function)
  v_teacher_id := auth.uid();

  -- Check if caller is a teacher or admin
  v_is_teacher := is_teacher_or_admin();

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Unauthorized: Only teachers can update gidouilles';
  END IF;

  -- Check if student is in one of the teacher's classes
  -- This query checks if there exists a class_member record where:
  -- - The student is p_student_id
  -- - The class is owned by the current teacher
  SELECT EXISTS (
    SELECT 1
    FROM class_members cm
    INNER JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = p_student_id
      AND c.teacher_id = v_teacher_id
  ) INTO v_student_in_class;

  IF NOT v_student_in_class THEN
    RAISE EXCEPTION 'Unauthorized: Student is not in your classes';
  END IF;

  -- Update the gidouilles field ONLY (atomic operation with built-in minimum enforcement)
  -- GREATEST(0, gidouilles + p_delta) ensures the result is never negative
  UPDATE profiles
  SET gidouilles = GREATEST(0, gidouilles + p_delta),
      updated_at = NOW()
  WHERE id = p_student_id
  RETURNING gidouilles INTO v_new_gidouilles;

  -- Return the new value
  RETURN v_new_gidouilles;
END;
$$;


ALTER FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_delta" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_delta" integer) IS 'Securely updates a student''s gidouilles count using atomic UPDATE (race-condition safe). Only teachers who have the student in their classes can call this. Enforces minimum of 0 gidouilles.';



CREATE OR REPLACE FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_class_id" "uuid", "p_delta" integer, "p_reason" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_new_gidouilles INTEGER;
    v_caller_role TEXT;
BEGIN
    -- SECURITY CHECK: Get caller's role to enforce authorization
    SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE id = auth.uid();

    -- Authorization: Only admins, teachers of the student, or system (NULL caller) can update
    IF auth.uid() IS NOT NULL AND NOT (
        v_caller_role = 'admin'
        OR (v_caller_role = 'teacher' AND EXISTS (
            SELECT 1 FROM public.class_members cm
            JOIN public.classes c ON c.id = cm.class_id
            WHERE cm.student_id = p_student_id
            AND cm.class_id = p_class_id
            AND cm.status = 'active'
            AND c.teacher_id = auth.uid()
        ))
    ) THEN
        RAISE EXCEPTION 'Non autorisé: seuls les professeurs de cet élève peuvent modifier ses gidouilles';
    END IF;

    -- Update gidouilles with floor at 0
    UPDATE public.profiles
    SET gidouilles = GREATEST(0, COALESCE(gidouilles, 0) + p_delta)
    WHERE id = p_student_id
    RETURNING gidouilles INTO v_new_gidouilles;

    -- Log the change in activity table
    INSERT INTO public.gidouilles_activity (
        student_id,
        class_id,
        delta,
        reason,
        created_by
    ) VALUES (
        p_student_id,
        p_class_id,
        p_delta,
        p_reason,
        COALESCE(p_created_by, auth.uid())
    );

    RETURN v_new_gidouilles;
END;
$$;


ALTER FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_class_id" "uuid", "p_delta" integer, "p_reason" "text", "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_student_gidouilles"("p_student_id" "uuid", "p_class_id" "uuid", "p_delta" integer, "p_reason" "text", "p_created_by" "uuid") IS 'Update student gidouilles with authorization checks. Logs to gidouilles_activity table.';



CREATE OR REPLACE FUNCTION "public"."update_student_observable_state"("p_student_id" "uuid", "p_skill_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_math_competence_id  uuid;
    v_total_attempts      integer;
    v_count_plus          integer;
    v_count_minus         integer;
    v_last_attempt_at     timestamptz;
    v_is_acquis           boolean;
BEGIN
    -- Resolve the parent math competence (via the subdimension) and guard
    -- that the skill is in family 'competence'.
    SELECT mcs.math_competence_id
      INTO v_math_competence_id
      FROM public.skills s
      JOIN public.math_competence_subdimensions mcs ON mcs.id = s.subdimension_id
     WHERE s.id = p_skill_id
       AND s.family = 'competence';

    IF v_math_competence_id IS NULL THEN
        -- Skill does not exist or is not Family B. Defensive: do nothing.
        RETURN;
    END IF;

    -- Aggregate plus/minus counts over all Family B attempts for this pair.
    SELECT COUNT(*)                            FILTER (WHERE TRUE),
           COUNT(*)                            FILTER (WHERE code = 'plus'),
           COUNT(*)                            FILTER (WHERE code = 'minus'),
           MAX(created_at)
      INTO v_total_attempts,
           v_count_plus,
           v_count_minus,
           v_last_attempt_at
      FROM public.skill_attempts
     WHERE student_id = p_student_id
       AND skill_id   = p_skill_id
       AND code IS NOT NULL;                   -- guard : Family B rows only

    -- Consolidation rule (§6.1bis).
    v_is_acquis := (v_count_plus >= 2) AND (v_count_plus > v_count_minus);

    IF v_total_attempts = 0 THEN
        -- No attempts left: clean the cache row.
        DELETE FROM public.student_observable_state
         WHERE student_id = p_student_id
           AND skill_id   = p_skill_id;
    ELSE
        INSERT INTO public.student_observable_state (
            student_id,
            skill_id,
            count_plus,
            count_minus,
            is_acquis,
            last_attempt_at,
            updated_at
        ) VALUES (
            p_student_id,
            p_skill_id,
            v_count_plus,
            v_count_minus,
            v_is_acquis,
            v_last_attempt_at,
            NOW()
        )
        ON CONFLICT (student_id, skill_id) DO UPDATE
            SET count_plus      = EXCLUDED.count_plus,
                count_minus     = EXCLUDED.count_minus,
                is_acquis       = EXCLUDED.is_acquis,
                last_attempt_at = EXCLUDED.last_attempt_at,
                updated_at      = NOW();
    END IF;

    -- Cascade : recompute the parent competence verdict.
    PERFORM public.update_student_competence_level(p_student_id, v_math_competence_id);
END $$;


ALTER FUNCTION "public"."update_student_observable_state"("p_student_id" "uuid", "p_skill_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_student_observable_state"("p_student_id" "uuid", "p_skill_id" "uuid") IS 'Recomputes student_observable_state (Family B observable consolidation). Rule (§6.1bis): is_acquis ssi count_plus >= 2 AND count_plus > count_minus. Cascades to update_student_competence_level for the parent math_competence.';



CREATE OR REPLACE FUNCTION "public"."update_student_progress_after_attempt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_subtopic_id UUID;
BEGIN
    -- Get the subtopic_id from the exercise
    SELECT subtopic_id INTO v_subtopic_id
    FROM exercises
    WHERE id = NEW.exercise_id;

    -- Insert or update student progress
    INSERT INTO student_progress (student_id, subtopic_id, exercises_completed, exercises_correct, total_points, last_practiced_at)
    VALUES (
        NEW.student_id,
        v_subtopic_id,
        1,
        CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
        NEW.points_earned,
        NOW()
    )
    ON CONFLICT (student_id, subtopic_id)
    DO UPDATE SET
        exercises_completed = student_progress.exercises_completed + 1,
        exercises_correct = student_progress.exercises_correct + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
        total_points = student_progress.total_points + NEW.points_earned,
        last_practiced_at = NOW(),
        mastery_level = LEAST(1.00, (student_progress.exercises_correct::NUMERIC + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END) / NULLIF(student_progress.exercises_completed + 1, 0));

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_student_progress_after_attempt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_student_skill_state_a"("p_student_id" "uuid", "p_skill_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_knowledge_type   text;
    v_window           integer;
    v_total_attempts   integer;
    v_total_successes  integer;
    v_distinct_tpl     integer;
    v_last_success_at  timestamptz;
    v_last_attempt_at  timestamptz;
    v_recent_successes integer;
    v_recent_failures  integer;
    v_is_acquired      boolean;
    v_needs_remed      boolean;
BEGIN
    SELECT s.knowledge_type
      INTO v_knowledge_type
      FROM public.skills s
     WHERE s.id = p_skill_id
       AND s.family = 'knowledge';

    IF v_knowledge_type IS NULL THEN
        RETURN;
    END IF;

    v_window := CASE v_knowledge_type
                    WHEN 'capacite_attendue' THEN 3
                    WHEN 'automatisme'       THEN 5
                END;

    -- Refonte 2026-06-10 : on retrouve les attempts via question_template_skills
    -- au lieu de filtrer sur skill_id (qui est NULL en régime A).
    SELECT COUNT(*)                            FILTER (WHERE TRUE),
           COUNT(*)                            FILTER (WHERE sa.success = TRUE),
           COUNT(DISTINCT sa.template_id)      FILTER (WHERE sa.success = TRUE),
           MAX(sa.created_at)                  FILTER (WHERE sa.success = TRUE),
           MAX(sa.created_at)
      INTO v_total_attempts,
           v_total_successes,
           v_distinct_tpl,
           v_last_success_at,
           v_last_attempt_at
      FROM public.skill_attempts sa
      JOIN public.question_template_skills qts
        ON qts.template_id = sa.template_id
     WHERE sa.student_id = p_student_id
       AND qts.skill_id  = p_skill_id
       AND sa.template_id IS NOT NULL    -- guard : Famille A only
       AND sa.success IS NOT NULL;        -- guard : Famille A only

    IF v_total_attempts = 0 THEN
        DELETE FROM public.student_skill_state_a
         WHERE student_id = p_student_id
           AND skill_id   = p_skill_id;
        RETURN;
    END IF;

    -- Recent window : last `v_window` attempts ordered by created_at DESC.
    WITH recent AS (
        SELECT sa.success
          FROM public.skill_attempts sa
          JOIN public.question_template_skills qts
            ON qts.template_id = sa.template_id
         WHERE sa.student_id = p_student_id
           AND qts.skill_id  = p_skill_id
           AND sa.template_id IS NOT NULL
           AND sa.success IS NOT NULL
         ORDER BY sa.created_at DESC
         LIMIT v_window
    )
    SELECT COUNT(*) FILTER (WHERE success = TRUE),
           COUNT(*) FILTER (WHERE success = FALSE)
      INTO v_recent_successes,
           v_recent_failures
      FROM recent;

    -- Règles §6.1 (inchangées)
    IF v_knowledge_type = 'capacite_attendue' THEN
        v_is_acquired := (v_distinct_tpl >= 2)
                     AND (v_recent_failures = 0);
    ELSE
        v_is_acquired := (v_total_successes >= 5)
                     AND (v_recent_successes >= 3);
    END IF;

    v_needs_remed := (NOT v_is_acquired) AND (v_recent_failures >= 2);

    INSERT INTO public.student_skill_state_a (
        student_id,
        skill_id,
        is_acquired,
        total_successes,
        distinct_template_successes,
        last_success_at,
        last_attempt_at,
        needs_remediation,
        updated_at
    ) VALUES (
        p_student_id,
        p_skill_id,
        v_is_acquired,
        v_total_successes,
        v_distinct_tpl,
        v_last_success_at,
        v_last_attempt_at,
        v_needs_remed,
        NOW()
    )
    ON CONFLICT (student_id, skill_id) DO UPDATE
        SET is_acquired                 = EXCLUDED.is_acquired,
            total_successes             = EXCLUDED.total_successes,
            distinct_template_successes = EXCLUDED.distinct_template_successes,
            last_success_at             = EXCLUDED.last_success_at,
            last_attempt_at             = EXCLUDED.last_attempt_at,
            needs_remediation           = EXCLUDED.needs_remediation,
            updated_at                  = NOW();
END $$;


ALTER FUNCTION "public"."update_student_skill_state_a"("p_student_id" "uuid", "p_skill_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_student_skill_state_a"("p_student_id" "uuid", "p_skill_id" "uuid") IS 'Recomputes student_skill_state_a depuis skill_attempts. Refonte 2026-06-10 : jointure via question_template_skills (skill_id NULL en régime A).';



