CREATE OR REPLACE FUNCTION "public"."upsert_2048_score"("p_user_id" "uuid", "p_score" integer, "p_reached_2048" boolean, "p_reached_4096" boolean) RETURNS TABLE("best_score" integer, "games_played" integer, "is_new_best" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
	v_existing_best_score integer;
	v_new_best_score integer;
BEGIN
	INSERT INTO game_2048_scores (
		user_id, best_score, games_played, tiles_2048_reached, tiles_4096_reached
	)
	VALUES (
		p_user_id, p_score, 1,
		CASE WHEN p_reached_2048 THEN 1 ELSE 0 END,
		CASE WHEN p_reached_4096 THEN 1 ELSE 0 END
	)
	ON CONFLICT (user_id)
	DO UPDATE SET
		best_score = GREATEST(game_2048_scores.best_score, p_score),
		games_played = game_2048_scores.games_played + 1,
		tiles_2048_reached = game_2048_scores.tiles_2048_reached + CASE WHEN p_reached_2048 THEN 1 ELSE 0 END,
		tiles_4096_reached = game_2048_scores.tiles_4096_reached + CASE WHEN p_reached_4096 THEN 1 ELSE 0 END
	RETURNING game_2048_scores.best_score, game_2048_scores.games_played
	INTO v_new_best_score, games_played;

	SELECT game_2048_scores.best_score
	INTO v_existing_best_score
	FROM game_2048_scores
	WHERE game_2048_scores.user_id = p_user_id;

	best_score := v_new_best_score;
	is_new_best := (p_score >= v_existing_best_score);
	RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."upsert_2048_score"("p_user_id" "uuid", "p_score" integer, "p_reached_2048" boolean, "p_reached_4096" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_checkpoint_run"("p_notebook_id" "uuid", "p_cell_id" "text", "p_status" "text", "p_error_message" "text") RETURNS "public"."python_notebook_checkpoint_runs"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := NOW();
  v_user UUID := auth.uid();
  v_result python_notebook_checkpoint_runs;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  INSERT INTO python_notebook_checkpoint_runs AS r (
    notebook_id, user_id, cell_id,
    status, error_message,
    ran_at,
    attempt_count, first_attempted_at, succeeded_at
  )
  VALUES (
    p_notebook_id, v_user, p_cell_id,
    p_status, p_error_message,
    v_now,
    1, v_now,
    CASE WHEN p_status = 'passed' THEN v_now ELSE NULL END
  )
  ON CONFLICT (notebook_id, user_id, cell_id) DO UPDATE SET
    status        = EXCLUDED.status,
    error_message = EXCLUDED.error_message,
    ran_at        = EXCLUDED.ran_at,
    -- Sticky counter: never decrements, +1 per Vérifier click.
    attempt_count = r.attempt_count + 1,
    -- Sticky timestamps: keep the original first/succeeded values.
    first_attempted_at = COALESCE(r.first_attempted_at, EXCLUDED.first_attempted_at),
    succeeded_at = COALESCE(
      r.succeeded_at,
      CASE WHEN EXCLUDED.status = 'passed' THEN EXCLUDED.ran_at ELSE NULL END
    )
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."upsert_checkpoint_run"("p_notebook_id" "uuid", "p_cell_id" "text", "p_status" "text", "p_error_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_checkpoint_run"("p_notebook_id" "uuid", "p_cell_id" "text", "p_status" "text", "p_error_message" "text") IS 'Atomic UPSERT that increments attempt_count by 1 on conflict, sets first_attempted_at on insert (preserved on conflict), and records succeeded_at on the first passing run (sticky). SECURITY INVOKER → RLS still applies.';



CREATE OR REPLACE FUNCTION "public"."upsert_error_occurrence"("p_error_signature" "text", "p_error_log_id" "uuid", "p_error_type" "text", "p_severity" "text", "p_message" "text", "p_url" "text", "p_file_path" "text", "p_line_number" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_occurrence_count INTEGER;
BEGIN
  INSERT INTO error_occurrences (
    error_signature, error_type, severity, message, url, file_path, line_number,
    last_error_log_id, last_seen, occurrence_count
  ) VALUES (
    p_error_signature, p_error_type, p_severity, p_message, p_url, p_file_path, p_line_number,
    p_error_log_id, NOW(), 1
  )
  ON CONFLICT (error_signature) DO UPDATE SET
    last_seen = NOW(),
    occurrence_count = error_occurrences.occurrence_count + 1,
    last_error_log_id = p_error_log_id,
    updated_at = NOW()
  RETURNING occurrence_count INTO v_occurrence_count;

  RETURN v_occurrence_count;
END;
$$;


