CREATE OR REPLACE FUNCTION "public"."use_2048_power"("p_power_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_student_id UUID;
    v_role TEXT;
    v_cost INTEGER;
    v_current_gidouilles INTEGER;
    v_new_gidouilles INTEGER;
    v_class_id UUID;
BEGIN
    -- 1. Auth check: must be a student
    v_student_id := auth.uid();
    IF v_student_id IS NULL THEN
        RAISE EXCEPTION 'Authentification requise';
    END IF;

    SELECT role INTO v_role FROM public.profiles WHERE id = v_student_id;
    IF v_role != 'student' THEN
        RAISE EXCEPTION 'Seuls les élèves peuvent utiliser les pouvoirs';
    END IF;

    -- 2. Validate power type and get cost
    v_cost := CASE p_power_type
        WHEN 'undo' THEN 5
        WHEN 'bomb_4' THEN 3
        WHEN 'bomb_16' THEN 8
        WHEN 'bomb_64' THEN 15
        WHEN 'freeze_spawn' THEN 3
        WHEN 'fusion' THEN 15
        WHEN 'joker' THEN 10
        WHEN 'vision' THEN 3
        WHEN 'multiplier_1_5' THEN 20
        WHEN 'multiplier_2' THEN 40
        ELSE NULL
    END;

    IF v_cost IS NULL THEN
        RAISE EXCEPTION 'Type de pouvoir invalide: %', p_power_type;
    END IF;

    -- 3. Check sufficient gidouilles
    SELECT COALESCE(gidouilles, 0) INTO v_current_gidouilles
    FROM public.profiles WHERE id = v_student_id;

    IF v_current_gidouilles < v_cost THEN
        RAISE EXCEPTION 'Pas assez de gidouilles (disponible: %, requis: %)', v_current_gidouilles, v_cost;
    END IF;

    -- 4. Get student's active class
    SELECT cm.class_id INTO v_class_id
    FROM public.class_members cm
    WHERE cm.student_id = v_student_id
    AND cm.status = 'active'
    LIMIT 1;

    IF v_class_id IS NULL THEN
        RAISE EXCEPTION 'Pas de classe active trouvée';
    END IF;

    -- 5. Debit gidouilles atomically
    UPDATE public.profiles
    SET gidouilles = gidouilles - v_cost
    WHERE id = v_student_id
    AND gidouilles >= v_cost
    RETURNING gidouilles INTO v_new_gidouilles;

    IF v_new_gidouilles IS NULL THEN
        RAISE EXCEPTION 'Pas assez de gidouilles';
    END IF;

    -- 6. Log in activity
    INSERT INTO public.gidouilles_activity (
        student_id,
        class_id,
        delta,
        reason,
        created_by
    ) VALUES (
        v_student_id,
        v_class_id,
        -v_cost,
        '2048 power: ' || p_power_type,
        v_student_id
    );

    -- 7. Return result
    RETURN jsonb_build_object(
        'success', true,
        'source', 'gidouilles',
        'gidouilles_spent', v_cost,
        'gidouilles_remaining', v_new_gidouilles
    );
END;
$$;


ALTER FUNCTION "public"."use_2048_power"("p_power_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_2048_power"("p_power_type" "text") IS 'Debit gidouilles for a 2048 power (fallback when no VIP card). SECURITY DEFINER for atomic debit + logging.';



CREATE OR REPLACE FUNCTION "public"."use_detector"("p_game_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_hints_used INTEGER;
  v_reduced_penalty_hints INTEGER;
  v_current_balance NUMERIC(10,2);
  v_detector_instance_id TEXT;
  v_consume_result JSONB;
  v_detector_cost NUMERIC(10,2) := 10.0;
  v_vip_cards JSONB;
BEGIN
  -- Step 1: Verify game ownership and get current state
  SELECT student_id, COALESCE(hints_used, 0), COALESCE(reduced_penalty_hints, 0)
  INTO v_student_id, v_hints_used, v_reduced_penalty_hints
  FROM public.minesweeper_games
  WHERE id = p_game_id
    AND student_id = auth.uid()
    AND status = 'in_progress'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found, not owned by you, or not in progress';
  END IF;

  -- Step 2: Check shared hint limit (hints + detectors share the same counter)
  IF v_hints_used >= 3 THEN
    RAISE EXCEPTION 'Maximum hints reached (3 per game)';
  END IF;

  -- Step 3: Find an available detector VIP card instance
  SELECT vip_cards INTO v_vip_cards
  FROM public.profiles
  WHERE id = v_student_id;

  IF v_vip_cards IS NOT NULL THEN
    SELECT key INTO v_detector_instance_id
    FROM jsonb_each(v_vip_cards) AS cards(key, value)
    LEFT JOIN public.vip_card_templates t ON t.id = value->>'cardId'
    WHERE value->>'cardId' LIKE 'minesweeper-detector%'
      AND (value->>'usedAt') IS NULL
      AND (
        (value->>'usesRemaining') IS NULL
        OR (value->>'usesRemaining')::INTEGER > 0
      )
    ORDER BY
      -- Prefer already-started cards first
      CASE
        WHEN (value->>'usesRemaining') IS NOT NULL
         AND t.uses_total IS NOT NULL
         AND (value->>'usesRemaining')::INTEGER < t.uses_total
        THEN 0
        ELSE 1
      END ASC,
      -- Then fewest charges remaining
      COALESCE((value->>'usesRemaining')::INTEGER, 1) ASC
    LIMIT 1;
  END IF;

  -- Step 4: If we found a card, consume it via use_vip_card()
  IF v_detector_instance_id IS NOT NULL THEN
    v_consume_result := public.use_vip_card(v_student_id, v_detector_instance_id, NULL, NULL, 'minesweeper');

    IF (v_consume_result->>'success')::BOOLEAN THEN
      UPDATE public.minesweeper_games
      SET hints_used = v_hints_used + 1,
          reduced_penalty_hints = v_reduced_penalty_hints + 1
      WHERE id = p_game_id;

      RETURN jsonb_build_object(
        'success', true,
        'hints_used', v_hints_used + 1,
        'hints_remaining', 2 - v_hints_used,
        'source', 'vip_card',
        'vip_card_consumed', true,
        'gidouilles_spent', 0,
        'penalty_notice', 'Carte VIP Detecteur utilisee - penalite reduite (5/11/17%)'
      );
    END IF;
  END IF;

  -- Step 5: No VIP card available - use gidouilles (costs 10g)
  SELECT gidouilles INTO v_current_balance
  FROM public.profiles
  WHERE id = v_student_id
  FOR UPDATE;

  IF v_current_balance < v_detector_cost THEN
    RAISE EXCEPTION 'Insufficient gidouilles. Required: %, Available: %', v_detector_cost, v_current_balance;
  END IF;

  UPDATE public.profiles
  SET gidouilles = gidouilles - v_detector_cost
  WHERE id = v_student_id;

  INSERT INTO public.gidouilles_activity (student_id, delta, reason)
  VALUES (v_student_id, -v_detector_cost, 'Detecteur Demineur');

  UPDATE public.minesweeper_games
  SET hints_used = v_hints_used + 1
  WHERE id = p_game_id;

  RETURN jsonb_build_object(
    'success', true,
    'hints_used', v_hints_used + 1,
    'hints_remaining', 2 - v_hints_used,
    'source', 'gidouilles',
    'vip_card_consumed', false,
    'gidouilles_spent', v_detector_cost,
    'remaining_gidouilles', v_current_balance - v_detector_cost,
    'penalty_notice', 'Gidouilles utilisees - penalite progressive (10/22/35%)'
  );
END;
$$;


ALTER FUNCTION "public"."use_detector"("p_game_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_detector"("p_game_id" "uuid") IS 'Use a detector in Minesweeper to flag a random mine. Shares hint counter (max 3). Priority: 1) VIP detector card, 2) Gidouilles (10.0 cost). Logs to gidouilles_activity.';



CREATE OR REPLACE FUNCTION "public"."use_hint"("p_game_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_hints_used INTEGER;
  v_reduced_penalty_hints INTEGER;
  v_current_balance NUMERIC(10,2);
  v_hint_instance_id TEXT;
  v_consume_result JSONB;
  v_hint_cost NUMERIC(10,2) := 5.0;
  v_penalty_notice TEXT;
  v_vip_cards JSONB;
BEGIN
  -- Step 1: Verify game ownership and get current state
  SELECT student_id, COALESCE(hints_used, 0), COALESCE(reduced_penalty_hints, 0)
  INTO v_student_id, v_hints_used, v_reduced_penalty_hints
  FROM public.minesweeper_games
  WHERE id = p_game_id
    AND student_id = auth.uid()
    AND status = 'in_progress'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Game not found, not owned by you, or not in progress';
  END IF;

  -- Step 2: Check hint limit
  IF v_hints_used >= 3 THEN
    RAISE EXCEPTION 'Maximum hints reached (3 per game)';
  END IF;

  -- Step 3: Find an available minesweeper hint VIP card instance
  -- Smart selection: prefer already-started card, then minimum charges
  SELECT vip_cards INTO v_vip_cards
  FROM public.profiles
  WHERE id = v_student_id;

  IF v_vip_cards IS NOT NULL THEN
    SELECT key INTO v_hint_instance_id
    FROM jsonb_each(v_vip_cards) AS cards(key, value)
    LEFT JOIN public.vip_card_templates t ON t.id = value->>'cardId'
    WHERE value->>'cardId' LIKE 'minesweeper-hint%'
      AND (value->>'usedAt') IS NULL
      AND (
        (value->>'usesRemaining') IS NULL
        OR (value->>'usesRemaining')::INTEGER > 0
      )
    ORDER BY
      CASE
        WHEN (value->>'usesRemaining') IS NOT NULL
         AND t.uses_total IS NOT NULL
         AND (value->>'usesRemaining')::INTEGER < t.uses_total
        THEN 0
        ELSE 1
      END ASC,
      COALESCE((value->>'usesRemaining')::INTEGER, 1) ASC
    LIMIT 1;
  END IF;

  -- Step 4: If we found a card, consume it via use_vip_card()
  IF v_hint_instance_id IS NOT NULL THEN
    v_consume_result := public.use_vip_card(v_student_id, v_hint_instance_id, NULL, NULL, 'minesweeper');

    IF (v_consume_result->>'success')::BOOLEAN THEN
      UPDATE public.minesweeper_games
      SET hints_used = v_hints_used + 1,
          reduced_penalty_hints = v_reduced_penalty_hints + 1
      WHERE id = p_game_id;

      RETURN jsonb_build_object(
        'success', true,
        'hints_used', v_hints_used + 1,
        'hints_remaining', 2 - v_hints_used,
        'source', 'vip_card',
        'item_consumed', false,
        'vip_card_consumed', true,
        'gidouilles_spent', 0,
        'penalty_notice', 'Carte VIP utilisee - penalite reduite (5/11/17%)'
      );
    END IF;
  END IF;

  -- Step 5: No VIP card available - use gidouilles (costs 5g)
  SELECT gidouilles INTO v_current_balance
  FROM public.profiles
  WHERE id = v_student_id
  FOR UPDATE;

  IF v_current_balance < v_hint_cost THEN
    RAISE EXCEPTION 'Insufficient gidouilles. Required: %, Available: %', v_hint_cost, v_current_balance;
  END IF;

  UPDATE public.profiles
  SET gidouilles = gidouilles - v_hint_cost
  WHERE id = v_student_id;

  INSERT INTO public.gidouilles_activity (student_id, delta, reason)
  VALUES (v_student_id, -v_hint_cost, 'Indice Demineur');

  UPDATE public.minesweeper_games
  SET hints_used = v_hints_used + 1
  WHERE id = p_game_id;

  RETURN jsonb_build_object(
    'success', true,
    'hints_used', v_hints_used + 1,
    'hints_remaining', 2 - v_hints_used,
    'source', 'gidouilles',
    'item_consumed', false,
    'vip_card_consumed', false,
    'gidouilles_spent', v_hint_cost,
    'remaining_gidouilles', v_current_balance - v_hint_cost,
    'penalty_notice', 'Gidouilles utilisees - penalite progressive (10/22/35%)'
  );
END;
$$;


ALTER FUNCTION "public"."use_hint"("p_game_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_hint"("p_game_id" "uuid") IS 'Use a hint in Minesweeper. Smart card selection: prefers already-started hint cards, then fewest charges. Priority: 1) VIP hint card, 2) Gidouilles (5.0 cost). Logs to gidouilles_activity.';



CREATE OR REPLACE FUNCTION "public"."use_item"("p_inventory_id" "uuid", "p_context" "text", "p_usage_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_inventory RECORD;
    v_template RECORD;
    v_effect JSONB;
    v_remaining_uses INTEGER;
BEGIN
    -- Get inventory and template details
    SELECT
        i.*,
        t.category,
        t.item_type,
        t.properties,
        t.display_name
    INTO v_inventory
    FROM student_item_inventory i
    JOIN shop_item_templates t ON t.id = i.template_id
    WHERE i.id = p_inventory_id
    AND i.student_id = auth.uid();

    IF v_inventory IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Article non trouvé dans votre inventaire'
        );
    END IF;

    -- Check if item is locked
    IF v_inventory.is_locked THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Cet article est verrouillé pour une transaction'
        );
    END IF;

    -- Check if item is consumable
    IF v_inventory.category != 'consumable' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Cet article n''est pas consommable'
        );
    END IF;

    -- Check if item can be used in this context
    IF v_inventory.properties->>'game' IS NOT NULL AND
       v_inventory.properties->>'game' != p_context THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Cet article ne peut être utilisé que dans %s', v_inventory.properties->>'game')
        );
    END IF;

    -- Apply the effect based on item type
    v_effect := jsonb_build_object(
        'type', v_inventory.item_type,
        'context', p_context,
        'applied_at', NOW()
    );

    -- Handle multi-use items
    IF v_inventory.uses_remaining IS NOT NULL THEN
        v_remaining_uses := v_inventory.uses_remaining - 1;

        IF v_remaining_uses > 0 THEN
            -- Decrement uses
            UPDATE student_item_inventory
            SET uses_remaining = v_remaining_uses,
                last_used_at = NOW(),
                total_uses_count = total_uses_count + 1,
                updated_at = NOW()
            WHERE id = p_inventory_id;
        ELSE
            -- Last use - remove from inventory
            DELETE FROM student_item_inventory
            WHERE id = p_inventory_id;
            v_remaining_uses := 0;
        END IF;
    ELSE
        -- Single use item - handle quantity
        IF v_inventory.quantity > 1 THEN
            -- Decrement quantity
            UPDATE student_item_inventory
            SET quantity = quantity - 1,
                last_used_at = NOW(),
                total_uses_count = total_uses_count + 1,
                updated_at = NOW()
            WHERE id = p_inventory_id;
            v_remaining_uses := v_inventory.quantity - 1;
        ELSE
            -- Last item - remove from inventory
            DELETE FROM student_item_inventory
            WHERE id = p_inventory_id;
            v_remaining_uses := 0;
        END IF;
    END IF;

    -- Log the usage
    INSERT INTO item_usage_log (
        student_id,
        inventory_id,
        template_id,
        usage_context,
        usage_data,
        effect_applied
    ) VALUES (
        v_inventory.student_id,
        p_inventory_id,
        v_inventory.template_id,
        p_context,
        p_usage_data,
        v_effect
    );

    RETURN jsonb_build_object(
        'success', true,
        'effect', v_effect,
        'remaining_uses', v_remaining_uses,
        'item_name', v_inventory.display_name
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Erreur lors de l''utilisation de l''article',
            'details', SQLERRM
        );
END;
$$;


ALTER FUNCTION "public"."use_item"("p_inventory_id" "uuid", "p_context" "text", "p_usage_data" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_item"("p_inventory_id" "uuid", "p_context" "text", "p_usage_data" "jsonb") IS 'Use a consumable item from inventory with effect tracking';



CREATE OR REPLACE FUNCTION "public"."use_mathemo_power"("p_power_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_student_id UUID;
    v_role TEXT;
    v_cost INTEGER;
    v_current_gidouilles INTEGER;
    v_new_gidouilles INTEGER;
    v_class_id UUID;
BEGIN
    -- 1. Auth check: must be a student
    v_student_id := auth.uid();
    IF v_student_id IS NULL THEN
        RAISE EXCEPTION 'Authentification requise';
    END IF;

    SELECT role INTO v_role FROM public.profiles WHERE id = v_student_id;
    IF v_role != 'student' THEN
        RAISE EXCEPTION 'Seuls les eleves peuvent utiliser les pouvoirs';
    END IF;

    -- 2. Validate power type and get cost
    v_cost := CASE p_power_type
        WHEN 'letter' THEN 5
        WHEN 'undo' THEN 5
        WHEN 'vowels' THEN 8
        WHEN 'multiplier' THEN 15
        ELSE NULL
    END;

    IF v_cost IS NULL THEN
        RAISE EXCEPTION 'Type de pouvoir invalide: %', p_power_type;
    END IF;

    -- 3. Check sufficient gidouilles
    SELECT COALESCE(gidouilles, 0) INTO v_current_gidouilles
    FROM public.profiles WHERE id = v_student_id;

    IF v_current_gidouilles < v_cost THEN
        RAISE EXCEPTION 'Pas assez de gidouilles (disponible: %, requis: %)', v_current_gidouilles, v_cost;
    END IF;

    -- 4. Get student's active class
    SELECT cm.class_id INTO v_class_id
    FROM public.class_members cm
    WHERE cm.student_id = v_student_id
    AND cm.status = 'active'
    LIMIT 1;

    IF v_class_id IS NULL THEN
        RAISE EXCEPTION 'Pas de classe active trouvee';
    END IF;

    -- 5. Debit gidouilles atomically
    UPDATE public.profiles
    SET gidouilles = gidouilles - v_cost
    WHERE id = v_student_id
    AND gidouilles >= v_cost
    RETURNING gidouilles INTO v_new_gidouilles;

    IF v_new_gidouilles IS NULL THEN
        RAISE EXCEPTION 'Pas assez de gidouilles';
    END IF;

    -- 6. Log in activity
    INSERT INTO public.gidouilles_activity (
        student_id,
        class_id,
        delta,
        reason,
        created_by
    ) VALUES (
        v_student_id,
        v_class_id,
        -v_cost,
        'mathemo power: ' || p_power_type,
        v_student_id
    );

    -- 7. Return result
    RETURN jsonb_build_object(
        'success', true,
        'source', 'gidouilles',
        'gidouilles_spent', v_cost,
        'gidouilles_remaining', v_new_gidouilles
    );
END;
$$;


ALTER FUNCTION "public"."use_mathemo_power"("p_power_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_mathemo_power"("p_power_type" "text") IS 'Debit gidouilles for a Mathemo power (fallback when no VIP card). SECURITY DEFINER for atomic debit + logging.';



CREATE OR REPLACE FUNCTION "public"."use_minesweeper_undo"("p_game_id" "uuid", "p_grid_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_undo_used BOOLEAN;
  v_instance_id TEXT;
  v_consume_result JSONB;
  v_vip_cards JSONB;
BEGIN
  -- CONCURRENCY NOTE:
  -- Lock order: minesweeper_games (FOR UPDATE here) -> profiles (FOR UPDATE inside
  -- use_vip_card). This consistent ordering prevents deadlocks.

  -- Step 1: Verify game ownership, status, and undo not yet used
  SELECT student_id, COALESCE(undo_used, false)
  INTO v_student_id, v_undo_used
  FROM public.minesweeper_games
  WHERE id = p_game_id
    AND student_id = auth.uid()
    AND status = 'in_progress'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Partie non trouvee, pas la votre, ou plus en cours'
    );
  END IF;

  IF v_undo_used THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Seconde Chance deja utilisee dans cette partie'
    );
  END IF;

  -- Step 2: Find oldest unused minesweeper-undo VIP card instance (FIFO)
  SELECT vip_cards INTO v_vip_cards
  FROM public.profiles
  WHERE id = v_student_id;

  IF v_vip_cards IS NOT NULL THEN
    SELECT key INTO v_instance_id
    FROM jsonb_each(v_vip_cards) AS cards(key, value)
    WHERE value->>'cardId' = 'minesweeper-undo'
      AND (value->>'usedAt') IS NULL
      AND (
        (value->>'usesRemaining') IS NULL
        OR (value->>'usesRemaining')::INTEGER > 0
      )
    ORDER BY (value->>'earnedAt')::TIMESTAMPTZ ASC
    LIMIT 1;
  END IF;

  -- Step 3: No card available -> fail (no gidouilles fallback)
  IF v_instance_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Aucune carte Seconde Chance disponible'
    );
  END IF;

  -- Step 4: Consume the card via use_vip_card()
  v_consume_result := public.use_vip_card(v_student_id, v_instance_id, NULL, NULL, 'minesweeper');

  IF NOT (v_consume_result->>'success')::BOOLEAN THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_consume_result->>'error', 'Echec de la consommation de la carte Seconde Chance')
    );
  END IF;

  -- Step 5: Update game state (no updated_at column in minesweeper_games)
  UPDATE public.minesweeper_games
  SET undo_used = true,
      grid_state = p_grid_state
  WHERE id = p_game_id;

  RETURN jsonb_build_object(
    'success', true,
    'source', 'vip_card',
    'message', 'Seconde Chance utilisee avec succes'
  );
END;
$$;


ALTER FUNCTION "public"."use_minesweeper_undo"("p_game_id" "uuid", "p_grid_state" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_minesweeper_undo"("p_game_id" "uuid", "p_grid_state" "jsonb") IS 'Uses a "Seconde Chance" VIP card in a Minesweeper game. Consumes the card via use_vip_card() and marks the game as having used undo. No gidouilles fallback.';



CREATE OR REPLACE FUNCTION "public"."use_vip_card"("p_student_id" "uuid", "p_instance_id" "text" DEFAULT NULL::"text", "p_card_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb", "p_context" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id UUID;
  v_vip_cards JSONB;
  v_instance_id TEXT;
  v_card_data JSONB;
  v_card_id TEXT;
  v_template RECORD;
  v_now TIMESTAMPTZ := NOW();
  v_now_str TEXT;
  v_oldest_instance_id TEXT;
  v_oldest_date TIMESTAMPTZ;
  v_loop_key TEXT;
  v_audit_metadata JSONB;
  v_uses_remaining INTEGER;
  v_is_fully_consumed BOOLEAN;
  v_use_number INTEGER;
  v_action_context TEXT;
BEGIN
  -- ========================================================================
  -- PARAMETER VALIDATION
  -- ========================================================================

  IF p_instance_id IS NULL AND p_card_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Either p_instance_id or p_card_id must be provided'
    );
  END IF;

  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Authentication required'
    );
  END IF;

  -- ========================================================================
  -- AUTHORIZATION
  -- ========================================================================

  IF v_caller_id != p_student_id THEN
    IF NOT is_teacher_or_admin() THEN
      RETURN jsonb_build_object(
        'success', FALSE,
        'error', 'Unauthorized: Only the card owner or a teacher can use cards'
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM class_members cm
      INNER JOIN classes c ON c.id = cm.class_id
      WHERE cm.student_id = p_student_id
        AND c.teacher_id = v_caller_id
        AND cm.status = 'active'
    ) THEN
      RETURN jsonb_build_object(
        'success', FALSE,
        'error', 'Unauthorized: Student is not in your active classes'
      );
    END IF;
  END IF;

  -- ========================================================================
  -- GET AND LOCK STUDENT'S VIP CARDS
  -- ========================================================================

  SELECT vip_cards INTO v_vip_cards
  FROM profiles
  WHERE id = p_student_id
  FOR UPDATE;

  IF v_vip_cards IS NULL THEN
    v_vip_cards := '{}'::JSONB;
  END IF;

  -- ========================================================================
  -- RESOLVE CARD INSTANCE (by instance_id or card_id FIFO)
  -- ========================================================================

  IF p_instance_id IS NOT NULL THEN
    v_instance_id := p_instance_id;
  ELSE
    FOR v_loop_key IN
      SELECT key FROM jsonb_each(v_vip_cards)
    LOOP
      DECLARE
        v_loop_data JSONB;
        v_loop_card_id TEXT;
        v_loop_used_at TEXT;
        v_loop_earned_at TIMESTAMPTZ;
        v_loop_uses_remaining INTEGER;
      BEGIN
        v_loop_data := v_vip_cards->v_loop_key;
        v_loop_card_id := v_loop_data->>'cardId';
        v_loop_used_at := v_loop_data->>'usedAt';

        IF v_loop_card_id = p_card_id AND v_loop_used_at IS NULL THEN
          v_loop_uses_remaining := (v_loop_data->>'usesRemaining')::INTEGER;
          IF v_loop_uses_remaining IS NOT NULL AND v_loop_uses_remaining <= 0 THEN
            CONTINUE;
          END IF;

          v_loop_earned_at := (v_loop_data->>'earnedAt')::TIMESTAMPTZ;

          IF v_oldest_date IS NULL OR v_loop_earned_at < v_oldest_date THEN
            v_oldest_date := v_loop_earned_at;
            v_oldest_instance_id := v_loop_key;
          END IF;
        END IF;
      END;
    END LOOP;

    IF v_oldest_instance_id IS NULL THEN
      RETURN jsonb_build_object(
        'success', FALSE,
        'error', 'No unused instance found for card: ' || COALESCE(p_card_id, 'unknown')
      );
    END IF;

    v_instance_id := v_oldest_instance_id;
  END IF;

  -- ========================================================================
  -- VALIDATE CARD INSTANCE
  -- ========================================================================

  v_card_data := v_vip_cards->v_instance_id;

  IF v_card_data IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card instance not found: ' || v_instance_id
    );
  END IF;

  IF v_card_data->>'usedAt' IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card has already been used'
    );
  END IF;

  v_card_id := v_card_data->>'cardId';

  -- ========================================================================
  -- GET TEMPLATE (for name, action->context, uses_total)
  -- ========================================================================

  SELECT id, name, action, uses_total INTO v_template
  FROM vip_card_templates
  WHERE id = v_card_id;

  IF v_template IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card template not found: ' || v_card_id
    );
  END IF;

  -- ========================================================================
  -- VALIDATE ACTIVATION CONTEXT (read from action JSONB)
  -- ========================================================================

  v_action_context := v_template.action->>'context';

  IF v_action_context IS NOT NULL AND v_action_context != 'any' THEN
    IF p_context IS NULL OR p_context != v_action_context THEN
      RETURN jsonb_build_object(
        'success', FALSE,
        'error', 'This card requires context: ' || v_action_context
      );
    END IF;
  END IF;

  -- ========================================================================
  -- PROCESS CARD USE (unified single-use / multi-use logic)
  -- ========================================================================

  v_uses_remaining := COALESCE((v_card_data->>'usesRemaining')::INTEGER, 1);

  IF v_uses_remaining <= 0 THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'Card has no remaining uses'
    );
  END IF;

  v_use_number := COALESCE(v_template.uses_total, 1) - v_uses_remaining + 1;
  v_uses_remaining := v_uses_remaining - 1;
  v_is_fully_consumed := (v_uses_remaining = 0);

  v_now_str := to_char(v_now, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');

  IF v_is_fully_consumed THEN
    v_card_data := v_card_data
      - 'activationRequestedAt'
      - 'activationRequestedBy'
      - 'activationApprovedAt'
      - 'activationApprovedBy'
      || jsonb_build_object(
        'usedAt', v_now_str,
        'usesRemaining', 0
      );
  ELSE
    v_card_data := v_card_data || jsonb_build_object(
      'usesRemaining', v_uses_remaining
    );
  END IF;

  v_vip_cards := jsonb_set(v_vip_cards, ARRAY[v_instance_id], v_card_data);

  -- ========================================================================
  -- UPDATE PROFILE
  -- ========================================================================

  UPDATE profiles
  SET vip_cards = v_vip_cards, updated_at = v_now
  WHERE id = p_student_id;

  -- ========================================================================
  -- AUDIT TRAIL
  -- ========================================================================

  v_audit_metadata := jsonb_build_object(
    'used_at', v_now_str,
    'usesRemaining', v_uses_remaining,
    'useNumber', v_use_number,
    'totalUses', COALESCE(v_template.uses_total, 1),
    'fullyConsumed', v_is_fully_consumed,
    'context', p_context
  ) || COALESCE(p_metadata, '{}'::JSONB);

  INSERT INTO public.vip_cards_activity (
    student_id, card_instance_id, card_template_id, action, metadata
  ) VALUES (
    p_student_id, v_instance_id, v_card_id, 'used',
    v_audit_metadata
  );

  -- ========================================================================
  -- RETURN UNIFIED RESULT
  -- ========================================================================

  RETURN jsonb_build_object(
    'success', TRUE,
    'cardName', v_template.name,
    'instanceId', v_instance_id,
    'cardId', v_card_id,
    'usesRemaining', v_uses_remaining,
    'isFullyConsumed', v_is_fully_consumed,
    'usedAt', CASE WHEN v_is_fully_consumed THEN v_now_str ELSE NULL END
  );
END;
$$;


ALTER FUNCTION "public"."use_vip_card"("p_student_id" "uuid", "p_instance_id" "text", "p_card_id" "text", "p_metadata" "jsonb", "p_context" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."use_vip_card"("p_student_id" "uuid", "p_instance_id" "text", "p_card_id" "text", "p_metadata" "jsonb", "p_context" "text") IS 'Unified RPC to mark a VIP card instance as used.
Supports both student self-use and teacher/admin use.
Handles single-use and multi-use cards uniformly.
Context check: verifies p_context matches action->>context (if set).
Game-specific validations are the responsibility of the calling RPC.
Lookup by instance_id (direct) or card_id (FIFO oldest unused).';



CREATE OR REPLACE FUNCTION "public"."validate_1on1_chat_creation"("p_user1_id" "uuid", "p_user2_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_are_friends BOOLEAN;
  v_existing_conversation UUID;
BEGIN
  -- Check if users are friends
  SELECT EXISTS (
    SELECT 1 FROM friendships
    WHERE (
      (requester_id = p_user1_id AND addressee_id = p_user2_id)
      OR (requester_id = p_user2_id AND addressee_id = p_user1_id)
    )
    AND status = 'accepted'
  ) INTO v_are_friends;

  IF NOT v_are_friends THEN
    RAISE EXCEPTION 'Users must be friends to create a 1-on-1 chat';
  END IF;

  -- Check if conversation already exists between these two users
  SELECT c.id INTO v_existing_conversation
  FROM conversations c
  WHERE c.is_group = false
  AND EXISTS (
    SELECT 1 FROM conversation_participants cp1
    WHERE cp1.conversation_id = c.id
    AND cp1.user_id = p_user1_id
  )
  AND EXISTS (
    SELECT 1 FROM conversation_participants cp2
    WHERE cp2.conversation_id = c.id
    AND cp2.user_id = p_user2_id
  )
  LIMIT 1;

  IF v_existing_conversation IS NOT NULL THEN
    RAISE EXCEPTION 'Conversation already exists between these users';
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."validate_1on1_chat_creation"("p_user1_id" "uuid", "p_user2_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_1on1_chat_creation"("p_user1_id" "uuid", "p_user2_id" "uuid") IS 'Validates that users are friends and no duplicate chat exists';



CREATE OR REPLACE FUNCTION "public"."validate_attachment_upload"("p_message_id" "uuid", "p_user_id" "uuid", "p_file_size" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_teacher BOOLEAN;
  v_is_participant BOOLEAN;
BEGIN
  -- Check if user is a teacher
  SELECT role IN ('teacher', 'admin') INTO v_is_teacher
  FROM profiles
  WHERE id = p_user_id;

  IF NOT v_is_teacher THEN
    RAISE EXCEPTION 'Only teachers can upload files';
  END IF;

  -- Check file size (1MB = 1048576 bytes)
  IF p_file_size > 1048576 THEN
    RAISE EXCEPTION 'File size exceeds 1MB limit';
  END IF;

  -- Check if user is a participant in the conversation
  SELECT EXISTS (
    SELECT 1
    FROM messages m
    JOIN conversation_participants cp ON cp.conversation_id = m.conversation_id
    WHERE m.id = p_message_id
    AND cp.user_id = p_user_id
  ) INTO v_is_participant;

  IF NOT v_is_participant THEN
    RAISE EXCEPTION 'User is not a participant in this conversation';
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."validate_attachment_upload"("p_message_id" "uuid", "p_user_id" "uuid", "p_file_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_attachment_upload"("p_message_id" "uuid", "p_user_id" "uuid", "p_file_size" integer) IS 'Validates file upload permissions and size limit';



CREATE OR REPLACE FUNCTION "public"."validate_class_message_recipients"("sender_uuid" "uuid", "class_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  sender_role TEXT;
  class_teacher_id UUID;
BEGIN
  -- Get sender's role
  SELECT role INTO sender_role
  FROM profiles
  WHERE id = sender_uuid;

  -- Only teachers can send class messages
  IF sender_role != 'teacher' AND sender_role != 'admin' THEN
    RETURN FALSE;
  END IF;

  -- Check if sender is the teacher of this class
  SELECT teacher_id INTO class_teacher_id
  FROM classes
  WHERE id = class_uuid
    AND is_active = TRUE;

  IF class_teacher_id IS NULL THEN
    RETURN FALSE; -- Class doesn't exist or is inactive
  END IF;

  -- Teacher must be the owner of the class (or admin)
  IF sender_role = 'admin' OR sender_uuid = class_teacher_id THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."validate_class_message_recipients"("sender_uuid" "uuid", "class_uuid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_class_message_recipients"("sender_uuid" "uuid", "class_uuid" "uuid") IS 'Validates that a teacher can send a group message to a specific class';



CREATE OR REPLACE FUNCTION "public"."validate_locked_entity_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    -- Check if entity exists in either marketplace_listings or marketplace_trades
    IF NOT EXISTS (
        SELECT 1 FROM public.marketplace_listings WHERE id = NEW.locked_entity_id
    ) AND NOT EXISTS (
        SELECT 1 FROM public.marketplace_trades WHERE id = NEW.locked_entity_id
    ) THEN
        RAISE EXCEPTION 'locked_entity_id % does not exist in marketplace_listings or marketplace_trades', NEW.locked_entity_id;
    END IF;

    -- Validate locked_for matches the actual entity type
    IF NEW.locked_for = 'listing' AND NOT EXISTS (
        SELECT 1 FROM public.marketplace_listings WHERE id = NEW.locked_entity_id
    ) THEN
        RAISE EXCEPTION 'locked_entity_id % is not a valid listing', NEW.locked_entity_id;
    END IF;

    IF NEW.locked_for = 'trade' AND NOT EXISTS (
        SELECT 1 FROM public.marketplace_trades WHERE id = NEW.locked_entity_id
    ) THEN
        RAISE EXCEPTION 'locked_entity_id % is not a valid trade', NEW.locked_entity_id;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_locked_entity_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_message_recipients"("sender_uuid" "uuid", "recipient_uuids" "uuid"[]) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  sender_role TEXT;
  recipient_uuid UUID;
  allowed_recipients UUID[];
BEGIN
  -- Get sender's role
  SELECT role INTO sender_role
  FROM profiles
  WHERE id = sender_uuid;

  IF sender_role IS NULL THEN
    RETURN FALSE; -- Sender doesn't exist
  END IF;

  -- Check if recipients array is empty
  IF array_length(recipient_uuids, 1) IS NULL OR array_length(recipient_uuids, 1) = 0 THEN
    RETURN FALSE; -- Must have at least one recipient
  END IF;

  -- STUDENTS can only message their TEACHERS
  IF sender_role = 'student' THEN
    -- Get all teacher IDs for this student
    SELECT array_agg(teacher_id)
    INTO allowed_recipients
    FROM get_student_teachers(sender_uuid);

    -- Check if all recipients are in the allowed list
    FOREACH recipient_uuid IN ARRAY recipient_uuids
    LOOP
      IF NOT (recipient_uuid = ANY(allowed_recipients)) THEN
        RETURN FALSE; -- This recipient is not one of student's teachers
      END IF;
    END LOOP;

    RETURN TRUE;
  END IF;

  -- TEACHERS can only message their STUDENTS
  IF sender_role = 'teacher' THEN
    -- Get all student IDs for this teacher
    SELECT array_agg(student_id)
    INTO allowed_recipients
    FROM get_teacher_students(sender_uuid);

    -- Check if all recipients are in the allowed list
    FOREACH recipient_uuid IN ARRAY recipient_uuids
    LOOP
      IF NOT (recipient_uuid = ANY(allowed_recipients)) THEN
        RETURN FALSE; -- This recipient is not one of teacher's students
      END IF;
    END LOOP;

    RETURN TRUE;
  END IF;

  -- ADMINS can message anyone (future-proof)
  IF sender_role = 'admin' THEN
    RETURN TRUE;
  END IF;

  -- Other roles cannot send messages
  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."validate_message_recipients"("sender_uuid" "uuid", "recipient_uuids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_message_recipients"("sender_uuid" "uuid", "recipient_uuids" "uuid"[]) IS 'Validates messaging permissions: students can only message teachers, teachers can only message students';



CREATE OR REPLACE FUNCTION "public"."validate_minesweeper_win"("p_grid_state" "jsonb", "p_difficulty" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_rows INTEGER;
  v_cols INTEGER;
  v_expected_rows INTEGER;
  v_expected_cols INTEGER;
  v_expected_mines INTEGER;
  v_total_cells INTEGER;
  v_mines_count INTEGER;
  v_revealed_count INTEGER;
  v_flagged_count INTEGER;
  v_grid_size INTEGER;
BEGIN
  -- Validate grid_state is not null and is an object
  IF p_grid_state IS NULL OR jsonb_typeof(p_grid_state) != 'object' THEN
    RETURN FALSE;
  END IF;

  -- Validate grid_state size (prevent DoS via huge payloads)
  v_grid_size := pg_column_size(p_grid_state);
  IF v_grid_size > 100000 THEN -- 100KB limit
    RETURN FALSE;
  END IF;

  -- Extract dimensions
  v_rows := (p_grid_state->>'rows')::INTEGER;
  v_cols := (p_grid_state->>'cols')::INTEGER;

  -- Validate difficulty and expected dimensions
  CASE p_difficulty
    WHEN 'beginner' THEN
      v_expected_rows := 9;
      v_expected_cols := 9;
      v_expected_mines := 10;
    WHEN 'intermediate' THEN
      v_expected_rows := 16;
      v_expected_cols := 16;
      v_expected_mines := 40;
    WHEN 'expert' THEN
      v_expected_rows := 16;
      v_expected_cols := 30;
      v_expected_mines := 99;
    ELSE
      RETURN FALSE; -- Invalid difficulty
  END CASE;

  -- Verify dimensions match difficulty preset
  IF v_rows != v_expected_rows OR v_cols != v_expected_cols THEN
    RETURN FALSE;
  END IF;

  v_total_cells := v_rows * v_cols;

  -- Validate required fields exist
  IF NOT (
    p_grid_state ? 'mines' AND
    p_grid_state ? 'revealed' AND
    p_grid_state ? 'flagged' AND
    p_grid_state ? 'adjacentCounts'
  ) THEN
    RETURN FALSE;
  END IF;

  -- Count mines
  v_mines_count := jsonb_array_length(p_grid_state->'mines');
  IF v_mines_count != v_expected_mines THEN
    RETURN FALSE; -- Mine count mismatch
  END IF;

  -- Count revealed cells
  v_revealed_count := jsonb_array_length(p_grid_state->'revealed');

  -- Count flagged cells
  v_flagged_count := jsonb_array_length(p_grid_state->'flagged');

  -- Validate counts are reasonable
  IF v_revealed_count < 0 OR v_revealed_count > v_total_cells THEN
    RETURN FALSE;
  END IF;

  IF v_flagged_count < 0 OR v_flagged_count > v_expected_mines * 2 THEN
    RETURN FALSE; -- Too many flags
  END IF;

  -- WIN CONDITION VALIDATION:
  -- All non-mine cells must be revealed
  -- Total cells = revealed + mines (flagged cells can overlap with mines or revealed)
  IF v_revealed_count != (v_total_cells - v_expected_mines) THEN
    RETURN FALSE; -- Not all safe cells revealed
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."validate_minesweeper_win"("p_grid_state" "jsonb", "p_difficulty" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_minesweeper_win"("p_grid_state" "jsonb", "p_difficulty" "text") IS 'Validates that a grid_state represents a legitimate win condition. Checks dimensions, mine count, and that all non-mine cells are revealed. IMMUTABLE for query optimization.';



CREATE OR REPLACE FUNCTION "public"."validate_riddle_attempt"("p_attempt_id" "uuid", "p_teacher_id" "uuid", "p_is_correct" boolean) RETURNS TABLE("success" boolean, "theoretical_reward" numeric, "actual_reward" numeric, "is_first_win" boolean, "week_best_reward" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id UUID;
  v_riddle_id UUID;
  v_difficulty INTEGER;
  v_attempt_number INTEGER;
  v_theoretical_gidouilles NUMERIC(10,2);
  v_actual_gidouilles NUMERIC(10,2);
  v_is_first_win BOOLEAN;
  v_week_best NUMERIC(10,2);
  v_school_id UUID;
  v_daily_result RECORD;
BEGIN
  -- Get attempt details
  SELECT ra.student_id, ra.riddle_id, ra.attempt_number
  INTO v_student_id, v_riddle_id, v_attempt_number
  FROM riddle_attempts ra
  WHERE ra.id = p_attempt_id AND ra.is_correct IS NULL; -- Only validate pending attempts

  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'Attempt not found or already validated';
  END IF;

  -- Verify teacher has permission (owns a class with this student)
  IF NOT EXISTS (
    SELECT 1 FROM class_members cm
    JOIN classes c ON c.id = cm.class_id
    WHERE cm.student_id = v_student_id AND c.teacher_id = p_teacher_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: You do not teach this student';
  END IF;

  -- Get riddle difficulty
  SELECT difficulty INTO v_difficulty
  FROM riddles
  WHERE id = v_riddle_id;

  -- Get student's school_id
  SELECT DISTINCT c.school_id INTO v_school_id
  FROM class_members cm
  JOIN classes c ON c.id = cm.class_id
  WHERE cm.student_id = v_student_id
    AND cm.status = 'active'
  LIMIT 1;

  -- Calculate theoretical reward if correct
  IF p_is_correct THEN
    v_theoretical_gidouilles := public.calculate_riddle_gidouilles(v_difficulty, v_attempt_number)::NUMERIC(10,2);
  ELSE
    v_theoretical_gidouilles := 0;
  END IF;

  -- Update attempt
  UPDATE riddle_attempts
  SET
    is_correct = p_is_correct,
    validated_at = now(),
    validated_by = p_teacher_id
  WHERE id = p_attempt_id;

  -- If correct and has school, use daily limit system
  IF p_is_correct AND v_theoretical_gidouilles > 0 AND v_school_id IS NOT NULL THEN
    SELECT * INTO v_daily_result
    FROM public.record_game_reward(
      v_student_id,
      'riddle',
      p_attempt_id,
      v_theoretical_gidouilles,
      v_school_id
    );

    v_actual_gidouilles := COALESCE(v_daily_result.actual_reward, 0);
    v_is_first_win := COALESCE(v_daily_result.is_first_win, FALSE);
    v_week_best := COALESCE(v_daily_result.week_best_reward, v_theoretical_gidouilles);

    -- Update attempt with actual reward
    UPDATE riddle_attempts
    SET gidouilles_awarded = v_actual_gidouilles::INTEGER
    WHERE id = p_attempt_id;
  ELSE
    v_actual_gidouilles := 0;
    v_is_first_win := FALSE;
    v_week_best := 0;
  END IF;

  RETURN QUERY SELECT
    TRUE,
    v_theoretical_gidouilles,
    v_actual_gidouilles,
    v_is_first_win,
    v_week_best;
END;
$$;


ALTER FUNCTION "public"."validate_riddle_attempt"("p_attempt_id" "uuid", "p_teacher_id" "uuid", "p_is_correct" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_riddle_attempt"("p_attempt_id" "uuid", "p_teacher_id" "uuid", "p_is_correct" boolean) IS 'Teacher validates a riddle attempt with daily limit system.

   Returns:
     - success: Always true if no exception
     - theoretical_reward: What student would have earned
     - actual_reward: What student actually earned (0 or 1)
     - is_first_win: Whether this was first win today
     - week_best_reward: Student best theoretical reward this week';



