COMMENT ON COLUMN "public"."exercise_assignments"."is_active" IS 'Whether assignment is active (false = hidden from students)';



COMMENT ON CONSTRAINT "assignment_student_consistency" ON "public"."exercise_assignments" IS 'Ensures assignment type matches populated foreign keys: student_id for student, class_id for class, neither for public';



CREATE TABLE IF NOT EXISTS "public"."exercise_completions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "exercise_id" "uuid" NOT NULL,
    "assignment_id" "uuid",
    "student_id" "uuid" NOT NULL,
    "completed_at" timestamp with time zone,
    "last_viewed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "view_count" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "exercise_completions_view_count_check" CHECK (("view_count" >= 1))
);


ALTER TABLE "public"."exercise_completions" OWNER TO "postgres";


COMMENT ON TABLE "public"."exercise_completions" IS 'Track student views and completion of exercises';



COMMENT ON COLUMN "public"."exercise_completions"."assignment_id" IS 'Links to assignment if completion is from an assignment. NULL if student accessed exercise directly (e.g., public library). SET NULL on assignment deletion to preserve completion history.';



COMMENT ON COLUMN "public"."exercise_completions"."completed_at" IS 'When student marked exercise as complete (null if not completed)';



COMMENT ON COLUMN "public"."exercise_completions"."last_viewed_at" IS 'Tracks most recent view for "recently viewed" features and activity monitoring';



COMMENT ON COLUMN "public"."exercise_completions"."view_count" IS 'Number of times student has viewed this exercise';



CREATE TABLE IF NOT EXISTS "public"."exercises" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text",
    "source" "text",
    "grades" "text"[],
    "topic" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "is_public" boolean DEFAULT false NOT NULL,
    "variables" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "distribution_mode" "text" DEFAULT 'on_demand'::"text" NOT NULL,
    "slug" "text",
    "resources" "jsonb" DEFAULT '[]'::"jsonb",
    "generic_functions" "text"[],
    "variations" "jsonb",
    "shared" "jsonb",
    "category" "text" NOT NULL,
    CONSTRAINT "exercises_category_check" CHECK (("category" = ANY (ARRAY['automatisme'::"text", 'application'::"text", 'adaptation'::"text", 'recherche'::"text", 'tache_complexe'::"text", 'situation_probleme'::"text", 'challenge'::"text", 'mission'::"text", 'synthese'::"text"]))),
    CONSTRAINT "exercises_distribution_mode_valid" CHECK (("distribution_mode" = ANY (ARRAY['on_demand'::"text", 'per_student'::"text", 'per_group'::"text"]))),
    CONSTRAINT "exercises_shared_is_object" CHECK ((("shared" IS NULL) OR ("jsonb_typeof"("shared") = 'object'::"text"))),
    CONSTRAINT "exercises_valid_grades" CHECK ("public"."is_valid_grade_array"("grades")),
    CONSTRAINT "exercises_variables_is_array" CHECK (("jsonb_typeof"("variables") = 'array'::"text")),
    CONSTRAINT "exercises_variations_is_array" CHECK ((("variations" IS NULL) OR ("jsonb_typeof"("variations") = 'array'::"text")))
);


ALTER TABLE "public"."exercises" OWNER TO "postgres";


COMMENT ON TABLE "public"."exercises" IS 'Exercise content is stored in the variations JSONB column. Legacy statement_md/solution_md columns were removed in January 2026.';



COMMENT ON COLUMN "public"."exercises"."grades" IS 'Applicable grade levels using canonical GradeCode values: CP, CE1, CE2, CM1, CM2, 6, 5, 4, 3, 2, 1_GEN, T_GEN, 1_SPE, T_SPE, T_EXP, T_COMP, 1_STMG, T_STMG';



COMMENT ON COLUMN "public"."exercises"."is_public" IS 'When true, exercise is visible in the public library to all teachers';



COMMENT ON COLUMN "public"."exercises"."variables" IS 'JSONB array of variable definitions for parameterization. Each variable has: name (string) and expression (string). Expression can contain: literals, variable refs {{var}}, random specs {{1-10}}, or eval {{eval:expr}}';



COMMENT ON COLUMN "public"."exercises"."distribution_mode" IS 'How parameterized instances are distributed: on_demand (students generate anytime), per_student (unique deterministic per student), per_group (same instance for group)';



COMMENT ON COLUMN "public"."exercises"."slug" IS 'URL-friendly identifier: topic-nanoid format, editable by teacher';



COMMENT ON COLUMN "public"."exercises"."resources" IS 'Array of supplementary resources: [{ type, url, title, description? }]';



COMMENT ON COLUMN "public"."exercises"."generic_functions" IS 'Custom function identifiers to recognize in math expressions.
When set, these identifiers will be parsed as function calls (e.g., P(x), Q''(x))
instead of implicit multiplication.
- NULL/undefined: Use parser defaults (f, g, h, u, v, w, F, G, H)
- []: Disable generic function parsing entirely
- [''f'', ''P'', ''Q'']: Recognize only these identifiers as functions';



COMMENT ON COLUMN "public"."exercises"."variations" IS 'JSONB array of exercise variations. Each variation contains:
- label: string (unique identifier, e.g., "default", "variant_a")
- statement_md: string (exercise statement in markdown)
- solution_md: string (solution in markdown)
- variables: array (optional, variable definitions for parameterization)
- hints: array (optional, progressive hints)
One variation is selected when presenting the exercise.';



COMMENT ON COLUMN "public"."exercises"."shared" IS 'JSONB object with shared defaults applied to all variations:
- default_hints: array (hints shared across all variations)
- default_variables: array (common variable definitions)
- metadata: object (additional shared metadata)
Values in individual variations override these defaults.';



COMMENT ON COLUMN "public"."exercises"."category" IS 'Exercise category: automatisme, application, adaptation, recherche, tache_complexe, situation_probleme, challenge, mission, synthese';



COMMENT ON CONSTRAINT "exercises_distribution_mode_valid" ON "public"."exercises" IS 'Restricts distribution_mode to valid values: on_demand, per_student, per_group';



COMMENT ON CONSTRAINT "exercises_shared_is_object" ON "public"."exercises" IS 'Ensures shared column contains a JSON object when not null';



COMMENT ON CONSTRAINT "exercises_variables_is_array" ON "public"."exercises" IS 'Ensures variables column contains a JSON array, not object or other type';



COMMENT ON CONSTRAINT "exercises_variations_is_array" ON "public"."exercises" IS 'Ensures variations column contains a JSON array when not null';



