COMMENT ON TABLE "public"."srs_decks" IS 'SRS flashcard decks (official from bank or personal custom)';



COMMENT ON COLUMN "public"."srs_decks"."deck_type" IS 'official = from question bank, personal = custom student deck';



COMMENT ON COLUMN "public"."srs_decks"."is_assigned" IS 'true = assigned by teacher (read-only for student)';



COMMENT ON COLUMN "public"."srs_decks"."config" IS 'FSRS configuration (desiredRetention, parameters, maxInterval)';



COMMENT ON COLUMN "public"."srs_decks"."is_auto_managed" IS 'true = deck géré automatiquement par le système (cas du deck Programme). L''élève ne peut ni modifier ses cartes ni ajouter de sections manuelles. Refonte 2026-06-10.';



CREATE OR REPLACE VIEW "public"."admin_content_stats" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."exercises") AS "total_exercises",
    ( SELECT "count"(*) AS "count"
           FROM "public"."assessments") AS "total_assessments",
    ( SELECT "count"(*) AS "count"
           FROM "public"."riddles") AS "total_riddles",
    ( SELECT "count"(*) AS "count"
           FROM "public"."srs_decks") AS "total_srs_decks",
    ( SELECT "count"(*) AS "count"
           FROM "public"."exercise_assignments"
          WHERE ("exercise_assignments"."assigned_at" > ("now"() - '24:00:00'::interval))) AS "assignments_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."exercise_completions"
          WHERE ("exercise_completions"."completed_at" > ("now"() - '24:00:00'::interval))) AS "completions_24h";


ALTER VIEW "public"."admin_content_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_content_stats" IS 'Pre-aggregated content statistics. Uses security_invoker to respect RLS.';



CREATE TABLE IF NOT EXISTS "public"."error_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "error_type" "text" NOT NULL,
    "severity" "text" DEFAULT 'error'::"text" NOT NULL,
    "message" "text" NOT NULL,
    "stack_trace" "text",
    "error_name" "text",
    "url" "text" NOT NULL,
    "file_path" "text",
    "line_number" integer,
    "column_number" integer,
    "user_id" "uuid",
    "user_role" "text",
    "session_id" "text",
    "request_method" "text",
    "status_code" integer,
    "request_headers" "jsonb",
    "request_body" "jsonb",
    "response_time" integer,
    "user_agent" "text",
    "browser_name" "text",
    "browser_version" "text",
    "os_name" "text",
    "device_type" "text",
    "viewport_width" integer,
    "viewport_height" integer,
    "context" "jsonb",
    "tags" "text"[],
    "resolved" boolean DEFAULT false,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_notes" "text",
    "error_signature" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "error_logs_check" CHECK ((("resolved" = false) OR (("resolved" = true) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL)))),
    CONSTRAINT "error_logs_error_type_check" CHECK (("error_type" = ANY (ARRAY['client_js'::"text", 'server_api'::"text", 'server_load'::"text", 'server_action'::"text", 'validation'::"text", 'performance'::"text", 'database'::"text"]))),
    CONSTRAINT "error_logs_message_check" CHECK (("char_length"("message") > 0)),
    CONSTRAINT "error_logs_severity_check" CHECK (("severity" = ANY (ARRAY['info'::"text", 'warning'::"text", 'error'::"text", 'critical'::"text"]))),
    CONSTRAINT "error_logs_user_role_check" CHECK (("user_role" = ANY (ARRAY['student'::"text", 'teacher'::"text", 'admin'::"text"])))
);


ALTER TABLE "public"."error_logs" OWNER TO "postgres";


COMMENT ON TABLE "public"."error_logs" IS 'Comprehensive error logging for monitoring application health';



COMMENT ON COLUMN "public"."error_logs"."error_type" IS 'Type of error: client_js, server_api, server_load, server_action, validation, performance, database';



COMMENT ON COLUMN "public"."error_logs"."severity" IS 'Error severity: info, warning, error, critical';



COMMENT ON COLUMN "public"."error_logs"."context" IS 'Flexible JSONB field for error-specific context data';



COMMENT ON COLUMN "public"."error_logs"."tags" IS 'Array of tags for categorization and filtering';



COMMENT ON COLUMN "public"."error_logs"."error_signature" IS 'Hash of error for deduplication (auto-generated)';



CREATE OR REPLACE VIEW "public"."admin_error_stats_24h" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE (("severity" = 'critical'::"text") AND ("created_at" > ("now"() - '24:00:00'::interval)))) AS "critical_errors_24h",
    "count"(*) FILTER (WHERE (("severity" = 'critical'::"text") AND ("created_at" > ("now"() - '01:00:00'::interval)))) AS "critical_errors_1h",
    "count"(*) FILTER (WHERE ("resolved" = false)) AS "unresolved_errors",
    "count"(*) FILTER (WHERE ("created_at" > ("now"() - '24:00:00'::interval))) AS "total_errors_24h",
    "count"(*) FILTER (WHERE ("created_at" > ("now"() - '01:00:00'::interval))) AS "total_errors_1h",
    "count"(*) FILTER (WHERE (("severity" = 'error'::"text") AND ("created_at" > ("now"() - '24:00:00'::interval)))) AS "error_level_24h",
    "count"(*) FILTER (WHERE (("severity" = 'warning'::"text") AND ("created_at" > ("now"() - '24:00:00'::interval)))) AS "warning_level_24h"
   FROM "public"."error_logs";


ALTER VIEW "public"."admin_error_stats_24h" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_error_stats_24h" IS 'Pre-aggregated error statistics for admin dashboard. Uses security_invoker to respect RLS.';



CREATE TABLE IF NOT EXISTS "public"."background_job_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_name" "text" NOT NULL,
    "status" "text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "execution_time_ms" integer,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "background_job_runs_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'success'::"text", 'failed'::"text", 'timeout'::"text"]))),
    CONSTRAINT "valid_completion" CHECK (((("status" = 'running'::"text") AND ("completed_at" IS NULL)) OR (("status" <> 'running'::"text") AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "valid_execution_time" CHECK ((("execution_time_ms" IS NULL) OR ("execution_time_ms" >= 0)))
);


ALTER TABLE "public"."background_job_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."background_job_runs" IS 'Tracks execution of background jobs (cron, queue workers). Auto-cleanup after 7 days.';



CREATE OR REPLACE VIEW "public"."admin_job_failures" WITH ("security_invoker"='true') AS
 SELECT "job_name",
    "count"(*) AS "failure_count",
    "max"("started_at") AS "last_failure",
    "array_agg"(DISTINCT "error_message") FILTER (WHERE ("error_message" IS NOT NULL)) AS "error_messages"
   FROM "public"."background_job_runs"
  WHERE (("status" = ANY (ARRAY['failed'::"text", 'timeout'::"text"])) AND ("started_at" > ("now"() - '24:00:00'::interval)))
  GROUP BY "job_name"
  ORDER BY ("count"(*)) DESC;


ALTER VIEW "public"."admin_job_failures" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_job_failures" IS 'Aggregated job failures for last 24h. Uses security_invoker to respect RLS.';



CREATE OR REPLACE VIEW "public"."admin_job_status" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("job_name") "job_name",
    "status",
    "started_at",
    "completed_at",
    "error_message",
    "execution_time_ms",
    "metadata"
   FROM "public"."background_job_runs"
  ORDER BY "job_name", "started_at" DESC;


ALTER VIEW "public"."admin_job_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_job_status" IS 'Latest execution status for each background job type. Uses security_invoker to respect RLS.';



CREATE TABLE IF NOT EXISTS "public"."user_presence" (
    "user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'offline'::"text" NOT NULL,
    "last_heartbeat" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_presence_status_check" CHECK (("status" = ANY (ARRAY['online'::"text", 'offline'::"text"])))
);


ALTER TABLE "public"."user_presence" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."admin_online_users" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "online_users",
    "count"(*) FILTER (WHERE ("last_heartbeat" > ("now"() - '00:01:00'::interval))) AS "online_users_1m",
    "count"(*) FILTER (WHERE ("last_heartbeat" > ("now"() - '00:05:00'::interval))) AS "online_users_5m"
   FROM "public"."user_presence"
  WHERE ("last_heartbeat" > ("now"() - '00:05:00'::interval));


ALTER VIEW "public"."admin_online_users" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_online_users" IS 'Real-time online user count. Uses security_invoker to respect RLS.';



CREATE OR REPLACE VIEW "public"."admin_pg_cron_jobs" WITH ("security_invoker"='on') AS
 SELECT "jobid",
    "schedule",
    "command",
    "nodename",
    "nodeport",
    "database",
    "username",
    "active",
    ( SELECT "jsonb_build_object"('status', "bjr"."status", 'started_at', "bjr"."started_at", 'execution_time_ms', "bjr"."execution_time_ms", 'metadata', "bjr"."metadata") AS "jsonb_build_object"
           FROM "public"."background_job_runs" "bjr"
          WHERE ("bjr"."job_name" = "replace"("j"."jobname", '-'::"text", '_'::"text"))
          ORDER BY "bjr"."started_at" DESC
         LIMIT 1) AS "last_run"
   FROM "cron"."job" "j"
  WHERE ("database" = "current_database"());


ALTER VIEW "public"."admin_pg_cron_jobs" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_pg_cron_jobs" IS 'Shows pg_cron jobs with their last run status from background_job_runs';



CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "full_name" "text",
    "role" "public"."user_role" DEFAULT 'student'::"public"."user_role" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "firstname" "text",
    "lastname" "text",
    "school_id" "uuid",
    "avatar_url" "text",
    "class_ids" "uuid"[] DEFAULT '{}'::"uuid"[],
    "grade" "text",
    "gidouilles" numeric(10,2) DEFAULT 0 NOT NULL,
    "vip_cards" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_test" boolean DEFAULT false NOT NULL,
    "vip_cards_history" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "bonus" integer DEFAULT 0 NOT NULL,
    "python_settings" "jsonb" DEFAULT '{"fontSize": 14, "editorTheme": "default", "showPedagogicErrors": true}'::"jsonb",
    "status" "public"."user_status" DEFAULT 'approved'::"public"."user_status" NOT NULL,
    "rejection_reason" "text",
    "status_changed_at" timestamp with time zone,
    "status_changed_by" "uuid",
    "consent_required" boolean DEFAULT false NOT NULL,
    "consent_granted_at" timestamp with time zone,
    "consent_grace_period_ends" timestamp with time zone,
    CONSTRAINT "firstname_no_html" CHECK ((("firstname" !~ '<[^>]+>'::"text") AND ("firstname" !~ '&[a-z]+;'::"text") AND ("firstname" !~ 'javascript:'::"text") AND ("length"("firstname") <= 50))),
    CONSTRAINT "lastname_no_html" CHECK ((("lastname" !~ '<[^>]+>'::"text") AND ("lastname" !~ '&[a-z]+;'::"text") AND ("lastname" !~ 'javascript:'::"text") AND ("length"("lastname") <= 50))),
    CONSTRAINT "profiles_bonus_non_negative" CHECK (("bonus" >= 0)),
    CONSTRAINT "profiles_gidouilles_non_negative" CHECK (("gidouilles" >= (0)::numeric)),
    CONSTRAINT "profiles_valid_grade" CHECK ((("grade" IS NULL) OR ("grade" = ANY (ARRAY['CP'::"text", 'CE1'::"text", 'CE2'::"text", 'CM1'::"text", 'CM2'::"text", '6'::"text", '5'::"text", '4'::"text", '3'::"text", '2'::"text", '1_GEN'::"text", 'T_GEN'::"text", '1_SPE'::"text", 'T_SPE'::"text", 'T_EXP'::"text", 'T_COMP'::"text", '1_STMG'::"text", 'T_STMG'::"text"]))))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'User profiles - gender field removed 2026-01-15 for GDPR compliance (data minimization)';



COMMENT ON COLUMN "public"."profiles"."firstname" IS 'User first name';



COMMENT ON COLUMN "public"."profiles"."lastname" IS 'User last name';



COMMENT ON COLUMN "public"."profiles"."school_id" IS 'Foreign key linking users to their school';



COMMENT ON COLUMN "public"."profiles"."avatar_url" IS 'URL to user avatar image';



COMMENT ON COLUMN "public"."profiles"."class_ids" IS 'Array of class UUIDs - defaults to empty array';



COMMENT ON COLUMN "public"."profiles"."grade" IS 'Student grade level using canonical codes: CP, CE1, CE2, CM1, CM2, 6, 5, 4, 3, 2, 1_GEN, T_GEN, 1_SPE, T_SPE, T_EXP, T_COMP, 1_STMG, T_STMG';



COMMENT ON COLUMN "public"."profiles"."gidouilles" IS 'Student currency balance. Decimal precision (2 places) allows nuanced rewards. 1 gidouille = meaningful achievement.';



COMMENT ON COLUMN "public"."profiles"."vip_cards" IS 'JSON object storing student VIP cards and their properties';



COMMENT ON COLUMN "public"."profiles"."is_test" IS 'Whether this user is a test user. Test users are isolated from real users in teacher dashboards.';



COMMENT ON COLUMN "public"."profiles"."vip_cards_history" IS 'Permanent history of all VIP cards ever earned by the student. Maps cardId to firstEarnedAt timestamp. Never deleted, even when cards are used/exchanged.';



COMMENT ON COLUMN "public"."profiles"."bonus" IS 'Student bonus points for rewards system (separate from gidouilles)';



COMMENT ON COLUMN "public"."profiles"."python_settings" IS 'Python playground preferences (editorTheme, fontSize, showPedagogicErrors)';



COMMENT ON COLUMN "public"."profiles"."status" IS 'User approval status. Default is approved for backward compatibility. New users requiring approval should be set to pending.';



COMMENT ON COLUMN "public"."profiles"."rejection_reason" IS 'Explanation for why a user was rejected. Only populated when status is rejected.';



COMMENT ON COLUMN "public"."profiles"."status_changed_at" IS 'Timestamp of the last status change. NULL for users who never had their status modified.';



COMMENT ON COLUMN "public"."profiles"."status_changed_by" IS 'Profile ID of the user who last changed this status. NULL if status was never changed or if the approver was deleted.';



COMMENT ON COLUMN "public"."profiles"."consent_required" IS 'True if student requires parental consent (grades 6-2, under 15 years old per RGPD Art. 8)';



COMMENT ON COLUMN "public"."profiles"."consent_granted_at" IS 'Timestamp when parental consent was granted. NULL means consent not yet received.';



COMMENT ON COLUMN "public"."profiles"."consent_grace_period_ends" IS 'End date of grace period for existing students. After this date, students without consent have read-only access. Migration 20260115144849 set initial 30-day grace periods.';



COMMENT ON CONSTRAINT "firstname_no_html" ON "public"."profiles" IS 'Prevents HTML tags, entities, and javascript: protocol in firstname for XSS protection';



COMMENT ON CONSTRAINT "lastname_no_html" ON "public"."profiles" IS 'Prevents HTML tags, entities, and javascript: protocol in lastname for XSS protection';



CREATE OR REPLACE VIEW "public"."admin_user_activity" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE ("created_at" > ("now"() - '24:00:00'::interval))) AS "new_users_24h",
    "count"(*) FILTER (WHERE ("created_at" > ("now"() - '7 days'::interval))) AS "new_users_7d",
    "count"(*) FILTER (WHERE ("created_at" > ("now"() - '30 days'::interval))) AS "new_users_30d",
    "count"(*) FILTER (WHERE ("role" = 'student'::"public"."user_role")) AS "total_students",
    "count"(*) FILTER (WHERE ("role" = 'teacher'::"public"."user_role")) AS "total_teachers",
    "count"(*) FILTER (WHERE ("role" = 'admin'::"public"."user_role")) AS "total_admins",
    "count"(*) AS "total_users",
    "count"(*) FILTER (WHERE ("updated_at" > ("now"() - '7 days'::interval))) AS "active_users_7d"
   FROM "public"."profiles";


ALTER VIEW "public"."admin_user_activity" OWNER TO "postgres";


COMMENT ON VIEW "public"."admin_user_activity" IS 'Pre-aggregated user statistics. Uses security_invoker to respect RLS.';



