    CONSTRAINT "valid_current_version" CHECK (("current_version" >= 1)),
    CONSTRAINT "valid_grades" CHECK (("grades" IS NOT NULL)),
    CONSTRAINT "valid_instantiation_count" CHECK (("instantiation_count" >= 0)),
