    CONSTRAINT "srs_card_stats_difficulty_check" CHECK ((("difficulty" >= (1)::double precision) AND ("difficulty" <= (10)::double precision))),
    CONSTRAINT "srs_card_stats_stability_check" CHECK (("stability" >= (0)::double precision)),
    CONSTRAINT "srs_card_stats_state_check" CHECK (("state" = ANY (ARRAY['new'::"text", 'learning'::"text", 'review'::"text", 'relearning'::"text"]))),
    CONSTRAINT "srs_card_stats_total_reviews_check" CHECK (("total_reviews" >= 0))
);


