CREATE OR REPLACE VIEW "public"."deck_stats_view" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "deck_id",
    "d"."owner_id",
    "d"."name",
    "d"."description",
    "d"."deck_type",
    "d"."is_assigned",
    "d"."config",
    "d"."created_at",
    "d"."updated_at",
    (COALESCE("count"(DISTINCT "c"."id"), (0)::bigint))::integer AS "total_cards",
    (COALESCE("count"(DISTINCT "c"."id") FILTER (WHERE (("cs"."state" = 'new'::"text") OR ("cs"."state" IS NULL))), (0)::bigint))::integer AS "new_count",
    (COALESCE("count"(DISTINCT "c"."id") FILTER (WHERE ("cs"."state" = 'learning'::"text")), (0)::bigint))::integer AS "learning_count",
    (COALESCE("count"(DISTINCT "c"."id") FILTER (WHERE ("cs"."state" = 'review'::"text")), (0)::bigint))::integer AS "review_count",
    (COALESCE("count"(DISTINCT "c"."id") FILTER (WHERE (("cs"."next_review" <= "now"()) AND ("cs"."state" = ANY (ARRAY['learning'::"text", 'review'::"text", 'relearning'::"text"])))), (0)::bigint))::integer AS "due_count"
   FROM (("public"."srs_decks" "d"
     LEFT JOIN "public"."srs_cards" "c" ON (("c"."deck_id" = "d"."id")))
     LEFT JOIN "public"."srs_card_stats" "cs" ON ((((("cs"."card_reference_type" = 'custom'::"text") AND ("cs"."card_reference_id" = "c"."id")) OR (("cs"."card_reference_type" = 'template'::"text") AND ("c"."template_id" IS NOT NULL) AND ("cs"."card_reference_id" = "c"."template_id"))) AND ("cs"."user_id" = "d"."owner_id"))))
  GROUP BY "d"."id", "d"."owner_id", "d"."name", "d"."description", "d"."deck_type", "d"."is_assigned", "d"."config", "d"."created_at", "d"."updated_at";


