CREATE TABLE IF NOT EXISTS "public"."evaluation_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "teacher_id" "uuid" NOT NULL,
    "class_id" "uuid",
    "niveau_scolaire" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "assessment_id" "uuid",
    "exercise_id" "uuid",
    "worksheet_id" "uuid",
    "task_date" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_evaluation_task_source" CHECK ((((
CASE
    WHEN ("assessment_id" IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN ("exercise_id" IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN ("worksheet_id" IS NOT NULL) THEN 1
    ELSE 0
END) <= 1))
);


