CREATE TABLE IF NOT EXISTS "public"."minesweeper_games" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid",
    "difficulty" "text" NOT NULL,
    "status" "text" NOT NULL,
    "grid_state" "jsonb" NOT NULL,
    "time_seconds" integer,
    "mines_count" integer NOT NULL,
    "flags_used" integer DEFAULT 0,
    "cells_revealed" integer DEFAULT 0,
    "gidouilles_awarded" numeric(10,2) DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "hints_used" integer DEFAULT 0 NOT NULL,
    "hint_penalty_applied" boolean DEFAULT false NOT NULL,
    "points_earned" integer DEFAULT 0 NOT NULL,
    "reduced_penalty_hints" integer DEFAULT 0 NOT NULL,
    "undo_used" boolean DEFAULT false NOT NULL,
    CONSTRAINT "check_hints_used_range" CHECK ((("hints_used" >= 0) AND ("hints_used" <= 3))),
    CONSTRAINT "check_reduced_penalty_hints_valid" CHECK ((("reduced_penalty_hints" >= 0) AND ("reduced_penalty_hints" <= "hints_used"))),
    CONSTRAINT "completed_must_have_time" CHECK (((("status" = 'in_progress'::"text") AND ("time_seconds" IS NULL)) OR (("status" = ANY (ARRAY['won'::"text", 'lost'::"text"])) AND ("time_seconds" IS NOT NULL) AND ("time_seconds" > 0)))),
    CONSTRAINT "grid_state_size_limit" CHECK (("pg_column_size"("grid_state") < 100000)),
    CONSTRAINT "in_progress_must_not_be_completed" CHECK (((("status" = 'in_progress'::"text") AND ("completed_at" IS NULL)) OR (("status" = ANY (ARRAY['won'::"text", 'lost'::"text"])) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "minesweeper_games_cells_revealed_check" CHECK (("cells_revealed" >= 0)),
    CONSTRAINT "minesweeper_games_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['beginner'::"text", 'intermediate'::"text", 'expert'::"text"]))),
    CONSTRAINT "minesweeper_games_flags_used_check" CHECK (("flags_used" >= 0)),
    CONSTRAINT "minesweeper_games_gidouilles_awarded_check" CHECK ((("gidouilles_awarded" >= (0)::numeric) AND ("gidouilles_awarded" <= 10.0))),
    CONSTRAINT "minesweeper_games_mines_count_check" CHECK (("mines_count" > 0)),
    CONSTRAINT "minesweeper_games_status_check" CHECK (("status" = ANY (ARRAY['in_progress'::"text", 'won'::"text", 'lost'::"text"]))),
    CONSTRAINT "public_games_no_gidouilles" CHECK (((("student_id" IS NULL) AND ("gidouilles_awarded" = (0)::numeric)) OR ("student_id" IS NOT NULL))),
    CONSTRAINT "reasonable_time_bounds" CHECK ((("time_seconds" IS NULL) OR ((("difficulty" = 'beginner'::"text") AND ("time_seconds" >= 1) AND ("time_seconds" <= 3600)) OR (("difficulty" = 'intermediate'::"text") AND ("time_seconds" >= 1) AND ("time_seconds" <= 7200)) OR (("difficulty" = 'expert'::"text") AND ("time_seconds" >= 1) AND ("time_seconds" <= 14400))))),
    CONSTRAINT "valid_cells_revealed" CHECK (("cells_revealed" <=
CASE
    WHEN ("difficulty" = 'beginner'::"text") THEN 81
    WHEN ("difficulty" = 'intermediate'::"text") THEN 256
    WHEN ("difficulty" = 'expert'::"text") THEN 480
    ELSE NULL::integer
END)),
    CONSTRAINT "valid_flags_used" CHECK (("flags_used" <= ("mines_count" * 2))),
    CONSTRAINT "valid_hints_used" CHECK ((("hints_used" >= 0) AND ("hints_used" <= 3))),
    CONSTRAINT "valid_mines_count" CHECK (((("difficulty" = 'beginner'::"text") AND ("mines_count" = 10)) OR (("difficulty" = 'intermediate'::"text") AND ("mines_count" = 40)) OR (("difficulty" = 'expert'::"text") AND ("mines_count" = 99)))),
    CONSTRAINT "valid_points_earned" CHECK (("points_earned" >= 0))
);


ALTER TABLE "public"."minesweeper_games" OWNER TO "postgres";


COMMENT ON TABLE "public"."minesweeper_games" IS 'Stores Minesweeper game sessions. Supports both public (student_id = NULL) and authenticated gameplay.';



COMMENT ON COLUMN "public"."minesweeper_games"."student_id" IS 'NULL for public games, UUID for authenticated user games. Only authenticated users earn gidouilles.';



COMMENT ON COLUMN "public"."minesweeper_games"."grid_state" IS 'JSONB storing complete game state: rows, cols, mines, revealed, flagged, adjacentCounts. Enables game resume.';



COMMENT ON COLUMN "public"."minesweeper_games"."gidouilles_awarded" IS 'Gidouilles earned for this game. Decimal for precise Strategy D calculations. Range: 0.3-8.0 per game.';



COMMENT ON COLUMN "public"."minesweeper_games"."started_at" IS 'Server-side timestamp when first cell was revealed. Used to calculate time_seconds on completion. Prevents client manipulation. Auto-set by trigger.';



COMMENT ON COLUMN "public"."minesweeper_games"."hints_used" IS 'Number of hints used in this game (max 3). Each hint costs 10 gidouilles and triggers 30% penalty on final reward.';



COMMENT ON COLUMN "public"."minesweeper_games"."hint_penalty_applied" IS 'Whether 30% penalty was applied to final reward due to hint usage. Set by complete_minesweeper_game().';



COMMENT ON COLUMN "public"."minesweeper_games"."points_earned" IS 'Points earned for this game. Calculated based on difficulty, time, hints used, streak bonus, and daily bonus. Only awarded for won games.';



COMMENT ON COLUMN "public"."minesweeper_games"."reduced_penalty_hints" IS 'Number of hints with reduced penalty (from VIP cards: 5/11/17% vs 10/22/35% for gidouilles hints).';



COMMENT ON COLUMN "public"."minesweeper_games"."undo_used" IS 'Whether the "Seconde Chance" undo item was used in this game. Limited to 1 per game.';



COMMENT ON CONSTRAINT "check_hints_used_range" ON "public"."minesweeper_games" IS 'Ensures hints_used is within valid range (0-3). Hints can only be incremented via the hint API endpoint which validates and charges gidouilles.';



COMMENT ON CONSTRAINT "grid_state_size_limit" ON "public"."minesweeper_games" IS 'Prevents DoS attacks via huge JSONB payloads (100KB limit)';



COMMENT ON CONSTRAINT "reasonable_time_bounds" ON "public"."minesweeper_games" IS 'Enforces reasonable time limits per difficulty to detect manipulation';



COMMENT ON CONSTRAINT "valid_cells_revealed" ON "public"."minesweeper_games" IS 'Prevents cells_revealed from exceeding grid size for each difficulty';



COMMENT ON CONSTRAINT "valid_flags_used" ON "public"."minesweeper_games" IS 'Prevents unrealistic flag counts (max 2x mine count)';



COMMENT ON CONSTRAINT "valid_hints_used" ON "public"."minesweeper_games" IS 'Enforces maximum 3 hints per game.';



COMMENT ON CONSTRAINT "valid_mines_count" ON "public"."minesweeper_games" IS 'Enforces exact mine counts per difficulty: beginner=10, intermediate=40, expert=99';



CREATE OR REPLACE VIEW "public"."minesweeper_leaderboard" WITH ("security_invoker"='on') AS
 WITH "ranked_games" AS (
         SELECT "mg"."student_id",
            "mg"."points_earned",
            "row_number"() OVER (PARTITION BY "mg"."student_id" ORDER BY "mg"."points_earned" DESC) AS "game_rank"
           FROM "public"."minesweeper_games" "mg"
          WHERE (("mg"."status" = 'won'::"text") AND ("mg"."student_id" IS NOT NULL) AND ("mg"."points_earned" > 0))
        ), "top10_stats" AS (
         SELECT "ranked_games"."student_id",
            "count"(*) AS "top_games_count",
            "sum"("ranked_games"."points_earned") AS "top_games_total",
            "round"("avg"("ranked_games"."points_earned"), 1) AS "avg_top_10"
           FROM "ranked_games"
          WHERE ("ranked_games"."game_rank" <= 10)
          GROUP BY "ranked_games"."student_id"
        ), "full_stats" AS (
         SELECT "t"."student_id",
            "p"."firstname",
            "p"."lastname",
            "p"."role",
            "t"."avg_top_10",
            "t"."top_games_count",
            "t"."top_games_total",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = 'won'::"text"))) AS "games_won",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = ANY (ARRAY['won'::"text", 'lost'::"text"])))) AS "games_played",
            ( SELECT "sum"("mg"."points_earned") AS "sum"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = 'won'::"text"))) AS "total_points",
            ( SELECT "sum"("mg"."gidouilles_awarded") AS "sum"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = 'won'::"text"))) AS "total_gidouilles",
            "round"((((( SELECT "count"(*) AS "count"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = 'won'::"text"))))::numeric / (NULLIF(( SELECT "count"(*) AS "count"
                   FROM "public"."minesweeper_games" "mg"
                  WHERE (("mg"."student_id" = "t"."student_id") AND ("mg"."status" = ANY (ARRAY['won'::"text", 'lost'::"text"])))), 0))::numeric) * (100)::numeric), 1) AS "win_rate"
           FROM ("top10_stats" "t"
             JOIN "public"."profiles" "p" ON (("t"."student_id" = "p"."id")))
        )
 SELECT "student_id",
    "firstname",
    "lastname",
    "role",
    "avg_top_10",
    "top_games_count",
    "games_won",
    "games_played",
    "total_points",
    "total_gidouilles",
    "win_rate",
    "row_number"() OVER (ORDER BY "avg_top_10" DESC, "games_won" DESC) AS "rank"
   FROM "full_stats"
  ORDER BY ("row_number"() OVER (ORDER BY "avg_top_10" DESC, "games_won" DESC));


ALTER VIEW "public"."minesweeper_leaderboard" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."game_scores_unified" WITH ("security_invoker"='true') AS
 SELECT '2048'::"text" AS "game",
    "g"."user_id",
    ("g"."best_score")::numeric AS "score",
    "g"."updated_at"
   FROM "public"."game_2048_scores" "g"
UNION ALL
 SELECT 'mathemo'::"text" AS "game",
    "m"."user_id",
    "m"."total_score" AS "score",
    "m"."updated_at"
   FROM "public"."mathemo_scores" "m"
UNION ALL
 SELECT 'minesweeper'::"text" AS "game",
    "ml"."student_id" AS "user_id",
    ("ml"."total_points")::numeric AS "score",
    ( SELECT "max"("mg"."completed_at") AS "max"
           FROM "public"."minesweeper_games" "mg"
          WHERE (("mg"."student_id" = "ml"."student_id") AND ("mg"."status" = 'won'::"text"))) AS "updated_at"
   FROM "public"."minesweeper_leaderboard" "ml";


ALTER VIEW "public"."game_scores_unified" OWNER TO "postgres";


COMMENT ON VIEW "public"."game_scores_unified" IS 'UNION ALL of game_2048_scores / mathemo_scores / minesweeper_leaderboard, one row per (game, user_id). security_invoker = true; NOT granted to clients — read only from public.game_leaderboard() (SECURITY DEFINER, runs as owner).';



