CREATE TABLE IF NOT EXISTS "public"."marketplace_listings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "creator_id" "uuid" NOT NULL,
    "school_id" "uuid" NOT NULL,
    "listing_type" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "offered_card_ids" "text"[] DEFAULT '{}'::"text"[],
    "offered_gidouilles" integer DEFAULT 0,
    "wanted_card_template_ids" "text"[] DEFAULT '{}'::"text"[],
    "wanted_gidouilles" integer DEFAULT 0,
    "max_proposals" integer DEFAULT 10,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "view_count" integer DEFAULT 0,
    "proposal_count" integer DEFAULT 0,
    CONSTRAINT "at_least_one_item" CHECK (((COALESCE("array_length"("offered_card_ids", 1), 0) > 0) OR ("offered_gidouilles" > 0) OR (COALESCE("array_length"("wanted_card_template_ids", 1), 0) > 0) OR ("wanted_gidouilles" > 0))),
    CONSTRAINT "marketplace_listings_listing_type_check" CHECK (("listing_type" = ANY (ARRAY['sell'::"text", 'buy'::"text"]))),
    CONSTRAINT "marketplace_listings_max_proposals_check" CHECK ((("max_proposals" >= 1) AND ("max_proposals" <= 50))),
    CONSTRAINT "marketplace_listings_offered_gidouilles_check" CHECK (("offered_gidouilles" >= 0)),
    CONSTRAINT "marketplace_listings_proposal_count_check" CHECK (("proposal_count" >= 0)),
    CONSTRAINT "marketplace_listings_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'expired'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "marketplace_listings_view_count_check" CHECK (("view_count" >= 0)),
    CONSTRAINT "marketplace_listings_wanted_gidouilles_check" CHECK (("wanted_gidouilles" >= 0)),
    CONSTRAINT "valid_status_timestamps" CHECK (((("status" = 'completed'::"text") AND ("completed_at" IS NOT NULL)) OR (("status" = 'cancelled'::"text") AND ("cancelled_at" IS NOT NULL)) OR ("status" = ANY (ARRAY['active'::"text", 'expired'::"text"]))))
);


