    "withdrawn_at" timestamp with time zone,
    CONSTRAINT "at_least_one_offer" CHECK (((COALESCE("array_length"("offered_card_ids", 1), 0) > 0) OR ("offered_gidouilles" > 0))),
    CONSTRAINT "marketplace_proposals_message_check" CHECK ((("message" IS NULL) OR ("length"("message") <= 500))),
