    CONSTRAINT "marketplace_proposals_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "valid_response_timestamp" CHECK (((("status" = ANY (ARRAY['accepted'::"text", 'rejected'::"text"])) AND ("responded_at" IS NOT NULL)) OR (("status" = 'withdrawn'::"text") AND ("withdrawn_at" IS NOT NULL)) OR ("status" = 'pending'::"text")))
);


