    CONSTRAINT "marketplace_trade_offers_initiator_gidouilles_check" CHECK (("initiator_gidouilles" >= 0)),
    CONSTRAINT "marketplace_trade_offers_message_check" CHECK ((("message" IS NULL) OR ("length"("message") <= 500))),
    CONSTRAINT "marketplace_trade_offers_offer_number_check" CHECK (("offer_number" >= 1)),
    CONSTRAINT "marketplace_trade_offers_partner_gidouilles_check" CHECK (("partner_gidouilles" >= 0)),
    CONSTRAINT "marketplace_trade_offers_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text", 'countered'::"text"])))
);


ALTER TABLE "public"."marketplace_trade_offers" OWNER TO "postgres";


COMMENT ON TABLE "public"."marketplace_trade_offers" IS 'Counter-offers within trades containing VIP cards and gidouilles';



COMMENT ON COLUMN "public"."marketplace_trade_offers"."offer_number" IS 'Sequential number for this trade, starting at 1';



CREATE TABLE IF NOT EXISTS "public"."marketplace_trades" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "trade_type" "text" NOT NULL,
    "status" "text" DEFAULT 'negotiating'::"text" NOT NULL,
    "initiator_id" "uuid" NOT NULL,
    "partner_id" "uuid" NOT NULL,
    "listing_id" "uuid",
    "proposal_id" "uuid",
    "conversation_id" "uuid",
    "current_offer" "jsonb",
    "last_offer_by" "uuid",
    "final_trade" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "validated_by_initiator" boolean DEFAULT false NOT NULL,
    "validated_by_partner" boolean DEFAULT false NOT NULL,
    "validated_at" timestamp with time zone,
    "confirmation_started_at" timestamp with time zone,
    "confirmed_by_initiator" boolean DEFAULT false,
    "confirmed_by_partner" boolean DEFAULT false,
    CONSTRAINT "different_participants" CHECK (("initiator_id" <> "partner_id")),
    CONSTRAINT "marketplace_trades_status_check" CHECK (("status" = ANY (ARRAY['negotiating'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "marketplace_trades_trade_type_check" CHECK (("trade_type" = ANY (ARRAY['friend'::"text", 'marketplace'::"text"]))),
    CONSTRAINT "valid_completion" CHECK (((("status" = 'completed'::"text") AND ("completed_at" IS NOT NULL) AND ("final_trade" IS NOT NULL)) OR (("status" = 'cancelled'::"text") AND ("cancelled_at" IS NOT NULL)) OR ("status" = 'negotiating'::"text"))),
    CONSTRAINT "valid_trade_relations" CHECK (((("trade_type" = 'friend'::"text") AND ("listing_id" IS NULL) AND ("proposal_id" IS NULL)) OR (("trade_type" = 'marketplace'::"text") AND ("listing_id" IS NOT NULL) AND ("proposal_id" IS NOT NULL)))),
    CONSTRAINT "validate_timestamps_consistency" CHECK (((("validated_at" IS NULL) AND ("confirmation_started_at" IS NULL)) OR (("validated_by_initiator" = true) AND ("validated_by_partner" = true) AND ("validated_at" IS NOT NULL) AND ("confirmation_started_at" IS NOT NULL))))
);


ALTER TABLE "public"."marketplace_trades" OWNER TO "postgres";


COMMENT ON TABLE "public"."marketplace_trades" IS 'Friend-to-friend trades of VIP cards and gidouilles';



COMMENT ON COLUMN "public"."marketplace_trades"."current_offer" IS 'Current state of negotiation in JSONB format';



COMMENT ON COLUMN "public"."marketplace_trades"."final_trade" IS 'Final agreed trade details, immutable once set';



COMMENT ON COLUMN "public"."marketplace_trades"."validated_by_initiator" IS 'TRUE when initiator has validated the current offer';



COMMENT ON COLUMN "public"."marketplace_trades"."validated_by_partner" IS 'TRUE when partner has validated the current offer';



COMMENT ON COLUMN "public"."marketplace_trades"."validated_at" IS 'Timestamp when both parties validated the offer (mutual agreement)';



COMMENT ON COLUMN "public"."marketplace_trades"."confirmation_started_at" IS 'Timestamp when the confirmation modal opened (both parties validated)';



COMMENT ON COLUMN "public"."marketplace_trades"."confirmed_by_initiator" IS 'Whether initiator has confirmed during final confirmation phase';



COMMENT ON COLUMN "public"."marketplace_trades"."confirmed_by_partner" IS 'Whether partner has confirmed during final confirmation phase';



COMMENT ON CONSTRAINT "validate_timestamps_consistency" ON "public"."marketplace_trades" IS 'Ensures timestamps are NULL when not fully validated, or both set when fully validated';



