    CONSTRAINT "message_templates_body_template_check" CHECK (("char_length"("body_template") >= 1)),
    CONSTRAINT "message_templates_check" CHECK (((("scope" = 'system'::"text") AND ("class_id" IS NULL)) OR (("scope" = 'class'::"text") AND ("class_id" IS NOT NULL)))),
    CONSTRAINT "message_templates_scope_check" CHECK (("scope" = ANY (ARRAY['system'::"text", 'class'::"text"]))),
    CONSTRAINT "message_templates_subject_template_check" CHECK ((("char_length"("subject_template") >= 1) AND ("char_length"("subject_template") <= 200))),
    CONSTRAINT "message_templates_title_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 100))),
    CONSTRAINT "message_templates_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['assessment_question'::"text", 'srs_help'::"text", 'system_notification'::"text", 'enigma_answer'::"text", 'general'::"text"])))
);


