    "conversion_errors" "jsonb" DEFAULT '[]'::"jsonb",
    "conversion_notes" "text",
    "converted_at" timestamp with time zone,
    "imported_at" timestamp with time zone,
    "validated_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "theme" "text",
    "domain" "text",
    "subdomain" "text",
    "level" integer,
    "old_question_json" "jsonb",
    "transformed_json" "jsonb",
    "review_status" "text" DEFAULT 'pending'::"text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    CONSTRAINT "migration_tracking_migration_status_check" CHECK (("migration_status" = ANY (ARRAY['pending'::"text", 'converted'::"text", 'imported'::"text", 'validated'::"text", 'failed'::"text"]))),
    CONSTRAINT "migration_tracking_phase_check" CHECK (("phase" = ANY (ARRAY[1, 2, 3, 4]))),
    CONSTRAINT "migration_tracking_review_status_check" CHECK (("review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


