CREATE OR REPLACE VIEW "public"."migration_review_tree" WITH ("security_invoker"='true') AS
 SELECT "theme",
    "domain",
    "subdomain",
    "count"(*) AS "total",
    "count"(*) FILTER (WHERE ("review_status" = 'approved'::"text")) AS "approved",
    "count"(*) FILTER (WHERE ("review_status" = 'pending'::"text")) AS "pending",
    "count"(*) FILTER (WHERE ("review_status" = 'rejected'::"text")) AS "rejected"
   FROM "public"."migration_tracking"
  WHERE ("theme" IS NOT NULL)
  GROUP BY "theme", "domain", "subdomain"
  ORDER BY "theme", "domain", "subdomain";


ALTER VIEW "public"."migration_review_tree" OWNER TO "postgres";


COMMENT ON VIEW "public"."migration_review_tree" IS 'Aggregated review status for migration tracking. Uses security_invoker to respect RLS.';



