CREATE TABLE IF NOT EXISTS "public"."minesweeper_player_stats" (
    "student_id" "uuid" NOT NULL,
    "rank" integer DEFAULT 1000,
    "ranked_wins" integer DEFAULT 0,
    "ranked_losses" integer DEFAULT 0,
    "ranked_win_streak" integer DEFAULT 0,
    "ranked_best_streak" integer DEFAULT 0,
    "quick_wins" integer DEFAULT 0,
    "quick_losses" integer DEFAULT 0,
    "total_matches" integer DEFAULT 0,
    "total_gidouilles_earned" integer DEFAULT 0,
    "season" "text" DEFAULT "to_char"("now"(), 'YYYY-MM'::"text") NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "games_played" integer DEFAULT 0,
    "games_won" integer DEFAULT 0,
    "win_streak" integer DEFAULT 0,
    "best_win_streak" integer DEFAULT 0,
    CONSTRAINT "minesweeper_player_stats_best_win_streak_check" CHECK (("best_win_streak" >= 0)),
    CONSTRAINT "minesweeper_player_stats_games_played_check" CHECK (("games_played" >= 0)),
    CONSTRAINT "minesweeper_player_stats_games_won_check" CHECK (("games_won" >= 0)),
    CONSTRAINT "minesweeper_player_stats_quick_losses_check" CHECK (("quick_losses" >= 0)),
    CONSTRAINT "minesweeper_player_stats_quick_wins_check" CHECK (("quick_wins" >= 0)),
    CONSTRAINT "minesweeper_player_stats_ranked_best_streak_check" CHECK (("ranked_best_streak" >= 0)),
    CONSTRAINT "minesweeper_player_stats_ranked_elo_check" CHECK ((("rank" >= 0) AND ("rank" <= 3000))),
    CONSTRAINT "minesweeper_player_stats_ranked_losses_check" CHECK (("ranked_losses" >= 0)),
    CONSTRAINT "minesweeper_player_stats_ranked_win_streak_check" CHECK (("ranked_win_streak" >= 0)),
    CONSTRAINT "minesweeper_player_stats_ranked_wins_check" CHECK (("ranked_wins" >= 0)),
    CONSTRAINT "minesweeper_player_stats_total_gidouilles_earned_check" CHECK (("total_gidouilles_earned" >= 0)),
    CONSTRAINT "minesweeper_player_stats_total_matches_check" CHECK (("total_matches" >= 0)),
    CONSTRAINT "minesweeper_player_stats_win_streak_check" CHECK (("win_streak" >= 0)),
    CONSTRAINT "total_matches_consistency" CHECK (("total_matches" = ((("ranked_wins" + "ranked_losses") + "quick_wins") + "quick_losses")))
);


ALTER TABLE "public"."minesweeper_player_stats" OWNER TO "postgres";


COMMENT ON TABLE "public"."minesweeper_player_stats" IS 'Player statistics for multiplayer Minesweeper - tracks wins, losses, ELO, streaks per season. Primary key: (student_id, season)';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."rank" IS 'ELO rating (1000 = default, updated after each ranked match). Renamed from ranked_elo for consistency.';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."ranked_win_streak" IS 'Current consecutive wins in ranked mode';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."ranked_best_streak" IS 'Best consecutive win streak ever achieved';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."season" IS 'Season identifier (YYYY-MM format). Part of primary key - allows multiple season records per student.';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."games_played" IS 'Total games played this season (ranked + quick). Should match total_matches.';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."games_won" IS 'Total games won this season (ranked + quick). Should match ranked_wins + quick_wins.';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."win_streak" IS 'Current consecutive wins (resets on loss). Updated by completion functions.';



COMMENT ON COLUMN "public"."minesweeper_player_stats"."best_win_streak" IS 'Best consecutive win streak achieved this season.';



CREATE OR REPLACE VIEW "public"."minesweeper_multiplayer_leaderboard" WITH ("security_invoker"='true') AS
 SELECT "s"."student_id",
    "p"."firstname",
    "p"."lastname",
    "p"."avatar_url",
    "s"."rank",
    "s"."ranked_wins",
    "s"."ranked_losses",
    "s"."ranked_win_streak",
    "s"."ranked_best_streak",
    "s"."total_gidouilles_earned",
    "s"."season",
        CASE
            WHEN (("s"."ranked_wins" + "s"."ranked_losses") = 0) THEN (0)::numeric
            ELSE "round"(((("s"."ranked_wins")::numeric / (("s"."ranked_wins" + "s"."ranked_losses"))::numeric) * (100)::numeric), 1)
        END AS "win_rate",
    ("s"."ranked_wins" + "s"."ranked_losses") AS "total_ranked_matches",
    "dense_rank"() OVER (PARTITION BY "s"."season" ORDER BY "s"."rank" DESC, "s"."ranked_wins" DESC) AS "leaderboard_rank"
   FROM ("public"."minesweeper_player_stats" "s"
     JOIN "public"."profiles" "p" ON (("p"."id" = "s"."student_id")))
  WHERE (("p"."role" = 'student'::"public"."user_role") AND ("s"."total_matches" > 0))
  ORDER BY "s"."rank" DESC, "s"."ranked_wins" DESC;


ALTER VIEW "public"."minesweeper_multiplayer_leaderboard" OWNER TO "postgres";


COMMENT ON VIEW "public"."minesweeper_multiplayer_leaderboard" IS 'Ranked leaderboard with player stats. Uses security_invoker to respect RLS.';



CREATE TABLE IF NOT EXISTS "public"."minesweeper_multiplayer_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "match_type" "text" NOT NULL,
    "difficulty" "text" NOT NULL,
    "seed" "text" NOT NULL,
    "player1_id" "uuid" NOT NULL,
    "player2_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'waiting'::"text" NOT NULL,
    "winner_id" "uuid",
    "player1_time" integer,
    "player2_time" integer,
    "player1_gidouilles" integer DEFAULT 0,
    "player2_gidouilles" integer DEFAULT 0,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "duration_seconds" integer,
    "winner_reward" integer DEFAULT 0,
    "loser_reward" integer DEFAULT 0,
    "elo_change" integer DEFAULT 0,
    CONSTRAINT "completed_must_have_timestamp" CHECK ((("status" <> 'completed'::"text") OR ("completed_at" IS NOT NULL))),
    CONSTRAINT "completed_must_have_winner" CHECK ((("status" <> 'completed'::"text") OR ("winner_id" IS NOT NULL))),
    CONSTRAINT "different_players" CHECK (("player1_id" <> "player2_id")),
    CONSTRAINT "minesweeper_multiplayer_matches_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['beginner'::"text", 'intermediate'::"text", 'expert'::"text"]))),
    CONSTRAINT "minesweeper_multiplayer_matches_duration_seconds_check" CHECK (("duration_seconds" > 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_elo_change_check" CHECK (("elo_change" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_loser_reward_check" CHECK (("loser_reward" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_match_type_check" CHECK (("match_type" = ANY (ARRAY['quick'::"text", 'challenge'::"text", 'ranked'::"text"]))),
    CONSTRAINT "minesweeper_multiplayer_matches_player1_gidouilles_check" CHECK (("player1_gidouilles" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_player1_time_check" CHECK (("player1_time" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_player2_gidouilles_check" CHECK (("player2_gidouilles" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_player2_time_check" CHECK (("player2_time" >= 0)),
    CONSTRAINT "minesweeper_multiplayer_matches_status_check" CHECK (("status" = ANY (ARRAY['waiting'::"text", 'countdown'::"text", 'in_progress'::"text", 'completed'::"text", 'abandoned'::"text"]))),
    CONSTRAINT "minesweeper_multiplayer_matches_winner_reward_check" CHECK (("winner_reward" >= 0)),
    CONSTRAINT "started_must_have_timestamp" CHECK ((("status" = ANY (ARRAY['waiting'::"text", 'countdown'::"text"])) OR ("started_at" IS NOT NULL))),
    CONSTRAINT "timestamps_order" CHECK ((("started_at" IS NULL) OR ("completed_at" IS NULL) OR ("started_at" <= "completed_at"))),
    CONSTRAINT "valid_winner" CHECK ((("winner_id" IS NULL) OR ("winner_id" = "player1_id") OR ("winner_id" = "player2_id")))
);


ALTER TABLE "public"."minesweeper_multiplayer_matches" OWNER TO "postgres";


COMMENT ON TABLE "public"."minesweeper_multiplayer_matches" IS 'Stores multiplayer Minesweeper matches between two players';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."match_type" IS 'quick: casual play, challenge: direct friend challenge, ranked: competitive with ELO';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."seed" IS 'Random seed for deterministic grid generation - ensures both players get identical grid';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."status" IS 'waiting: waiting for opponent, countdown: 3-2-1 countdown, in_progress: actively playing, completed: finished normally, abandoned: one player left';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."duration_seconds" IS 'Time in seconds taken by the winner to complete the game';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."winner_reward" IS 'Gidouilles awarded to the winner (includes base reward + bonuses)';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."loser_reward" IS 'Gidouilles awarded to the loser (usually 0, except for consolation prizes)';



COMMENT ON COLUMN "public"."minesweeper_multiplayer_matches"."elo_change" IS 'ELO rating points gained by winner and lost by loser (0 for non-ranked matches)';



