CREATE TABLE IF NOT EXISTS "public"."minesweeper_reference_times" (
    "cycle" "text" NOT NULL,
    "difficulty" "text" NOT NULL,
    "reference_time" integer NOT NULL,
    "fallback_time" integer NOT NULL,
    "min_bound" integer NOT NULL,
    "max_bound" integer NOT NULL,
    "min_samples" integer DEFAULT 30 NOT NULL,
    "sample_count" integer DEFAULT 0,
    "calculated_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "minesweeper_reference_times_check" CHECK (("max_bound" > "min_bound")),
    CONSTRAINT "minesweeper_reference_times_cycle_check" CHECK (("cycle" = ANY (ARRAY['cycle_2'::"text", 'cycle_3'::"text", 'cycle_4'::"text", 'seconde'::"text", 'cycle_terminal'::"text"]))),
    CONSTRAINT "minesweeper_reference_times_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['beginner'::"text", 'intermediate'::"text", 'expert'::"text"]))),
    CONSTRAINT "minesweeper_reference_times_fallback_time_check" CHECK (("fallback_time" > 0)),
    CONSTRAINT "minesweeper_reference_times_min_bound_check" CHECK (("min_bound" > 0)),
    CONSTRAINT "minesweeper_reference_times_min_samples_check" CHECK (("min_samples" > 0)),
    CONSTRAINT "minesweeper_reference_times_reference_time_check" CHECK (("reference_time" > 0)),
    CONSTRAINT "minesweeper_reference_times_sample_count_check" CHECK (("sample_count" >= 0)),
    CONSTRAINT "valid_fallback_bounds" CHECK ((("fallback_time" >= "min_bound") AND ("fallback_time" <= "max_bound"))),
    CONSTRAINT "valid_reference_bounds" CHECK ((("reference_time" >= "min_bound") AND ("reference_time" <= "max_bound")))
);


