    CONSTRAINT "minesweeper_student_achievements_difficulty_check" CHECK ((("difficulty" = ANY (ARRAY['beginner'::"text", 'intermediate'::"text", 'expert'::"text"])) OR ("difficulty" IS NULL)))
);


