COMMENT ON TABLE "public"."minesweeper_student_achievements" IS 'Tracks which achievements each student has unlocked. Includes reference to the game where it was earned.';



COMMENT ON COLUMN "public"."minesweeper_student_achievements"."difficulty" IS 'Only populated for difficulty_specific achievements. NULL for global achievements (e.g., first_victory).';



COMMENT ON COLUMN "public"."minesweeper_student_achievements"."game_id" IS 'Reference to the game where this achievement was unlocked. ON DELETE SET NULL preserves achievement history.';



CREATE OR REPLACE VIEW "public"."minesweeper_student_achievement_progress" WITH ("security_invoker"='on') AS
 SELECT "p"."id" AS "student_id",
    "a"."id" AS "achievement_id",
    "a"."name",
    "a"."description",
    "a"."icon",
    "a"."difficulty_specific",
        CASE
            WHEN "a"."difficulty_specific" THEN "diffs"."difficulty"
            ELSE NULL::"text"
        END AS "difficulty",
    "sa"."unlocked_at",
    "sa"."game_id",
    ("sa"."unlocked_at" IS NOT NULL) AS "is_unlocked"
   FROM ((("public"."profiles" "p"
     CROSS JOIN "public"."minesweeper_achievements" "a")
     LEFT JOIN LATERAL ( SELECT "d"."difficulty"
           FROM ( VALUES ('beginner'::"text"), ('intermediate'::"text"), ('expert'::"text")) "d"("difficulty")
          WHERE "a"."difficulty_specific"
        UNION ALL
         SELECT NULL::"text" AS "difficulty"
          WHERE (NOT "a"."difficulty_specific")) "diffs" ON (true))
     LEFT JOIN "public"."minesweeper_student_achievements" "sa" ON ((("sa"."student_id" = "p"."id") AND ("sa"."achievement_id" = "a"."id") AND (("a"."difficulty_specific" AND ("sa"."difficulty" = "diffs"."difficulty")) OR ((NOT "a"."difficulty_specific") AND ("sa"."difficulty" IS NULL) AND ("diffs"."difficulty" IS NULL))))))
  WHERE ("p"."role" = 'student'::"public"."user_role");


