CREATE OR REPLACE VIEW "public"."minesweeper_student_achievements_compat" WITH ("security_invoker"='true') AS
 SELECT "id",
    "student_id",
    "replace"("achievement_id", 'minesweeper_'::"text", ''::"text") AS "achievement_id",
    ("context_data" ->> 'difficulty'::"text") AS "difficulty",
    "unlocked_at",
        CASE
            WHEN (("context_data" ->> 'reference_id'::"text") IS NOT NULL) THEN (("context_data" ->> 'reference_id'::"text"))::"uuid"
            ELSE NULL::"uuid"
        END AS "game_id"
   FROM "public"."student_achievements" "sa"
  WHERE ("achievement_id" ~~ 'minesweeper_%'::"text");


