CREATE TABLE IF NOT EXISTS "public"."minesweeper_tournament_games" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "student_id" "uuid" NOT NULL,
    "game_number" integer NOT NULL,
    "seed" "text" NOT NULL,
    "status" "text" DEFAULT 'in_progress'::"text" NOT NULL,
    "time_seconds" integer,
    "grid_state" "jsonb",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "grid_3bv" integer,
    "score" integer,
    CONSTRAINT "completed_must_have_data" CHECK (((("status" = 'in_progress'::"text") AND ("completed_at" IS NULL)) OR (("status" = ANY (ARRAY['won'::"text", 'lost'::"text", 'abandoned'::"text"])) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "grid_state_size_limit" CHECK ((("grid_state" IS NULL) OR ("pg_column_size"("grid_state") < 100000))),
    CONSTRAINT "minesweeper_tournament_games_game_number_check" CHECK (("game_number" >= 1)),
    CONSTRAINT "minesweeper_tournament_games_grid_3bv_check" CHECK ((("grid_3bv" IS NULL) OR ("grid_3bv" > 0))),
    CONSTRAINT "minesweeper_tournament_games_score_check" CHECK ((("score" IS NULL) OR ("score" >= 0))),
    CONSTRAINT "minesweeper_tournament_games_status_check" CHECK (("status" = ANY (ARRAY['in_progress'::"text", 'won'::"text", 'lost'::"text", 'abandoned'::"text"]))),
    CONSTRAINT "minesweeper_tournament_games_time_seconds_check" CHECK ((("time_seconds" IS NULL) OR ("time_seconds" > 0))),
    CONSTRAINT "valid_seed_format" CHECK (("seed" ~ '^tournament-[a-f0-9-]+-game-[0-9]+$'::"text")),
    CONSTRAINT "won_must_have_time" CHECK ((("status" <> 'won'::"text") OR ("time_seconds" IS NOT NULL)))
);


ALTER TABLE "public"."minesweeper_tournament_games" OWNER TO "postgres";


COMMENT ON TABLE "public"."minesweeper_tournament_games" IS 'Individual game records for tournament participation. Top X games (by time) are averaged for ranking.';



COMMENT ON COLUMN "public"."minesweeper_tournament_games"."game_number" IS 'Sequential game number for this student in this tournament. Starts at 1.';



COMMENT ON COLUMN "public"."minesweeper_tournament_games"."seed" IS 'Deterministic seed for grid generation. Format: tournament-{tournament_id}-game-{game_number}. Same seed = same grid.';



COMMENT ON COLUMN "public"."minesweeper_tournament_games"."grid_3bv" IS '3BV (Bechtel Board Benchmark Value) of the grid - minimum clicks needed to solve';



