CREATE TABLE IF NOT EXISTS "public"."minesweeper_tournaments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "creator_id" "uuid" NOT NULL,
    "creator_role" "text" NOT NULL,
    "scope" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "difficulty" "text" NOT NULL,
    "start_date" timestamp with time zone NOT NULL,
    "end_date" timestamp with time zone NOT NULL,
    "top_x_games" integer DEFAULT 3 NOT NULL,
    "podium_rewards" "jsonb" DEFAULT '{"1": 10, "2": 5, "3": 3}'::"jsonb" NOT NULL,
    "podium_places" integer DEFAULT 3 NOT NULL,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "global_requires_admin" CHECK ((("scope" = 'classes'::"text") OR (("scope" = 'global'::"text") AND ("creator_role" = 'admin'::"text")))),
    CONSTRAINT "minesweeper_tournaments_creator_role_check" CHECK (("creator_role" = ANY (ARRAY['teacher'::"text", 'admin'::"text"]))),
    CONSTRAINT "minesweeper_tournaments_description_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 1000))),
    CONSTRAINT "minesweeper_tournaments_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['beginner'::"text", 'intermediate'::"text", 'expert'::"text"]))),
    CONSTRAINT "minesweeper_tournaments_name_check" CHECK ((("length"("name") >= 3) AND ("length"("name") <= 100))),
    CONSTRAINT "minesweeper_tournaments_podium_places_check" CHECK ((("podium_places" >= 1) AND ("podium_places" <= 10))),
    CONSTRAINT "minesweeper_tournaments_scope_check" CHECK (("scope" = ANY (ARRAY['classes'::"text", 'global'::"text"]))),
    CONSTRAINT "minesweeper_tournaments_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'active'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "minesweeper_tournaments_top_x_games_check" CHECK ((("top_x_games" >= 1) AND ("top_x_games" <= 20))),
    CONSTRAINT "valid_date_range" CHECK (("end_date" > "start_date"))
);


ALTER TABLE "public"."minesweeper_tournaments" OWNER TO "postgres";


COMMENT ON TABLE "public"."minesweeper_tournaments" IS 'Minesweeper tournaments. Teachers create class-scoped, admins can create global. Top X games averaged for ranking.';



COMMENT ON COLUMN "public"."minesweeper_tournaments"."top_x_games" IS 'Number of best games to average for ranking (1-20). Higher values reward consistency.';



COMMENT ON COLUMN "public"."minesweeper_tournaments"."podium_rewards" IS 'JSON object mapping place (1,2,3...) to gidouilles reward. Default: {"1": 10, "2": 5, "3": 3}';



COMMENT ON COLUMN "public"."minesweeper_tournaments"."podium_places" IS 'Number of podium places that receive rewards (1-10). Must have matching entries in podium_rewards.';



CREATE OR REPLACE VIEW "public"."minesweeper_tournament_standings" WITH ("security_invoker"='on') AS
 WITH "ranked_games" AS (
         SELECT "g"."tournament_id",
            "g"."student_id",
            "g"."score",
            "g"."grid_3bv",
            "g"."time_seconds",
            "row_number"() OVER (PARTITION BY "g"."tournament_id", "g"."student_id" ORDER BY "g"."score" DESC NULLS LAST) AS "rank_in_student"
           FROM "public"."minesweeper_tournament_games" "g"
          WHERE ("g"."status" = 'won'::"text")
        ), "top_games" AS (
         SELECT "rg"."tournament_id",
            "rg"."student_id",
            "rg"."score",
            "rg"."grid_3bv",
            "rg"."time_seconds"
           FROM ("ranked_games" "rg"
             JOIN "public"."minesweeper_tournaments" "t" ON (("t"."id" = "rg"."tournament_id")))
          WHERE (("rg"."rank_in_student" <= "t"."top_x_games") AND ("rg"."score" IS NOT NULL))
        ), "aggregated" AS (
         SELECT "top_games"."tournament_id",
            "top_games"."student_id",
            "count"(*) AS "games_won",
            "avg"("top_games"."score") AS "average_score",
            "avg"((("top_games"."grid_3bv")::numeric / (GREATEST(1, "top_games"."time_seconds"))::numeric)) AS "average_3bvs"
           FROM "top_games"
          GROUP BY "top_games"."tournament_id", "top_games"."student_id"
        )
 SELECT "a"."tournament_id",
    "a"."student_id",
    "p"."firstname",
    "p"."lastname",
    ("a"."games_won")::integer AS "games_won",
    "round"("a"."average_score", 1) AS "average_score",
    "round"("a"."average_3bvs", 3) AS "average_3bvs",
    ("row_number"() OVER (PARTITION BY "a"."tournament_id" ORDER BY "a"."average_score" DESC))::integer AS "position"
   FROM ("aggregated" "a"
     JOIN "public"."profiles" "p" ON (("p"."id" = "a"."student_id")));


ALTER VIEW "public"."minesweeper_tournament_standings" OWNER TO "postgres";


COMMENT ON VIEW "public"."minesweeper_tournament_standings" IS 'Tournament standings ranked by average score (3BV-based efficiency).
   Shows average_score and average_3bvs for the top X games per student.';



