    "parent_email" "text",
    CONSTRAINT "pending_students_valid_grade" CHECK ((("grade" IS NULL) OR ("grade" = ANY (ARRAY['CP'::"text", 'CE1'::"text", 'CE2'::"text", 'CM1'::"text", 'CM2'::"text", '6'::"text", '5'::"text", '4'::"text", '3'::"text", '2'::"text", '1_GEN'::"text", 'T_GEN'::"text", '1_SPE'::"text", 'T_SPE'::"text", 'T_EXP'::"text", 'T_COMP'::"text", '1_STMG'::"text", 'T_STMG'::"text"])))),
    CONSTRAINT "valid_parent_email_format" CHECK ((("parent_email" IS NULL) OR ("parent_email" ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'::"text")))
);


