CREATE TABLE IF NOT EXISTS "public"."question_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "type" "text" NOT NULL,
    "options" "jsonb",
    "precision" "jsonb",
    "grades" "text"[] NOT NULL,
    "delay" integer,
    "multiple_answers" boolean,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid",
    "theme" "text" NOT NULL,
    "domain" "text" NOT NULL,
    "subdomain" "text",
    "level" integer NOT NULL,
    "variations" "jsonb" NOT NULL,
    "exercise_instruction" "text",
    "status" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "shared" "jsonb",
    "default_display_options" "jsonb",
    "test_specs" "jsonb",
    CONSTRAINT "question_templates_level_positive" CHECK (("level" > 0)),
    CONSTRAINT "question_templates_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text"]))),
    CONSTRAINT "question_templates_type_check" CHECK (("type" = ANY (ARRAY['numerical_exact'::"text", 'numerical_decimal'::"text", 'numerical_rounded'::"text", 'algebraic_transform'::"text", 'fill_in_blanks'::"text", 'multiple_choice'::"text"]))),
    CONSTRAINT "question_templates_valid_grades" CHECK ("public"."is_valid_grade_array"("grades")),
    CONSTRAINT "variations_minimum_one" CHECK (("jsonb_array_length"("variations") >= 1))
);


ALTER TABLE "public"."question_templates" OWNER TO "postgres";


COMMENT ON TABLE "public"."question_templates" IS 'Question templates with variations support and random generation. Each template has one or more variations, with optional shared defaults. Uses {{var}}, {{random:...}}, {{eval:...}} syntax.';



COMMENT ON COLUMN "public"."question_templates"."type" IS 'Type of question: numerical_exact, numerical_decimal, numerical_rounded, algebraic_transform, fill_in_blanks, multiple_choice';



COMMENT ON COLUMN "public"."question_templates"."options" IS 'Validation options: allowEquivalent, allowDifferentForms, validator, etc.';



COMMENT ON COLUMN "public"."question_templates"."precision" IS 'DEPRECATED - precision is now in shared.blankDefaults.precision';



COMMENT ON COLUMN "public"."question_templates"."grades" IS 'Applicable grade levels using canonical codes: CP, CE1, CE2, CM1, CM2, 6, 5, 4, 3, 2, 1_GEN, T_GEN, 1_SPE, T_SPE, T_EXP, T_COMP, 1_STMG, T_STMG';



COMMENT ON COLUMN "public"."question_templates"."delay" IS 'Time limit in seconds (optional)';



COMMENT ON COLUMN "public"."question_templates"."theme" IS 'Question theme (e.g., Algèbre, Géométrie) - independent from grades';



COMMENT ON COLUMN "public"."question_templates"."domain" IS 'Question domain within theme (e.g., Équations, Polynômes)';



COMMENT ON COLUMN "public"."question_templates"."subdomain" IS 'Optional subdomain for finer categorization (e.g., Linéaires, Quadratiques)';



COMMENT ON COLUMN "public"."question_templates"."level" IS 'Difficulty level as positive integer (no max) - independent from grades';



COMMENT ON COLUMN "public"."question_templates"."variations" IS 'JSONB array of question variations. Each variation now contains markdown strings instead of ContentField arrays. Structure: [{ statement: string, variables?: {...}[], answer: string | string[], correction?: string, blanks?: {...}[], choices?: { content: string, isCorrect: boolean }[] }]';



COMMENT ON COLUMN "public"."question_templates"."exercise_instruction" IS 'Optional shared instruction for all variations (e.g., "Calculer", "Résoudre"). In normal display: shown before statement. In worksheets: used as exercise title.';



COMMENT ON COLUMN "public"."question_templates"."status" IS 'Template status: "draft" (work-in-progress, can have duplicate categories) or "published" (active, must have unique category combination of theme/domain/subdomain/level)';



COMMENT ON COLUMN "public"."question_templates"."title" IS 'Template title with LaTeX support - used for organization and display (required)';



COMMENT ON COLUMN "public"."question_templates"."description" IS 'Optional rich text description for internal documentation and student context';



COMMENT ON COLUMN "public"."question_templates"."shared" IS 'Shared defaults applied to all variations. Contains: statement, solution, variables, correction, choices, validationRules. Per-variation values override shared values (except variables which are merged).';



COMMENT ON COLUMN "public"."question_templates"."default_display_options" IS 'Display options for math expressions (shuffleTerms, removeNullTerms, etc.). Cascade: GLOBAL < TEMPLATE < VARIABLE';



COMMENT ON COLUMN "public"."question_templates"."test_specs" IS 'Deterministic test specifications: fixed variables + expected validation results for regression testing';



