CREATE OR REPLACE VIEW "public"."riddle_progress" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "student_id",
    "p"."firstname",
    "p"."lastname",
    "p"."avatar_url",
    "count"(DISTINCT
        CASE
            WHEN ("ra"."is_correct" = true) THEN "ra"."riddle_id"
            ELSE NULL::"uuid"
        END) AS "riddles_completed",
    "count"("ra"."id") AS "total_attempts",
    COALESCE("sum"("ra"."gidouilles_awarded"), (0)::bigint) AS "riddles_gidouilles",
    "max"("ra"."created_at") FILTER (WHERE ("ra"."is_correct" = true)) AS "last_success_at",
    "row_number"() OVER (ORDER BY COALESCE("sum"("ra"."gidouilles_awarded"), (0)::bigint) DESC) AS "rank"
   FROM ("public"."profiles" "p"
     LEFT JOIN "public"."riddle_attempts" "ra" ON (("ra"."student_id" = "p"."id")))
  WHERE ("p"."role" = 'student'::"public"."user_role")
  GROUP BY "p"."id", "p"."firstname", "p"."lastname", "p"."avatar_url"
  ORDER BY COALESCE("sum"("ra"."gidouilles_awarded"), (0)::bigint) DESC;


ALTER VIEW "public"."riddle_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."riddle_progress" IS 'Student progress and leaderboard data. Uses security_invoker to respect RLS policies.';



CREATE OR REPLACE VIEW "public"."riddle_stats" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "riddle_id",
    "r"."riddle_number",
    "r"."title",
    "r"."genre",
    "r"."difficulty",
    "r"."created_by",
    "count"(DISTINCT "ra"."student_id") AS "unique_students",
    "count"("ra"."id") AS "total_attempts",
    COALESCE("avg"("ra"."attempt_number"), (0)::numeric) AS "avg_attempts_to_success",
    "count"("ra"."id") FILTER (WHERE ("ra"."is_correct" = true)) AS "successful_attempts",
        CASE
            WHEN ("count"("ra"."id") > 0) THEN "round"(((("count"("ra"."id") FILTER (WHERE ("ra"."is_correct" = true)))::numeric / ("count"("ra"."id"))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "success_rate_percent",
    "count"("ra"."id") FILTER (WHERE ("ra"."attempt_number" = 1)) AS "first_attempts",
    "count"("ra"."id") FILTER (WHERE ("ra"."attempt_number" = 2)) AS "second_attempts",
    "count"("ra"."id") FILTER (WHERE ("ra"."attempt_number" >= 3)) AS "third_plus_attempts",
    "count"("ra"."id") FILTER (WHERE ("ra"."is_correct" IS NULL)) AS "pending_validations",
    COALESCE("sum"("ra"."gidouilles_awarded"), (0)::bigint) AS "total_gidouilles_awarded"
   FROM ("public"."riddles" "r"
     LEFT JOIN "public"."riddle_attempts" "ra" ON (("ra"."riddle_id" = "r"."id")))
  GROUP BY "r"."id", "r"."riddle_number", "r"."title", "r"."genre", "r"."difficulty", "r"."created_by";


ALTER VIEW "public"."riddle_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."riddle_stats" IS 'Statistics per riddle for teachers. Uses security_invoker to respect RLS policies.';



CREATE OR REPLACE VIEW "public"."riddle_student_history" WITH ("security_invoker"='true') AS
 SELECT "ra"."student_id",
    "ra"."riddle_id",
    "r"."riddle_number",
    "r"."title" AS "riddle_title",
    "r"."genre",
    "r"."difficulty",
    "min"("ra"."attempt_number") AS "first_attempt_number",
    "max"("ra"."attempt_number") AS "latest_attempt_number",
    "count"("ra"."id") AS "total_attempts",
    "bool_or"(("ra"."is_correct" = true)) AS "ever_succeeded",
    "min"("ra"."created_at") FILTER (WHERE ("ra"."is_correct" = true)) AS "first_success_at",
    "max"("ra"."gidouilles_awarded") AS "max_gidouilles_earned",
    COALESCE("sum"("ra"."gidouilles_awarded"), (0)::bigint) AS "total_gidouilles_earned",
    ( SELECT "riddle_attempts"."created_at"
           FROM "public"."riddle_attempts"
          WHERE (("riddle_attempts"."student_id" = "ra"."student_id") AND ("riddle_attempts"."riddle_id" = "ra"."riddle_id"))
          ORDER BY "riddle_attempts"."attempt_number" DESC
         LIMIT 1) AS "last_attempt_at"
   FROM ("public"."riddle_attempts" "ra"
     JOIN "public"."riddles" "r" ON (("r"."id" = "ra"."riddle_id")))
  GROUP BY "ra"."student_id", "ra"."riddle_id", "r"."riddle_number", "r"."title", "r"."genre", "r"."difficulty";


ALTER VIEW "public"."riddle_student_history" OWNER TO "postgres";


COMMENT ON VIEW "public"."riddle_student_history" IS 'Individual student riddle history. Uses security_invoker to respect RLS policies.';



