CREATE TABLE IF NOT EXISTS "public"."skill_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "skill_id" "uuid",
    "success" boolean,
    "template_id" "uuid",
    "code" "text",
    "task_id" "uuid",
    "source" "text" NOT NULL,
    "source_ref" "uuid",
    "with_help" boolean DEFAULT false NOT NULL,
    "phase_blocage" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "grade" smallint,
    CONSTRAINT "chk_attempt_code_values" CHECK ((("code" IS NULL) OR ("code" = ANY (ARRAY['plus'::"text", 'minus'::"text"])))),
    CONSTRAINT "chk_attempt_family_regime" CHECK (((("template_id" IS NOT NULL) AND ("success" IS NOT NULL) AND ("skill_id" IS NULL) AND ("code" IS NULL) AND ("task_id" IS NULL)) OR (("skill_id" IS NOT NULL) AND ("code" IS NOT NULL) AND ("task_id" IS NOT NULL) AND ("template_id" IS NULL) AND ("success" IS NULL) AND ("grade" IS NULL)))),
    CONSTRAINT "chk_attempt_grade_range" CHECK ((("grade" IS NULL) OR (("grade" >= 1) AND ("grade" <= 4)))),
    CONSTRAINT "chk_attempt_source_values" CHECK (("source" = ANY (ARRAY['auto'::"text", 'srs'::"text", 'teacher'::"text", 'student_self'::"text"])))
);


ALTER TABLE "public"."skill_attempts" OWNER TO "postgres";


COMMENT ON TABLE "public"."skill_attempts" IS 'Dual-regime attempts table (decision 54). Family knowledge rows carry (success, template_id), family competence rows carry (code, task_id). Attempts are IMMUTABLE: no UPDATE/DELETE allowed via RLS.';



COMMENT ON COLUMN "public"."skill_attempts"."skill_id" IS 'Famille B uniquement (observable). NULL pour les rows Famille A : la liaison vers les capacités passe par question_template_skills à la lecture.';



COMMENT ON COLUMN "public"."skill_attempts"."code" IS 'Family competence only: ''plus'' (+) or ''minus'' (-). The ''∅'' code is implicit (no row stored = out of perimeter).';



COMMENT ON COLUMN "public"."skill_attempts"."with_help" IS 'Marker for analytics / error-book. Does NOT affect the acquisition rule (decision 58 - tutor help is a marker, not a penalty).';



COMMENT ON COLUMN "public"."skill_attempts"."grade" IS 'Famille A uniquement. Grade FSRS auto-évalué (1=Again, 2=Hard, 3=Good, 4=Easy). Pour les attempts Monde 1 (quiz interactif), dérivé de success : success=true → grade=3 ; success=false → grade=1. NULL pour Famille B et pour les attempts historiques (cold start, décision 8 du chantier 2026-06).';



COMMENT ON CONSTRAINT "chk_attempt_family_regime" ON "public"."skill_attempts" IS 'XOR strict Famille A (per-template, grade libre) vs Famille B (per-skill+task, grade interdit). Refonte 2026-06-10 follow-up : grade NULL imposé en B.';



COMMENT ON CONSTRAINT "chk_attempt_source_values" ON "public"."skill_attempts" IS 'Source de l''attempt. ''srs'' ajouté en 2026-06-10 pour les attempts générés par les reviews SRS (Monde 2).';



