CREATE TABLE IF NOT EXISTS "public"."skills" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "objective_id" "uuid",
    "subdimension_id" "uuid",
    "family" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("objective_id" IS NOT NULL) THEN 'knowledge'::"text"
    ELSE 'competence'::"text"
END) STORED,
    "niveau_scolaire" "text",
    "observable_code" "text",
    "name" "text" NOT NULL,
    "teacher_grid_text" "text",
    "knowledge_type" "text",
    "display_order" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_skill_competence_code" CHECK ((("subdimension_id" IS NULL) OR (("observable_code" IS NOT NULL) AND ("knowledge_type" IS NULL)))),
    CONSTRAINT "chk_skill_family" CHECK ((("objective_id" IS NOT NULL) <> ("subdimension_id" IS NOT NULL))),
    CONSTRAINT "chk_skill_knowledge_rang" CHECK ((("objective_id" IS NULL) OR (("display_order" >= 1) AND ("display_order" <= 4) AND ("knowledge_type" IS NOT NULL)))),
    CONSTRAINT "chk_skill_knowledge_type_values" CHECK ((("knowledge_type" IS NULL) OR ("knowledge_type" = ANY (ARRAY['automatisme'::"text", 'capacite_attendue'::"text"]))))
);


ALTER TABLE "public"."skills" OWNER TO "postgres";


COMMENT ON TABLE "public"."skills" IS 'Unit of attempt - "capacite" for family knowledge, "observable" for family competence. Family is a GENERATED column derived from the XOR FK pair (objective_id, subdimension_id). See docs/wip/skills-referentiel-design.md §7.';



COMMENT ON COLUMN "public"."skills"."family" IS 'Generated column (cannot be set manually). "knowledge" = Family A capacity, "competence" = Family B observable. Cf. decision 67.';



COMMENT ON COLUMN "public"."skills"."observable_code" IS 'Family competence only: code from the cadre canonique (A1, B3, C2, ...). Used by the conjunctive rules.';



COMMENT ON COLUMN "public"."skills"."knowledge_type" IS 'Family knowledge only: rubric BO 2026 cycle 3. Drives the acquisition rule: "automatisme" (5 successes total, 3 of last 5) vs "capacite_attendue" (>= 1 success on >= 2 distinct templates, no failure in last 3). NULL for family competence. Cf. decisions 66 + 68.';



COMMENT ON COLUMN "public"."skills"."display_order" IS 'Family knowledge: rang 1..4 under the objective (ordered by difficulty). Family competence: display order under the sub-dimension.';



