CREATE TABLE IF NOT EXISTS "public"."srs_anti_fraud_flags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "capacity_skill_id" "uuid",
    "flag_type" "text" NOT NULL,
    "severity" smallint NOT NULL,
    "score" real NOT NULL,
    "window_start" timestamp with time zone NOT NULL,
    "window_end" timestamp with time zone NOT NULL,
    "sample_size" integer NOT NULL,
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "resolved" boolean DEFAULT false NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_srs_anti_fraud_flag_type" CHECK (("flag_type" = ANY (ARRAY['high_easy_ratio'::"text", 'no_again'::"text", 'fast_timeSpent'::"text", 'burst'::"text", 'srs_vs_quiz_gap'::"text", 'composite'::"text"]))),
    CONSTRAINT "chk_srs_anti_fraud_resolved_coherent" CHECK (((("resolved" = true) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL)) OR (("resolved" = false) AND ("resolved_by" IS NULL) AND ("resolved_at" IS NULL)))),
    CONSTRAINT "chk_srs_anti_fraud_sample_positive" CHECK (("sample_size" >= 0)),
    CONSTRAINT "chk_srs_anti_fraud_score" CHECK ((("score" >= (0)::double precision) AND ("score" <= (1)::double precision))),
    CONSTRAINT "chk_srs_anti_fraud_severity" CHECK ((("severity" >= 1) AND ("severity" <= 5))),
    CONSTRAINT "chk_srs_anti_fraud_window" CHECK (("window_end" > "window_start"))
);


ALTER TABLE "public"."srs_anti_fraud_flags" OWNER TO "postgres";


COMMENT ON TABLE "public"."srs_anti_fraud_flags" IS 'Drapeaux de suspicion de triche SRS générés par le job runAntiFraudJob. Granularité (élève × capacité × type). Soft delete via resolved=true.';



COMMENT ON COLUMN "public"."srs_anti_fraud_flags"."capacity_skill_id" IS 'FK vers skills (famille A). NULL réservé à des flags globaux futurs (V3).';



COMMENT ON COLUMN "public"."srs_anti_fraud_flags"."flag_type" IS 'high_easy_ratio | no_again | fast_timeSpent | burst | srs_vs_quiz_gap | composite';



