CREATE MATERIALIZED VIEW "public"."student_achievement_stats" AS
 SELECT "student_id",
    "count"(*) AS "achievement_count",
    COALESCE("sum"("points_awarded"), (0)::bigint) AS "total_points",
    COALESCE("sum"("gidouilles_awarded"), (0)::bigint) AS "total_gidouilles",
    "max"("unlocked_at") AS "last_unlock",
    "min"("unlocked_at") AS "first_unlock"
   FROM "public"."student_achievements"
  GROUP BY "student_id"
  WITH NO DATA;


