CREATE OR REPLACE VIEW "public"."student_coursework_view" WITH ("security_invoker"='true') AS
 SELECT "sc"."id" AS "shared_coursework_id",
    "sc"."class_id",
    "c"."name" AS "class_name",
    "sc"."category_id",
    "cc"."name" AS "category_name",
    "cc"."icon" AS "category_icon",
    "cc"."color" AS "category_color",
    "sc"."visible",
    "sc"."display_order",
    "gcw"."id" AS "coursework_id",
    "gcw"."title",
    COALESCE("sc"."description_override", "gcw"."description") AS "description",
    "gcw"."coursework_type",
    "gcw"."state",
    "gcw"."due_date",
    "gcw"."due_time",
    "gcw"."max_points",
    "gcw"."created_time",
    "gcw"."updated_time",
    "gcc"."name" AS "google_course_name",
    "gcc"."section" AS "google_course_section",
    (EXISTS ( SELECT 1
           FROM "public"."shared_coursework_students" "scs"
          WHERE ("scs"."shared_coursework_id" = "sc"."id"))) AS "has_student_restrictions"
   FROM (((("public"."shared_coursework" "sc"
     JOIN "public"."google_classroom_coursework" "gcw" ON (("gcw"."id" = "sc"."coursework_id")))
     JOIN "public"."google_classroom_courses" "gcc" ON (("gcc"."id" = "gcw"."google_course_id")))
     JOIN "public"."classes" "c" ON (("c"."id" = "sc"."class_id")))
     LEFT JOIN "public"."coursework_categories" "cc" ON (("cc"."id" = "sc"."category_id")))
  WHERE (("sc"."visible" = true) AND ("gcw"."state" = 'PUBLISHED'::"text"));


ALTER VIEW "public"."student_coursework_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."student_coursework_view" IS 'Student view of Google Classroom coursework. Uses security_invoker to respect RLS.';



