CREATE OR REPLACE VIEW "public"."user_conversations_view" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "conversation_id",
    "c"."name",
    "c"."is_group",
    "c"."class_id",
    "c"."created_by",
    "c"."last_message_preview",
    "c"."last_message_at",
    "c"."updated_at",
    "cp"."user_id",
    "cp"."last_read_at",
    "cp"."is_archived",
    "cp"."is_muted",
    ( SELECT "count"(*) AS "count"
           FROM "public"."messages" "m"
          WHERE (("m"."conversation_id" = "c"."id") AND ("m"."deleted_at" IS NULL) AND ("m"."sender_id" <> "cp"."user_id") AND (("cp"."last_read_at" IS NULL) OR ("m"."created_at" > "cp"."last_read_at")))) AS "unread_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."conversation_participants" "cp2"
          WHERE ("cp2"."conversation_id" = "c"."id")) AS "participant_count",
        CASE
            WHEN ("c"."is_group" = false) THEN ( SELECT "p"."id"
               FROM ("public"."conversation_participants" "cp2"
                 JOIN "public"."profiles" "p" ON (("p"."id" = "cp2"."user_id")))
              WHERE (("cp2"."conversation_id" = "c"."id") AND ("cp2"."user_id" <> "cp"."user_id"))
             LIMIT 1)
            ELSE NULL::"uuid"
        END AS "other_user_id",
        CASE
            WHEN ("c"."is_group" = false) THEN ( SELECT "p"."firstname"
               FROM ("public"."conversation_participants" "cp2"
                 JOIN "public"."profiles" "p" ON (("p"."id" = "cp2"."user_id")))
              WHERE (("cp2"."conversation_id" = "c"."id") AND ("cp2"."user_id" <> "cp"."user_id"))
             LIMIT 1)
            ELSE NULL::"text"
        END AS "other_user_firstname",
        CASE
            WHEN ("c"."is_group" = false) THEN ( SELECT "p"."lastname"
               FROM ("public"."conversation_participants" "cp2"
                 JOIN "public"."profiles" "p" ON (("p"."id" = "cp2"."user_id")))
              WHERE (("cp2"."conversation_id" = "c"."id") AND ("cp2"."user_id" <> "cp"."user_id"))
             LIMIT 1)
            ELSE NULL::"text"
        END AS "other_user_lastname",
        CASE
            WHEN ("c"."is_group" = false) THEN ( SELECT "p"."avatar_url"
               FROM ("public"."conversation_participants" "cp2"
                 JOIN "public"."profiles" "p" ON (("p"."id" = "cp2"."user_id")))
              WHERE (("cp2"."conversation_id" = "c"."id") AND ("cp2"."user_id" <> "cp"."user_id"))
             LIMIT 1)
            ELSE NULL::"text"
        END AS "other_user_avatar_url"
   FROM ("public"."conversations" "c"
     JOIN "public"."conversation_participants" "cp" ON (("cp"."conversation_id" = "c"."id")))
  WHERE ("cp"."is_archived" = false);


ALTER VIEW "public"."user_conversations_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."user_conversations_view" IS 'Optimized view for user conversation list with unread counts';



