CREATE TABLE IF NOT EXISTS "public"."vip_card_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "config_name" "text" NOT NULL,
    "common_probability" integer NOT NULL,
    "rare_probability" integer NOT NULL,
    "epic_probability" integer NOT NULL,
    "legendary_probability" integer NOT NULL,
    "is_active" boolean DEFAULT false NOT NULL,
    "description" "text",
    "valid_from" timestamp with time zone,
    "valid_until" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "probabilities_sum_100" CHECK ((((("common_probability" + "rare_probability") + "epic_probability") + "legendary_probability") = 100)),
    CONSTRAINT "vip_card_config_common_probability_check" CHECK ((("common_probability" >= 0) AND ("common_probability" <= 100))),
    CONSTRAINT "vip_card_config_epic_probability_check" CHECK ((("epic_probability" >= 0) AND ("epic_probability" <= 100))),
    CONSTRAINT "vip_card_config_legendary_probability_check" CHECK ((("legendary_probability" >= 0) AND ("legendary_probability" <= 100))),
    CONSTRAINT "vip_card_config_rare_probability_check" CHECK ((("rare_probability" >= 0) AND ("rare_probability" <= 100)))
);


ALTER TABLE "public"."vip_card_config" OWNER TO "postgres";


COMMENT ON TABLE "public"."vip_card_config" IS 'Configurable probability distributions for VIP card rarity-weighted drawing. Only one config can be active at a time (enforced by unique index). Probabilities must sum to exactly 100.';



CREATE TABLE IF NOT EXISTS "public"."vip_card_templates" (
    "id" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text" NOT NULL,
    "image_path" "text" NOT NULL,
    "category" "text",
    "rarity" "text" NOT NULL,
    "is_enabled" boolean DEFAULT true NOT NULL,
    "action" "jsonb",
    "sort_order" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "base_price" integer DEFAULT 0 NOT NULL,
    "is_purchasable" boolean DEFAULT true NOT NULL,
    "max_owned_per_student" integer DEFAULT 5 NOT NULL,
    "uses_total" integer,
    "sell_price" integer,
    CONSTRAINT "vip_card_templates_base_price_positive" CHECK (("base_price" >= 0)),
    CONSTRAINT "vip_card_templates_category_check" CHECK ((("category" IS NULL) OR ("category" = ANY (ARRAY['bonus'::"text", 'privilege'::"text", 'social'::"text", 'power'::"text"])))),
    CONSTRAINT "vip_card_templates_max_owned_positive" CHECK ((("max_owned_per_student" > 0) AND ("max_owned_per_student" <= 100))),
    CONSTRAINT "vip_card_templates_rarity_check" CHECK (("rarity" = ANY (ARRAY['common'::"text", 'rare'::"text", 'epic'::"text", 'legendary'::"text"]))),
    CONSTRAINT "vip_card_templates_uses_total_positive" CHECK ((("uses_total" IS NULL) OR ("uses_total" > 0)))
);


ALTER TABLE "public"."vip_card_templates" OWNER TO "postgres";


COMMENT ON TABLE "public"."vip_card_templates" IS 'Master list of all VIP card definitions with rarity metadata. Cards can be temporarily disabled without deletion. The ''action'' column stores JSONB for cards with special abilities (e.g., draw_cards, remove_warnings, exchange_cards, add_gidouilles).';



COMMENT ON COLUMN "public"."vip_card_templates"."base_price" IS 'Price in gidouilles to purchase this card. Defaults based on rarity: common=20, rare=50, epic=150, legendary=500';



COMMENT ON COLUMN "public"."vip_card_templates"."is_purchasable" IS 'Whether this card can be purchased with gidouilles';



COMMENT ON COLUMN "public"."vip_card_templates"."max_owned_per_student" IS 'Maximum number of active (unused) copies a student can own';



COMMENT ON COLUMN "public"."vip_card_templates"."uses_total" IS 'For consumable cards: number of times card can be used. NULL = single-use (current behavior)';



COMMENT ON COLUMN "public"."vip_card_templates"."sell_price" IS 'Price in gidouilles when student sells the card back to the system. Based on rarity (~20% of base price).';



