);


ALTER TABLE "public"."worksheet_templates" OWNER TO "postgres";


COMMENT ON TABLE "public"."worksheet_templates" IS 'Worksheet templates for PDF generation. System templates have UUIDs starting with 00000000-0000-4000-8000- and created_by = NULL.';



COMMENT ON COLUMN "public"."worksheet_templates"."template_content" IS 'Typst template code with placeholders like {{title}}, {{exercises}}';



COMMENT ON COLUMN "public"."worksheet_templates"."placeholders" IS 'JSON array defining available placeholders and their types';



CREATE TABLE IF NOT EXISTS "public"."worksheets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "type" "text" DEFAULT 'worksheet'::"text" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "version" integer DEFAULT 1,
    "published_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "template_id" "uuid",
    "estimated_duration_minutes" integer,
    "total_points" numeric(10,2),
    "grades" "text"[] DEFAULT '{}'::integer[],
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "created_by" "uuid" NOT NULL,
    "school_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "worksheets_duration_check" CHECK ((("estimated_duration_minutes" IS NULL) OR ("estimated_duration_minutes" > 0))),
    CONSTRAINT "worksheets_points_check" CHECK ((("total_points" IS NULL) OR ("total_points" >= (0)::numeric))),
    CONSTRAINT "worksheets_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"]))),
    CONSTRAINT "worksheets_title_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 255))),
    CONSTRAINT "worksheets_type_check" CHECK (("type" = ANY (ARRAY['worksheet'::"text", 'assessment'::"text", 'exam'::"text", 'quiz'::"text", 'homework'::"text"]))),
    CONSTRAINT "worksheets_valid_grades" CHECK ("public"."is_valid_grade_array"("grades")),
    CONSTRAINT "worksheets_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."worksheets" OWNER TO "postgres";


