CREATE POLICY "Addressee can update friendship status" ON "public"."friendships" FOR UPDATE USING (("auth"."uid"() = "addressee_id"));



CREATE POLICY "Admin full access to migration_edits" ON "public"."migration_edits" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



CREATE POLICY "Admin full access to migration_images" ON "public"."migration_images" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



CREATE POLICY "Admin full access to migration_tracking" ON "public"."migration_tracking" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



CREATE POLICY "Admins can create academic periods" ON "public"."academic_periods" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



CREATE POLICY "Admins can create any notification" ON "public"."notifications" FOR INSERT WITH CHECK ((( SELECT ("profiles"."role")::"text" AS "role"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"())) = 'admin'::"text"));



CREATE POLICY "Admins can create school holidays" ON "public"."school_holidays" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))));



CREATE POLICY "Admins can delete any notification" ON "public"."notifications" FOR UPDATE USING ((( SELECT ("profiles"."role")::"text" AS "role"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"())) = 'admin'::"text")) WITH CHECK ((( SELECT ("profiles"."role")::"text" AS "role"
   FROM "public"."profiles"
  WHERE ("profiles"."id" = "auth"."uid"())) = 'admin'::"text"));



CREATE POLICY "Admins can delete bug reports" ON "public"."bug_reports" FOR DELETE TO "authenticated" USING ("public"."is_admin"());



CREATE POLICY "Admins can delete pending students" ON "public"."pending_students" FOR DELETE USING ("public"."is_admin"());



CREATE POLICY "Admins can delete riddle of the day" ON "public"."riddle_of_the_day" FOR DELETE USING ("public"."is_admin"());



CREATE POLICY "Admins can insert pending students" ON "public"."pending_students" FOR INSERT WITH CHECK ("public"."is_admin"());



CREATE POLICY "Admins can insert welcome emails" ON "public"."welcome_emails_sent" FOR INSERT WITH CHECK ("public"."is_admin"());



