CREATE POLICY "Users can view their sent or received messages" ON "public"."private_messages" FOR SELECT USING ((("auth"."uid"() = "sender_id") OR (EXISTS ( SELECT 1
   FROM "public"."message_inbox"
  WHERE (("message_inbox"."message_id" = "private_messages"."id") AND ("message_inbox"."recipient_id" = "auth"."uid"()) AND ("message_inbox"."deleted" = false))))));



COMMENT ON POLICY "Users can view their sent or received messages" ON "public"."private_messages" IS 'Allow users to view messages they sent or received';



CREATE POLICY "Users can view tournament classes" ON "public"."minesweeper_tournament_classes" FOR SELECT TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))) OR (EXISTS ( SELECT 1
   FROM "public"."classes" "c"
  WHERE (("c"."id" = "minesweeper_tournament_classes"."class_id") AND ("c"."teacher_id" = "auth"."uid"())))) OR (EXISTS ( SELECT 1
   FROM "public"."class_members" "cm"
  WHERE (("cm"."class_id" = "minesweeper_tournament_classes"."class_id") AND ("cm"."student_id" = "auth"."uid"()))))));



CREATE POLICY "Users can view tournament co-participants profiles" ON "public"."profiles" FOR SELECT TO "authenticated" USING ("public"."shares_tournament"("id"));



CREATE POLICY "Users can view tournament games" ON "public"."minesweeper_tournament_games" FOR SELECT TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))) OR ("student_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "public"."minesweeper_tournaments" "t"
  WHERE (("t"."id" = "minesweeper_tournament_games"."tournament_id") AND ("t"."creator_id" = "auth"."uid"())))) OR (EXISTS ( SELECT 1
   FROM ("public"."minesweeper_tournament_classes" "tc"
     JOIN "public"."class_members" "cm" ON (("cm"."class_id" = "tc"."class_id")))
  WHERE (("tc"."tournament_id" = "minesweeper_tournament_games"."tournament_id") AND ("cm"."student_id" = "auth"."uid"()))))));



CREATE POLICY "Users can view worksheet exercises" ON "public"."worksheet_exercises" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."worksheets"
  WHERE (("worksheets"."id" = "worksheet_exercises"."worksheet_id") AND (("worksheets"."created_by" = "auth"."uid"()) OR (EXISTS ( SELECT 1
           FROM "public"."profiles"
          WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))) OR (("worksheets"."status" = 'published'::"text") AND (EXISTS ( SELECT 1
           FROM "public"."profiles" "p1",
            "public"."profiles" "p2"
          WHERE (("p1"."id" = "auth"."uid"()) AND ("p2"."id" = "worksheets"."created_by") AND ("p1"."school_id" = "p2"."school_id") AND ("p1"."school_id" IS NOT NULL) AND ("p1"."role" = 'teacher'::"public"."user_role"))))) OR "public"."student_has_worksheet_access"("worksheets"."id"))))));



CREATE POLICY "Users can view worksheet sections" ON "public"."worksheet_sections" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."worksheets"
  WHERE (("worksheets"."id" = "worksheet_sections"."worksheet_id") AND (("worksheets"."created_by" = "auth"."uid"()) OR (EXISTS ( SELECT 1
           FROM "public"."profiles"
          WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))) OR (("worksheets"."status" = 'published'::"text") AND (EXISTS ( SELECT 1
           FROM "public"."profiles" "p1",
            "public"."profiles" "p2"
          WHERE (("p1"."id" = "auth"."uid"()) AND ("p2"."id" = "worksheets"."created_by") AND ("p1"."school_id" = "p2"."school_id") AND ("p1"."school_id" IS NOT NULL) AND ("p1"."role" = 'teacher'::"public"."user_role"))))) OR "public"."student_has_worksheet_access"("worksheets"."id"))))));



CREATE POLICY "Users can view worksheets" ON "public"."worksheets" FOR SELECT TO "authenticated" USING ((("created_by" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"public"."user_role")))) OR (("status" = 'published'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."profiles" "p1",
    "public"."profiles" "p2"
  WHERE (("p1"."id" = "auth"."uid"()) AND ("p2"."id" = "worksheets"."created_by") AND ("p1"."school_id" = "p2"."school_id") AND ("p1"."school_id" IS NOT NULL) AND ("p1"."role" = 'teacher'::"public"."user_role"))))) OR "public"."student_has_worksheet_access"("id")));



